INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38671, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "糖が発酵してできる有機酸の一種。ヨーグルトなどに含まれる。", "primary_collocate": null, "pronunciation": "にゅうさん", "ipa": "ɲɯːsaɴ", "syllable_count": 4, "sentences": [{"text": "発酵の進んだ生地では、糖から生じた乳酸が穏やかな酸味を与え、香りの輪郭を整える。", "target_word": "乳酸", "complexity_tier": "T5", "furigana": "発酵(はっこう)の進(すす)んだ生地(きじ)では、糖(とう)から生(しょう)じた乳酸(にゅうさん)が穏(おだ)やかな酸味(さんみ)を与(あた)え、香(かお)りの輪郭(りんかく)を整(ととの)える。", "sentence_source": "generated"}, {"text": "ヨーグルトがすっぱいのは、乳酸が含まれているからです。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "ヨーグルトがすっぱいのは、乳酸(にゅうさん)が含(ふく)まれているからです。", "sentence_source": "generated"}, {"text": "糖が発酵すると、乳酸ができます。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "糖(とう)が発酵(はっこう)すると、乳酸(にゅうさん)ができます。", "sentence_source": "generated"}, {"text": "漬物を作る間に、野菜の糖が乳酸に変わって、味が深くなります。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "漬物(つけもの)を作(つく)る間(あいだ)に、野菜(やさい)の糖(とう)が乳酸(にゅうさん)に変(か)わって、味(あじ)が深(ふか)くなります。", "sentence_source": "generated"}, {"text": "この飲み物には乳酸が入っているので、少しすっぱい味がします。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "この飲(の)み物(もの)には乳酸(にゅうさん)が入(はい)っているので、少(すこ)しすっぱい味(あじ)がします。", "sentence_source": "generated"}, {"text": "乳酸には、食べ物が傷むのを防ぐはたらきもあります。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "乳酸(にゅうさん)には、食(た)べ物(もの)が傷(いた)むのを防(ふせ)ぐはたらきもあります。", "sentence_source": "generated"}, {"text": "チーズの風味は、乳酸などの有機酸のはたらきで生まれる。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "チーズの風味(ふうみ)は、乳酸(にゅうさん)などの有機酸(ゆうきさん)のはたらきで生(う)まれる。", "sentence_source": "generated"}, {"text": "牛乳を室温に置いておくと、乳酸ができて、やがてすっぱくなる。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "牛乳[ぎゅうにゅう]を室温[しつおん]に置いておくと、乳酸[にゅうさん]ができて、やがてすっぱくなる。", "sentence_source": "generated"}, {"text": "キムチの酸味のもとは、主に乳酸だ。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "キムチの酸味(さんみ)のもとは、主(おも)に乳酸(にゅうさん)だ。", "sentence_source": "generated"}, {"text": "パンの生地は、発酵の間に乳酸を作り、少しすっぱくなる。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "パンの生地[きじ]は、発酵[はっこう]の間[あいだ]に乳酸[にゅうさん]を作[つく]り、少[すこ]しすっぱくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "乳酸", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "糖の発酵でできる有機酸。ヨーグルトや漬物の酸味のもと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a709c419-0fda-4240-8628-7e66ce402bcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38671, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "砂糖", "is_correct": false, "explanation": "砂糖は甘さのもとで、糖から生じるものではなく、酸味も与えないので合わない。"}, {"text": "乳酸", "is_correct": true, "explanation": "糖が発酵して生じる乳酸が酸味を与えるので、空欄に入る。"}, {"text": "食塩", "is_correct": false, "explanation": "食塩は塩味のもとで、酸味を与えるものではないので合わない。"}, {"text": "空気", "is_correct": false, "explanation": "空気は酸味を与えず、糖から生じるものでもないので合わない。"}], "explanations": {"砂糖": "砂糖は甘さのもとで、糖から生じるものではなく、酸味も与えないので合わない。", "乳酸": "糖が発酵して生じる乳酸が酸味を与えるので、空欄に入る。", "食塩": "食塩は塩味のもとで、酸味を与えるものではないので合わない。", "空気": "空気は酸味を与えず、糖から生じるものでもないので合わない。"}, "sentence_index": 0, "correct_answer": "乳酸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "研究室では、ヨーグルトから乳酸を取り出して培養し、増やした。", "explanation": "ここは〈乳酸菌〉の意味。培養して増やすのは細菌なので、化学物質の乳酸には合わない。"}, {"text": "お酢の酸っぱさは、乳酸によるものだ。", "explanation": "ここは〈酢酸〉の意味。お酢の酸っぱさは酢酸によるもので、乳酸とは混同しやすいがこの文では合わない。"}, {"text": "朝は乳酸を一杯食べてから出かける。", "explanation": "ここは〈乳製品〉の意味。一杯食べるのはヨーグルトなどの乳製品で、乳酸という物質には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38671, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香料", "is_correct": false, "explanation": "香料は香りをつける物質で、有機酸ではないので「〜などの有機酸」の例として合わない。"}, {"text": "乳酸", "is_correct": true, "explanation": "乳酸は有機酸の一種なので、「乳酸などの有機酸」の例として入る。"}, {"text": "水分", "is_correct": false, "explanation": "水分は有機酸の仲間ではないので、「〜などの有機酸」の例として合わない。"}, {"text": "石油", "is_correct": false, "explanation": "石油は炭化水素の混合物で有機酸ではないので、「〜などの有機酸」の例として合わない。"}], "explanations": {"香料": "香料は香りをつける物質で、有機酸ではないので「〜などの有機酸」の例として合わない。", "乳酸": "乳酸は有機酸の一種なので、「乳酸などの有機酸」の例として入る。", "水分": "水分は有機酸の仲間ではないので、「〜などの有機酸」の例として合わない。", "石油": "石油は炭化水素の混合物で有機酸ではないので、「〜などの有機酸」の例として合わない。"}, "sentence_index": 6, "correct_answer": "乳酸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パンを膨らませるため、生地に乳酸を入れて発酵させた。", "explanation": "ここは〈酵母〉の意味。生地を膨らませるのは酵母の働きで、乳酸は酸味を出すものなので合わない。"}, {"text": "米のでんぷんを糖に変えるのは、乳酸の役目だ。", "explanation": "ここは〈麹〉の意味。でんぷんを糖に変えるのは麹などの働きで、乳酸は糖が発酵してできる酸なので合わない。"}, {"text": "ヨーグルトに乳酸を加えると、甘くなる。", "explanation": "ここは〈砂糖〉の意味。甘くするものは砂糖で、すっぱさのもとの乳酸では甘さは出ない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38671, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "野菜の糖は、発酵すると乳酸と変わる。", "corrected_sentence": "野菜の糖は、発酵すると乳酸に変わる。", "error_description": "「と」が誤り。「変わる」は「〜に変わる」で変化の結果を「に」で示す。「と」にすると「違う」の意味になってしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38671, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ヨーグルトのすっぱい味は、乳酸がおかげです。", "corrected_sentence": "ヨーグルトのすっぱい味は、乳酸のおかげです。", "error_description": "「が」が誤り。「おかげ」は「〜のおかげ」と「の」で名詞につなぐ。「が」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
