INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38672, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物から作られる、かたいプラスチックの一種です。", "primary_collocate": null, "pronunciation": "ぴーえるえー", "ipa": "piːeɾɯeː", "syllable_count": 6, "sentences": [{"text": "PLA は、とうもろこしから作られるプラスチックだ。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "PLA は、とうもろこしから作[つく]られるプラスチックだ。", "sentence_source": "generated"}, {"text": "PLA のフォークは、ふつうのプラスチックより少し高い。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "PLA のフォークは、ふつうのプラスチックより少[すこ]し高[たか]い。", "sentence_source": "generated"}, {"text": "PLA は、石油のプラスチックより熱に弱い。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "PLA は、石油[せきゆ]のプラスチックより熱[ねつ]に弱[よわ]い。", "sentence_source": "generated"}, {"text": "工作で使う PLA は、かたくて加工しやすい。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "工作[こうさく]で使[つか]う PLA は、かたくて加工[かこう]しやすい。", "sentence_source": "generated"}, {"text": "店のストローが紙から PLA のものに変わった。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "店[みせ]のストローが紙[かみ]から PLA のものに変[か]わった。", "sentence_source": "generated"}, {"text": "PLA は植物から作られるので、環境にやさしいと言われる。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "PLA は植物[しょくぶつ]から作[つく]られるので、環境[かんきょう]にやさしいと言[い]われる。", "sentence_source": "generated"}, {"text": "熱いお茶を入れると、PLA の容器はやわらかくなる。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "熱[あつ]いお茶[ちゃ]を入[い]れると、PLA の容器[ようき]はやわらかくなる。", "sentence_source": "generated"}, {"text": "このおもちゃは PLA で作られているので、軽くてじょうぶだ。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "このおもちゃは PLA で作[つく]られているので、軽[かる]くてじょうぶだ。", "sentence_source": "generated"}, {"text": "使い終わった PLA は、特別な方法で土に返せる。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "使[つか]い終[お]わった PLA は、特別[とくべつ]な方法[ほうほう]で土[つち]に返[かえ]せる。", "sentence_source": "generated"}, {"text": "学校の授業で、PLA の箱を作った。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "学校[がっこう]の授業[じゅぎょう]で、PLA の箱[はこ]を作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "PLA", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "植物由来で作られるかたいプラスチック素材（日用品・工作の文脈）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de7ed79c-919b-44ee-a142-5d1255fc3aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38672, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "PLA", "is_correct": true, "explanation": "正解。とうもろこし由来のプラスチックを指す。"}, {"text": "紙", "is_correct": false, "explanation": "紙はプラスチックではないので、「プラスチックだ」という文が事実に合わない。"}, {"text": "木材", "is_correct": false, "explanation": "木材はプラスチックではないので、「プラスチックだ」という文が事実に合わない。"}, {"text": "石油", "is_correct": false, "explanation": "石油はプラスチックの原料であって、プラスチックそのものではない。"}], "explanations": {"PLA": "正解。とうもろこし由来のプラスチックを指す。", "紙": "紙はプラスチックではないので、「プラスチックだ」という文が事実に合わない。", "木材": "木材はプラスチックではないので、「プラスチックだ」という文が事実に合わない。", "石油": "石油はプラスチックの原料であって、プラスチックそのものではない。"}, "sentence_index": 0, "correct_answer": "PLA"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "PLA は石油から作られるプラスチックで、ペットボトルに使われる。", "explanation": "ここは〈PET〉の説明。PET は石油由来なので、植物由来の PLA とは合わない。"}, {"text": "PLA は、熱に強い無機物だ。", "explanation": "ここは〈ガラス〉の説明。ガラスは無機物で、植物から作られる PLA の説明としては合わない。"}, {"text": "PLA は、磁石にくっつく。", "explanation": "ここは〈金属〉の説明。金属は磁石にくっつくが、PLA はプラスチックなので磁石にはくっつかず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38672, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "PLA", "is_correct": true, "explanation": "正解。熱に弱く、お茶の熱でやわらかくなる樹脂を指す。"}, {"text": "ガラス", "is_correct": false, "explanation": "ガラスは熱でやわらかくならないので、文の内容が事実に合わない。"}, {"text": "陶器", "is_correct": false, "explanation": "陶器は熱でやわらかくならないので、文の内容が事実に合わない。"}, {"text": "金属", "is_correct": false, "explanation": "金属は熱でやわらかくならないので、文の内容が事実に合わない。"}], "explanations": {"PLA": "正解。熱に弱く、お茶の熱でやわらかくなる樹脂を指す。", "ガラス": "ガラスは熱でやわらかくならないので、文の内容が事実に合わない。", "陶器": "陶器は熱でやわらかくならないので、文の内容が事実に合わない。", "金属": "金属は熱でやわらかくならないので、文の内容が事実に合わない。"}, "sentence_index": 6, "correct_answer": "PLA"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "PLA は、植物の種の周りの毛から作られ、服に使われる。", "explanation": "ここは〈綿〉の説明。PLA はとうもろこし由来のプラスチックで、種の周りの毛からは作られないので合わない。"}, {"text": "PLA は、水に沈まず浮く軽い樹脂で、救命具に使われる。", "explanation": "ここは〈ポリエチレン〉の説明。ポリエチレンは水に浮くが、PLA は水より重く沈むので合わない。"}, {"text": "PLA は、水にとかすと甘くなる。", "explanation": "ここは〈砂糖〉の説明。砂糖は水にとけて甘くなるが、PLA はプラスチックで甘くならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38672, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このストローは、PLA を作られている。", "corrected_sentence": "このストローは、PLA で作られている。", "error_description": "材料は「で」で示す。「PLA を」は目的語になり、「作られている」と続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38672, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この箱は、PLA に作られている。", "corrected_sentence": "この箱は、PLA で作られている。", "error_description": "材料は「で」で示す。「PLA に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
