INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38673, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生分解性プラスチックの一種で、トウモロコシなどから作られるポリ乳酸の略称。", "primary_collocate": null, "pronunciation": "ぴーえるえー", "ipa": "piːeɾɯeː", "syllable_count": 6, "sentences": [{"text": "PLA とは、ポリ乳酸の略称だ。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "PLA とは、ポリ乳酸[にゅうさん]の略称[りゃくしょう]だ。", "sentence_source": "generated"}, {"text": "PLA は微生物によって水と二酸化炭素に分解される。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "PLA は微生物[びせいぶつ]によって水[みず]と二酸化炭素[にさんかたんそ]に分解[ぶんかい]される。", "sentence_source": "generated"}, {"text": "PLA の原料には、トウモロコシのでんぷんが使われる。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "PLA の原料[げんりょう]には、トウモロコシのでんぷんが使[つか]われる。", "sentence_source": "generated"}, {"text": "包装材を PLA に替える企業が増えている。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "包装材[ほうそうざい]を PLA に替[か]える企業[きぎょう]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "PLA は石油由来の樹脂に比べ、耐熱性が低い。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "PLA は石油[せきゆ]由来[ゆらい]の樹脂[じゅし]に比[くら]べ、耐熱性[たいねつせい]が低[ひく]い。", "sentence_source": "generated"}, {"text": "医療分野でも、体内で溶ける糸に PLA が利用されている。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "医療[いりょう]分野[ぶんや]でも、体内[たいない]で溶[と]ける糸[いと]に PLA が利用[りよう]されている。", "sentence_source": "generated"}, {"text": "発酵で得た乳酸を重合すると、PLA ができる。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "発酵[はっこう]で得[え]た乳酸[にゅうさん]を重合[じゅうごう]すると、PLA ができる。", "sentence_source": "generated"}, {"text": "PLA は堆肥化施設で、数か月かけて分解される。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "PLA は堆肥化[たいひか]施設[しせつ]で、数[すう]か月[げつ]かけて分解[ぶんかい]される。", "sentence_source": "generated"}, {"text": "環境規制の強化で、PLA の需要が伸びている。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "環境[かんきょう]規制[きせい]の強化[きょうか]で、PLA の需要[じゅよう]が伸[の]びている。", "sentence_source": "generated"}, {"text": "PLA は比較的低い温度で成形できる。", "target_word": "PLA", "complexity_tier": "T3", "furigana": "PLA は比較的[ひかくてき]低[ひく]い温度[おんど]で成形[せいけい]できる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "PLA", "label": "基本形"}], "register": "plain", "sense_fingerprint": "ポリ乳酸の略称で、生分解性をもつ樹脂（化学・環境分野の文脈）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de7ed79c-919b-44ee-a142-5d1255fc3aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38673, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "PLA", "is_correct": true, "explanation": "正解。ポリ乳酸の略称なので、文が正しい。"}, {"text": "乳酸", "is_correct": false, "explanation": "乳酸は物質名で、ポリ乳酸の略称ではない。"}, {"text": "PET", "is_correct": false, "explanation": "PET は別の樹脂の略称で、ポリ乳酸の略称ではない。"}, {"text": "ABS", "is_correct": false, "explanation": "ABS は別の樹脂の略称で、ポリ乳酸の略称ではない。"}], "explanations": {"PLA": "正解。ポリ乳酸の略称なので、文が正しい。", "乳酸": "乳酸は物質名で、ポリ乳酸の略称ではない。", "PET": "PET は別の樹脂の略称で、ポリ乳酸の略称ではない。", "ABS": "ABS は別の樹脂の略称で、ポリ乳酸の略称ではない。"}, "sentence_index": 0, "correct_answer": "PLA"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "PLA は、激しい運動のあとに筋肉にたまる物質だ。", "explanation": "ここは〈乳酸〉の説明。PLA は樹脂で、筋肉にたまる物質ではないので合わない。"}, {"text": "PLA は石油から作られ、飲み物のボトルに使われる樹脂だ。", "explanation": "ここは〈PET〉の説明。PET は石油由来で、PLA はとうもろこし由来なので合わない。"}, {"text": "PLA は、糖をアルコールに変える微生物だ。", "explanation": "ここは〈酵母〉の説明。PLA は樹脂で、微生物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38673, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "PLA", "is_correct": true, "explanation": "正解。乳酸を重合してできる樹脂を指す。"}, {"text": "砂糖", "is_correct": false, "explanation": "重合でできるのは高分子で、砂糖は重合の結果として合わない。"}, {"text": "水素", "is_correct": false, "explanation": "重合でできるのは高分子で、水素は文の内容に合わない。"}, {"text": "食塩", "is_correct": false, "explanation": "重合でできるのは高分子で、食塩は文の内容に合わない。"}], "explanations": {"PLA": "正解。乳酸を重合してできる樹脂を指す。", "砂糖": "重合でできるのは高分子で、砂糖は重合の結果として合わない。", "水素": "重合でできるのは高分子で、水素は文の内容に合わない。", "食塩": "重合でできるのは高分子で、食塩は文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "PLA"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "PLA は、力を加えると大きくのびて元に戻る。", "explanation": "ここは〈ゴム〉の説明。PLA はかたくてのびにくい樹脂なので、ゴムのような弾性はないので合わない。"}, {"text": "PLA は、木の繊維から作られ、本の表紙に使われる。", "explanation": "ここは〈紙〉の説明。紙は木の繊維から作られるが、PLA はとうもろこし由来のプラスチックなので合わない。"}, {"text": "PLA は、燃えない鉱物で、窓に使われる。", "explanation": "ここは〈ガラス〉の説明。ガラスは鉱物から作られる無機物で、PLA は植物由来の樹脂なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38673, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "PLA は、微生物によって分解する樹脂だ。", "corrected_sentence": "PLA は、微生物によって分解される樹脂だ。", "error_description": "「によって」の後は受け身の「分解される」が必要。「分解する」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38673, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "PLA を、低い温度で成形できる樹脂だ。", "corrected_sentence": "PLA は、低い温度で成形できる樹脂だ。", "error_description": "主語を示すには「は」が必要。「を」だと PLA が目的語になり、文の主題が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38674, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」は「由来」が説明される対象を示すので、目的語として合う。"}, {"text": "に", "is_correct": false, "explanation": "「由来に、博物館の人が説明してくれた」は説明の対象を示せない。"}, {"text": "ので", "is_correct": false, "explanation": "「由来ので」は接続の「ので」になり、名詞に続かず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「由来へ」は方向の「へ」になり、説明の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「を」は「由来」が説明される対象を示すので、目的語として合う。", "に": "「由来に、博物館の人が説明してくれた」は説明の対象を示せない。", "ので": "「由来ので」は接続の「ので」になり、名詞に続かず文が成り立たない。", "へ": "「由来へ」は方向の「へ」になり、説明の対象を示せない。"}, "error_tags": {"に": "相手・位置", "ので": "接続", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38674, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「は」は「由来」を話題として示し、「由来は葉の形にあるそうだ」の形で成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「由来を、葉の形にあるそうだ」は目的語になり、文の主題が立たない。"}, {"text": "と", "is_correct": false, "explanation": "「由来と、葉の形にあるそうだ」は並列となり、主題にならない。"}, {"text": "より", "is_correct": false, "explanation": "「由来より」は比較の「より」になり、主題を示せない。"}], "correct_answer": "は", "explanations": {"は": "「は」は「由来」を話題として示し、「由来は葉の形にあるそうだ」の形で成り立つ。", "を": "「由来を、葉の形にあるそうだ」は目的語になり、文の主題が立たない。", "と": "「由来と、葉の形にあるそうだ」は並列となり、主題にならない。", "より": "「由来より」は比較の「より」になり、主題を示せない。"}, "error_tags": {"を": "目的語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38674, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが生まれたもとになるもの。", "primary_collocate": null, "pronunciation": "ゆらい", "ipa": "jɯɾai", "syllable_count": 3, "sentences": [{"text": "このお菓子の名前には、面白い由来がある。", "target_word": "由来", "complexity_tier": "T3", "furigana": "このお菓子[かし]の名前[なまえ]には、面白[おもしろ]い由来[ゆらい]がある。", "sentence_source": "generated"}, {"text": "刀に伝わる由来を、博物館の人が説明してくれた。", "target_word": "由来", "complexity_tier": "T3", "furigana": "刀[かたな]に伝[つた]わる由来[ゆらい]を、博物館[はくぶつかん]の人[ひと]が説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "その由来は、百年前の小さな出来事にさかのぼる。", "target_word": "由来", "complexity_tier": "T3", "furigana": "その由来[ゆらい]は、百年前[ひゃくねんまえ]の小[ちい]さな出来事[できごと]にさかのぼる。", "sentence_source": "generated"}, {"text": "由来が分からない古い箱が、倉庫から出てきた。", "target_word": "由来", "complexity_tier": "T3", "furigana": "由来[ゆらい]が分[わ]からない古[ふる]い箱[はこ]が、倉庫[そうこ]から出[で]てきた。", "sentence_source": "generated"}, {"text": "この駅の名前の由来には、いろいろな説がある。", "target_word": "由来", "complexity_tier": "T3", "furigana": "この駅[えき]の名前[なまえ]の由来[ゆらい]には、いろいろな説[せつ]がある。", "sentence_source": "generated"}, {"text": "このお守りの由来を聞いて、大切にしようと思った。", "target_word": "由来", "complexity_tier": "T3", "furigana": "このお守[まも]りの由来[ゆらい]を聞[き]いて、大切[たいせつ]にしようと思[おも]った。", "sentence_source": "generated"}, {"text": "ことわざの由来を知ると、意味がよく分かる。", "target_word": "由来", "complexity_tier": "T3", "furigana": "ことわざの由来[ゆらい]を知[し]ると、意味[いみ]がよく分[わ]かる。", "sentence_source": "generated"}, {"text": "この木の名前の由来は、葉の形にあるそうだ。", "target_word": "由来", "complexity_tier": "T3", "furigana": "この木[き]の名前[なまえ]の由来[ゆらい]は、葉[は]の形[かたち]にあるそうだ。", "sentence_source": "generated"}, {"text": "絵本には、この町の祭りの由来が分かりやすく書かれている。", "target_word": "由来", "complexity_tier": "T3", "furigana": "絵本[えほん]には、この町[まち]の祭[まつ]りの由来[ゆらい]が分[わ]かりやすく書[か]かれている。", "sentence_source": "generated"}, {"text": "由来のはっきりしない言い伝えは、地域によって話が違うことが多い。", "target_word": "由来", "complexity_tier": "T3", "furigana": "由来[ゆらい]のはっきりしない言い伝え[いいつたえ]は、地域[ちいき]によって話[はなし]が違[ちが]うことが多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "由来する", "label": "辞書形"}, {"form": "由来した", "label": "過去形"}, {"form": "由来して", "label": "て形"}, {"form": "由来の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "名前・品物・出来事が生まれたもとになった事情やいわれ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38674, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "由来", "is_correct": true, "explanation": "「面白い由来」は、名前の出どころの話として文に合う。"}, {"text": "衰退", "is_correct": false, "explanation": "「衰退」は勢いが弱まることで、「面白い衰退」は成り立たない。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつけることで、「面白い点火」は意味をなさない。"}, {"text": "撤去", "is_correct": false, "explanation": "「撤去」は取り除くことで、「面白い撤去」は意味をなさない。"}], "explanations": {"由来": "「面白い由来」は、名前の出どころの話として文に合う。", "衰退": "「衰退」は勢いが弱まることで、「面白い衰退」は成り立たない。", "点火": "「点火」は火をつけることで、「面白い点火」は意味をなさない。", "撤去": "「撤去」は取り除くことで、「面白い撤去」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "由来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "申し込みの由来は、来週末までだ。", "explanation": "ここは〈期限〉の意味。由来は物事の起こりや出どころで、締め切りの日は表さない。"}, {"text": "このパソコンの由来は、とても高い。", "explanation": "ここは〈性能〉の意味。由来は出どころを指すので、性能の高さは表さない。"}, {"text": "このかばんの由来は、三万円だった。", "explanation": "ここは〈値段〉の意味。由来は起こりを表すので、金額は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38674, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "由来", "is_correct": true, "explanation": "「ことわざの由来」はことわざの出どころを指し、知ると分かる内容に合う。"}, {"text": "改札", "is_correct": false, "explanation": "「改札」は駅で切符を確かめる場所のことで、ことわざの説明には合わない。"}, {"text": "燃料", "is_correct": false, "explanation": "「燃料」は燃やすもので、ことわざの話には合わない。"}, {"text": "衣装", "is_correct": false, "explanation": "「衣装」は服装のことで、ことわざとは結びつかない。"}], "explanations": {"由来": "「ことわざの由来」はことわざの出どころを指し、知ると分かる内容に合う。", "改札": "「改札」は駅で切符を確かめる場所のことで、ことわざの説明には合わない。", "燃料": "「燃料」は燃やすもので、ことわざの話には合わない。", "衣装": "「衣装」は服装のことで、ことわざとは結びつかない。"}, "sentence_index": 6, "correct_answer": "由来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱の由来は、深い青だ。", "explanation": "ここは〈色〉の意味。由来は出どころを指すので、色は表さない。"}, {"text": "この荷物の由来は、十キロだ。", "explanation": "ここは〈重さ〉の意味。由来は起こりを表すので、重さは表さない。"}, {"text": "この部屋の由来は、八畳だ。", "explanation": "ここは〈大きさ〉の意味。由来は出どころを表すので、広さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
