INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38675, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が起こったり、存在するようになったりするもと。", "primary_collocate": null, "pronunciation": "ゆらい", "ipa": "jɯɾai", "syllable_count": 3, "sentences": [{"text": "この野菜の香りは、土壌由来の成分によるものだ。", "target_word": "由来", "complexity_tier": "T3", "furigana": "この野菜[やさい]の香[か]りは、土壌由来[どじょうゆらい]の成分[せいぶん]によるものだ。", "sentence_source": "generated"}, {"text": "この神社の名前の由来は、近くを流れる川にあります。", "target_word": "由来", "complexity_tier": "T3", "furigana": "この神社[じんじゃ]の名前[なまえ]の由来[ゆらい]は、近[ちか]くを流[なが]れる川[かわ]にあります。", "sentence_source": "generated"}, {"text": "日本語には、中国語に由来する言葉がたくさんある。", "target_word": "由来", "complexity_tier": "T3", "furigana": "日本語[にほんご]には、中国語[ちゅうごくご]に由来[ゆらい]する言葉[ことば]がたくさんある。", "sentence_source": "generated"}, {"text": "祭りの由来を調べて、レポートにまとめた。", "target_word": "由来", "complexity_tier": "T3", "furigana": "祭[まつ]りの由来[ゆらい]を調[しら]べて、レポートにまとめた。", "sentence_source": "generated"}, {"text": "この料理は、江戸時代の屋台に由来すると言われている。", "target_word": "由来", "complexity_tier": "T3", "furigana": "この料理[りょうり]は、江戸時代[えどじだい]の屋台[やたい]に由来[ゆらい]すると言[い]われている。", "sentence_source": "generated"}, {"text": "地名の由来を知ると、町の歴史が見えてくる。", "target_word": "由来", "complexity_tier": "T3", "furigana": "地名[ちめい]の由来[ゆらい]を知[し]ると、町[まち]の歴史[れきし]が見[み]えてくる。", "sentence_source": "generated"}, {"text": "「ありがとう」という言葉の由来を、祖母が教えてくれた。", "target_word": "由来", "complexity_tier": "T3", "furigana": "「ありがとう」という言葉[ことば]の由来[ゆらい]を、祖母[そぼ]が教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "この習慣の由来は、はっきり分かっていない。", "target_word": "由来", "complexity_tier": "T3", "furigana": "この習慣[しゅうかん]の由来[ゆらい]は、はっきり分[わ]かっていない。", "sentence_source": "generated"}, {"text": "彼の名字の由来について、家族で話し合った。", "target_word": "由来", "complexity_tier": "T3", "furigana": "彼[かれ]の名字[みょうじ]の由来[ゆらい]について、家族[かぞく]で話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "校名の由来を、校長先生が入学式で話した。", "target_word": "由来", "complexity_tier": "T3", "furigana": "校名[こうめい]の由来[ゆらい]を、校長先生[こうちょうせんせい]が入学式[にゅうがくしき]で話[はな]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "由来する", "label": "辞書形"}, {"form": "由来した", "label": "過去形"}, {"form": "由来して", "label": "て形"}, {"form": "由来の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "言葉・習慣・料理などが、どこから来たかという起源・出どころ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38675, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "由来", "is_correct": true, "explanation": "「土壌由来」は土壌から生まれたものという意味で、文に合う。"}, {"text": "衰退", "is_correct": false, "explanation": "「衰退」は勢いが弱まることで、土壌を表す語としては成り立たない。"}, {"text": "解体", "is_correct": false, "explanation": "「土壌解体の」は意味をなさず、土壌の出どころを表さない。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつけることで、土壌の説明には使えない。"}], "explanations": {"由来": "「土壌由来」は土壌から生まれたものという意味で、文に合う。", "衰退": "「衰退」は勢いが弱まることで、土壌を表す語としては成り立たない。", "解体": "「土壌解体の」は意味をなさず、土壌の出どころを表さない。", "点火": "「点火」は火をつけることで、土壌の説明には使えない。"}, "sentence_index": 0, "correct_answer": "由来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このセーターの由来は、手触りのやわらかさだ。", "explanation": "ここは〈質感〉の意味。由来は起こりを表すので、手触りは表さない。"}, {"text": "この料理の由来は、なめらかな舌触りだ。", "explanation": "ここは〈食感〉の意味。由来は起こりを表すので、舌触りは表さない。"}, {"text": "この薬の由来は、すぐに表れる。", "explanation": "ここは〈効果〉の意味。由来は出どころを指すので、薬の働きが表れることは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38675, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "由来", "is_correct": true, "explanation": "「言葉の由来」は言葉の成り立ちを表し、教えてもらう内容に合う。"}, {"text": "修繕", "is_correct": false, "explanation": "「修繕」は壊れたものを直すことで、言葉には使わない。"}, {"text": "消灯", "is_correct": false, "explanation": "「消灯」は明かりを消すことで、言葉の説明とは合わない。"}, {"text": "出港", "is_correct": false, "explanation": "「出港」は船が港を離れることで、言葉の話には合わない。"}], "explanations": {"由来": "「言葉の由来」は言葉の成り立ちを表し、教えてもらう内容に合う。", "修繕": "「修繕」は壊れたものを直すことで、言葉には使わない。", "消灯": "「消灯」は明かりを消すことで、言葉の説明とは合わない。", "出港": "「出港」は船が港を離れることで、言葉の話には合わない。"}, "sentence_index": 6, "correct_answer": "由来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープの由来は、少し薄い。", "explanation": "ここは〈味〉の意味。由来は物事の出どころで、味の濃さは表さない。"}, {"text": "このクラスの由来は、三十人だ。", "explanation": "ここは〈人数〉の意味。由来は起こりを指すので、人の数は表さない。"}, {"text": "この金属の由来は、とても柔らかい。", "explanation": "ここは〈性質〉の意味。由来は物事の起こりを指すので、物の性質は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38675, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この踊りは、江戸時代の行事を由来する。", "corrected_sentence": "この踊りは、江戸時代の行事に由来する。", "error_description": "「由来する」は「〜に由来する」と使うので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38675, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この祭りの由来を作ると、楽しみ方が変わる。", "corrected_sentence": "この祭りの由来を知ると、楽しみ方が変わる。", "error_description": "「由来」は「知る」と組み合わせて使うので、「作る」は使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
