INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38676, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「糖に変わる」と、変化の結果を示す。"}, {"text": "を", "is_correct": false, "explanation": "「糖を変わります」は目的語を取る形になるが、「変わる」は目的語を取らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「糖と変わります」は相手や並列を示すが、変化の結果にはならないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「糖で変わります」は手段を示すが、変化の結果を表さないので合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。「糖に変わる」と、変化の結果を示す。", "を": "「糖を変わります」は目的語を取る形になるが、「変わる」は目的語を取らないので合わない。", "と": "「糖と変わります」は相手や並列を示すが、変化の結果にはならないので合わない。", "で": "「糖で変わります」は手段を示すが、変化の結果を表さないので合わない。"}, "error_tags": {"を": "目的語を示す助詞", "と": "並列・相手を示す助詞", "で": "手段・場所を示す助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38676, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あまいもののなかま。砂糖やくだものには、あまい味があります。", "primary_collocate": null, "pronunciation": "とう", "ipa": "toː", "syllable_count": 2, "sentences": [{"text": "砂糖やはちみつは、糖のなかまです。", "target_word": "糖", "complexity_tier": "T3", "furigana": "砂糖[さとう]やはちみつは、糖[とう]のなかまです。", "sentence_source": "generated"}, {"text": "あまい味のもとは、たいてい糖の一種です。", "target_word": "糖", "complexity_tier": "T3", "furigana": "あまい味[あじ]のもとは、たいてい糖[とう]の一種[いっしゅ]です。", "sentence_source": "generated"}, {"text": "糖は、あまい味がするもののなかまの名前です。", "target_word": "糖", "complexity_tier": "T3", "furigana": "糖[とう]は、あまい味[あじ]がするもののなかまの名前[なまえ]です。", "sentence_source": "generated"}, {"text": "理科の時間に、糖とは何かを習いました。", "target_word": "糖", "complexity_tier": "T3", "furigana": "理科[りか]の時間[じかん]に、糖[とう]とは何[なに]かを習[なら]いました。", "sentence_source": "generated"}, {"text": "くだものには、いろいろな種類の糖があります。", "target_word": "糖", "complexity_tier": "T3", "furigana": "くだものには、いろいろな種類[しゅるい]の糖[とう]があります。", "sentence_source": "generated"}, {"text": "この本は、糖の種類をわかりやすく説明しています。", "target_word": "糖", "complexity_tier": "T3", "furigana": "この本[ほん]は、糖[とう]の種類[しゅるい]をわかりやすく説明[せつめい]しています。", "sentence_source": "generated"}, {"text": "先生は「あまいものは、たいてい糖の仲間だ」と言いました。", "target_word": "糖", "complexity_tier": "T3", "furigana": "先生[せんせい]は「あまいものは、たいてい糖[とう]の仲間[なかま]だ」と言[い]いました。", "sentence_source": "generated"}, {"text": "ごはんもパンも、体の中で糖に変わります。", "target_word": "糖", "complexity_tier": "T3", "furigana": "ごはんもパンも、体[からだ]の中[なか]で糖[とう]に変[か]わります。", "sentence_source": "generated"}, {"text": "あまい味がしないものは、糖の仲間ではありません。", "target_word": "糖", "complexity_tier": "T3", "furigana": "あまい味[あじ]がしないものは、糖[とう]の仲間[なかま]ではありません。", "sentence_source": "generated"}, {"text": "糖の仲間は、水にとけやすいものが多いです。", "target_word": "糖", "complexity_tier": "T3", "furigana": "糖[とう]の仲間[なかま]は、水[みず]にとけやすいものが多[おお]いです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "糖", "label": "基本形"}], "register": "polite", "sense_fingerprint": "あまい味のもとになるものの種類・なかま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38676, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "糖", "is_correct": true, "explanation": "正解。砂糖やはちみつが仲間とする、あまい味のもとの種類を指す語。"}, {"text": "塩", "is_correct": false, "explanation": "塩はしょっぱい味のもとで、砂糖やはちみつのなかまではないので合わない。"}, {"text": "油", "is_correct": false, "explanation": "油はあぶらの仲間で、砂糖やはちみつのなかまとは言えないので合わない。"}, {"text": "酢", "is_correct": false, "explanation": "酢はすっぱい味のもとで、砂糖やはちみつのなかまではないので合わない。"}], "explanations": {"糖": "正解。砂糖やはちみつが仲間とする、あまい味のもとの種類を指す語。", "塩": "塩はしょっぱい味のもとで、砂糖やはちみつのなかまではないので合わない。", "油": "油はあぶらの仲間で、砂糖やはちみつのなかまとは言えないので合わない。", "酢": "酢はすっぱい味のもとで、砂糖やはちみつのなかまではないので合わない。"}, "sentence_index": 0, "correct_answer": "糖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糖は、料理に入れると味がしょっぱくなります。", "explanation": "ここは〈塩〉の意味。糖はあまい味のもとで、しょっぱくはならないので合わない。"}, {"text": "糖は、料理にすっぱい味を加えます。", "explanation": "ここは〈酢〉の意味。糖はすっぱい味を出すものではないので合わない。"}, {"text": "糖は、料理を揚げるために使います。", "explanation": "ここは〈油〉の意味。糖は揚げ物に使う材料ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38676, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "糖", "is_correct": true, "explanation": "正解。「あまいものの仲間」として文の内容に合う語。"}, {"text": "水", "is_correct": false, "explanation": "水はあまいものの仲間ではないので、「たいてい水の仲間だ」は文に合わない。"}, {"text": "酸素", "is_correct": false, "explanation": "酸素は気体で、あまいものの仲間ではないので合わない。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は金属で、あまい味のもとではないので合わない。"}], "explanations": {"糖": "正解。「あまいものの仲間」として文の内容に合う語。", "水": "水はあまいものの仲間ではないので、「たいてい水の仲間だ」は文に合わない。", "酸素": "酸素は気体で、あまいものの仲間ではないので合わない。", "鉄": "鉄は金属で、あまい味のもとではないので合わない。"}, "sentence_index": 6, "correct_answer": "糖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "糖は、紙に字を書くインクです。", "explanation": "ここは〈インク〉の意味。糖は字を書く液体ではないので合わない。"}, {"text": "糖は、床をみがいてつやを出すワックスです。", "explanation": "ここは〈ワックス〉の意味。糖は床に塗ってつやを出すものではないので合わない。"}, {"text": "糖は、タイヤを作るゴムの材料です。", "explanation": "ここは〈ゴム〉の意味。糖はタイヤの材料にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38676, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "さとうきびには、糖を多く含まれています。", "corrected_sentence": "さとうきびには、糖が多く含まれています。", "error_description": "「含まれる」は主語を「が」で示すので、「糖を」は誤り。「糖が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
