INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38677, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「糖が入る」と、入るものを主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「糖をたくさん入っています」は「入る」の目的語にならず、不自然で合わないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「糖でたくさん入っています」は手段を示すので、入るものの主語にはならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「糖とたくさん入っています」は並列の意味になり、主語を示さないので合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「糖が入る」と、入るものを主語として示す。", "を": "「糖をたくさん入っています」は「入る」の目的語にならず、不自然で合わないので合わない。", "で": "「糖でたくさん入っています」は手段を示すので、入るものの主語にはならないので合わない。", "と": "「糖とたくさん入っています」は並列の意味になり、主語を示さないので合わない。"}, "error_tags": {"を": "目的語を示す助詞", "で": "手段・場所を示す助詞", "と": "並列・相手を示す助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
