INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38677, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物からとれる、あまい味がする物質。体のエネルギーになる。", "primary_collocate": null, "pronunciation": "とう", "ipa": "toː", "syllable_count": 2, "sentences": [{"text": "糖は体のエネルギーになります。", "target_word": "糖", "complexity_tier": "T3", "furigana": "糖[とう]は体[からだ]のエネルギーになります。", "sentence_source": "generated"}, {"text": "果物には糖がたくさん入っています。", "target_word": "糖", "complexity_tier": "T3", "furigana": "果物[くだもの]には糖[とう]がたくさん入[はい]っています。", "sentence_source": "generated"}, {"text": "サトウキビから糖をとります。", "target_word": "糖", "complexity_tier": "T3", "furigana": "サトウキビから糖[とう]をとります。", "sentence_source": "generated"}, {"text": "運動のあとは、糖をとると元気になります。", "target_word": "糖", "complexity_tier": "T3", "furigana": "運動[うんどう]のあとは、糖[とう]をとると元気[げんき]になります。", "sentence_source": "generated"}, {"text": "糖をとりすぎると、体に良くありません。", "target_word": "糖", "complexity_tier": "T3", "furigana": "糖[とう]をとりすぎると、体[からだ]に良[よ]くありません。", "sentence_source": "generated"}, {"text": "脳は、糖をエネルギーにして働きます。", "target_word": "糖", "complexity_tier": "T3", "furigana": "脳[のう]は、糖[とう]をエネルギーにして働[はたら]きます。", "sentence_source": "generated"}, {"text": "このジュースは、糖の量が少ないです。", "target_word": "糖", "complexity_tier": "T3", "furigana": "このジュースは、糖[とう]の量[りょう]が少[すく]ないです。", "sentence_source": "generated"}, {"text": "植物は、光を使って糖を作ります。", "target_word": "糖", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は、光[ひかり]を使[つか]って糖[とう]を作[つく]ります。", "sentence_source": "generated"}, {"text": "糖が足りないと、頭がぼんやりします。", "target_word": "糖", "complexity_tier": "T3", "furigana": "糖[とう]が足[た]りないと、頭[あたま]がぼんやりします。", "sentence_source": "generated"}, {"text": "医者に、糖を減らすように言われました。", "target_word": "糖", "complexity_tier": "T3", "furigana": "医者[いしゃ]に、糖[とう]を減[へ]らすように言[い]われました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "糖", "label": "基本形"}], "register": "polite", "sense_fingerprint": "植物にある、あまくて体のエネルギーになる物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38677, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "糖", "is_correct": true, "explanation": "正解。あまくて体のエネルギーになる物質として定義されている語。"}, {"text": "水", "is_correct": false, "explanation": "水は体の材料にはなるが、エネルギー源ではないので合わない。"}, {"text": "塩", "is_correct": false, "explanation": "塩はエネルギー源ではないので、体のエネルギーになるとは言えないので合わない。"}, {"text": "ビタミン", "is_correct": false, "explanation": "ビタミンは体の調子を整える栄養素で、エネルギーにはならないので合わない。"}], "explanations": {"糖": "正解。あまくて体のエネルギーになる物質として定義されている語。", "水": "水は体の材料にはなるが、エネルギー源ではないので合わない。", "塩": "塩はエネルギー源ではないので、体のエネルギーになるとは言えないので合わない。", "ビタミン": "ビタミンは体の調子を整える栄養素で、エネルギーにはならないので合わない。"}, "sentence_index": 0, "correct_answer": "糖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糖は、手についた汚れを落とす石けんです。", "explanation": "ここは〈石けん〉の意味。糖は汚れを落とすものではないので合わない。"}, {"text": "糖は、字を書いたり絵をかいたりする紙です。", "explanation": "ここは〈紙〉の意味。糖は書いたり描いたりするものではないので合わない。"}, {"text": "糖は、外の光を通すガラスです。", "explanation": "ここは〈ガラス〉の意味。糖は光を通す素材ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38677, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "糖", "is_correct": true, "explanation": "正解。「このジュースの糖の量」として文に合う語。"}, {"text": "色", "is_correct": false, "explanation": "色は量で数える対象ではないので、「色の量」は文に合わない。"}, {"text": "形", "is_correct": false, "explanation": "形は量を表す語ではないので、文に合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢はジュースの量を表す語ではないので、文に合わない。"}], "explanations": {"糖": "正解。「このジュースの糖の量」として文に合う語。", "色": "色は量で数える対象ではないので、「色の量」は文に合わない。", "形": "形は量を表す語ではないので、文に合わない。", "年齢": "年齢はジュースの量を表す語ではないので、文に合わない。"}, "sentence_index": 6, "correct_answer": "糖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "糖は、雨風から家を守る屋根の材料です。", "explanation": "ここは〈屋根材〉の意味。糖は建物の屋根に使う材料ではないので合わない。"}, {"text": "糖は、寒い冬に部屋を暖める暖房器具です。", "explanation": "ここは〈暖房器具〉の意味。糖は部屋を暖める道具ではないので合わない。"}, {"text": "糖は、体を守る免疫を高めるたんぱく質です。", "explanation": "ここは〈たんぱく質〉の意味。糖は免疫を高めるたんぱく質とは別のものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
