INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38678, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを作ること。", "primary_collocate": null, "pronunciation": "ごうせい", "ipa": "ɡoːseː", "syllable_count": 4, "sentences": [{"text": "二つの写真を合成して、一枚にしました。", "target_word": "合成", "complexity_tier": "T3", "furigana": "二[ふた]つの写真[しゃしん]を合成[ごうせい]して、一枚[いちまい]にしました。", "sentence_source": "generated"}, {"text": "この画像は合成だと、すぐにわかりました。", "target_word": "合成", "complexity_tier": "T3", "furigana": "この画像[がぞう]は合成[ごうせい]だと、すぐにわかりました。", "sentence_source": "generated"}, {"text": "声を合成する技術が進んでいます。", "target_word": "合成", "complexity_tier": "T3", "furigana": "声[こえ]を合成[ごうせい]する技術[ぎじゅつ]が進[すす]んでいます。", "sentence_source": "generated"}, {"text": "合成した音声は、まだ少し機械のように聞こえます。", "target_word": "合成", "complexity_tier": "T3", "furigana": "合成[ごうせい]した音声[おんせい]は、まだ少[すこ]し機械[きかい]のように聞[き]こえます。", "sentence_source": "generated"}, {"text": "彼は写真を合成して、友達をおどろかせました。", "target_word": "合成", "complexity_tier": "T3", "furigana": "彼[かれ]は写真[しゃしん]を合成[ごうせい]して、友達[ともだち]をおどろかせました。", "sentence_source": "generated"}, {"text": "いくつかの音を合成すると、新しい音ができます。", "target_word": "合成", "complexity_tier": "T3", "furigana": "いくつかの音[おと]を合成[ごうせい]すると、新[あたら]しい音[おと]ができます。", "sentence_source": "generated"}, {"text": "色を合成して、新しい色を作りました。", "target_word": "合成", "complexity_tier": "T3", "furigana": "色[いろ]を合成[ごうせい]して、新[あたら]しい色[いろ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "この動画には、合成された映像が使われています。", "target_word": "合成", "complexity_tier": "T3", "furigana": "この動画[どうが]には、合成[ごうせい]された映像[えいぞう]が使[つか]われています。", "sentence_source": "generated"}, {"text": "合成の仕方を、先生に教えてもらいました。", "target_word": "合成", "complexity_tier": "T3", "furigana": "合成[ごうせい]の仕方[しかた]を、先生[せんせい]に教[おし]えてもらいました。", "sentence_source": "generated"}, {"text": "本物に見えても、合成かもしれません。", "target_word": "合成", "complexity_tier": "T3", "furigana": "本物[ほんもの]に見[み]えても、合成[ごうせい]かもしれません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "合成する", "label": "辞書形"}, {"form": "合成した", "label": "過去形"}, {"form": "合成される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "写真や音など、複数のものを合わせて一つのものを作ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: おどろか (Zipf 1.65)']::text[], '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38678, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合成", "is_correct": true, "explanation": "写真を組み合わせて一枚にする意味で、空所に入る。"}, {"text": "分解", "is_correct": false, "explanation": "写真を分解しても一枚にはならず、二つを一枚にする文の内容と合わない。"}, {"text": "切断", "is_correct": false, "explanation": "写真を切り離す意味で、二つを一枚にする文脈と逆になる。"}, {"text": "発芽", "is_correct": false, "explanation": "芽が出る意味で、写真には使えない。"}], "explanations": {"合成": "写真を組み合わせて一枚にする意味で、空所に入る。", "分解": "写真を分解しても一枚にはならず、二つを一枚にする文の内容と合わない。", "切断": "写真を切り離す意味で、二つを一枚にする文脈と逆になる。", "発芽": "芽が出る意味で、写真には使えない。"}, "sentence_index": 0, "correct_answer": "合成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は来週のテストの問題を合成しました。", "explanation": "ここは〈作成〉の意味。合成は既にある複数のものを合わせる意味なので、問題を新しく書く場面には合わない。"}, {"text": "二つの会社が合成して、一つの会社になりました。", "explanation": "ここは〈合併〉の意味。合成は物や素材を組み合わせる意味で、会社が一つになる場面には使わない。"}, {"text": "作家は夜通し、新しい短編小説を合成していた。", "explanation": "ここは〈創作〉の意味。合成は既存の要素を組み合わせる意味で、物語を一から生み出す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38678, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合成", "is_correct": true, "explanation": "色を混ぜ合わせて新しい色を作る意味で、空所に入る。"}, {"text": "発酵", "is_correct": false, "explanation": "微生物のはたらきで物を変える現象で、色を混ぜる文とは合わない。"}, {"text": "凝固", "is_correct": false, "explanation": "液体が固まる意味で、色を混ぜて新しい色を作る場面に合わない。"}, {"text": "配送", "is_correct": false, "explanation": "品物を届ける意味で、色には使えない。"}], "explanations": {"合成": "色を混ぜ合わせて新しい色を作る意味で、空所に入る。", "発酵": "微生物のはたらきで物を変える現象で、色を混ぜる文とは合わない。", "凝固": "液体が固まる意味で、色を混ぜて新しい色を作る場面に合わない。", "配送": "品物を届ける意味で、色には使えない。"}, "sentence_index": 6, "correct_answer": "合成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い本を合成して、ページごとにばらばらにしました。", "explanation": "ここは〈分解〉の意味。合成は複数のものを組み合わせる意味なので、ばらばらに分ける場面では使えない。"}, {"text": "費用を合成すると、全部で三万円になります。", "explanation": "ここは〈合計〉の意味。合成は物を組み合わせて作る意味で、数を足す場面には使えない。"}, {"text": "たくさんの服から合成して、一着選びました。", "explanation": "ここは〈選択〉の意味。合成は組み合わせて新しく作ることで、候補の中から選ぶ場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38678, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三枚の写真を合成に、一枚にしました。", "corrected_sentence": "三枚の写真を合成して、一枚にしました。", "error_description": "合成の直後に「に」を付けたのが誤り。「合成する」のて形「合成して」にして「一枚にしました」につなぐ必要がある。「合成に」では文が続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38678, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い映像と新しい映像を合成られて、一つの動画にしました。", "corrected_sentence": "古い映像と新しい映像を合成して、一つの動画にしました。", "error_description": "「合成する」の活用の誤り。「合成られて」という形はない。正しくはて形の「合成して」。「合成される」は受身で、この文の内容には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38679, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "化学の意味での合成の対義語。組み立てて物質を作ることの反対に、物質をばらすことを表す。"}, {"text": "抽出", "is_correct": false, "explanation": "材料から成分を取り出す意味で、合成の対義語としては載っていない。"}, {"text": "粉砕", "is_correct": false, "explanation": "かたいものを細かく砕く意味で、合成との対義関係はない。"}, {"text": "発酵", "is_correct": false, "explanation": "微生物のはたらきで物質を変える意味で、合成の対義語ではない。"}], "correct_answer": "分解", "explanations": {"分解": "化学の意味での合成の対義語。組み立てて物質を作ることの反対に、物質をばらすことを表す。", "抽出": "材料から成分を取り出す意味で、合成の対義語としては載っていない。", "粉砕": "かたいものを細かく砕く意味で、合成との対義関係はない。", "発酵": "微生物のはたらきで物質を変える意味で、合成の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38679, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜に成功する」の形で、目的を表す「に」が「合成」に付く。"}, {"text": "を", "is_correct": false, "explanation": "「成功」は「に」を取る語なので、「合成を成功」とは言えない。"}, {"text": "の", "is_correct": false, "explanation": "「合成の成功」は名詞同士の結びつきで、「成功しました」と続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「成功」と結びつかず、「合成へ成功」は誤り。"}], "correct_answer": "に", "explanations": {"に": "「〜に成功する」の形で、目的を表す「に」が「合成」に付く。", "を": "「成功」は「に」を取る語なので、「合成を成功」とは言えない。", "の": "「合成の成功」は名詞同士の結びつきで、「成功しました」と続かない。", "へ": "方向を表す「へ」は「成功」と結びつかず、「合成へ成功」は誤り。"}, "error_tags": {"を": "目的語", "の": "所有・修飾", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "化学の意味での合成の対義語。組み立てて物質を作ることの反対に、物質をばらすことを表す。"}, {"text": "解凍", "is_correct": false, "explanation": "凍った物を溶かす意味で、合成の対義語ではない。"}, {"text": "切除", "is_correct": false, "explanation": "体の一部を取り除く意味で、合成との対義関係はない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分を取り除く意味で、合成の対義語ではない。"}], "correct_answer": "分解", "explanations": {"分解": "化学の意味での合成の対義語。組み立てて物質を作ることの反対に、物質をばらすことを表す。", "解凍": "凍った物を溶かす意味で、合成の対義語ではない。", "切除": "体の一部を取り除く意味で、合成との対義関係はない。", "乾燥": "水分を取り除く意味で、合成の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38679, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "材料や原料を組み合わせて、一つのものを作り出すこと。", "primary_collocate": null, "pronunciation": "ごうせい", "ipa": "ɡoːseː", "syllable_count": 4, "sentences": [{"text": "工場では、原料を合成して薬を作ります。", "target_word": "合成", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、原料[げんりょう]を合成[ごうせい]して薬[くすり]を作[つく]ります。", "sentence_source": "generated"}, {"text": "植物は光を使って養分を合成します。", "target_word": "合成", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は光[ひかり]を使[つか]って養分[ようぶん]を合成[ごうせい]します。", "sentence_source": "generated"}, {"text": "二つの物質を合成すると、新しい物ができます。", "target_word": "合成", "complexity_tier": "T3", "furigana": "二[ふた]つの物質[ぶっしつ]を合成[ごうせい]すると、新[あたら]しい物[もの]ができます。", "sentence_source": "generated"}, {"text": "この薬は、研究室で合成されました。", "target_word": "合成", "complexity_tier": "T3", "furigana": "この薬[くすり]は、研究室[けんきゅうしつ]で合成[ごうせい]されました。", "sentence_source": "generated"}, {"text": "化学の実験で、水素と窒素からアンモニアを合成しました。", "target_word": "合成", "complexity_tier": "T3", "furigana": "化学[かがく]の実験[じっけん]で、水素[すいそ]と窒素[ちっそ]からアンモニアを合成[ごうせい]しました。", "sentence_source": "generated"}, {"text": "合成によって、自然にはない物質が作られます。", "target_word": "合成", "complexity_tier": "T3", "furigana": "合成[ごうせい]によって、自然[しぜん]にはない物質[ぶっしつ]が作[つく]られます。", "sentence_source": "generated"}, {"text": "石油から合成した材料が、服に使われています。", "target_word": "合成", "complexity_tier": "T3", "furigana": "石油[せきゆ]から合成[ごうせい]した材料[ざいりょう]が、服[ふく]に使[つか]われています。", "sentence_source": "generated"}, {"text": "研究者は、新しい物質の合成に成功しました。", "target_word": "合成", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、新[あたら]しい物質[ぶっしつ]の合成[ごうせい]に成功[せいこう]しました。", "sentence_source": "generated"}, {"text": "人の体は、ビタミンCを自分で合成できません。", "target_word": "合成", "complexity_tier": "T3", "furigana": "人[ひと]の体[からだ]は、ビタミンCを自分[じぶん]で合成[ごうせい]できません。", "sentence_source": "generated"}, {"text": "合成の方法を変えると、できる物も変わります。", "target_word": "合成", "complexity_tier": "T3", "furigana": "合成[ごうせい]の方法[ほうほう]を変[か]えると、できる物[もの]も変[か]わります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "合成する", "label": "辞書形"}, {"form": "合成した", "label": "過去形"}, {"form": "合成される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "原料を化学的に組み合わせて物質を作り出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38679, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合成", "is_correct": true, "explanation": "原料を組み合わせて薬を作る意味で、空所に入る。"}, {"text": "発芽", "is_correct": false, "explanation": "種や球根から芽が出る意味で、原料から薬を作る文には合わない。"}, {"text": "配送", "is_correct": false, "explanation": "品物を届ける意味で、原料から薬を作る工程とは合わない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、原料を薬に変える文脈には当てはまらない。"}], "explanations": {"合成": "原料を組み合わせて薬を作る意味で、空所に入る。", "発芽": "種や球根から芽が出る意味で、原料から薬を作る文には合わない。", "配送": "品物を届ける意味で、原料から薬を作る工程とは合わない。", "点火": "火をつける意味で、原料を薬に変える文脈には当てはまらない。"}, "sentence_index": 0, "correct_answer": "合成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この写真は、二人の顔を合成したものです。", "explanation": "ここは〈画像の加工〉の意味。写真を組み合わせる場面で、原料を化学的に組み合わせる合成とは別の意味になる。"}, {"text": "この歌手は、複数の音を合成して、新しい曲を作りました。", "explanation": "ここは〈音の重ね合わせ〉の意味。音を組み合わせる場面で、化学的に物質を作る合成とは別の意味になる。"}, {"text": "二つの動画を合成して、一つの映像にしました。", "explanation": "ここは〈映像の加工〉の意味。映像を組み合わせる場面で、原料を化学的に組み合わせる合成とは別の意味になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38679, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合成", "is_correct": true, "explanation": "石油を化学的に組み合わせて材料を作る意味で、空所に入る。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける意味で、石油から材料を作る文には合わない。"}, {"text": "開演", "is_correct": false, "explanation": "舞台が始まる意味で、材料の話には使えない。"}, {"text": "演奏", "is_correct": false, "explanation": "楽器で音楽を奏でる意味で、石油から材料を作る文脈には合わない。"}], "explanations": {"合成": "石油を化学的に組み合わせて材料を作る意味で、空所に入る。", "採点": "点数をつける意味で、石油から材料を作る文には合わない。", "開演": "舞台が始まる意味で、材料の話には使えない。", "演奏": "楽器で音楽を奏でる意味で、石油から材料を作る文脈には合わない。"}, "sentence_index": 6, "correct_answer": "合成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水を合成して、水素と酸素に分けました。", "explanation": "ここは〈分解〉の意味。合成は材料を組み合わせて物を作る意味で、一つの物質を成分に分ける場面には使えない。"}, {"text": "この雑誌は、二枚の絵を合成して、表紙にしました。", "explanation": "ここは〈画像の加工〉の意味。絵を組み合わせる場面で、化学的に物質を作る合成とは別の意味になる。"}, {"text": "コーヒーの粉を合成して、かすを取り除きました。", "explanation": "ここは〈ろ過〉の意味。合成は組み合わせて作る意味で、混ざった物から不要な物を取り除く場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38679, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三種類の原料を合成に、新しい薬を作ります。", "corrected_sentence": "三種類の原料を合成して、新しい薬を作ります。", "error_description": "「合成」の直後に「に」を置いたのが誤り。て形「合成して」にして「薬を作ります」につなぐ必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38679, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、新しい原料を合成られて、薬を作る方法を研究しています。", "corrected_sentence": "研究者は、新しい原料を合成して、薬を作る方法を研究しています。", "error_description": "「合成する」の活用の誤り。「合成られて」という形はない。正しくはて形の「合成して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
