INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38680, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "親から子へ、体の特徴が伝わること。", "primary_collocate": null, "pronunciation": "いでん", "ipa": "ideɴ", "syllable_count": 3, "sentences": [{"text": "目の色は、親から遺伝します。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "目[め]の色[いろ]は、親[おや]から遺伝[いでん]します。", "sentence_source": "generated"}, {"text": "背の高さは、遺伝だけで決まるわけではありません。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "背[せ]の高[たか]さは、遺伝[いでん]だけで決[き]まるわけではありません。", "sentence_source": "generated"}, {"text": "父の髪の色が、私に遺伝しました。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "父[ちち]の髪[かみ]の色[いろ]が、私[わたし]に遺伝[いでん]しました。", "sentence_source": "generated"}, {"text": "母に似た顔は、遺伝のせいかもしれません。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "母[はは]に似[に]た顔[かお]は、遺伝[いでん]のせいかもしれません。", "sentence_source": "generated"}, {"text": "兄も私も、親の足の速さが遺伝しました。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "兄[あに]も私[わたし]も、親[おや]の足[あし]の速[はや]さが遺伝[いでん]しました。", "sentence_source": "generated"}, {"text": "この病気は、子に遺伝することがあります。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "この病気[びょうき]は、子[こ]に遺伝[いでん]することがあります。", "sentence_source": "generated"}, {"text": "遺伝のおかげで、弟は父そっくりの声です。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "遺伝[いでん]のおかげで、弟[おとうと]は父[ちち]そっくりの声[こえ]です。", "sentence_source": "generated"}, {"text": "親の特徴が子に遺伝するのは、自然なことです。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "親[おや]の特徴[とくちょう]が子[こ]に遺伝[いでん]するのは、自然[しぜん]なことです。", "sentence_source": "generated"}, {"text": "髪のくせは遺伝だと、医者に言われました。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "髪[かみ]のくせは遺伝[いでん]だと、医者[いしゃ]に言[い]われました。", "sentence_source": "generated"}, {"text": "この双子は、遺伝の影響で顔つきがよく似ています。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "この双子[ふたご]は、遺伝[いでん]の影響[えいきょう]で顔つき[かおつき]がよく似[に]ています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遺伝する", "label": "辞書形"}, {"form": "遺伝した", "label": "過去形"}, {"form": "遺伝して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "親の体の特徴が子に伝わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38680, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遺伝", "is_correct": true, "explanation": "親から子へ体の特徴が伝わる意味で、空所に入る。"}, {"text": "誕生", "is_correct": false, "explanation": "生まれる意味で、「親から」と続けると目の色の文として不自然。"}, {"text": "反省", "is_correct": false, "explanation": "自分の行いを省みる意味で、目の色の話には合わない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解く意味で、目の色が親から伝わる文脈には合わない。"}], "explanations": {"遺伝": "親から子へ体の特徴が伝わる意味で、空所に入る。", "誕生": "生まれる意味で、「親から」と続けると目の色の文として不自然。", "反省": "自分の行いを省みる意味で、目の色の話には合わない。", "解散": "集まりを解く意味で、目の色が親から伝わる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "遺伝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は、長男が親から遺伝して、今も続いている。", "explanation": "ここは〈継承〉の意味。店や地位を受け継ぐ場面で、遺伝は生き物の性質が親から子へ伝わることなので合わない。"}, {"text": "この風邪は、家族に遺伝しやすいので注意が必要だ。", "explanation": "ここは〈伝染〉の意味。病原体が人から人へうつる場面で、遺伝は親の性質が子に伝わることなので合わない。"}, {"text": "この踊りは、昔から村に遺伝されている。", "explanation": "ここは〈伝承〉の意味。言い伝えや文化を次の世代へ受け継ぐ場面で、遺伝は体の性質の伝わりを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38680, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遺伝", "is_correct": true, "explanation": "親から特徴が伝わる意味で、父の声に似る理由として自然に入る。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける意味で、声が似る理由としては成り立たない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、弟の声が父に似る理由にはならない。"}, {"text": "脱税", "is_correct": false, "explanation": "税金を逃れる意味で、声の話と結びつかない。"}], "explanations": {"遺伝": "親から特徴が伝わる意味で、父の声に似る理由として自然に入る。", "採点": "点数をつける意味で、声が似る理由としては成り立たない。", "点火": "火をつける意味で、弟の声が父に似る理由にはならない。", "脱税": "税金を逃れる意味で、声の話と結びつかない。"}, "sentence_index": 6, "correct_answer": "遺伝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究者は、古い町の遺伝を発掘しました。", "explanation": "ここは〈遺跡〉の意味。昔の町の跡を指す場面で、親から子へ伝わる体の特徴の遺伝は合わない。"}, {"text": "毎朝走るのが遺伝して、体が丈夫になりました。", "explanation": "ここは〈習慣〉の意味。身についた行動の繰り返しを指す場面で、親から子へ伝わる体の特徴の遺伝は合わない。"}, {"text": "祖父の遺伝には、家を売ると書かれていました。", "explanation": "ここは〈遺言〉の意味。死後の意思を書いた文書を指す場面で、体の特徴が子に伝わる遺伝は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38680, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この体質は、母から娘へ遺伝れます。", "corrected_sentence": "この体質は、母から娘へ遺伝します。", "error_description": "「遺伝する」はサ変動詞で、丁寧形は「遺伝します」。「遺伝れます」は存在しない活用で、「れます」を付けたのが誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38680, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この体質は、母から娘に遺伝でします。", "corrected_sentence": "この体質は、母から娘に遺伝します。", "error_description": "「遺伝」の直後に「で」を付けたのが誤り。「遺伝する」はそのまま「遺伝します」と続けるので、助詞は不要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
