INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38681, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生物の性質が親から子へと伝わるもとになるもの。これはDNAに書かれた情報であり、体の形や色、病気のかかりやすさなどを決める。", "primary_collocate": null, "pronunciation": "いでん", "ipa": "ideɴ", "syllable_count": 3, "sentences": [{"text": "遺伝の情報は、DNAに書かれています。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "遺伝[いでん]の情報[じょうほう]は、DNAに書[か]かれています。", "sentence_source": "generated"}, {"text": "花の色は、遺伝の働きで決まります。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "花[はな]の色[いろ]は、遺伝[いでん]の働[はたら]きで決[き]まります。", "sentence_source": "generated"}, {"text": "遺伝によって、親と子の体の形は似ます。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "遺伝[いでん]によって、親[おや]と子[こ]の体[からだ]の形[かたち]は似[に]ます。", "sentence_source": "generated"}, {"text": "研究者は、犬の毛の色を決める遺伝を調べました。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、犬[いぬ]の毛[け]の色[いろ]を決[き]める遺伝[いでん]を調[しら]べました。", "sentence_source": "generated"}, {"text": "遺伝の仕組みは、中学の理科で習います。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "遺伝[いでん]の仕組[しく]みは、中学[ちゅうがく]の理科[りか]で習[なら]います。", "sentence_source": "generated"}, {"text": "病気のかかりやすさも、遺伝と関係があります。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "病気[びょうき]のかかりやすさも、遺伝[いでん]と関係[かんけい]があります。", "sentence_source": "generated"}, {"text": "遺伝の情報は、細胞の中に入っています。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "遺伝[いでん]の情報[じょうほう]は、細胞[さいぼう]の中[なか]に入[はい]っています。", "sentence_source": "generated"}, {"text": "メンデルは、豆を使って遺伝の法則を見つけました。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "メンデルは、豆[まめ]を使[つか]って遺伝[いでん]の法則[ほうそく]を見[み]つけました。", "sentence_source": "generated"}, {"text": "遺伝に問題があると、体の働きが変わることがあります。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "遺伝[いでん]に問題[もんだい]があると、体[からだ]の働[はたら]きが変[か]わることがあります。", "sentence_source": "generated"}, {"text": "遺伝の研究で、新しい薬が作られるようになりました。", "target_word": "遺伝", "complexity_tier": "T3", "furigana": "遺伝[いでん]の研究[けんきゅう]で、新[あたら]しい薬[くすり]が作[つく]られるようになりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遺伝する", "label": "辞書形"}, {"form": "遺伝した", "label": "過去形"}, {"form": "遺伝して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "DNAに書かれた、性質が伝わるもとになる情報や仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38681, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遺伝", "is_correct": true, "explanation": "DNAに書かれた、性質を伝える情報を指すので、空所に入る。"}, {"text": "発芽", "is_correct": false, "explanation": "芽が出る意味で、DNAの情報とは合わない。"}, {"text": "配送", "is_correct": false, "explanation": "品物を届ける意味で、DNAに書かれた情報には使えない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解く意味で、DNAの情報には合わない。"}], "explanations": {"遺伝": "DNAに書かれた、性質を伝える情報を指すので、空所に入る。", "発芽": "芽が出る意味で、DNAの情報とは合わない。", "配送": "品物を届ける意味で、DNAに書かれた情報には使えない。", "解散": "集まりを解く意味で、DNAの情報には合わない。"}, "sentence_index": 0, "correct_answer": "遺伝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "研究者は、顕微鏡で遺伝を一つずつ数えました。", "explanation": "ここは〈遺伝子〉の意味。遺伝は仕組みや情報の名前で、一つずつ数える物ではないので合わない。"}, {"text": "彼は遺伝が弱く、季節の変わり目に風邪をひきやすい。", "explanation": "ここは〈体質〉の意味。体の弱さを指す場面で、遺伝はDNAの情報を指すので合わない。"}, {"text": "研究室では、培養した遺伝を毎日観察しています。", "explanation": "ここは〈細胞〉の意味。培養して観察するのは細胞で、遺伝は情報の仕組みなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38681, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遺伝", "is_correct": true, "explanation": "DNAに書かれた情報を指す意味で、細胞の中の情報の文に入る。"}, {"text": "反省", "is_correct": false, "explanation": "自分の行いを省みる意味で、細胞の中の情報とは合わない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、細胞の情報には使えない。"}, {"text": "脱税", "is_correct": false, "explanation": "税金を逃れる意味で、細胞の情報とは結びつかない。"}], "explanations": {"遺伝": "DNAに書かれた情報を指す意味で、細胞の中の情報の文に入る。", "反省": "自分の行いを省みる意味で、細胞の中の情報とは合わない。", "点火": "火をつける意味で、細胞の情報には使えない。", "脱税": "税金を逃れる意味で、細胞の情報とは結びつかない。"}, "sentence_index": 6, "correct_answer": "遺伝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この村では、遺伝の踊りを毎年、子どもたちが練習します。", "explanation": "ここは〈伝統〉の意味。代々受け継がれる文化や踊りを指す場面で、DNAに書かれた情報の遺伝は合わない。"}, {"text": "研究者は、古い町の遺伝を発掘しました。", "explanation": "ここは〈遺跡〉の意味。昔の町の跡を指す場面で、DNAに書かれた情報の遺伝は合わない。"}, {"text": "祖父の遺伝には、家を売ると書かれていました。", "explanation": "ここは〈遺言〉の意味。死後の意思を書いた文書を指す場面で、DNAに書かれた情報の遺伝は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38681, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遺伝に仕組みは、細胞の核の中にあります。", "corrected_sentence": "遺伝の仕組みは、細胞の核の中にあります。", "error_description": "「遺伝」の直後の助詞が誤り。「遺伝の仕組み」と名詞を修飾するには「の」が必要。「遺伝に仕組み」は「に」では名詞をつなげず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38681, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "DNAの情報は、細胞分裂のときに遺伝ります。", "corrected_sentence": "DNAの情報は、細胞分裂のときに遺伝します。", "error_description": "「遺伝する」はサ変動詞で、丁寧形は「遺伝します」。「遺伝ります」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38682, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す。「進め方を改変して」で、改変の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「進め方が改変して」では進め方が自ら変わる意味になり、改変の対象として合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や結果を示す。「進め方に改変して」では改変の対象が示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「進め方へ改変して」は意味をなさない。"}], "correct_answer": "を", "explanations": {"を": "対象を表す。「進め方を改変して」で、改変の目的語を示す。", "が": "主語を示すが、「進め方が改変して」では進め方が自ら変わる意味になり、改変の対象として合わない。", "に": "相手や結果を示す。「進め方に改変して」では改変の対象が示せない。", "へ": "方向を示す。「進め方へ改変して」は意味をなさない。"}, "error_tags": {"が": "主語", "に": "相手・結果", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38682, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す。「作り方を改変して」で、改変の目的語を示す。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、「作り方と改変して」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示すが、「作り方の改変して」では動詞の目的語が示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「作り方で改変して」は作り方を手段にする意味になり、文意に合わない。"}], "correct_answer": "を", "explanations": {"を": "対象を表す。「作り方を改変して」で、改変の目的語を示す。", "と": "並列や相手を示すが、「作り方と改変して」では文が成り立たない。", "の": "連体修飾を示すが、「作り方の改変して」では動詞の目的語が示せない。", "で": "手段や場所を示す。「作り方で改変して」は作り方を手段にする意味になり、文意に合わない。"}, "error_tags": {"と": "並列・相手", "の": "連体修飾", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38682, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを、もっとよくするために、変えること。", "primary_collocate": null, "pronunciation": "かいへん", "ipa": "kaiheɴ", "syllable_count": 4, "sentences": [{"text": "使いにくかったので、アプリの画面を改変した。", "target_word": "改変", "complexity_tier": "T3", "furigana": "使[つか]いにくかったので、アプリの画面[がめん]を改変[かいへん]した。", "sentence_source": "generated"}, {"text": "会社は仕事の進め方を改変して、残業を減らした。", "target_word": "改変", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は仕事[しごと]の進[すす]め方[かた]を改変[かいへん]して、残業[ざんぎょう]を減[へ]らした。", "sentence_source": "generated"}, {"text": "この規則は古いので、来年までに改変する予定だ。", "target_word": "改変", "complexity_tier": "T3", "furigana": "この規則[きそく]は古[ふる]いので、来年[らいねん]までに改変[かいへん]する予定[よてい]だ。", "sentence_source": "generated"}, {"text": "先生は授業の内容を改変し、生徒がもっと楽しめるようにした。", "target_word": "改変", "complexity_tier": "T3", "furigana": "先生[せんせい]は授業[じゅぎょう]の内容[ないよう]を改変[かいへん]し、生徒[せいと]がもっと楽[たの]しめるようにした。", "sentence_source": "generated"}, {"text": "町の古い制度を改変したおかげで、住民の負担が軽くなった。", "target_word": "改変", "complexity_tier": "T3", "furigana": "町[まち]の古[ふる]い制度[せいど]を改変[かいへん]したおかげで、住民[じゅうみん]の負担[ふたん]が軽[かる]くなった。", "sentence_source": "generated"}, {"text": "計画の改変には、チーム全員の意見が必要だった。", "target_word": "改変", "complexity_tier": "T3", "furigana": "計画[けいかく]の改変[かいへん]には、チーム全員[ぜんいん]の意見[いけん]が必要[ひつよう]だった。", "sentence_source": "generated"}, {"text": "店の入り口を改変した結果、お客さんが増えた。", "target_word": "改変", "complexity_tier": "T3", "furigana": "店[みせ]の入[い]り口[ぐち]を改変[かいへん]した結果[けっか]、お客[きゃく]さんが増[ふ]えた。", "sentence_source": "generated"}, {"text": "彼は料理の作り方を少し改変して、より軽い味にした。", "target_word": "改変", "complexity_tier": "T3", "furigana": "彼[かれ]は料理[りょうり]の作[つく]り方[かた]を少[すこ]し改変[かいへん]して、より軽[かる]い味[あじ]にした。", "sentence_source": "generated"}, {"text": "古いルールを改変しなければ、問題はなくならない。", "target_word": "改変", "complexity_tier": "T3", "furigana": "古[ふる]いルールを改変[かいへん]しなければ、問題[もんだい]はなくならない。", "sentence_source": "generated"}, {"text": "大きな改変ではなく、小さな改変を重ねて製品をよくした。", "target_word": "改変", "complexity_tier": "T3", "furigana": "大[おお]きな改変[かいへん]ではなく、小[ちい]さな改変[かいへん]を重[かさ]ねて製品[せいひん]をよくした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "改変", "label": "基本形"}, {"form": "改変する", "label": "終止形"}, {"form": "改変した", "label": "過去形"}, {"form": "改変して", "label": "て形"}, {"form": "改変される", "label": "受身形"}], "register": "書き言葉", "sense_fingerprint": "よりよくするために、仕組みや内容を変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38682, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改変", "is_correct": true, "explanation": "ここは「改変」。画面の内容や仕組みを変えるという意味で文に合う。"}, {"text": "予約", "is_correct": false, "explanation": "予約は日時や席を前もって取ることで、画面には使わない。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案に点をつけることで、画面には合わない。"}, {"text": "返却", "is_correct": false, "explanation": "返却は借りた物を返すことで、画面の変更には合わない。"}], "explanations": {"改変": "ここは「改変」。画面の内容や仕組みを変えるという意味で文に合う。", "予約": "予約は日時や席を前もって取ることで、画面には使わない。", "採点": "採点は答案に点をつけることで、画面には合わない。", "返却": "返却は借りた物を返すことで、画面の変更には合わない。"}, "sentence_index": 0, "correct_answer": "改変"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の会議は場所を改変したので、大会議室に移った。", "explanation": "ここは〈変更〉の意味。改変は内容や仕組みを作り変える語で、会議の場所のように別のものに替えるだけの場合は変更を使う。"}, {"text": "寝不足の体調を改変するため、早めに休んだ。", "explanation": "ここは〈改善〉の意味。改変は内容や形を変える語で、体調をよくする場合は改善や回復を使う。"}, {"text": "春の試験に合格して、新しい資格を改変した。", "explanation": "ここは〈取得〉の意味。資格や免許を新しく得る場合は取得を使う。改変は既にある内容や形を変える語で、新たに得ることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38682, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改変", "is_correct": true, "explanation": "ここは「改変」。店の入り口の構造を変えたという意味で文に合う。"}, {"text": "精算", "is_correct": false, "explanation": "精算は支払いを済ませることで、入り口には合わない。"}, {"text": "予告", "is_correct": false, "explanation": "予告は前もって知らせることで、入り口を変える意味にはならない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物を頼むことで、入り口には使わない。"}], "explanations": {"改変": "ここは「改変」。店の入り口の構造を変えたという意味で文に合う。", "精算": "精算は支払いを済ませることで、入り口には合わない。", "予告": "予告は前もって知らせることで、入り口を変える意味にはならない。", "注文": "注文は品物を頼むことで、入り口には使わない。"}, "sentence_index": 6, "correct_answer": "改変"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "文化財の壁画を改変して、元の色に戻した。", "explanation": "ここは〈修復〉の意味。傷んだものを元の状態に戻す場合は修復を使う。改変は内容や形を変えて作り直す語で、元に戻す意味はない。"}, {"text": "新しい辞書を作るため、言葉を集めて載せた。", "explanation": "ここは〈収録〉の意味。言葉を集めて書物に載せる場合は収録を使う。改変は既にある内容や形を変える語で、新しく集めて載せることには使わない。"}, {"text": "病気を改変して、早く治した。", "explanation": "ここは〈治療〉の意味。病気や怪我を治す場合は治療を使う。改変は内容や形を変える語で、病気を治すことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38682, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い仕組みが改変したので、手続きが早くなった。", "corrected_sentence": "古い仕組みを改変したので、手続きが早くなった。", "error_description": "誤り：「が」。改変は対象を「を」で示す語なので、「仕組みを改変した」が正しい。正しい助詞は「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38682, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "設計に改変を見せて、部屋を広くした。", "corrected_sentence": "設計に改変を加えて、部屋を広くした。", "error_description": "誤り：「見せて」。改変は「加える」と組み合わせて使うので、「改変を加えて」が正しい。正しい語は「加えて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38683, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す。「形を改変したので」で、改変の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「形が改変したので」では形が自ら変わる意味になり、改変の対象として合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、「形と改変したので」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「形へ改変したので」では改変の対象が示せない。"}], "correct_answer": "を", "explanations": {"を": "対象を表す。「形を改変したので」で、改変の目的語を示す。", "が": "主語を示すが、「形が改変したので」では形が自ら変わる意味になり、改変の対象として合わない。", "と": "並列や相手を示すが、「形と改変したので」では文が成り立たない。", "へ": "方向を示す。「形へ改変したので」では改変の対象が示せない。"}, "error_tags": {"が": "主語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38683, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す。「仕組みを改変する」で、改変の目的語を示す。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す。「仕組みで改変する」では改変の対象が示せず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "相手や結果を示す。「仕組みに改変する」では改変の対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を示す。「仕組みより改変する」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "対象を表す。「仕組みを改変する」で、改変の目的語を示す。", "で": "手段を示す。「仕組みで改変する」では改変の対象が示せず、文が成り立たない。", "に": "相手や結果を示す。「仕組みに改変する」では改変の対象を示せない。", "より": "比較や起点を示す。「仕組みより改変する」では意味が通らない。"}, "error_tags": {"で": "手段", "に": "相手・結果", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38683, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の内容や形を、より良いものに変えること。", "primary_collocate": null, "pronunciation": "かいへん", "ipa": "kaiheɴ", "syllable_count": 4, "sentences": [{"text": "古い校則の内容を改変し、生徒の意見も入れた。", "target_word": "改変", "complexity_tier": "T3", "furigana": "古[ふる]い校則[こうそく]の内容[ないよう]を改変[かいへん]し、生徒[せいと]の意見[いけん]も入[い]れた。", "sentence_source": "generated"}, {"text": "設計図の形を改変したので、機械が使いやすくなった。", "target_word": "改変", "complexity_tier": "T3", "furigana": "設計図[せっけいず]の形[かたち]を改変[かいへん]したので、機械[きかい]が使[つか]いやすくなった。", "sentence_source": "generated"}, {"text": "町はバス路線を改変して、駅までの時間を短くした。", "target_word": "改変", "complexity_tier": "T3", "furigana": "町[まち]はバス路線[ろせん]を改変[かいへん]して、駅[えき]までの時間[じかん]を短[みじか]くした。", "sentence_source": "generated"}, {"text": "脚本を改変した結果、物語がわかりやすくなった。", "target_word": "改変", "complexity_tier": "T3", "furigana": "脚本[きゃくほん]を改変[かいへん]した結果[けっか]、物語[ものがたり]がわかりやすくなった。", "sentence_source": "generated"}, {"text": "彼女は服の形を改変して、動きやすい服に作り直した。", "target_word": "改変", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は服[ふく]の形[かたち]を改変[かいへん]して、動[うご]きやすい服[ふく]に作[つく]り直[なお]した。", "sentence_source": "generated"}, {"text": "会議で、サービスの内容を改変する案が出た。", "target_word": "改変", "complexity_tier": "T3", "furigana": "会議[かいぎ]で、サービスの内容[ないよう]を改変[かいへん]する案[あん]が出[で]た。", "sentence_source": "generated"}, {"text": "去年の説明書は不評だったので、全面的に改変した。", "target_word": "改変", "complexity_tier": "T3", "furigana": "去年[きょねん]の説明書[せつめいしょ]は不評[ふひょう]だったので、全面的[ぜんめんてき]に改変[かいへん]した。", "sentence_source": "generated"}, {"text": "組織の仕組みを改変する前に、まず問題点を整理した。", "target_word": "改変", "complexity_tier": "T3", "furigana": "組織[そしき]の仕組[しく]みを改変[かいへん]する前[まえ]に、まず問題点[もんだいてん]を整理[せいり]した。", "sentence_source": "generated"}, {"text": "机の配置を改変すると、教室の雰囲気が明るくなった。", "target_word": "改変", "complexity_tier": "T3", "furigana": "机[つくえ]の配置[はいち]を改変[かいへん]すると、教室[きょうしつ]の雰囲気[ふんいき]が明[あか]るくなった。", "sentence_source": "generated"}, {"text": "古い工場の仕組みを改変して、作業の時間が半分になった。", "target_word": "改変", "complexity_tier": "T3", "furigana": "古[ふる]い工場[こうじょう]の仕組[しく]みを改変[かいへん]して、作業[さぎょう]の時間[じかん]が半分[はんぶん]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "改変", "label": "基本形"}, {"form": "改変する", "label": "終止形"}, {"form": "改変した", "label": "過去形"}, {"form": "改変して", "label": "て形"}, {"form": "改変される", "label": "受身形"}], "register": "書き言葉", "sense_fingerprint": "内容や形をより良いものに変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38683, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改変", "is_correct": true, "explanation": "ここは「改変」。校則の内容を変えるという意味で文に合う。"}, {"text": "予約", "is_correct": false, "explanation": "予約は前もって取り決めることで、内容を変える意味にはならない。"}, {"text": "精算", "is_correct": false, "explanation": "精算は金額を支払って締めることで、校則の内容には合わない。"}, {"text": "返却", "is_correct": false, "explanation": "返却は借りた物を返すことで、校則の内容には合わない。"}], "explanations": {"改変": "ここは「改変」。校則の内容を変えるという意味で文に合う。", "予約": "予約は前もって取り決めることで、内容を変える意味にはならない。", "精算": "精算は金額を支払って締めることで、校則の内容には合わない。", "返却": "返却は借りた物を返すことで、校則の内容には合わない。"}, "sentence_index": 0, "correct_answer": "改変"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外国の小説を改変して、日本語で読めるようにした。", "explanation": "ここは〈翻訳〉の意味。言語を置き換える場合は翻訳を使い、改変は内容や形を変える語。"}, {"text": "壊れた古い像を改変して、元の姿に戻した。", "explanation": "ここは〈修復〉の意味。壊れたものを元に戻す場合は修復を使う。"}, {"text": "写真の形式を改変して、小さいデータにした。", "explanation": "ここは〈変換〉の意味。形式や単位を別のものに換える場合は変換を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38683, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改変", "is_correct": true, "explanation": "ここは「改変」。説明書の内容を全面的に変えたという意味で文に合う。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案に点をつけることで、説明書を変える意味にはならない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物を頼むことで、説明書の内容には合わない。"}, {"text": "返済", "is_correct": false, "explanation": "返済は借りた金を返すことで、説明書には合わない。"}], "explanations": {"改変": "ここは「改変」。説明書の内容を全面的に変えたという意味で文に合う。", "採点": "採点は答案に点をつけることで、説明書を変える意味にはならない。", "注文": "注文は品物を頼むことで、説明書の内容には合わない。", "返済": "返済は借りた金を返すことで、説明書には合わない。"}, "sentence_index": 6, "correct_answer": "改変"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑の野菜を改変して、早朝に収穫した。", "explanation": "ここは〈収穫〉の意味。畑で作物を取り入れる場合は収穫を使う。改変は内容や形を変える語で、取り入れることには使わない。"}, {"text": "毎朝の体温を改変して、記録した。", "explanation": "ここは〈測定〉の意味。数量をはかる場合は測定を使う。改変は内容や形を変える語で、数値をはかることには使わない。"}, {"text": "深く呼吸を改変して、息を整えた。", "explanation": "ここは〈整える〉の意味。乱れた呼吸を落ち着かせる場合は整えるを使う。改変は内容や形を変える語で、体の働きを整えることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38683, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作業手順に改変したので、ミスが減った。", "corrected_sentence": "作業手順を改変したので、ミスが減った。", "error_description": "誤り：「に」。改変は対象を「を」で示すので、「手順を改変した」が正しい。正しい助詞は「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38683, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "組み立てのやり方に改変を見せて、時間を縮めた。", "corrected_sentence": "組み立てのやり方に改変を加えて、時間を縮めた。", "error_description": "誤り：「見せて」。改変は「加える」と組み合わせて使うので、「改変を加えて」が正しい。正しい語は「加えて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
