INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38684, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とてもはやいこと。すぐにすること。", "primary_collocate": null, "pronunciation": "じんそく", "ipa": "dʑinsokɯ", "syllable_count": 4, "sentences": [{"text": "地震のあと、市は迅速に避難所を開いた。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、市[し]は迅速[じんそく]に避難所[ひなんじょ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "迅速な対応のおかげで、けが人は出なかった。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "迅速[じんそく]な対応[たいおう]のおかげで、けが人[にん]は出[で]なかった。", "sentence_source": "generated"}, {"text": "店員の迅速なサービスに、お客さんは満足した。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "店員[てんいん]の迅速[じんそく]なサービスに、お客[きゃく]さんは満足[まんぞく]した。", "sentence_source": "generated"}, {"text": "連絡は迅速にお願いします。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "連絡[れんらく]は迅速[じんそく]にお願[ねが]いします。", "sentence_source": "generated"}, {"text": "火事の知らせを聞いて、消防車が迅速に現場へ向かった。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "火事[かじ]の知[し]らせを聞[き]いて、消防車[しょうぼうしゃ]が迅速[じんそく]に現場[げんば]へ向[む]かった。", "sentence_source": "generated"}, {"text": "彼は問題が起きても、いつも行動が迅速だ。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "彼[かれ]は問題[もんだい]が起[お]きても、いつも行動[こうどう]が迅速[じんそく]だ。", "sentence_source": "generated"}, {"text": "迅速に動かなければ、電車に間に合わない。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "迅速[じんそく]に動[うご]かなければ、電車[でんしゃ]に間[ま]に合[あ]わない。", "sentence_source": "generated"}, {"text": "病院では、迅速な判断が命を救うことがある。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "病院[びょういん]では、迅速[じんそく]な判断[はんだん]が命[いのち]を救[すく]うことがある。", "sentence_source": "generated"}, {"text": "事故の情報は、迅速に家族へ伝えられた。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "事故[じこ]の情報[じょうほう]は、迅速[じんそく]に家族[かぞく]へ伝[つた]えられた。", "sentence_source": "generated"}, {"text": "この会社は注文から配達まで迅速で、評判がいい。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は注文[ちゅうもん]から配達[はいたつ]まで迅速[じんそく]で、評判[ひょうばん]がいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "迅速だ", "label": "終止形"}, {"form": "迅速な", "label": "連体形"}, {"form": "迅速に", "label": "連用形"}, {"form": "迅速で", "label": "て形"}], "register": "やや硬い", "sense_fingerprint": "とてもはやい、すぐに行うさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abc5df8a-7a09-4c1e-8bc7-9f0613fb5212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38684, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迅速", "is_correct": true, "explanation": "すぐに行うさまを表し、地震後に避難所をすぐ開いた文脈に合う。"}, {"text": "豪雨", "is_correct": false, "explanation": "気象を表す名詞で、「に」を付けても動作を修飾できず文が成り立たない。"}, {"text": "不便", "is_correct": false, "explanation": "都合の悪さを表し、動作の速さとは関係ない。"}, {"text": "残念", "is_correct": false, "explanation": "気持ちを表す語で、動作の速さを表さない。"}], "explanations": {"迅速": "すぐに行うさまを表し、地震後に避難所をすぐ開いた文脈に合う。", "豪雨": "気象を表す名詞で、「に」を付けても動作を修飾できず文が成り立たない。", "不便": "都合の悪さを表し、動作の速さとは関係ない。", "残念": "気持ちを表す語で、動作の速さを表さない。"}, "sentence_index": 0, "correct_answer": "迅速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕立が迅速に降ってきて、洗濯物が濡れた。", "explanation": "〈急に〉との混同。迅速は人の行動や処理の速さに使い、天気の突然の変化には使わない。"}, {"text": "合格の知らせを聞いて、彼女は迅速に大喜びした。", "explanation": "〈すぐに〉との混同。迅速は行動や処理の速さを表す語で、感情の表し方には使わない。"}, {"text": "電車が迅速に遅れて、会議に間に合わなかった。", "explanation": "〈遅延〉との混同。迅速は速い対応や動作を表す語で、遅延という出来事の様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38684, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迅速", "is_correct": true, "explanation": "すぐ動く速さを表し、電車に間に合うための条件として合う。"}, {"text": "立派", "is_correct": false, "explanation": "見事さを表す語で、動きの速さを表さない。"}, {"text": "不要", "is_correct": false, "explanation": "必要ないという意味で、ここでは文の条件が成り立たない。"}, {"text": "贅沢", "is_correct": false, "explanation": "ぜいたくさを表し、動作の速さとは結びつかない。"}], "explanations": {"迅速": "すぐ動く速さを表し、電車に間に合うための条件として合う。", "立派": "見事さを表す語で、動きの速さを表さない。", "不要": "必要ないという意味で、ここでは文の条件が成り立たない。", "贅沢": "ぜいたくさを表し、動作の速さとは結びつかない。"}, "sentence_index": 6, "correct_answer": "迅速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅のベンチで、迅速に待ち続けた。", "explanation": "〈ゆっくり〉との混同。迅速は素早く行う意味で、長く時間をかけて待つ様子とは合わない。"}, {"text": "仕事のあと、迅速に休んだ。", "explanation": "〈くつろぐ〉との混同。くつろぐのは時間をかけて楽しむことで、速さを表す迅速とは合わない。"}, {"text": "その問題を迅速に悩んだ。", "explanation": "〈じっくり〉との混同。迅速は短い時間で行う意味で、時間をかけて悩む様子とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38684, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防隊が現場へ迅速いに向かった。", "corrected_sentence": "消防隊が現場へ迅速に向かった。", "error_description": "誤り：「迅速いに」。正しくは「迅速に」。迅速は形容詞ではなく形状詞なので、形容詞の語尾「い」を付けるのは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "迅速", "is_correct": true, "explanation": "形状詞の語幹で、「な」が続いて名詞を修飾する形に合う。"}, {"text": "迅速に", "is_correct": false, "explanation": "副詞形では「な対応」に続かず、名詞を修飾できない。"}, {"text": "迅速だ", "is_correct": false, "explanation": "断定の形では「な対応」に続かず、名詞を修飾できない。"}, {"text": "迅速で", "is_correct": false, "explanation": "て形では名詞に直接続かず、「な対応」の形にならない。"}], "correct_form": "迅速", "base_form": "迅速だ", "form_label": "連体形（〜な）", "sentence_index": 1, "explanations": {"迅速": "形状詞の語幹で、「な」が続いて名詞を修飾する形に合う。", "迅速に": "副詞形では「な対応」に続かず、名詞を修飾できない。", "迅速だ": "断定の形では「な対応」に続かず、名詞を修飾できない。", "迅速で": "て形では名詞に直接続かず、「な対応」の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38684, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "配送業者は注文から配達まで迅速が、評判がいい。", "corrected_sentence": "配送業者は注文から配達まで迅速で、評判がいい。", "error_description": "誤り：「迅速が」。正しくは「迅速で」。「迅速」と「評判がいい」をつなぐには「で」が必要で、「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "迅速", "is_correct": true, "explanation": "形状詞の語幹で、「な判断」の形に続く語として合う。"}, {"text": "迅速で", "is_correct": false, "explanation": "て形では名詞に直接続かず、「な判断」の形にならない。"}, {"text": "迅速だろう", "is_correct": false, "explanation": "推量形では名詞を修飾できず、「な判断」の形にならない。"}, {"text": "迅速だったら", "is_correct": false, "explanation": "条件形では名詞を修飾できず、文が成り立たない。"}], "correct_form": "迅速", "base_form": "迅速だ", "form_label": "連体形（〜な）", "sentence_index": 7, "explanations": {"迅速": "形状詞の語幹で、「な判断」の形に続く語として合う。", "迅速で": "て形では名詞に直接続かず、「な判断」の形にならない。", "迅速だろう": "推量形では名詞を修飾できず、「な判断」の形にならない。", "迅速だったら": "条件形では名詞を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38685, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩慢", "is_correct": true, "explanation": "すばやさの反対の遅さを表し、動作や変化の速さの対義語として合う。"}, {"text": "豪快", "is_correct": false, "explanation": "勢いのよさを表す語で、速さの反対ではない。"}, {"text": "地味", "is_correct": false, "explanation": "目立たない様子を表し、速さとは関係ない。"}, {"text": "丁寧", "is_correct": false, "explanation": "念入りさを表し、速さの反対ではない。"}], "correct_answer": "緩慢", "explanations": {"緩慢": "すばやさの反対の遅さを表し、動作や変化の速さの対義語として合う。", "豪快": "勢いのよさを表す語で、速さの反対ではない。", "地味": "目立たない様子を表し、速さとは関係ない。", "丁寧": "念入りさを表し、速さの反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38685, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩慢", "is_correct": true, "explanation": "すばやさの反対の遅さを表し、動作や変化の速さの対義語として合う。"}, {"text": "切実", "is_correct": false, "explanation": "差し迫って切ない様子を表し、速さの反対ではない。"}, {"text": "元気", "is_correct": false, "explanation": "活発さを表す語で、速さの反対ではない。"}, {"text": "上品", "is_correct": false, "explanation": "品のよさを表す語で、速さの対義にはならない。"}], "correct_answer": "緩慢", "explanations": {"緩慢": "すばやさの反対の遅さを表し、動作や変化の速さの対義語として合う。", "切実": "差し迫って切ない様子を表し、速さの反対ではない。", "元気": "活発さを表す語で、速さの反対ではない。", "上品": "品のよさを表す語で、速さの対義にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38685, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事をためらわず、短い時間で行うさま。動作や変化が速いこと。", "primary_collocate": null, "pronunciation": "じんそく", "ipa": "dʑinsokɯ", "syllable_count": 4, "sentences": [{"text": "彼はためらうことなく、迅速に決断した。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "彼[かれ]はためらうことなく、迅速[じんそく]に決断[けつだん]した。", "sentence_source": "generated"}, {"text": "迅速な手続きのため、書類を前日に準備しておいた。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "迅速[じんそく]な手続[てつづ]きのため、書類[しょるい]を前日[ぜんじつ]に準備[じゅんび]しておいた。", "sentence_source": "generated"}, {"text": "委員会は問題について迅速な処理を約束した。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "委員会[いいんかい]は問題[もんだい]について迅速[じんそく]な処理[しょり]を約束[やくそく]した。", "sentence_source": "generated"}, {"text": "災害時には、情報を迅速かつ正確に伝えることが大切だ。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "災害時[さいがいじ]には、情報[じょうほう]を迅速[じんそく]かつ正確[せいかく]に伝[つた]えることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "担当者は迅速に動いて、故障をその日のうちに直した。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "担当者[たんとうしゃ]は迅速[じんそく]に動[うご]いて、故障[こしょう]をその日[ひ]のうちに直[なお]した。", "sentence_source": "generated"}, {"text": "迅速な行動が求められる場面では、迷う時間がない。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "迅速[じんそく]な行動[こうどう]が求[もと]められる場面[ばめん]では、迷[まよ]う時間[じかん]がない。", "sentence_source": "generated"}, {"text": "窓口の職員が迅速に対応し、待ち時間はほとんどなかった。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "窓口[まどぐち]の職員[しょくいん]が迅速[じんそく]に対応[たいおう]し、待[ま]ち時間[じかん]はほとんどなかった。", "sentence_source": "generated"}, {"text": "彼女は迅速に資料をまとめて、会議に間に合わせた。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は迅速[じんそく]に資料[しりょう]をまとめて、会議[かいぎ]に間[ま]に合[あ]わせた。", "sentence_source": "generated"}, {"text": "状況の変化に応じて、迅速に計画を変更した。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "状況[じょうきょう]の変化[へんか]に応[おう]じて、迅速[じんそく]に計画[けいかく]を変更[へんこう]した。", "sentence_source": "generated"}, {"text": "医師の迅速な判断で、患者は一命を取りとめた。", "target_word": "迅速", "complexity_tier": "T3", "furigana": "医師[いし]の迅速[じんそく]な判断[はんだん]で、患者[かんじゃ]は一命[いちめい]を取[と]りとめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "迅速だ", "label": "終止形"}, {"form": "迅速な", "label": "連体形"}, {"form": "迅速に", "label": "連用形"}, {"form": "迅速で", "label": "て形"}], "register": "やや硬い", "sense_fingerprint": "ためらわず短い時間で行うさま、動作や変化の速さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 取りとめ (Zipf 1.88)']::text[], 'abc5df8a-7a09-4c1e-8bc7-9f0613fb5212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38685, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迅速", "is_correct": true, "explanation": "ためらわず短い時間で行うさまを表し、すぐ決断した文脈に合う。"}, {"text": "閑静", "is_correct": false, "explanation": "静かで落ち着いた様子を表し、決断の速さを表さないので文が成り立たない。"}, {"text": "豪華", "is_correct": false, "explanation": "立派で華やかな様子で、決断とは結びつかない。"}, {"text": "平等", "is_correct": false, "explanation": "差がない様子を表し、決断の速さを表さない。"}], "explanations": {"迅速": "ためらわず短い時間で行うさまを表し、すぐ決断した文脈に合う。", "閑静": "静かで落ち着いた様子を表し、決断の速さを表さないので文が成り立たない。", "豪華": "立派で華やかな様子で、決断とは結びつかない。", "平等": "差がない様子を表し、決断の速さを表さない。"}, "sentence_index": 0, "correct_answer": "迅速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は迅速に熟考して、結論を出した。", "explanation": "〈慎重〉との混同。迅速はためらわず短時間で行う意味で、慎重に時間をかける判断とは合わない。"}, {"text": "彼は迅速にためらって、答えられなかった。", "explanation": "〈もたつく〉との混同。迅速は迷わず速く行う意味で、ぐずぐずする様子とは合わない。"}, {"text": "山道を迅速に散歩した。", "explanation": "〈ぶらぶら〉との混同。迅速は素早く行う意味で、ゆったり歩く様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38685, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迅速", "is_correct": true, "explanation": "すばやく対応したという意味で、待ち時間が少なかった文脈に合う。"}, {"text": "厳か", "is_correct": false, "explanation": "おごそかな様子を表し、対応の速さを表さない。"}, {"text": "大らか", "is_correct": false, "explanation": "おおらかな様子を表し、速さとは関係ない。"}, {"text": "閑散", "is_correct": false, "explanation": "人の少ない様子を表し、対応の速さとは結びつかず文が成り立たない。"}], "explanations": {"迅速": "すばやく対応したという意味で、待ち時間が少なかった文脈に合う。", "厳か": "おごそかな様子を表し、対応の速さを表さない。", "大らか": "おおらかな様子を表し、速さとは関係ない。", "閑散": "人の少ない様子を表し、対応の速さとは結びつかず文が成り立たない。"}, "sentence_index": 6, "correct_answer": "迅速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は迅速に悲しんだ。", "explanation": "〈しょんぼり〉との混同。迅速は素早く行う意味で、落ち込んだ様子を表す語ではない。"}, {"text": "この店の料理は迅速に美味しい。", "explanation": "〈速い〉との混同。迅速は行動や処理の速さを表す語で、料理の味の良さには使わない。"}, {"text": "彼女は迅速に優しい性格だ。", "explanation": "〈きびきび〉との混同。迅速は速さを表す語で、性格の特徴を表す場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38685, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は迅速の判断で、会議を始めた。", "corrected_sentence": "彼女は迅速な判断で、会議を始めた。", "error_description": "誤り：「迅速の」。正しくは「迅速な」。形状詞は名詞を修飾するとき「な」を付け、「の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "迅速", "is_correct": true, "explanation": "形状詞の語幹で、「な手続き」の形に続く語として合う。"}, {"text": "迅速に", "is_correct": false, "explanation": "副詞形では「な手続き」に続かず、名詞を修飾できない。"}, {"text": "迅速だ", "is_correct": false, "explanation": "断定の形では名詞を修飾できず、「な手続き」の形にならない。"}, {"text": "迅速で", "is_correct": false, "explanation": "て形では名詞に直接続かず、「な手続き」の形にならない。"}], "correct_form": "迅速", "base_form": "迅速だ", "form_label": "連体形（〜な）", "sentence_index": 1, "explanations": {"迅速": "形状詞の語幹で、「な手続き」の形に続く語として合う。", "迅速に": "副詞形では「な手続き」に続かず、名詞を修飾できない。", "迅速だ": "断定の形では名詞を修飾できず、「な手続き」の形にならない。", "迅速で": "て形では名詞に直接続かず、「な手続き」の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38685, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "修理担当者は迅速いに動いて、故障を当日中に直した。", "corrected_sentence": "修理担当者は迅速に動いて、故障を当日中に直した。", "error_description": "誤り：「迅速いに」。正しくは「迅速に」。形状詞に形容詞の語尾「い」を付けるのは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "迅速", "is_correct": true, "explanation": "形状詞の語幹で、「に」が続いて動詞を修飾する形に合う。"}, {"text": "迅速な", "is_correct": false, "explanation": "連体形では「に資料をまとめて」に続かず、副詞として働かない。"}, {"text": "迅速だった", "is_correct": false, "explanation": "過去形では副詞として働かず、「に」に続かない。"}, {"text": "迅速だろう", "is_correct": false, "explanation": "推量形では副詞として働かず、「に」に続かない。"}], "correct_form": "迅速", "base_form": "迅速だ", "form_label": "連用形（〜に）", "sentence_index": 7, "explanations": {"迅速": "形状詞の語幹で、「に」が続いて動詞を修飾する形に合う。", "迅速な": "連体形では「に資料をまとめて」に続かず、副詞として働かない。", "迅速だった": "過去形では副詞として働かず、「に」に続かない。", "迅速だろう": "推量形では副詞として働かず、「に」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38686, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「株によって」で、種類による違いを表す。"}, {"text": "を", "is_correct": false, "explanation": "「をよって」という形は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「でよって」という形は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へよって」という形は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「株によって」で、種類による違いを表す。", "を": "「をよって」という形は成り立たない。", "で": "「でよって」という形は成り立たない。", "へ": "「へよって」という形は成り立たない。"}, "error_tags": {"を": "object_marker", "で": "location", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38686, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「増える」の主語を表すので「が」。"}, {"text": "を", "is_correct": false, "explanation": "「増える」は自動詞で目的語を取らない。"}, {"text": "に", "is_correct": false, "explanation": "「株に増える」では意味の通る文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「増える」の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「増える」の主語を表すので「が」。", "を": "「増える」は自動詞で目的語を取らない。", "に": "「株に増える」では意味の通る文にならない。", "へ": "「へ」は方向を表し、「増える」の主語にならない。"}, "error_tags": {"を": "object_marker", "に": "target", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38686, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "細菌などの微生物で、同じ種の中の特定の系統。", "primary_collocate": null, "pronunciation": "かぶ", "ipa": "kabɯ", "syllable_count": 2, "sentences": [{"text": "この菌の株は水の中でよく増える。", "target_word": "株", "complexity_tier": "T3", "furigana": "この菌[きん]の株[かぶ]は水[みず]の中[なか]でよく増[ふ]える。", "sentence_source": "generated"}, {"text": "細菌は株によって形がちがいます。", "target_word": "株", "complexity_tier": "T3", "furigana": "細菌[さいきん]は株[かぶ]によって形[かたち]がちがいます。", "sentence_source": "generated"}, {"text": "先生は顕微鏡で新しい菌の株を見せてくれた。", "target_word": "株", "complexity_tier": "T3", "furigana": "先生[せんせい]は顕微鏡[けんびきょう]で新[あたら]しい菌[きん]の株[かぶ]を見[み]せてくれた。", "sentence_source": "generated"}, {"text": "顕微鏡で株を見た。", "target_word": "株", "complexity_tier": "T1", "furigana": "顕微鏡[けんびきょう]で株[かぶ]を見[み]た。", "sentence_source": "generated"}, {"text": "細菌の株の名前を書きました。", "target_word": "株", "complexity_tier": "T2", "furigana": "細菌[さいきん]の株[かぶ]の名前[なまえ]を書[か]きました。", "sentence_source": "generated"}, {"text": "これは古い細菌の株だ。", "target_word": "株", "complexity_tier": "T2", "furigana": "これは古[ふる]い細菌[さいきん]の株[かぶ]だ。", "sentence_source": "generated"}, {"text": "二つの菌の株を比べている。", "target_word": "株", "complexity_tier": "T3", "furigana": "二[ふた]つの菌[きん]の株[かぶ]を比[くら]べている。", "sentence_source": "generated"}, {"text": "株が増えると、水の色が変わる。", "target_word": "株", "complexity_tier": "T4", "furigana": "株[かぶ]が増[ふ]えると、水[みず]の色[いろ]が変[か]わる。", "sentence_source": "generated"}, {"text": "研究室には百の株がある。", "target_word": "株", "complexity_tier": "T3", "furigana": "研究室[けんきゅうしつ]には百[ひゃく]の株[かぶ]がある。", "sentence_source": "generated"}, {"text": "弱い株は薬で死んでしまう。", "target_word": "株", "complexity_tier": "T3", "furigana": "弱[よわ]い株[かぶ]は薬[くすり]で死[し]んでしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "菌株", "label": "派生"}, {"form": "変異株", "label": "派生"}, {"form": "一株", "label": "助数詞"}], "register": "plain", "sense_fingerprint": "名詞 | 微生物の小さな種類の一つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb0ade9-23c9-46b2-b597-ca2a2de71a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38686, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "株", "is_correct": true, "explanation": "見出し語「かぶ」そのもの。"}, {"text": "河馬", "is_correct": false, "explanation": "「かば」で、二拍目だけが違う別語。"}, {"text": "黴", "is_correct": false, "explanation": "「かび」で、二拍目だけが違う別語。"}, {"text": "傘", "is_correct": false, "explanation": "「かさ」で、二拍目だけが違う別語。"}, {"text": "鍵", "is_correct": false, "explanation": "「かぎ」で、二拍目だけが違う別語。"}], "explanations": {"株": "見出し語「かぶ」そのもの。", "河馬": "「かば」で、二拍目だけが違う別語。", "黴": "「かび」で、二拍目だけが違う別語。", "傘": "「かさ」で、二拍目だけが違う別語。", "鍵": "「かぎ」で、二拍目だけが違う別語。"}, "sentence_index": null, "correct_answer": "株"}, "level_3": {"options": [{"text": "株", "is_correct": true, "explanation": "小さな生き物の種類を指すので意味が合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、机は生き物ではなく意味が合わない。"}, {"text": "石", "is_correct": false, "explanation": "形は合うが、石は生き物ではなく意味が合わない。"}, {"text": "駅", "is_correct": false, "explanation": "形は合うが、駅は生き物ではなく意味が合わない。"}], "explanations": {"株": "小さな生き物の種類を指すので意味が合う。", "机": "形は合うが、机は生き物ではなく意味が合わない。", "石": "形は合うが、石は生き物ではなく意味が合わない。", "駅": "形は合うが、駅は生き物ではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "株"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は昨日、株に乗って学校へ行った。", "explanation": "株は小さな生き物の種類で、乗り物ではない。"}, {"text": "株は台所でカレーを作っている。", "explanation": "株は生き物の種類で、料理をする主語にはならない。"}, {"text": "株を飛行機で空へ飛ばした。", "explanation": "株は微生物の種類で、飛行機で飛ばす物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38686, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "株", "is_correct": true, "explanation": "見出し語「かぶ」そのもの。"}, {"text": "籠", "is_correct": false, "explanation": "「かご」で、二拍目だけが違う別語。"}, {"text": "亀", "is_correct": false, "explanation": "「かめ」で、二拍目だけが違う別語。"}, {"text": "釜", "is_correct": false, "explanation": "「かま」で、二拍目だけが違う別語。"}, {"text": "紙", "is_correct": false, "explanation": "「かみ」で、二拍目だけが違う別語。"}], "explanations": {"株": "見出し語「かぶ」そのもの。", "籠": "「かご」で、二拍目だけが違う別語。", "亀": "「かめ」で、二拍目だけが違う別語。", "釜": "「かま」で、二拍目だけが違う別語。", "紙": "「かみ」で、二拍目だけが違う別語。"}, "sentence_index": null, "correct_answer": "株"}, "level_3": {"options": [{"text": "株", "is_correct": true, "explanation": "二つの種類を比べるという意味で合う。"}, {"text": "雨", "is_correct": false, "explanation": "形は合うが、「二つの雨」を比べる意味が合わない。"}, {"text": "風", "is_correct": false, "explanation": "形は合うが、二つ数えて比べる対象として意味が合わない。"}, {"text": "雷", "is_correct": false, "explanation": "形は合うが、二つ数えて比べる対象として意味が合わない。"}], "explanations": {"株": "二つの種類を比べるという意味で合う。", "雨": "形は合うが、「二つの雨」を比べる意味が合わない。", "風": "形は合うが、二つ数えて比べる対象として意味が合わない。", "雷": "形は合うが、二つ数えて比べる対象として意味が合わない。"}, "sentence_index": 6, "correct_answer": "株"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は黒板の株を読んで笑った。", "explanation": "株は微生物の種類で、黒板に書いて読む物としては合わない。"}, {"text": "私は毎朝、株を歯みがきに使っている。", "explanation": "株は生き物の種類で、歯みがきに使う物ではない。"}, {"text": "株は昨日、友だちの家に遊びに来た。", "explanation": "株は生き物の種類で、人のように遊びに来ることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
