INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38687, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この株」を主題として示すので「は」。"}, {"text": "を", "is_correct": false, "explanation": "「効きにくい」の文で、「株を」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、ここでは成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「この株と薬が効きにくい」では文がつながらない。"}], "correct_answer": "は", "explanations": {"は": "「この株」を主題として示すので「は」。", "を": "「効きにくい」の文で、「株を」は文として成り立たない。", "へ": "「へ」は方向を表し、ここでは成り立たない。", "と": "「この株と薬が効きにくい」では文がつながらない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38687, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「その株の遺伝子」で、株の持つ遺伝子を表す。"}, {"text": "を", "is_correct": false, "explanation": "後ろに「遺伝子を」があり、「を」が重なって不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、名詞をつなげない。"}, {"text": "よ", "is_correct": false, "explanation": "「よ」は文末の助詞で、この位置では成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「その株の遺伝子」で、株の持つ遺伝子を表す。", "を": "後ろに「遺伝子を」があり、「を」が重なって不自然。", "へ": "「へ」は方向を表し、名詞をつなげない。", "よ": "「よ」は文末の助詞で、この位置では成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "よ": "sentence_final"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38687, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "細菌や菌類など、顕微鏡で見るような小さな生物の特定の種類。", "primary_collocate": null, "pronunciation": "かぶ", "ipa": "kabɯ", "syllable_count": 2, "sentences": [{"text": "この菌の株は寒い場所でもよく育つ。", "target_word": "株", "complexity_tier": "T3", "furigana": "この菌[きん]の株[かぶ]は寒[さむ]い場所[ばしょ]でもよく育[そだ]つ。", "sentence_source": "generated"}, {"text": "この株は薬が効きにくい。", "target_word": "株", "complexity_tier": "T3", "furigana": "この株[かぶ]は薬[くすり]が効[き]きにくい。", "sentence_source": "generated"}, {"text": "研究者は新しい株を培養した。", "target_word": "株", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は新[あたら]しい株[かぶ]を培養[ばいよう]した。", "sentence_source": "generated"}, {"text": "二つの株には小さな違いがある。", "target_word": "株", "complexity_tier": "T3", "furigana": "二[ふた]つの株[かぶ]には小[ちい]さな違[ちが]いがある。", "sentence_source": "generated"}, {"text": "菌の株ごとに性質が異なる。", "target_word": "株", "complexity_tier": "T3", "furigana": "菌[きん]の株[かぶ]ごとに性質[せいしつ]が異[こと]なる。", "sentence_source": "generated"}, {"text": "実験で使った株は冷凍庫に保存してある。", "target_word": "株", "complexity_tier": "T3", "furigana": "実験[じっけん]で使[つか]った株[かぶ]は冷凍庫[れいとうこ]に保存[ほぞん]してある。", "sentence_source": "generated"}, {"text": "変異した株が見つかったと報告された。", "target_word": "株", "complexity_tier": "T4", "furigana": "変異[へんい]した株[かぶ]が見[み]つかったと報告[ほうこく]された。", "sentence_source": "generated"}, {"text": "その株の遺伝子を調べてみよう。", "target_word": "株", "complexity_tier": "T3", "furigana": "その株[かぶ]の遺伝子[いでんし]を調[しら]べてみよう。", "sentence_source": "generated"}, {"text": "病原性の強い株が広がっている。", "target_word": "株", "complexity_tier": "T3", "furigana": "病原性[びょうげんせい]の強[つよ]い株[かぶ]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "同じ種でも、株によってワクチンの効果が違う。", "target_word": "株", "complexity_tier": "T4", "furigana": "同[おな]じ種[しゅ]でも、株[かぶ]によってワクチンの効果[こうか]が違[ちが]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "菌株", "label": "派生"}, {"form": "変異株", "label": "派生"}, {"form": "一株", "label": "助数詞"}], "register": "plain", "sense_fingerprint": "名詞 | 細菌や菌類の特定の系統・種類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb0ade9-23c9-46b2-b597-ca2a2de71a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38687, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "株", "is_correct": true, "explanation": "見出し語「かぶ」そのもの。"}, {"text": "河馬", "is_correct": false, "explanation": "「かば」で、二拍目だけが違う別語。"}, {"text": "黴", "is_correct": false, "explanation": "「かび」で、二拍目だけが違う別語。"}, {"text": "傘", "is_correct": false, "explanation": "「かさ」で、二拍目だけが違う別語。"}, {"text": "鍵", "is_correct": false, "explanation": "「かぎ」で、二拍目だけが違う別語。"}], "explanations": {"株": "見出し語「かぶ」そのもの。", "河馬": "「かば」で、二拍目だけが違う別語。", "黴": "「かび」で、二拍目だけが違う別語。", "傘": "「かさ」で、二拍目だけが違う別語。", "鍵": "「かぎ」で、二拍目だけが違う別語。"}, "sentence_index": null, "correct_answer": "株"}, "level_3": {"options": [{"text": "株", "is_correct": true, "explanation": "菌の特定の系統を指すので意味が合う。"}, {"text": "箱", "is_correct": false, "explanation": "形は合うが、箱は育つ物ではなく意味が合わない。"}, {"text": "窓", "is_correct": false, "explanation": "形は合うが、窓は育つ物ではなく意味が合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが、鉛筆は育つ物ではなく意味が合わない。"}], "explanations": {"株": "菌の特定の系統を指すので意味が合う。", "箱": "形は合うが、箱は育つ物ではなく意味が合わない。", "窓": "形は合うが、窓は育つ物ではなく意味が合わない。", "鉛筆": "形は合うが、鉛筆は育つ物ではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "株"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この株は昨日、東京から大阪へ引っ越した。", "explanation": "株は菌の系統で、人のように引っ越すことはできない。"}, {"text": "私は毎日、株をご飯にかけて食べる。", "explanation": "株は微生物の種類で、ご飯にかけて食べる物ではない。"}, {"text": "株は大きな声で先生に挨拶した。", "explanation": "株は菌の系統なので、挨拶する主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLU