INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38688, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す。「石油を原料にして」で、石油が原料にされる対象であることを示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「石油が原料にして」では石油が主語になり、文意が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「石油へ原料にして」は意味をなさない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を示すが、「石油より原料にして」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "対象を表す。「石油を原料にして」で、石油が原料にされる対象であることを示す。", "が": "主語を示すが、「石油が原料にして」では石油が主語になり、文意が通らない。", "へ": "方向を示す。「石油へ原料にして」は意味をなさない。", "より": "比較や起点を示すが、「石油より原料にして」は文が成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較・起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38688, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。「石油がなくなったら」で、なくなる主体を示す。"}, {"text": "に", "is_correct": false, "explanation": "相手や結果を示すが、「石油になくなったら」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「石油でなくなったら」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、「石油となくなったら」は不自然で、なくなる主体を示せない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。「石油がなくなったら」で、なくなる主体を示す。", "に": "相手や結果を示すが、「石油になくなったら」では文が成り立たない。", "で": "手段や場所を示すが、「石油でなくなったら」は意味が通らない。", "と": "並列や相手を示すが、「石油となくなったら」は不自然で、なくなる主体を示せない。"}, "error_tags": {"に": "相手・結果", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38688, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面の下からとれる、車を動かしたり、プラスチックを作ったりするのに使う油です。", "primary_collocate": null, "pronunciation": "せきゆ", "ipa": "sekijɯ", "syllable_count": 3, "sentences": [{"text": "車を動かすために、石油から作った燃料が使われる。", "target_word": "石油", "complexity_tier": "T3", "furigana": "車[くるま]を動[うご]かすために、石油[せきゆ]から作[つく]った燃料[ねんりょう]が使[つか]われる。", "sentence_source": "generated"}, {"text": "プラスチックの多くは、石油を原料にして作られる。", "target_word": "石油", "complexity_tier": "T3", "furigana": "プラスチックの多[おお]くは、石油[せきゆ]を原料[げんりょう]にして作[つく]られる。", "sentence_source": "generated"}, {"text": "日本は石油をほとんど外国から買っている。", "target_word": "石油", "complexity_tier": "T3", "furigana": "日本[にほん]は石油[せきゆ]をほとんど外国[がいこく]から買[か]っている。", "sentence_source": "generated"}, {"text": "石油が高くなると、ガソリンの値段も上がる。", "target_word": "石油", "complexity_tier": "T3", "furigana": "石油[せきゆ]が高[たか]くなると、ガソリンの値段[ねだん]も上[あ]がる。", "sentence_source": "generated"}, {"text": "この国は地下に石油が眠っているので、豊かだ。", "target_word": "石油", "complexity_tier": "T3", "furigana": "この国[くに]は地下[ちか]に石油[せきゆ]が眠[ねむ]っているので、豊[ゆた]かだ。", "sentence_source": "generated"}, {"text": "石油を使いすぎると、空気がよごれてしまう。", "target_word": "石油", "complexity_tier": "T3", "furigana": "石油[せきゆ]を使[つか]いすぎると、空気[くうき]がよごれてしまう。", "sentence_source": "generated"}, {"text": "海の事故で石油が流れ出し、魚が死んだ。", "target_word": "石油", "complexity_tier": "T3", "furigana": "海[うみ]の事故[じこ]で石油[せきゆ]が流[なが]れ出[だ]し、魚[さかな]が死[し]んだ。", "sentence_source": "generated"}, {"text": "石油がなくなったら、車の代わりに何を使えばいいだろうか。", "target_word": "石油", "complexity_tier": "T3", "furigana": "石油[せきゆ]がなくなったら、車[くるま]の代[か]わりに何[なに]を使[つか]えばいいだろうか。", "sentence_source": "generated"}, {"text": "地面に深い穴をあけて、石油をくみ上げる。", "target_word": "石油", "complexity_tier": "T3", "furigana": "地面[じめん]に深[ふか]い穴[あな]をあけて、石油[せきゆ]をくみ上[あ]げる。", "sentence_source": "generated"}, {"text": "石油は、バスや船を動かす燃料としても大切だ。", "target_word": "石油", "complexity_tier": "T3", "furigana": "石油[せきゆ]は、バスや船[ふね]を動[うご]かす燃料[ねんりょう]としても大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "石油", "label": "基本形"}, {"form": "石油を", "label": "を格"}, {"form": "石油が", "label": "が格"}, {"form": "石油は", "label": "主題形"}], "register": "標準", "sense_fingerprint": "地下からとれ、車の燃料やプラスチックの原料になる油", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: くみ上げる (Zipf 1.79)']::text[], '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38688, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石油", "is_correct": true, "explanation": "ここは「石油」。石油から作った燃料という意味で文に合う。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄から燃料を作ることはなく、文に合わない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は洗うための物で、燃料の材料にはならない。"}, {"text": "粘土", "is_correct": false, "explanation": "粘土は燃料の材料ではなく、文に合わない。"}], "explanations": {"石油": "ここは「石油」。石油から作った燃料という意味で文に合う。", "鉄": "鉄から燃料を作ることはなく、文に合わない。", "石鹸": "石鹸は洗うための物で、燃料の材料にはならない。", "粘土": "粘土は燃料の材料ではなく、文に合わない。"}, "sentence_index": 0, "correct_answer": "石油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天ぷらを揚げるのに、石油を使った。", "explanation": "ここは〈油〉の意味。石油は地下からとれる燃料や原料で、食べ物を揚げる油には使わない。"}, {"text": "車のガソリンが切れたので、石油を満タンに入れた。", "explanation": "ここは〈ガソリン〉の意味。車に入れるのは精製したガソリンで、原料の石油は入れない。"}, {"text": "床をぴかぴかにするため、石油を塗った。", "explanation": "ここは〈ワックス〉の意味。床を磨く塗料は別の物で、石油は床の仕上げには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38688, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石油", "is_correct": true, "explanation": "ここは「石油」。海に流れ出す油として文に合う。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書が海に流れ出すことはなく、文に合わない。"}, {"text": "家具", "is_correct": false, "explanation": "家具は流れ出すものではなく、文に合わない。"}, {"text": "紙袋", "is_correct": false, "explanation": "紙袋が海に流れ出して魚が死ぬ文脈には合わない。"}], "explanations": {"石油": "ここは「石油」。海に流れ出す油として文に合う。", "教科書": "教科書が海に流れ出すことはなく、文に合わない。", "家具": "家具は流れ出すものではなく、文に合わない。", "紙袋": "紙袋が海に流れ出して魚が死ぬ文脈には合わない。"}, "sentence_index": 6, "correct_answer": "石油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "石油は固い塊なので、ストーブに入れてそのまま燃やす。", "explanation": "ここは〈石炭〉の意味。石油は黒くてねばる液体なので、固い塊として燃やすのは石炭の使い方。"}, {"text": "石油は気体なので、ボンベに入れて家庭に届ける。", "explanation": "ここは〈天然ガス〉の意味。石油は液体で、気体を容器に入れて送るのは天然ガス。"}, {"text": "手を洗うために、石油を泡立てて使った。", "explanation": "ここは〈石鹸〉の意味。泡で汚れを落とすのは石鹸で、石油は手を洗う物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38688, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "石油が燃やすと、二酸化炭素が出る。", "corrected_sentence": "石油を燃やすと、二酸化炭素が出る。", "error_description": "誤り：「が」。燃やすの対象は「を」で示す。正しい助詞は「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38688, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の下の井戸から石油を組み立てる。", "corrected_sentence": "山の下の井戸から石油を掘り出す。", "error_description": "誤り：「組み立てる」。石油は掘り出すもので、組み立てる対象ではない。正しい語は「掘り出す」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38689, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す。「石油を精製すると」で、精製される目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「石油へ精製すると」は意味をなさない。"}, {"text": "に", "is_correct": false, "explanation": "相手や結果を示すが、「石油に精製すると」では精製される対象が示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を示すが、「石油より精製すると」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "対象を表す。「石油を精製すると」で、精製される目的語を示す。", "へ": "方向を示す。「石油へ精製すると」は意味をなさない。", "に": "相手や結果を示すが、「石油に精製すると」では精製される対象が示せない。", "より": "比較や起点を示すが、「石油より精製すると」は文が成り立たない。"}, "error_tags": {"へ": "方向", "に": "相手・結果", "より": "比較・起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38689, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾を示す。「石油の量」で、量の持ち主を示す。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「石油で量には限りがある」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「石油から量には限りがある」では意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「石油を量には限りがある」は文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾を示す。「石油の量」で、量の持ち主を示す。", "で": "手段や場所を示すが、「石油で量には限りがある」では文が成り立たない。", "から": "起点を示すが、「石油から量には限りがある」では意味が通らない。", "を": "目的語を示すが、「石油を量には限りがある」は文が成り立たない。"}, "error_tags": {"で": "手段・場所", "から": "起点", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38689, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地下から採れる、燃料やプラスチックの原料となる、黒くてねばり気のある液体。", "primary_collocate": null, "pronunciation": "せきゆ", "ipa": "sekijɯ", "syllable_count": 3, "sentences": [{"text": "地下から出てきた石油は、黒くてどろっとしている。", "target_word": "石油", "complexity_tier": "T3", "furigana": "地下[ちか]から出[で]てきた石油[せきゆ]は、黒[くろ]くてどろっとしている。", "sentence_source": "generated"}, {"text": "石油を精製すると、ガソリンや灯油が取れる。", "target_word": "石油", "complexity_tier": "T3", "furigana": "石油[せきゆ]を精製[せいせい]すると、ガソリンや灯油[とうゆ]が取[と]れる。", "sentence_source": "generated"}, {"text": "石油の価格が下がったので、工場の費用も減った。", "target_word": "石油", "complexity_tier": "T3", "furigana": "石油[せきゆ]の価格[かかく]が下[さ]がったので、工場[こうじょう]の費用[ひよう]も減[へ]った。", "sentence_source": "generated"}, {"text": "海の底にある石油を、大きな船で掘り出す。", "target_word": "石油", "complexity_tier": "T3", "furigana": "海[うみ]の底[そこ]にある石油[せきゆ]を、大[おお]きな船[ふね]で掘[ほ]り出[だ]す。", "sentence_source": "generated"}, {"text": "石油は燃料だけでなく、薬や服の原料にもなる。", "target_word": "石油", "complexity_tier": "T3", "furigana": "石油[せきゆ]は燃料[ねんりょう]だけでなく、薬[くすり]や服[ふく]の原料[げんりょう]にもなる。", "sentence_source": "generated"}, {"text": "中東には、世界でも有名な石油の産地がある。", "target_word": "石油", "complexity_tier": "T3", "furigana": "中東[ちゅうとう]には、世界[せかい]でも有名[ゆうめい]な石油[せきゆ]の産地[さんち]がある。", "sentence_source": "generated"}, {"text": "タンカーは、石油を遠い国から運んでくる。", "target_word": "石油", "complexity_tier": "T3", "furigana": "タンカーは、石油[せきゆ]を遠[とお]い国[くに]から運[はこ]んでくる。", "sentence_source": "generated"}, {"text": "石油の量には限りがあるので、節約が必要だ。", "target_word": "石油", "complexity_tier": "T3", "furigana": "石油[せきゆ]の量[りょう]には限[かぎ]りがあるので、節約[せつやく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "手についた石油は、においが強くて落ちにくい。", "target_word": "石油", "complexity_tier": "T3", "furigana": "手[て]についた石油[せきゆ]は、においが強[つよ]くて落[お]ちにくい。", "sentence_source": "generated"}, {"text": "昔の人は、地面からにじみ出る石油を不思議に思った。", "target_word": "石油", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、地面[じめん]からにじみ出[で]る石油[せきゆ]を不思議[ふしぎ]に思[おも]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "石油", "label": "基本形"}, {"form": "石油を", "label": "を格"}, {"form": "石油が", "label": "が格"}, {"form": "石油の", "label": "の格"}], "register": "標準", "sense_fingerprint": "黒くてねばり気のある、燃料や原料になる地下資源の液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38689, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石油", "is_correct": true, "explanation": "ここは「石油」。地下から出てきた黒くてどろっとした液体として文に合う。"}, {"text": "空気", "is_correct": false, "explanation": "空気は黒くてどろっとしないので、文に合わない。"}, {"text": "花", "is_correct": false, "explanation": "花は黒くてどろっとしないので、文に合わない。"}, {"text": "氷", "is_correct": false, "explanation": "氷は黒くてどろっとしないので、文に合わない。"}], "explanations": {"石油": "ここは「石油」。地下から出てきた黒くてどろっとした液体として文に合う。", "空気": "空気は黒くてどろっとしないので、文に合わない。", "花": "花は黒くてどろっとしないので、文に合わない。", "氷": "氷は黒くてどろっとしないので、文に合わない。"}, "sentence_index": 0, "correct_answer": "石油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天ぷらを揚げるのに、石油を鍋に入れた。", "explanation": "ここは〈食用油〉の意味。石油は黒くてどろっとした地下資源で、食べ物を揚げる油には使わない。"}, {"text": "床をぴかぴかにするため、石油を布で塗った。", "explanation": "ここは〈ワックス〉の意味。床を磨くワックスは別の物で、石油は床の仕上げには使わない。"}, {"text": "手紙を書くために、石油を筆につけた。", "explanation": "ここは〈墨〉の意味。筆で書く黒い液体は墨やインクで、石油は書くための液には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38689, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石油", "is_correct": true, "explanation": "ここは「石油」。タンカーが遠い国から運ぶ積み荷として文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は運んでくるものではなく、文に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "季節を船で運んでくることはなく、文に合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は船で運ぶものではなく、文に合わない。"}], "explanations": {"石油": "ここは「石油」。タンカーが遠い国から運ぶ積み荷として文に合う。", "天気": "天気は運んでくるものではなく、文に合わない。", "季節": "季節を船で運んでくることはなく、文に合わない。", "雲": "雲は船で運ぶものではなく、文に合わない。"}, "sentence_index": 6, "correct_answer": "石油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地下から掘り出した石油は、黒くて固く、燃やすと煙が出る。", "explanation": "ここは〈石炭〉の意味。石油は黒くてねばる液体で、固くはない。固い燃料で煙が出るのは石炭。"}, {"text": "石油は透明で軽い気体なので、パイプで家まで送る。", "explanation": "ここは〈天然ガス〉の意味。石油は液体で、透明な気体ではない。気体を送るのは天然ガス。"}, {"text": "汚れた手を、石油の泡で洗った。", "explanation": "ここは〈石鹸〉の意味。泡で手を洗うのは石鹸で、石油ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38689, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "油田で石油に掘り出す作業は、とても危険だ。", "corrected_sentence": "油田で石油を掘り出す作業は、とても危険だ。", "error_description": "誤り：「に」。掘り出すの対象は「を」で示す。正しい助詞は「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38689, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "石油を大量に飲み干して、価格を安定させた。", "corrected_sentence": "石油を大量に買い付けて、価格を安定させた。", "error_description": "誤り：「飲み干して」。石油は飲めないので、目的語の石油と合わない。正しい語は「買い付けて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38690, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "期待する対象を示す「に」です。"}, {"text": "の", "is_correct": false, "explanation": "「旅行の期待している」は動詞の前で使えず不適切です。"}, {"text": "と", "is_correct": false, "explanation": "「旅行と期待している」は対象を示せず不適切です。"}, {"text": "や", "is_correct": false, "explanation": "「旅行や期待している」は列挙になり動詞に続かず不適切です。"}], "correct_answer": "に", "explanations": {"に": "期待する対象を示す「に」です。", "の": "「旅行の期待している」は動詞の前で使えず不適切です。", "と": "「旅行と期待している」は対象を示せず不適切です。", "や": "「旅行や期待している」は列挙になり動詞に続かず不適切です。"}, "error_tags": {"の": "possession", "と": "quotation/accompaniment", "や": "listing"}, "sentence_index": 3}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失望", "is_correct": true, "explanation": "期待がはずれてがっかりすることで、期待の反対です。"}, {"text": "希望", "is_correct": false, "explanation": "期待に近い意味で、反対ではありません。"}, {"text": "予想", "is_correct": false, "explanation": "先を考えることで、反対の関係ではありません。"}, {"text": "満足", "is_correct": false, "explanation": "気持ちが満たされることで、期待の反対ではありません。"}], "correct_answer": "失望", "explanations": {"失望": "期待がはずれてがっかりすることで、期待の反対です。", "希望": "期待に近い意味で、反対ではありません。", "予想": "先を考えることで、反対の関係ではありません。", "満足": "気持ちが満たされることで、期待の反対ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38690, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "期待する対象を示す「に」です。"}, {"text": "か", "is_correct": false, "explanation": "「旅行か期待している」は文が成り立ちません。"}, {"text": "ね", "is_correct": false, "explanation": "「ね」は文末の助詞で、ここには入りません。"}, {"text": "ば", "is_correct": false, "explanation": "「旅行ば期待している」は名詞に付かず誤りです。"}], "correct_answer": "に", "explanations": {"に": "期待する対象を示す「に」です。", "か": "「旅行か期待している」は文が成り立ちません。", "ね": "「ね」は文末の助詞で、ここには入りません。", "ば": "「旅行ば期待している」は名詞に付かず誤りです。"}, "error_tags": {"か": "question", "ね": "sentence-final", "ば": "conditional"}, "sentence_index": 3}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "落胆", "is_correct": true, "explanation": "期待がはずれてがっかりすることで、期待の反対です。"}, {"text": "約束", "is_correct": false, "explanation": "前もって決めることで、反対の関係ではありません。"}, {"text": "準備", "is_correct": false, "explanation": "前もって整えることで、反対の関係ではありません。"}, {"text": "計画", "is_correct": false, "explanation": "先の予定を立てることで、反対の関係ではありません。"}], "correct_answer": "落胆", "explanations": {"落胆": "期待がはずれてがっかりすることで、期待の反対です。", "約束": "前もって決めることで、反対の関係ではありません。", "準備": "前もって整えることで、反対の関係ではありません。", "計画": "先の予定を立てることで、反対の関係ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38690, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これから、いいことがあるだろうと考えること。", "primary_collocate": null, "pronunciation": "きたい", "ipa": "kitai", "syllable_count": 3, "sentences": [{"text": "期待は大きい。", "target_word": "期待", "complexity_tier": "T1", "furigana": "期待[きたい]は大[おお]きい。", "sentence_source": "generated"}, {"text": "期待しています。", "target_word": "期待しています", "complexity_tier": "T2", "furigana": "期待[きたい]しています。", "sentence_source": "generated"}, {"text": "いい結果を期待します。", "target_word": "期待します", "complexity_tier": "T2", "furigana": "いい結果[けっか]を期待[きたい]します。", "sentence_source": "generated"}, {"text": "旅行に期待している。", "target_word": "期待している", "complexity_tier": "T3", "furigana": "旅行[りょこう]に期待[きたい]している。", "sentence_source": "generated"}, {"text": "期待して待っていた。", "target_word": "期待して", "complexity_tier": "T3", "furigana": "期待[きたい]して待[ま]っていた。", "sentence_source": "generated"}, {"text": "試合の前から、期待が高まった。", "target_word": "期待", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]から、期待[きたい]が高[たか]まった。", "sentence_source": "generated"}, {"text": "新しい店に期待して、友だちと行ってみた。", "target_word": "期待して", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]に期待[きたい]して、友[とも]だちと行[い]ってみた。", "sentence_source": "generated"}, {"text": "期待したより、ずっと楽しい一日だった。", "target_word": "期待した", "complexity_tier": "T3", "furigana": "期待[きたい]したより、ずっと楽[たの]しい一日[いちにち]だった。", "sentence_source": "generated"}, {"text": "彼女は期待に胸をふくらませて、手紙を開けた。", "target_word": "期待", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は期待[きたい]に胸[むね]をふくらませて、手紙[てがみ]を開[あ]けた。", "sentence_source": "generated"}, {"text": "春になればいいことがあると期待しながら、冬を過ごした。", "target_word": "期待しながら", "complexity_tier": "T4", "furigana": "春[はる]になればいいことがあると期待[きたい]しながら、冬[ふゆ]を過[す]ごした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "期待する", "label": "活用"}, {"form": "期待した", "label": "活用"}, {"form": "期待される", "label": "活用"}, {"form": "期待感", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | よいことがあると考えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: contains vocabulary far above tier T1: ふくらませ (Zipf 2.35)']::text[], '2f21d344-fdd8-4556-ab3d-6bddeaf03a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38690, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "期待", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "機会", "is_correct": false, "explanation": "「きかい」で、「た」が「か」に変わった別の語です。"}, {"text": "帰宅", "is_correct": false, "explanation": "「きたく」で、語末の「い」が「く」に変わった別の語です。"}, {"text": "機内", "is_correct": false, "explanation": "「きない」で、「た」が「な」に変わった別の語です。"}, {"text": "嫌い", "is_correct": false, "explanation": "「きらい」で、「た」が「ら」に変わった別の語です。"}, {"text": "規定", "is_correct": false, "explanation": "「きてい」で、「た」が「て」に変わった別の語です。"}], "explanations": {"期待": "見出し語そのものです。", "機会": "「きかい」で、「た」が「か」に変わった別の語です。", "帰宅": "「きたく」で、語末の「い」が「く」に変わった別の語です。", "機内": "「きない」で、「た」が「な」に変わった別の語です。", "嫌い": "「きらい」で、「た」が「ら」に変わった別の語です。", "規定": "「きてい」で、「た」が「て」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "期待"}, "level_3": {"options": [{"text": "期待", "is_correct": true, "explanation": "「期待は大きい」で、よいことを望む気持ちが大きいという意味に合います。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが、「時間は大きい」とは言わず意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気を「大きい」とは言わず意味が合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが、「宿題は大きい」では意味が合わない。"}], "explanations": {"期待": "「期待は大きい」で、よいことを望む気持ちが大きいという意味に合います。", "時間": "形は合うが、「時間は大きい」とは言わず意味が合わない。", "天気": "形は合うが、天気を「大きい」とは言わず意味が合わない。", "宿題": "形は合うが、「宿題は大きい」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "期待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "期待を食べて、朝ご飯にした。", "explanation": "期待は食べられるものではなく、気持ちを表す語なので使い方が誤りです。"}, {"text": "去年の事故を、今もとても期待している。", "explanation": "期待はこれからのよいことに使う語で、過去のつらい出来事には使えません。"}, {"text": "この箱の期待は三キロある。", "explanation": "期待は重さを量れるものではなく、気持ちなので誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
