INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38691, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "期待する内容「合格」を示す「を」です。"}, {"text": "で", "is_correct": false, "explanation": "「合格で期待している」は場所や手段を表してしまい不適切です。"}, {"text": "や", "is_correct": false, "explanation": "「合格や期待している」は列挙が動詞に続かず不適切です。"}, {"text": "より", "is_correct": false, "explanation": "「合格より期待している」は比べる相手がなく成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "期待する内容「合格」を示す「を」です。", "で": "「合格で期待している」は場所や手段を表してしまい不適切です。", "や": "「合格や期待している」は列挙が動詞に続かず不適切です。", "より": "「合格より期待している」は比べる相手がなく成り立ちません。"}, "error_tags": {"で": "location/means", "や": "listing", "より": "comparison"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失望", "is_correct": true, "explanation": "期待が外れて望みを失うことで、期待の反対にあたる。"}, {"text": "願望", "is_correct": false, "explanation": "願い望むことで、期待と近い意味。反対ではない。"}, {"text": "予想", "is_correct": false, "explanation": "先を見通すことで、期待と近い意味。反対ではない。"}, {"text": "信頼", "is_correct": false, "explanation": "相手を信じて頼ることで、期待と近い意味。反対ではない。"}], "correct_answer": "失望", "explanations": {"失望": "期待が外れて望みを失うことで、期待の反対にあたる。", "願望": "願い望むことで、期待と近い意味。反対ではない。", "予想": "先を見通すことで、期待と近い意味。反対ではない。", "信頼": "相手を信じて頼ることで、期待と近い意味。反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38691, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "ほど", "options": [{"text": "ほど", "is_correct": true, "explanation": "「期待していたほど」で、程度を表す。"}, {"text": "を", "is_correct": false, "explanation": "「期待していたを」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「期待していたへ」は文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「期待していたに」は文として成り立たない。"}], "correct_answer": "ほど", "explanations": {"ほど": "「期待していたほど」で、程度を表す。", "を": "「期待していたを」は文として成り立たない。", "へ": "「期待していたへ」は文として成り立たない。", "に": "「期待していたに」は文として成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "に": "target_marker"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "諦め", "is_correct": true, "explanation": "実現を願うことをやめることで、期待の反対にあたる。"}, {"text": "希望", "is_correct": false, "explanation": "望みを持つことで、期待と近い意味。反対ではない。"}, {"text": "予測", "is_correct": false, "explanation": "先を見通すことで、期待と近い意味。反対ではない。"}, {"text": "要求", "is_correct": false, "explanation": "相手に求めることで、期待と近い意味。反対ではない。"}], "correct_answer": "諦め", "explanations": {"諦め": "実現を願うことをやめることで、期待の反対にあたる。", "希望": "望みを持つことで、期待と近い意味。反対ではない。", "予測": "先を見通すことで、期待と近い意味。反対ではない。", "要求": "相手に求めることで、期待と近い意味。反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38691, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることが実現するだろうと予想して、そうなることを強く願うこと。", "primary_collocate": null, "pronunciation": "きたい", "ipa": "kitai", "syllable_count": 3, "sentences": [{"text": "父は息子の合格を期待している。", "target_word": "期待している", "complexity_tier": "T3", "furigana": "父[ちち]は息子[むすこ]の合格[ごうかく]を期待[きたい]している。", "sentence_source": "generated"}, {"text": "期待しています。", "target_word": "期待しています", "complexity_tier": "T2", "furigana": "期待[きたい]しています。", "sentence_source": "generated"}, {"text": "期待が大きいです。", "target_word": "期待", "complexity_tier": "T2", "furigana": "期待[きたい]が大[おお]きいです。", "sentence_source": "generated"}, {"text": "母は私に期待している。", "target_word": "期待している", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]に期待[きたい]している。", "sentence_source": "generated"}, {"text": "みんなの期待に応えたい。", "target_word": "期待", "complexity_tier": "T3", "furigana": "みんなの期待[きたい]に応[こた]えたい。", "sentence_source": "generated"}, {"text": "期待どおりの結果が出た。", "target_word": "期待", "complexity_tier": "T3", "furigana": "期待[きたい]どおりの結果[けっか]が出[で]た。", "sentence_source": "generated"}, {"text": "新しい先生には、大きな期待をかけている。", "target_word": "期待", "complexity_tier": "T3", "furigana": "新[あたら]しい先生[せんせい]には、大[おお]きな期待[きたい]をかけている。", "sentence_source": "generated"}, {"text": "期待していたほど、料理はおいしくなかった。", "target_word": "期待していた", "complexity_tier": "T4", "furigana": "期待[きたい]していたほど、料理[りょうり]はおいしくなかった。", "sentence_source": "generated"}, {"text": "彼の才能に期待して、会社は大きな仕事を任せた。", "target_word": "期待して", "complexity_tier": "T4", "furigana": "彼[かれ]の才能[さいのう]に期待[きたい]して、会社[かいしゃ]は大[おお]きな仕事[しごと]を任[まか]せた。", "sentence_source": "generated"}, {"text": "期待が高すぎると、結果に失望しやすい。", "target_word": "期待", "complexity_tier": "T4", "furigana": "期待[きたい]が高[たか]すぎると、結果[けっか]に失望[しつぼう]しやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "期待する", "label": "活用"}, {"form": "期待した", "label": "活用"}, {"form": "期待される", "label": "活用"}, {"form": "期待感", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 実現を予想し強く願うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f21d344-fdd8-4556-ab3d-6bddeaf03a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38691, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "期待", "is_correct": true, "explanation": "見出し語「きたい」そのもの。"}, {"text": "機会", "is_correct": false, "explanation": "「きかい」は「た」が「か」に変わる1拍違いの別語。"}, {"text": "機内", "is_correct": false, "explanation": "「きない」は「た」が「な」に変わる1拍違いの別語。"}, {"text": "嫌い", "is_correct": false, "explanation": "「きらい」は「た」が「ら」に変わる1拍違いの別語。"}, {"text": "死体", "is_correct": false, "explanation": "「したい」は「き」が「し」に変わる1拍違いの別語。"}], "explanations": {"期待": "見出し語「きたい」そのもの。", "機会": "「きかい」は「た」が「か」に変わる1拍違いの別語。", "機内": "「きない」は「た」が「な」に変わる1拍違いの別語。", "嫌い": "「きらい」は「た」が「ら」に変わる1拍違いの別語。", "死体": "「したい」は「き」が「し」に変わる1拍違いの別語。"}, "sentence_index": null, "correct_answer": "期待"}, "level_3": {"options": [{"text": "期待", "is_correct": true, "explanation": "息子が合格することを願っているという意味に合います。"}, {"text": "掃除", "is_correct": false, "explanation": "形は合うが、「合格を掃除している」では意味が合わない。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが、「合格を運転している」では意味が合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが、「合格を洗濯している」では意味が合わない。"}], "explanations": {"期待": "息子が合格することを願っているという意味に合います。", "掃除": "形は合うが、「合格を掃除している」では意味が合わない。", "運転": "形は合うが、「合格を運転している」では意味が合わない。", "洗濯": "形は合うが、「合格を洗濯している」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "期待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は台所で、期待を細かく切っている。", "explanation": "期待は包丁で切れる物ではなく気持ちなので誤りです。"}, {"text": "私は昨日、駅で友達を期待して電車に乗った。", "explanation": "「期待する」は「待つ」の意味では使えない。"}, {"text": "彼は自分の失敗を期待して、深く反省した。", "explanation": "「期待する」は「後悔する」の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38691, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "期待", "is_correct": true, "explanation": "見出し語「きたい」そのもの。"}, {"text": "帰宅", "is_correct": false, "explanation": "「きたく」は「い」が「く」に変わる1拍違いの別語。"}, {"text": "額", "is_correct": false, "explanation": "「ひたい」は「き」が「ひ」に変わる1拍違いの別語。"}, {"text": "地帯", "is_correct": false, "explanation": "「ちたい」は「き」が「ち」に変わる1拍違いの別語。"}, {"text": "危害", "is_correct": false, "explanation": "「きがい」は「た」が「が」に変わる1拍違いの別語。"}], "explanations": {"期待": "見出し語「きたい」そのもの。", "帰宅": "「きたく」は「い」が「く」に変わる1拍違いの別語。", "額": "「ひたい」は「き」が「ひ」に変わる1拍違いの別語。", "地帯": "「ちたい」は「き」が「ち」に変わる1拍違いの別語。", "危害": "「きがい」は「た」が「が」に変わる1拍違いの別語。"}, "sentence_index": null, "correct_answer": "期待"}, "level_3": {"options": [{"text": "期待", "is_correct": true, "explanation": "「期待をかける」は先生に望みを託す自然な表現。"}, {"text": "空気", "is_correct": false, "explanation": "形は合うが、空気をかけるという意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節をかけるという意味が合わない。"}, {"text": "履歴", "is_correct": false, "explanation": "形は合うが、履歴をかけるという意味が合わない。"}], "explanations": {"期待": "「期待をかける」は先生に望みを託す自然な表現。", "空気": "形は合うが、空気をかけるという意味が合わない。", "季節": "形は合うが、季節をかけるという意味が合わない。", "履歴": "形は合うが、履歴をかけるという意味が合わない。"}, "sentence_index": 6, "correct_answer": "期待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、部屋の窓を期待して空気を入れ替えている。", "explanation": "「期待する」は「開ける」の意味では使えない。"}, {"text": "この道は期待が広くて、車がたくさん通る。", "explanation": "「期待」は「幅」の意味では使えない。"}, {"text": "期待を三本買って、花びんにさした。", "explanation": "期待は花のように買って飾る物ではなく気持ちなので誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.valida