INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38692, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「真だと」の「と」。「わかった」の内容を導く引用の「と」で、ここでは正しい。"}, {"text": "を", "is_correct": false, "explanation": "「わかる」は「何を」を目的語にとるが、「真だを」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「真だに」は助詞の接続として不自然で、「わかった」にも続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、ここでは意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "「真だと」の「と」。「わかった」の内容を導く引用の「と」で、ここでは正しい。", "を": "「わかる」は「何を」を目的語にとるが、「真だを」は成り立たない。", "に": "「真だに」は助詞の接続として不自然で、「わかった」にも続かない。", "へ": "「へ」は方向を表すので、ここでは意味が通らない。"}, "error_tags": {"を": "目的語", "に": "位置", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偽", "is_correct": true, "explanation": "「真偽」の対になる語で、「本当でないこと」を表す対義語。"}, {"text": "理由", "is_correct": false, "explanation": "名詞だが、真の対義語ではない。「理由をつける」の語で、真偽とは対にならない。"}, {"text": "結論", "is_correct": false, "explanation": "名詞だが、真の対義語ではない。判断の終わりを指し、真偽の対にはならない。"}, {"text": "方法", "is_correct": false, "explanation": "名詞だが、真の対義語ではない。やり方を指し、真偽とは対にならない。"}], "correct_answer": "偽", "explanations": {"偽": "「真偽」の対になる語で、「本当でないこと」を表す対義語。", "理由": "名詞だが、真の対義語ではない。「理由をつける」の語で、真偽とは対にならない。", "結論": "名詞だが、真の対義語ではない。判断の終わりを指し、真偽の対にはならない。", "方法": "名詞だが、真の対義語ではない。やり方を指し、真偽とは対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
