INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38692, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "本当のこと。うそではないこと。", "primary_collocate": null, "pronunciation": "しん", "ipa": "ɕiɴ", "syllable_count": 2, "sentences": [{"text": "彼の話が真か偽か、まだ誰にもわからない。", "target_word": "真", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]が真[しん]か偽[ぎ]か、まだ誰[だれ]にもわからない。", "sentence_source": "generated"}, {"text": "調べた結果、うわさは真だとわかった。", "target_word": "真", "complexity_tier": "T3", "furigana": "調[しら]べた結果[けっか]、うわさは真[しん]だとわかった。", "sentence_source": "generated"}, {"text": "先生は、真と偽を見分ける力を身につけなさいと言った。", "target_word": "真", "complexity_tier": "T3", "furigana": "先生[せんせい]は、真[しん]と偽[にせ]を見分[みわ]ける力[ちから]を身[み]につけなさいと言[い]った。", "sentence_source": "generated"}, {"text": "この文が真か偽かを、理由をつけて答えてください。", "target_word": "真", "complexity_tier": "T3", "furigana": "この文[ぶん]が真[しん]か偽[ぎ]かを、理由[りゆう]をつけて答[こた]えてください。", "sentence_source": "generated"}, {"text": "彼の言葉が真であることを、証拠が示している。", "target_word": "真", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]が真[しん]であることを、証拠[しょうこ]が示[しめ]している。", "sentence_source": "generated"}, {"text": "命題が真であれば、その答えは正しいことになる。", "target_word": "真", "complexity_tier": "T3", "furigana": "命題[めいだい]が真[しん]であれば、その答[こた]えは正[ただ]しいことになる。", "sentence_source": "generated"}, {"text": "古い言い伝えだが、真であると信じる人は多い。", "target_word": "真", "complexity_tier": "T3", "furigana": "古[ふる]い言[い]い伝[つた]えだが、真[しん]であると信[しん]じる人[ひと]は多[おお]い。", "sentence_source": "generated"}, {"text": "友人の言うことが真なら、すぐに警察に知らせるべきだ。", "target_word": "真", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の言[い]うことが真[しん]なら、すぐに警察[けいさつ]に知[し]らせるべきだ。", "sentence_source": "generated"}, {"text": "その報告は真だったので、会社は急いで対応した。", "target_word": "真", "complexity_tier": "T3", "furigana": "その報告[ほうこく]は真[しん]だったので、会社[かいしゃ]は急[いそ]いで対応[たいおう]した。", "sentence_source": "generated"}, {"text": "真と偽が入りまじった情報の中から、事実を探した。", "target_word": "真", "complexity_tier": "T3", "furigana": "真[しん]と偽[ぎ]が入[い]りまじった情報[じょうほう]の中[なか]から、事実[じじつ]を探[さが]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "真", "label": "基本形"}, {"form": "真だ", "label": "断定形"}, {"form": "真であれば", "label": "仮定形"}, {"form": "真の", "label": "連体形"}], "register": "書き言葉", "sense_fingerprint": "偽りでない、本当であること(偽の対)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 入りまじっ (Zipf 1.06)']::text[], '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38692, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真", "is_correct": true, "explanation": "「本当のこと」を表す名詞。「彼の話が真か偽か」の位置に入り、意味が通る。"}, {"text": "海", "is_correct": false, "explanation": "名詞だが、「彼の話が海か偽か」は意味をなさない。"}, {"text": "机", "is_correct": false, "explanation": "名詞だが、「彼の話が机か偽か」は意味をなさない。"}, {"text": "花", "is_correct": false, "explanation": "名詞だが、「彼の話が花か偽か」は意味をなさない。"}], "explanations": {"真": "「本当のこと」を表す名詞。「彼の話が真か偽か」の位置に入り、意味が通る。", "海": "名詞だが、「彼の話が海か偽か」は意味をなさない。", "机": "名詞だが、「彼の話が机か偽か」は意味をなさない。", "花": "名詞だが、「彼の話が花か偽か」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この壺は真だと鑑定されたので、高値で売れた。", "explanation": "ここは〈本物〉の意味。真は話や報告の内容がうそでないことを表し、物が本物かどうかは〈本物〉で言う。"}, {"text": "真夏の太陽が照りつけ、池の水がぬるくなった。", "explanation": "接頭語の〈まっ盛り〉（真夏）の用法。真は名詞として話の内容がうそでないことを表し、季節の強調には使わない。"}, {"text": "その船は真南へ進んだ。", "explanation": "接頭語の〈まっすぐ〉（真南）の用法。真は名詞として話の内容がうそでないことを表し、方角の強調には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38692, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真", "is_correct": true, "explanation": "「本当のこと」を表す名詞。「古い言い伝えが本当だと信じる」の意味に合う。"}, {"text": "山", "is_correct": false, "explanation": "名詞だが、「山であると信じる人」は意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "名詞だが、「窓であると信じる人」は意味が通らない。"}, {"text": "雪", "is_correct": false, "explanation": "名詞だが、「雪であると信じる人」は意味が通らない。"}], "explanations": {"真": "「本当のこと」を表す名詞。「古い言い伝えが本当だと信じる」の意味に合う。", "山": "名詞だが、「山であると信じる人」は意味が通らない。", "窓": "名詞だが、「窓であると信じる人」は意味が通らない。", "雪": "名詞だが、「雪であると信じる人」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "真"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "真冬の朝、池が一面に凍った。", "explanation": "接頭語の〈まっ盛り〉（真冬）の用法。真は名詞として話の内容がうそでないことを表し、季節の強調には使わない。"}, {"text": "真上に向かって、ロケットが打ち上がった。", "explanation": "接頭語の〈まっすぐ〉（真上）の用法。真は名詞として話の内容がうそでないことを表し、方向の強調には使わない。"}, {"text": "朝日で空が真っ赤に染まった。", "explanation": "接頭語の〈非常に〉（真っ赤）の用法。真は名詞として話の内容がうそでないことを表し、色の強調には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38692, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その報告が真のとわかった。", "corrected_sentence": "その報告が真だとわかった。", "error_description": "「真」は名詞なので、述語は「真だ」（「真だと」）になる。「真のと」の「の」は後ろに名詞が続く形で、ここでは続かないため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38692, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その話が真をどうか、確かめよう。", "corrected_sentence": "その話が真かどうか、確かめよう。", "error_description": "「真かどうか」の「か」は選択を表す助詞。「を」にすると「真をどうか」となり、「どうか」と続かず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
