INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38694, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "他のものを通してつながること", "primary_collocate": null, "pronunciation": "かんせつ", "ipa": "kansetsɯ", "syllable_count": 4, "sentences": [{"text": "間接的に知りました。", "target_word": "間接的に", "complexity_tier": "T2", "furigana": "間接的[かんせつてき]に知[し]りました。", "sentence_source": "generated"}, {"text": "間接の影響を受けた。", "target_word": "間接", "complexity_tier": "T2", "furigana": "間接[かんせつ]の影響[えいきょう]を受[う]けた。", "sentence_source": "generated"}, {"text": "友人を通して間接に連絡した。", "target_word": "間接に", "complexity_tier": "T3", "furigana": "友人[ゆうじん]を通[とお]して間接[かんせつ]に連絡[れんらく]した。", "sentence_source": "generated"}, {"text": "直接より間接のほうが安全だ。", "target_word": "間接", "complexity_tier": "T3", "furigana": "直接[ちょくせつ]より間接[かんせつ]のほうが安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "間接的な方法で問題を解く。", "target_word": "間接的な", "complexity_tier": "T3", "furigana": "間接的[かんせつてき]な方法[ほうほう]で問題[もんだい]を解[と]く。", "sentence_source": "generated"}, {"text": "間接的に聞いた話を信じるのは危険だ。", "target_word": "間接的に", "complexity_tier": "T4", "furigana": "間接的[かんせつてき]に聞[き]いた話[はなし]を信[しん]じるのは危険[きけん]だ。", "sentence_source": "generated"}, {"text": "彼は間接的に私を助けてくれた。", "target_word": "間接的に", "complexity_tier": "T3", "furigana": "彼[かれ]は間接的[かんせつてき]に私[わたし]を助[たす]けてくれた。", "sentence_source": "generated"}, {"text": "その話は直接ではなく、間接に聞いた。", "target_word": "間接に", "complexity_tier": "T3", "furigana": "その話[はなし]は直接[ちょくせつ]ではなく、間接[かんせつ]に聞[き]いた。", "sentence_source": "generated"}, {"text": "事故の間接的な原因を調べた。", "target_word": "間接的な", "complexity_tier": "T3", "furigana": "事故[じこ]の間接的[かんせつてき]な原因[げんいん]を調[しら]べた。", "sentence_source": "generated"}, {"text": "間接でも責任はあります。", "target_word": "間接", "complexity_tier": "T3", "furigana": "間接[かんせつ]でも責任[せきにん]はあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "間接的", "label": "派生"}, {"form": "間接税", "label": "派生"}, {"form": "間接照明", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 他のものを通してつながること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be06c00-e07b-4845-a5a1-5b9d6c46fb56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38694, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "間接", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "感染", "is_correct": false, "explanation": "かんせん。つ→んの一音だけが違う別語。"}, {"text": "観察", "is_correct": false, "explanation": "かんさつ。せ→さの一音だけが違う別語。"}, {"text": "簡潔", "is_correct": false, "explanation": "かんけつ。せ→けの一音だけが違う別語。"}, {"text": "完成", "is_correct": false, "explanation": "かんせい。つ→いの一音だけが違う別語。"}], "explanations": {"間接": "見出し語そのもの。", "感染": "かんせん。つ→んの一音だけが違う別語。", "観察": "かんさつ。せ→さの一音だけが違う別語。", "簡潔": "かんけつ。せ→けの一音だけが違う別語。", "完成": "かんせい。つ→いの一音だけが違う別語。"}, "sentence_index": null, "correct_answer": "間接"}, "level_3": {"options": [{"text": "間接的に", "is_correct": true, "explanation": "「間接的に知る」で、他を通して知る意味になる。"}, {"text": "一時的に", "is_correct": false, "explanation": "形は合うが、「一時的に知りました」では知り方として意味が合わない。"}, {"text": "感情的に", "is_correct": false, "explanation": "形は合うが、「感情的に知りました」では意味が通りにくい。"}, {"text": "立体的に", "is_correct": false, "explanation": "形は合うが、「立体的に知りました」では知り方として意味が合わない。"}], "explanations": {"間接的に": "「間接的に知る」で、他を通して知る意味になる。", "一時的に": "形は合うが、「一時的に知りました」では知り方として意味が合わない。", "感情的に": "形は合うが、「感情的に知りました」では意味が通りにくい。", "立体的に": "形は合うが、「立体的に知りました」では知り方として意味が合わない。"}, "sentence_index": 0, "correct_answer": "間接的に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "間接を食べて、お腹がいっぱいになった。", "explanation": "「間接」は食べ物ではなく、他を通してつながる関係を表す語。"}, {"text": "この部屋は間接で、とても広い。", "explanation": "「間接」は部屋の広さを表さない。"}, {"text": "彼は間接に歩いて、駅まで行った。", "explanation": "「間接に」は歩き方を表さない。つながり方を表す語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.val