INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38695, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物事が直接ではなく、他のものを介して関係すること", "primary_collocate": null, "pronunciation": "かんせつ", "ipa": "kansetsɯ", "syllable_count": 4, "sentences": [{"text": "具体的には、無垢材の家具と白壁の組み合わせ、あるいは間接照明による陰影の演出などが効果的です。", "target_word": "間接", "complexity_tier": "T6", "furigana": "具体的[ぐたいてき]には、無垢材[むくざい]の家具[かぐ]と白壁[しろかべ]の組[く]み合[あ]わせ、あるいは間接照明[かんせつしょうめい]による陰影[いんえい]の演出[えんしゅつ]などが効果的[こうかてき]です。", "sentence_source": "mined"}, {"text": "間接的に聞きました。", "target_word": "間接的に", "complexity_tier": "T2", "furigana": "間接的[かんせつてき]に聞[き]きました。", "sentence_source": "generated"}, {"text": "それは間接的に聞いた話です。", "target_word": "間接的に", "complexity_tier": "T3", "furigana": "それは間接的[かんせつてき]に聞[き]いた話[はなし]です。", "sentence_source": "generated"}, {"text": "直接ではなく間接に伝えた。", "target_word": "間接に", "complexity_tier": "T3", "furigana": "直接[ちょくせつ]ではなく間接[かんせつ]に伝[つた]えた。", "sentence_source": "generated"}, {"text": "間接的な言い方は丁寧に聞こえる。", "target_word": "間接的な", "complexity_tier": "T3", "furigana": "間接的[かんせつてき]な言[い]い方[かた]は丁寧[ていねい]に聞[き]こえる。", "sentence_source": "generated"}, {"text": "直接と間接の違いを調べる。", "target_word": "間接", "complexity_tier": "T3", "furigana": "直接[ちょくせつ]と間接[かんせつ]の違[ちが]いを調[しら]べる。", "sentence_source": "generated"}, {"text": "彼の失敗は、間接的に私にも関係がある。", "target_word": "間接的に", "complexity_tier": "T4", "furigana": "彼[かれ]の失敗[しっぱい]は、間接的[かんせつてき]に私[わたし]にも関係[かんけい]がある。", "sentence_source": "generated"}, {"text": "人を通して間接に頼むことにした。", "target_word": "間接に", "complexity_tier": "T3", "furigana": "人[ひと]を通[とお]して間接[かんせつ]に頼[たの]むことにした。", "sentence_source": "generated"}, {"text": "間接的な影響も無視できない。", "target_word": "間接的な", "complexity_tier": "T3", "furigana": "間接的[かんせつてき]な影響[えいきょう]も無視[むし]できない。", "sentence_source": "generated"}, {"text": "間接的に言われて、気づかなかった。", "target_word": "間接的に", "complexity_tier": "T4", "furigana": "間接的[かんせつてき]に言[い]われて、気[き]づかなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "間接的", "label": "派生"}, {"form": "間接税", "label": "派生"}, {"form": "間接照明", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 直接でなく他を介して関わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be06c00-e07b-4845-a5a1-5b9d6c46fb56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
