INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38695, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "間接", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "幹線", "is_correct": false, "explanation": "かんせん。つ→んの一音だけが違う別語。"}, {"text": "貫徹", "is_correct": false, "explanation": "かんてつ。せ→ての一音だけが違う別語。"}, {"text": "歓声", "is_correct": false, "explanation": "かんせい。つ→いの一音だけが違う別語。"}, {"text": "乾湿", "is_correct": false, "explanation": "かんしつ。せ→しの一音だけが違う別語。"}], "explanations": {"間接": "見出し語そのもの。", "幹線": "かんせん。つ→んの一音だけが違う別語。", "貫徹": "かんてつ。せ→ての一音だけが違う別語。", "歓声": "かんせい。つ→いの一音だけが違う別語。", "乾湿": "かんしつ。せ→しの一音だけが違う別語。"}, "sentence_index": null, "correct_answer": "間接"}, "level_3": {"options": [{"text": "間接的に", "is_correct": true, "explanation": "「間接的に関係がある」で、他を介して関わる意味になる。"}, {"text": "芸術的に", "is_correct": false, "explanation": "形は合うが、「芸術的に関係がある」では失敗との関わり方として意味が合わない。"}, {"text": "感情的に", "is_correct": false, "explanation": "形は合うが、他人の失敗との関係を表す意味としては合わない。"}, {"text": "積極的に", "is_correct": false, "explanation": "形は合うが、「積極的に関係がある」では意味が合わない。"}], "explanations": {"間接的に": "「間接的に関係がある」で、他を介して関わる意味になる。", "芸術的に": "形は合うが、「芸術的に関係がある」では失敗との関わり方として意味が合わない。", "感情的に": "形は合うが、他人の失敗との関係を表す意味としては合わない。", "積極的に": "形は合うが、「積極的に関係がある」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "間接的に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "間接的に走ったので、とても疲れた。", "explanation": "「間接的に」は走り方を表さない。他を介することを表す語。"}, {"text": "彼は間接的な犬を飼っている。", "explanation": "「間接的な」は動物の種類や性質を表す語ではない。"}, {"text": "間接的に暑い日で、水をたくさん飲んだ。", "explanation": "「間接的に」は「とても」の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = 