INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38695, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "間接な理由で、彼は会社を辞めた。", "corrected_sentence": "間接的な理由で、彼は会社を辞めた。", "error_description": "「理由」を修飾する形は「間接な」ではなく「間接的な」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38695, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "間接的の影響が出たので、対策を考えた。", "corrected_sentence": "間接的な影響が出たので、対策を考えた。", "error_description": "名詞「影響」を修飾する形は「間接的の」ではなく「間接的な」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38696, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "除く", "is_correct": true, "explanation": "「含める」の対義語。数や範囲から外す意味で、含めるの反対になる。"}, {"text": "眺める", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。見て楽しむ意味。"}, {"text": "運ぶ", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。物を移動させる意味。"}, {"text": "集める", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。一か所に寄せる意味。"}], "correct_answer": "除く", "explanations": {"除く": "「含める」の対義語。数や範囲から外す意味で、含めるの反対になる。", "眺める": "動詞だが、含めるの対義語ではない。見て楽しむ意味。", "運ぶ": "動詞だが、含めるの対義語ではない。物を移動させる意味。", "集める": "動詞だが、含めるの対義語ではない。一か所に寄せる意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38696, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「新しい案を含めれば」の「を」。「含める」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「新しい案が含めれば」は、含めるに目的語がなく成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「新しい案に含めれば」は「に」が重なり、含める対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、含める対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "「新しい案を含めれば」の「を」。「含める」の目的語を示す。", "が": "「新しい案が含めれば」は、含めるに目的語がなく成り立たない。", "に": "「新しい案に含めれば」は「に」が重なり、含める対象を示せない。", "へ": "「へ」は方向を表すので、含める対象には使えない。"}, "error_tags": {"が": "主語", "に": "位置", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "除く", "is_correct": true, "explanation": "「含める」の対義語。数や範囲から外す意味で、含めるの反対になる。"}, {"text": "描く", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。絵や線で表す意味。"}, {"text": "焼く", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。火で加熱する意味。"}, {"text": "叩く", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。打つ意味。"}], "correct_answer": "除く", "explanations": {"除く": "「含める」の対義語。数や範囲から外す意味で、含めるの反対になる。", "描く": "動詞だが、含めるの対義語ではない。絵や線で表す意味。", "焼く": "動詞だが、含めるの対義語ではない。火で加熱する意味。", "叩く": "動詞だが、含めるの対義語ではない。打つ意味。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38696, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ふくめる。数や範囲の中に入れて、全体の一部として数えること。", "primary_collocate": null, "pronunciation": "ふくめる", "ipa": "ɸɯkɯmeɾɯ", "syllable_count": 4, "sentences": [{"text": "私を含めて、五人がパーティーに参加した。", "target_word": "含めて", "complexity_tier": "T3", "furigana": "私[わたし]を含[ふく]めて、五人[ごにん]がパーティーに参加[さんか]した。", "sentence_source": "generated"}, {"text": "値段には、消費税も含めてあります。", "target_word": "含めて", "complexity_tier": "T3", "furigana": "値段[ねだん]には、消費税[しょうひぜい]も含[ふく]めてあります。", "sentence_source": "generated"}, {"text": "子どもを含めると、全部で十人になる。", "target_word": "含めると", "complexity_tier": "T3", "furigana": "子[こ]どもを含[ふく]めると、全部[ぜんぶ]で十人[じゅうにん]になる。", "sentence_source": "generated"}, {"text": "費用に食事代を含めるかどうか、先生に聞いた。", "target_word": "含める", "complexity_tier": "T3", "furigana": "費用[ひよう]に食事代[しょくじだい]を含[ふく]めるかどうか、先生[せんせい]に聞[き]いた。", "sentence_source": "generated"}, {"text": "彼は自分の失敗も含めて、すべて正直に話した。", "target_word": "含めて", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の失敗[しっぱい]も含[ふく]めて、すべて正直[しょうじき]に話[はな]した。", "sentence_source": "generated"}, {"text": "送料を含めた金額を、先に教えてください。", "target_word": "含めた", "complexity_tier": "T3", "furigana": "送料[そうりょう]を含[ふく]めた金額[きんがく]を、先[さき]に教[おし]えてください。", "sentence_source": "generated"}, {"text": "欠席者を含めないで、出席の数を数えた。", "target_word": "含めないで", "complexity_tier": "T3", "furigana": "欠席者[けっせきしゃ]を含[ふく]めないで、出席[しゅっせき]の数[かず]を数[かぞ]えた。", "sentence_source": "generated"}, {"text": "計画に新しい案を含めれば、もっと良くなる。", "target_word": "含めれば", "complexity_tier": "T3", "furigana": "計画[けいかく]に新[あたら]しい案[あん]を含[ふく]めれば、もっと良[よ]くなる。", "sentence_source": "generated"}, {"text": "荷物の重さは、かばんも含めて量ってください。", "target_word": "含めて", "complexity_tier": "T3", "furigana": "荷物[にもつ]の重[おも]さは、かばんも含[ふく]めて量[はか]ってください。", "sentence_source": "generated"}, {"text": "休みの日を含めると、旅行は七日間だ。", "target_word": "含めると", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]を含[ふく]めると、旅行[りょこう]は七日間[なのかかん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "含める", "label": "終止形"}, {"form": "含めた", "label": "過去形"}, {"form": "含めて", "label": "て形"}, {"form": "含めない", "label": "否定形"}, {"form": "含めれば", "label": "仮定形"}, {"form": "含められる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "数や範囲の中に、あるものを入れて考えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38696, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "含めて", "is_correct": true, "explanation": "「私を含めて、五人」の形で、対象を数に入れて並べる意味に合う。"}, {"text": "磨いて", "is_correct": false, "explanation": "「私を磨いて、五人が」は意味が通らない。"}, {"text": "割って", "is_correct": false, "explanation": "「私を割って、五人が」は意味が通らない。"}, {"text": "冷やして", "is_correct": false, "explanation": "「私を冷やして、五人が」は意味が通らない。"}], "explanations": {"含めて": "「私を含めて、五人」の形で、対象を数に入れて並べる意味に合う。", "磨いて": "「私を磨いて、五人が」は意味が通らない。", "割って": "「私を割って、五人が」は意味が通らない。", "冷やして": "「私を冷やして、五人が」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "含めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は子どもの靴を玄関の前に含めた。", "explanation": "ここは〈置く〉の意味。「含める」は数や範囲に入れることで、物を所定の場所に置く動作には使わない。"}, {"text": "かばんに本を含めて、駅へ向かった。", "explanation": "ここは〈入れる〉の意味。「含める」は数や範囲に入れることで、物を容器に入れる動作には使わない。"}, {"text": "強い風で、旗を柱に含めた。", "explanation": "ここは〈結びつける〉の意味。「含める」は数や範囲に入れることで、物を柱に縛る動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38696, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "含めないで", "is_correct": true, "explanation": "「含めない」のて形。「欠席者を含めないで」の形で、対象を数に入れない意味に合う。"}, {"text": "眠って", "is_correct": false, "explanation": "「欠席者を眠って」は意味が通らない。"}, {"text": "振って", "is_correct": false, "explanation": "「欠席者を振って」は意味が通らない。"}, {"text": "煮て", "is_correct": false, "explanation": "「欠席者を煮て」は意味が通らない。"}], "explanations": {"含めないで": "「含めない」のて形。「欠席者を含めないで」の形で、対象を数に入れない意味に合う。", "眠って": "「欠席者を眠って」は意味が通らない。", "振って": "「欠席者を振って」は意味が通らない。", "煮て": "「欠席者を煮て」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "含めないで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ご飯を茶碗に含めて、食卓へ運んだ。", "explanation": "ここは〈盛る〉の意味。「含める」は数や範囲に入れることで、器に食べ物を盛る動作には使わない。"}, {"text": "コップに水を含めて、ゆっくり飲んだ。", "explanation": "ここは〈注ぐ〉の意味。「含める」は数や範囲に入れることで、容器に液体を注ぐ動作には使わない。"}, {"text": "棚に荷物を含めて、扉を閉めた。", "explanation": "ここは〈乗せる〉の意味。「含める」は数や範囲に入れることで、物を置く動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38696, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女を含めに、三人が参加した。", "corrected_sentence": "彼女を含めて、三人が参加した。", "error_description": "「含める」の後は「て」で続けて「〜を含めて」と言う。「含めに」という形は存在せず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "含めて", "is_correct": true, "explanation": "て形。「含めてあります」の「含めて」で、「〜てある」に続く形。"}, {"text": "含めた", "is_correct": false, "explanation": "た形は過去や完了を表し、「含めたあります」の形にはならない。"}, {"text": "含めない", "is_correct": false, "explanation": "否定形。消費税を入れない意味になり、文の内容と逆になる。"}, {"text": "含めれば", "is_correct": false, "explanation": "仮定形。「含めれば、〜てあります」とは続かず、文の形が合わない。"}], "correct_form": "含めて", "base_form": "含める", "form_label": "て形", "sentence_index": 1, "explanations": {"含めて": "て形。「含めてあります」の「含めて」で、「〜てある」に続く形。", "含めた": "た形は過去や完了を表し、「含めたあります」の形にはならない。", "含めない": "否定形。消費税を入れない意味になり、文の内容と逆になる。", "含めれば": "仮定形。「含めれば、〜てあります」とは続かず、文の形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38696, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遅刻者が含めないで、人数を数えた。", "corrected_sentence": "遅刻者を含めないで、人数を数えた。", "error_description": "「含める」は他動詞なので、対象は「を」で示す。「が」にすると目的語がなくなり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "含めれば", "is_correct": true, "explanation": "仮定形。「含めれば、もっと良くなる」の条件を表す形に合う。"}, {"text": "含めます", "is_correct": false, "explanation": "丁寧形。文の普通体と合わず、条件の文として続かない。"}, {"text": "含めよう", "is_correct": false, "explanation": "意志形。「〜しよう」の意味になり、条件の文に合わない。"}, {"text": "含めている", "is_correct": false, "explanation": "進行形。「含めている」は継続を表し、条件の文に合わない。"}], "correct_form": "含めれば", "base_form": "含める", "form_label": "仮定形", "sentence_index": 7, "explanations": {"含めれば": "仮定形。「含めれば、もっと良くなる」の条件を表す形に合う。", "含めます": "丁寧形。文の普通体と合わず、条件の文として続かない。", "含めよう": "意志形。「〜しよう」の意味になり、条件の文に合わない。", "含めている": "進行形。「含めている」は継続を表し、条件の文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38697, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "除く", "is_correct": true, "explanation": "「含める」の対義語。数や範囲から外す意味で、含めるの反対になる。"}, {"text": "買う", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。金銭で手に入れる意味。"}, {"text": "並べる", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。順に置く意味。"}, {"text": "結ぶ", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。ひもや関係をつなぐ意味。"}], "correct_answer": "除く", "explanations": {"除く": "「含める」の対義語。数や範囲から外す意味で、含めるの反対になる。", "買う": "動詞だが、含めるの対義語ではない。金銭で手に入れる意味。", "並べる": "動詞だが、含めるの対義語ではない。順に置く意味。", "結ぶ": "動詞だが、含めるの対義語ではない。ひもや関係をつなぐ意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38697, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「私を含めた」の「を」。「含める」の対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「私に含めた三人」は対象を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、含める対象には使えない。"}, {"text": "で", "is_correct": false, "explanation": "「私で含めた」は手段の意味になり、含める対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「私を含めた」の「を」。「含める」の対象を示す。", "に": "「私に含めた三人」は対象を示せず、不自然。", "へ": "「へ」は方向を示すので、含める対象には使えない。", "で": "「私で含めた」は手段の意味になり、含める対象として成り立たない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "で": "手段"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "除く", "is_correct": true, "explanation": "「含める」の対義語。数や範囲から外す意味で、含めるの反対になる。"}, {"text": "描く", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。絵や線で表す意味。"}, {"text": "焼く", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。火で加熱する意味。"}, {"text": "叩く", "is_correct": false, "explanation": "動詞だが、含めるの対義語ではない。打つ意味。"}], "correct_answer": "除く", "explanations": {"除く": "「含める」の対義語。数や範囲から外す意味で、含めるの反対になる。", "描く": "動詞だが、含めるの対義語ではない。絵や線で表す意味。", "焼く": "動詞だが、含めるの対義語ではない。火で加熱する意味。", "叩く": "動詞だが、含めるの対義語ではない。打つ意味。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38697, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "全体の一部として、数や範囲の中に入れて数えること。", "primary_collocate": null, "pronunciation": "ふくめる", "ipa": "ɸɯkɯmeɾɯ", "syllable_count": 4, "sentences": [{"text": "税金を含めると、全部で一万円になります。", "target_word": "含める", "complexity_tier": "T3", "furigana": "税金[ぜいきん]を含[ふく]めると、全部[ぜんぶ]で一万円[いちまんえん]になります。", "sentence_source": "generated"}, {"text": "私も含めて、五人がパーティーに参加しました。", "target_word": "含めて", "complexity_tier": "T3", "furigana": "私[わたし]も含[ふく]めて、五人[ごにん]がパーティーに参加[さんか]しました。", "sentence_source": "generated"}, {"text": "送料を含めた値段を教えてください。", "target_word": "含めた", "complexity_tier": "T3", "furigana": "送料[そうりょう]を含[ふく]めた値段[ねだん]を教[おし]えてください。", "sentence_source": "generated"}, {"text": "子どもを含めると、家族は六人です。", "target_word": "含める", "complexity_tier": "T3", "furigana": "子[こ]どもを含[ふく]めると、家族[かぞく]は六人[ろくにん]です。", "sentence_source": "generated"}, {"text": "彼は自分の失敗も含めて、すべて正直に話した。", "target_word": "含めて", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の失敗[しっぱい]も含[ふく]めて、すべて正直[しょうじき]に話[はな]した。", "sentence_source": "generated"}, {"text": "朝食を含めて、宿泊の料金は一人八千円です。", "target_word": "含めて", "complexity_tier": "T3", "furigana": "朝食[ちょうしょく]を含[ふく]めて、宿泊[しゅくはく]の料金[りょうきん]は一人[ひとり]八千円[はっせんえん]です。", "sentence_source": "generated"}, {"text": "日曜日を含めれば、旅行は三日間になる。", "target_word": "含めれば", "complexity_tier": "T3", "furigana": "日曜日[にちようび]を含[ふく]めれば、旅行[りょこう]は三日間[みっかかん]になる。", "sentence_source": "generated"}, {"text": "先生は、私を含めた三人を職員室に呼んだ。", "target_word": "含めた", "complexity_tier": "T3", "furigana": "先生[せんせい]は、私[わたし]を含[ふく]めた三人[さんにん]を職員室[しょくいんしつ]に呼[よ]んだ。", "sentence_source": "generated"}, {"text": "手数料を含めないと、本当の値段は分かりません。", "target_word": "含めない", "complexity_tier": "T3", "furigana": "手数料[てすうりょう]を含[ふく]めないと、本当[ほんとう]の値段[ねだん]は分[わ]かりません。", "sentence_source": "generated"}, {"text": "会議の人数に、オンラインで参加する人も含めてください。", "target_word": "含めて", "complexity_tier": "T3", "furigana": "会議[かいぎ]の人数[にんずう]に、オンラインで参加[さんか]する人[ひと]も含[ふく]めてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "含める", "label": "辞書形"}, {"form": "含めます", "label": "丁寧形"}, {"form": "含めて", "label": "て形"}, {"form": "含めた", "label": "た形"}, {"form": "含めない", "label": "ない形"}, {"form": "含めれば", "label": "仮定形"}, {"form": "含められる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "含める：数や費用などを全体の一部として数に入れる、ふくめて考える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38697, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "含める", "is_correct": true, "explanation": "動詞「含める」の基本形。「税金を含めると」の語幹に合い、総額の計算に入れる意味で通る。"}, {"text": "眺める", "is_correct": false, "explanation": "動詞だが、「税金を眺めると」は意味が通らない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "動詞だが、「税金を運ぶと」は意味が通らない。"}, {"text": "干す", "is_correct": false, "explanation": "動詞だが、「税金を干すと」は意味が通らない。"}], "explanations": {"含める": "動詞「含める」の基本形。「税金を含めると」の語幹に合い、総額の計算に入れる意味で通る。", "眺める": "動詞だが、「税金を眺めると」は意味が通らない。", "運ぶ": "動詞だが、「税金を運ぶと」は意味が通らない。", "干す": "動詞だが、「税金を干すと」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "含める"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は娘の靴を玄関に含めた。", "explanation": "ここは〈並べる〉の意味。「含める」は数や範囲に入れることで、物を一列に並べる動作には使わない。"}, {"text": "コップに水を含めて、ゆっくり飲んだ。", "explanation": "ここは〈注ぐ〉の意味。「含める」は数や範囲に入れることで、容器に液体を注ぐ動作には使わない。"}, {"text": "茶碗にご飯を含めた。", "explanation": "ここは〈盛る〉の意味。「含める」は数や範囲に入れることで、器に食べ物を盛る動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38697, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "含めれば", "is_correct": true, "explanation": "仮定形。「日曜日を含めれば」の条件の形で、数に入れた場合の日数を示す。"}, {"text": "掘れば", "is_correct": false, "explanation": "「日曜日を掘れば」は意味が通らない。"}, {"text": "眠れば", "is_correct": false, "explanation": "「日曜日を眠れば」は意味が通らない。"}, {"text": "煮れば", "is_correct": false, "explanation": "「日曜日を煮れば」は意味が通らない。"}], "explanations": {"含めれば": "仮定形。「日曜日を含めれば」の条件の形で、数に入れた場合の日数を示す。", "掘れば": "「日曜日を掘れば」は意味が通らない。", "眠れば": "「日曜日を眠れば」は意味が通らない。", "煮れば": "「日曜日を煮れば」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "含めれば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "かばんから本を含めて、机に置いた。", "explanation": "ここは〈取り出す〉の意味。「含める」は数や範囲に入れることで、かばんの中から物を出す動作には使わない。"}, {"text": "箱にお菓子を含めた。", "explanation": "ここは〈詰める〉の意味。「含める」は数や範囲に入れることで、箱に物を詰める動作には使わない。"}, {"text": "ビールを含めて、冷蔵庫でしばらく待った。", "explanation": "ここは〈冷やす〉の意味。「含める」は数や範囲に入れることで、温度を下げる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38697, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会費を含めれ、すべて支払った。", "corrected_sentence": "会費を含めて、すべて支払った。", "error_description": "「含める」は「含めて」の形で後ろに続ける。「含めれ」は仮定形が途中で切れた形で、文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "含めて", "is_correct": true, "explanation": "て形。「私も含めて」の形で、他の人を並べて示す用法に合う。"}, {"text": "含めた", "is_correct": false, "explanation": "た形は完了を表し、「私も含めた、五人が」は並べる用法として続かない。"}, {"text": "含めない", "is_correct": false, "explanation": "否定形。「私も含めない」は私を入れない意味になり、文と逆になる。"}, {"text": "含めます", "is_correct": false, "explanation": "丁寧形。「含めます、五人が」は文として続かない。"}], "correct_form": "含めて", "base_form": "含める", "form_label": "て形", "sentence_index": 1, "explanations": {"含めて": "て形。「私も含めて」の形で、他の人を並べて示す用法に合う。", "含めた": "た形は完了を表し、「私も含めた、五人が」は並べる用法として続かない。", "含めない": "否定形。「私も含めない」は私を入れない意味になり、文と逆になる。", "含めます": "丁寧形。「含めます、五人が」は文として続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38697, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週の調査には、私も含めるにした。", "corrected_sentence": "来週の調査には、私も含めることにした。", "error_description": "「〜ことにする」の「こと」が必要。「含めるにした」は「こと」がないため、「にする」と続かず誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "含めた", "is_correct": true, "explanation": "た形。「私を含めた三人」の連体修飾で、対象を数に入れた人数を表す。"}, {"text": "含めます", "is_correct": false, "explanation": "丁寧形。名詞を直接修飾できず、「私を含めます三人」は成り立たない。"}, {"text": "含めよう", "is_correct": false, "explanation": "意志形。「含めよう」の意味になり、既に行った出来事の文と合わない。"}, {"text": "含めれば", "is_correct": false, "explanation": "仮定形。名詞を修飾できず、「私を含めれば三人」は成り立たない。"}], "correct_form": "含めた", "base_form": "含める", "form_label": "た形", "sentence_index": 7, "explanations": {"含めた": "た形。「私を含めた三人」の連体修飾で、対象を数に入れた人数を表す。", "含めます": "丁寧形。名詞を直接修飾できず、「私を含めます三人」は成り立たない。", "含めよう": "意志形。「含めよう」の意味になり、既に行った出来事の文と合わない。", "含めれば": "仮定形。名詞を修飾できず、「私を含めれば三人」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38698, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "ライフを主題にして「〜のことだ」と定義する文になるので、主題のはが正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格。「人のライフへ」では定義文の主題が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の格。定義文の主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の格。「ライフで」は定義文の主題にならない。"}], "correct_answer": "は", "explanations": {"は": "ライフを主題にして「〜のことだ」と定義する文になるので、主題のはが正しい。", "へ": "方向を示す格。「人のライフへ」では定義文の主題が成り立たない。", "を": "目的語の格。定義文の主語にはならない。", "で": "手段・場所の格。「ライフで」は定義文の主題にならない。"}, "error_tags": {"を": "対格", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38698, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ライフが限られている」で、ライフが主語となる正しい格。"}, {"text": "を", "is_correct": false, "explanation": "目的語の格。「限られている」の主語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「ライフに限られている」は限る対象を示す形として不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の格。ライフを主語として述べる文には入らない。"}], "correct_answer": "が", "explanations": {"が": "「ライフが限られている」で、ライフが主語となる正しい格。", "を": "目的語の格。「限られている」の主語にはならない。", "に": "「ライフに限られている」は限る対象を示す形として不自然。", "で": "手段・場所の格。ライフを主語として述べる文には入らない。"}, "error_tags": {"を": "対格", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38698, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生きること。生まれてから死ぬまでの時間のことです。", "primary_collocate": null, "pronunciation": "らいふ", "ipa": "ɾaiɸɯ", "syllable_count": 3, "sentences": [{"text": "仕事だけでなく、ライフも大切にしたい。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "仕事[しごと]だけでなく、ライフも大切[たいせつ]にしたい。", "sentence_source": "generated"}, {"text": "人のライフは、生まれてから死ぬまでの時間のことだ。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "人[ひと]のライフは、生[う]まれてから死[し]ぬまでの時間[じかん]のことだ。", "sentence_source": "generated"}, {"text": "私はライフを大切にするため、毎朝早く起きて散歩をする。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "私[わたし]はライフを大切[たいせつ]にするため、毎朝[まいあさ]早[はや]く起[お]きて散歩[さんぽ]をする。", "sentence_source": "generated"}, {"text": "彼はライフの最後の時間を、家族と過ごすと決めた。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "彼[かれ]はライフの最後[さいご]の時間[じかん]を、家族[かぞく]と過[す]ごすと決[き]めた。", "sentence_source": "generated"}, {"text": "ライフを楽しむために、私は毎日好きな音楽を聞く。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "ライフを楽[たの]しむために、私[わたし]は毎日[まいにち]好[す]きな音楽[おんがく]を聞[き]く。", "sentence_source": "generated"}, {"text": "祖母は八十年、ライフを笑顔で楽しみ続けた。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "祖母[そぼ]は八十年[はちじゅうねん]、ライフを笑顔[えがお]で楽[たの]しみ続[つづ]けた。", "sentence_source": "generated"}, {"text": "ライフを一か月ほどで終えてしまう昆虫もいる。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "ライフを一か月[いっかげつ]ほどで終[お]えてしまう昆虫[こんちゅう]もいる。", "sentence_source": "generated"}, {"text": "私たちはライフが限られているからこそ、やりたいことを先にやるべきだ。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "私[わたし]たちはライフが限[かぎ]られているからこそ、やりたいことを先[さき]にやるべきだ。", "sentence_source": "generated"}, {"text": "今日の授業では、人間のライフの長さについて勉強しました。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "今日[きょう]の授業[じゅぎょう]では、人間[にんげん]のライフの長[なが]さについて勉強[べんきょう]しました。", "sentence_source": "generated"}, {"text": "病気をしてから、ライフの大切さを考えるようになった。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "病気[びょうき]をしてから、ライフの大切[たいせつ]さを考[かんが]えるようになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ライフ", "label": "基本形"}, {"form": "ライフを", "label": "を格"}], "register": "標準（丁寧体・普通体）", "sense_fingerprint": "生まれてから死ぬまでの生きる時間・一生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '729dc63f-8b18-4b3c-895a-efbae94aab11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38698, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ライフ", "is_correct": true, "explanation": "「仕事だけでなく〜も大切にしたい」で、仕事と並ぶ生き方全体を指すライフが入る。"}, {"text": "ゴミ", "is_correct": false, "explanation": "仕事と並べて大切にする対象として不自然で、空欄に入らない。"}, {"text": "ヒーター", "is_correct": false, "explanation": "家電の名詞で、生き方として大切にする対象にならない。"}, {"text": "ロッカー", "is_correct": false, "explanation": "仕事と並べて大切にするものとして文の意味が通らない。"}], "explanations": {"ライフ": "「仕事だけでなく〜も大切にしたい」で、仕事と並ぶ生き方全体を指すライフが入る。", "ゴミ": "仕事と並べて大切にする対象として不自然で、空欄に入らない。", "ヒーター": "家電の名詞で、生き方として大切にする対象にならない。", "ロッカー": "仕事と並べて大切にするものとして文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "ライフ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風の夜、町のライフが一時止まった。", "explanation": "ここは〈ライフライン〉（電気・水道など暮らしを支える設備）の意味。生涯の時間を指すライフとは違う。"}, {"text": "医師は、その患者のライフを救うため夜通し手術を続けた。", "explanation": "ここは〈命〉の意味。「命を救う」の命をライフに置き換えた形で、救う対象としては使わない。"}, {"text": "地震のあと、病院のライフが三日間途切れた。", "explanation": "ここも〈ライフライン〉の意味。生涯の時間を指すライフとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38698, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ライフ", "is_correct": true, "explanation": "「ライフを一か月ほどで終える」で、生涯の時間を指すライフが入る。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "一か月ほどで終えるという時間の文脈に合わない。"}, {"text": "ボタン", "is_correct": false, "explanation": "時間の長さを終えるという文脈に合わない。"}, {"text": "トラック", "is_correct": false, "explanation": "乗り物の名詞で、生涯の時間の意味に入らない。"}], "explanations": {"ライフ": "「ライフを一か月ほどで終える」で、生涯の時間を指すライフが入る。", "ハンカチ": "一か月ほどで終えるという時間の文脈に合わない。", "ボタン": "時間の長さを終えるという文脈に合わない。", "トラック": "乗り物の名詞で、生涯の時間の意味に入らない。"}, "sentence_index": 6, "correct_answer": "ライフ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震のあと、街のライフが止まった。", "explanation": "ここは〈ライフライン〉（暮らしを支える設備）の意味。一生の時間を指すライフとは違う。"}, {"text": "停電で、この地区のライフがすべて断たれた。", "explanation": "ここも〈ライフライン〉の意味。生涯の時間を指す語としては使わない。"}, {"text": "この牛乳は賞味期限が過ぎて、ライフが切れていた。", "explanation": "ここは食品の消費期限の意味。生涯の時間を指すライフは、牛乳の保存期限には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38698, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "忙しくても、ライフが大切にする人が増えている。", "corrected_sentence": "忙しくても、ライフを大切にする人が増えている。", "error_description": "「大切にする」の目的語はを格で示す。ライフが（が格）にすると主語になり、文が成り立たない。正しくはライフを。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38698, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "日々のライフに、丁寧に過ごしたいと思う。", "corrected_sentence": "日々のライフを、丁寧に過ごしたいと思う。", "error_description": "「過ごす」の目的語はを格で示す。ライフに（に格）にすると場所や相手のように読まれ、文が不自然になる。正しくはライフを。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38699, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "ライフを主題にして「死と対になる言葉」と説明する文になるので、主題のはが正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語の格。定義文の主題にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の格。「ライフで」は定義文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格。「ライフへ死と対になる言葉で」は成り立たない。"}], "correct_answer": "は", "explanations": {"は": "ライフを主題にして「死と対になる言葉」と説明する文になるので、主題のはが正しい。", "を": "目的語の格。定義文の主題にならない。", "で": "手段・場所の格。「ライフで」は定義文に合わない。", "へ": "方向を示す格。「ライフへ死と対になる言葉で」は成り立たない。"}, "error_tags": {"を": "対格", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死", "is_correct": true, "explanation": "生命の状態としてのライフの対義語は死。対義語として辞典に並ぶ。"}, {"text": "机", "is_correct": false, "explanation": "名詞だが、生命の状態の対義語ではない。"}, {"text": "海", "is_correct": false, "explanation": "名詞だが、生命の状態の対義語ではない。"}, {"text": "時計", "is_correct": false, "explanation": "名詞だが、生命の状態の対義語ではない。"}], "correct_answer": "死", "explanations": {"死": "生命の状態としてのライフの対義語は死。対義語として辞典に並ぶ。", "机": "名詞だが、生命の状態の対義語ではない。", "海": "名詞だが、生命の状態の対義語ではない。", "時計": "名詞だが、生命の状態の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38699, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ライフがある」で、ライフが主語として存在を示す正しい格。"}, {"text": "を", "is_correct": false, "explanation": "目的語の格。存在を示す文の主語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "存在の場所や相手を示す格で、ライフの主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の格。営まれる位置は示せても、主語のライフは示せない。"}], "correct_answer": "が", "explanations": {"が": "「ライフがある」で、ライフが主語として存在を示す正しい格。", "を": "目的語の格。存在を示す文の主語にはならない。", "に": "存在の場所や相手を示す格で、ライフの主語にはならない。", "で": "手段・場所の格。営まれる位置は示せても、主語のライフは示せない。"}, "error_tags": {"を": "対格", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死", "is_correct": true, "explanation": "生命の状態としてのライフの対義語は死。対義語として辞典に並ぶ。"}, {"text": "雨", "is_correct": false, "explanation": "名詞だが、生命の状態の対義語ではない。"}, {"text": "窓", "is_correct": false, "explanation": "名詞だが、生命の状態の対義語ではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "名詞だが、生命の状態の対義語ではない。"}], "correct_answer": "死", "explanations": {"死": "生命の状態としてのライフの対義語は死。対義語として辞典に並ぶ。", "雨": "名詞だが、生命の状態の対義語ではない。", "窓": "名詞だが、生命の状態の対義語ではない。", "鉛筆": "名詞だが、生命の状態の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38699, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生物が生存している状態。活動や成長、代謝などの生命現象を伴う、死と対をなす概念。", "primary_collocate": null, "pronunciation": "らいふ", "ipa": "ɾaiɸɯ", "syllable_count": 3, "sentences": [{"text": "ライフがあるものは、成長や代謝によって形を変えていく。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "ライフがあるものは、成長[せいちょう]や代謝[たいしゃ]によって形[かたち]を変[か]えていく。", "sentence_source": "generated"}, {"text": "ライフは死と対になる言葉で、生きている状態を指す。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "ライフは死[し]と対[つい]になる言葉[ことば]で、生[い]きている状態[じょうたい]を指[さ]す。", "sentence_source": "generated"}, {"text": "科学者は、火星にライフが存在するかどうかを調べている。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]は、火星[かせい]にライフが存在[そんざい]するかどうかを調[しら]べている。", "sentence_source": "generated"}, {"text": "地球で最初のライフは、海の中で生まれたと考えられている。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "地球[ちきゅう]で最初[さいしょ]のライフは、海[うみ]の中[なか]で生[う]まれたと考[かんが]えられている。", "sentence_source": "generated"}, {"text": "ウイルスにライフがあるかどうかは、学者の間でも意見が分かれる。", "target_word": "ライフ", "complexity_tier": "T4", "furigana": "ウイルスにライフがあるかどうかは、学者[がくしゃ]の間[あいだ]でも意見[いけん]が分[わ]かれる。", "sentence_source": "generated"}, {"text": "細胞が動きを止めると、そこからライフが失われていく。", "target_word": "ライフ", "complexity_tier": "T4", "furigana": "細胞[さいぼう]が動[うご]きを止[と]めると、そこからライフが失[うしな]われていく。", "sentence_source": "generated"}, {"text": "生き物は、ライフが続くように栄養をとり続ける。", "target_word": "ライフ", "complexity_tier": "T3", "furigana": "生[い]き物[もの]は、ライフが続[つづ]くように栄養[えいよう]をとり続[つづ]ける。", "sentence_source": "generated"}, {"text": "深海にも、光のない場所で営まれるライフがある。", "target_word": "ライフ", "complexity_tier": "T4", "furigana": "深海[しんかい]にも、光[ひかり]のない場所[ばしょ]で営[いとな]まれるライフがある。", "sentence_source": "generated"}, {"text": "医者は、心臓が止まった時点でライフの終わりと判断した。", "target_word": "ライフ", "complexity_tier": "T4", "furigana": "医者[いしゃ]は、心臓[しんぞう]が止[と]まった時点[じてん]でライフの終[お]わりと判断[はんだん]した。", "sentence_source": "generated"}, {"text": "授業では、ライフとは何かを、成長や増殖という点から考えた。", "target_word": "ライフ", "complexity_tier": "T4", "furigana": "授業[じゅぎょう]では、ライフとは何[なに]かを、成長[せいちょう]や増殖[ぞうしょく]という点[てん]から考[かんが]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ライフ", "label": "基本形"}, {"form": "ライフが", "label": "が格"}], "register": "標準（普通体・丁寧体）", "sense_fingerprint": "成長や代謝を伴う生命現象としての生、死の対義概念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '729dc63f-8b18-4b3c-895a-efbae94aab11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38699, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ライフ", "is_correct": true, "explanation": "「ライフがあるものは、成長や代謝によって形を変える」で、生命現象を伴うライフが入る。"}, {"text": "ペンキ", "is_correct": false, "explanation": "成長や代謝で形が変わる主語として不自然。生命の意味に合わない。"}, {"text": "タオル", "is_correct": false, "explanation": "代謝や成長を行う主語にならない。"}, {"text": "ホテル", "is_correct": false, "explanation": "生物の文脈に入らない。"}], "explanations": {"ライフ": "「ライフがあるものは、成長や代謝によって形を変える」で、生命現象を伴うライフが入る。", "ペンキ": "成長や代謝で形が変わる主語として不自然。生命の意味に合わない。", "タオル": "代謝や成長を行う主語にならない。", "ホテル": "生物の文脈に入らない。"}, "sentence_index": 0, "correct_answer": "ライフ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震のあと、町のライフが止まった。", "explanation": "ここは〈ライフライン〉（暮らしを支える設備）の意味。生存状態のライフとは違う。"}, {"text": "宇宙にはライフがいるかもしれない。", "explanation": "ここは〈生命体〉の意味。ライフは生存状態を指す語で、いる存在を数える語ではない。"}, {"text": "祭りの夜、町はライフにあふれていた。", "explanation": "ここは〈活気〉の意味。生存状態のライフは、にぎわいや勢いを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38699, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ライフ", "is_correct": true, "explanation": "「ライフが続くように栄養をとり続ける」で、生存を続ける状態のライフが入る。"}, {"text": "スプーン", "is_correct": false, "explanation": "栄養を続けることと結びつかず、文が通らない。"}, {"text": "カーテン", "is_correct": false, "explanation": "生存を続けるという文脈に合わない。"}, {"text": "ノート", "is_correct": false, "explanation": "生物の生存の文脈に入らない。"}], "explanations": {"ライフ": "「ライフが続くように栄養をとり続ける」で、生存を続ける状態のライフが入る。", "スプーン": "栄養を続けることと結びつかず、文が通らない。", "カーテン": "生存を続けるという文脈に合わない。", "ノート": "生物の生存の文脈に入らない。"}, "sentence_index": 6, "correct_answer": "ライフ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨で、この地区のライフが一時止まった。", "explanation": "ここは〈ライフライン〉の意味。生物の生存状態を指すライフとは違う。"}, {"text": "この池にはライフが暮らしている。", "explanation": "ここは〈生き物〉の意味。ライフは生存状態を指す語で、暮らしている生き物そのものは指さない。"}, {"text": "この牛乳は賞味期限が過ぎて、ライフが切れていた。", "explanation": "ここは食品の消費期限の意味。生存状態のライフは、牛乳の期限を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38699, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "生物は、ライフに維持するために栄養をとる。", "corrected_sentence": "生物は、ライフを維持するために栄養をとる。", "error_description": "「維持する」の目的語はを格で示す。ライフに（に格）とすると目的語の関係が成り立たない。正しくはライフを。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38699, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "生き物は、ライフに守るために水分をとる。", "corrected_sentence": "生き物は、ライフを守るために水分をとる。", "error_description": "「守る」の目的語はを格で示す。ライフに（に格）とすると目的語の関係が成り立たない。正しくはライフを。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
