INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38700, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「繰り返している」の目的語を示す「を」が、サイクルの後に付く。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、繰り返す対象を表す位置には合わず、文が崩れる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、繰り返す対象を表す位置には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ修飾の助詞なので、「サイクルの繰り返している」は動詞の目的語にならず文が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「繰り返している」の目的語を示す「を」が、サイクルの後に付く。", "から": "「から」は起点を示すので、繰り返す対象を表す位置には合わず、文が崩れる。", "より": "「より」は比較を示すので、繰り返す対象を表す位置には合わない。", "の": "「の」は名詞をつなぐ修飾の助詞なので、「サイクルの繰り返している」は動詞の目的語にならず文が崩れる。"}, "error_tags": {"から": "起点", "より": "比較", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38700, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ぐるぐる回ること。同じことを何度も繰り返すこと。", "primary_collocate": null, "pronunciation": "さいくる", "ipa": "saikɯɾɯ", "syllable_count": 4, "sentences": [{"text": "毎朝同じ時刻に起きるサイクルを守ると、体調がよくなる。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]同[おな]じ時刻[じこく]に起[お]きるサイクルを守[まも]ると、体調[たいちょう]がよくなる。", "sentence_source": "generated"}, {"text": "宿題をためてあわてて終わらせるサイクルを、今学期こそやめたい。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]をためてあわてて終[お]わらせるサイクルを、今学期[こんがっき]こそやめたい。", "sentence_source": "generated"}, {"text": "家と会社を往復するだけのサイクルから、旅行で抜け出した。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "家[いえ]と会社[かいしゃ]を往復[おうふく]するだけのサイクルから、旅行[りょこう]で抜[ぬ]け出[だ]した。", "sentence_source": "generated"}, {"text": "彼は働いて疲れて休むというサイクルを、何年も続けている。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "彼[かれ]は働[はたら]いて疲[つか]れて休[やす]むというサイクルを、何年[なんねん]も続[つづ]けている。", "sentence_source": "generated"}, {"text": "季節は、春から冬まで一年のサイクルで巡ってくる。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "季節[きせつ]は、春[はる]から冬[ふゆ]まで一年[いちねん]のサイクルで巡[めぐ]ってくる。", "sentence_source": "generated"}, {"text": "夜勤が続くと、食事と睡眠のサイクルが昼と夜で逆になる。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "夜勤[やきん]が続[つづ]くと、食事[しょくじ]と睡眠[すいみん]のサイクルが昼[ひる]と夜[よる]で逆[ぎゃく]になる。", "sentence_source": "generated"}, {"text": "ラジオ体操を中心に朝のサイクルを作ると、一日が楽に始まる。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "ラジオ体操[たいそう]を中心[ちゅうしん]に朝[あさ]のサイクルを作[つく]ると、一日[いちにち]が楽[らく]に始[はじ]まる。", "sentence_source": "generated"}, {"text": "この川の水位は、数年おきに上がり下がりするサイクルを繰り返している。", "target_word": "サイクル", "complexity_tier": "T4", "furigana": "この川[かわ]の水位[すいい]は、数年[すうねん]おきに上[あ]がり下[さ]がりするサイクルを繰[く]り返[かえ]している。", "sentence_source": "generated"}, {"text": "買って、使って、捨てるだけのサイクルに疑問を持ち、物を修理して使うことにした。", "target_word": "サイクル", "complexity_tier": "T4", "furigana": "買[か]って、使[つか]って、捨[す]てるだけのサイクルに疑問[ぎもん]を持[も]ち、物[もの]を修理[しゅうり]して使[つか]うことにした。", "sentence_source": "generated"}, {"text": "赤ちゃんは、泣いて、ミルクを飲んで、眠るサイクルで一日を過ごす。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは、泣[な]いて、ミルクを飲[の]んで、眠[ねむ]るサイクルで一日[いちにち]を過[す]ごす。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サイクル", "label": "基本形(名詞)"}], "register": "neutral", "sense_fingerprint": "同じ行動や出来事が繰り返される、決まったパターン(生活のくり返しなど)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38700, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サイクル", "is_correct": true, "explanation": "「毎朝同じ時刻に起きるサイクル」は生活の決まった繰り返しを表し、守るの対象になる。"}, {"text": "会議", "is_correct": false, "explanation": "「会議を守る」は成り立たず、体調の文脈とも結びつかない。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙を守る」は意味が通らず、起きる時刻の文脈に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気を守る」は成り立たず、毎朝の生活リズムとは関係しない。"}], "explanations": {"サイクル": "「毎朝同じ時刻に起きるサイクル」は生活の決まった繰り返しを表し、守るの対象になる。", "会議": "「会議を守る」は成り立たず、体調の文脈とも結びつかない。", "手紙": "「手紙を守る」は意味が通らず、起きる時刻の文脈に合わない。", "天気": "「天気を守る」は成り立たず、毎朝の生活リズムとは関係しない。"}, "sentence_index": 0, "correct_answer": "サイクル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "サイクルで海沿いの道を走った。", "explanation": "ここは〈自転車〉の意味。生活の繰り返しという語義では乗り物を指せないので合わない。"}, {"text": "この会議は、サイクルとして一度だけ開かれた。", "explanation": "ここは〈単発〉の意味。同じことを何度も繰り返す流れを表すサイクルは、一度だけの会議には合わない。"}, {"text": "列に並んで、サイクルを待った。", "explanation": "ここは〈順番〉の意味。順番を待つ場面では順番を使い、生活の繰り返しを指すサイクルは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38700, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サイクル", "is_correct": true, "explanation": "「朝のサイクルを作る」は、朝の決まった流れを整える意味で自然に成り立つ。"}, {"text": "財布", "is_correct": false, "explanation": "「朝の財布を作る」は成り立たず、生活の流れを表さない。"}, {"text": "天気", "is_correct": false, "explanation": "「朝の天気を作る」は意味が通らず、生活リズムの文脈に合わない。"}, {"text": "鳴き声", "is_correct": false, "explanation": "「朝の鳴き声を作る」は成り立たず、ラジオ体操の文脈とも合わない。"}], "explanations": {"サイクル": "「朝のサイクルを作る」は、朝の決まった流れを整える意味で自然に成り立つ。", "財布": "「朝の財布を作る」は成り立たず、生活の流れを表さない。", "天気": "「朝の天気を作る」は意味が通らず、生活リズムの文脈に合わない。", "鳴き声": "「朝の鳴き声を作る」は成り立たず、ラジオ体操の文脈とも合わない。"}, "sentence_index": 6, "correct_answer": "サイクル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅の目的地を、サイクルで一つずつ決めた。", "explanation": "ここは〈自転車〉の意味。自転車で決めるという手段は成り立たず、繰り返す流れを表すサイクルとは合わない。"}, {"text": "この店のサイクルは、昼の二時に閉まる。", "explanation": "ここは〈営業時間〉の意味。閉店の時刻は営業時間で表し、繰り返す流れを表すサイクルは時刻には使わない。"}, {"text": "このバスのサイクルは四十人だ。", "explanation": "ここは〈定員〉の意味。乗れる人数の上限を指す語で、生活の流れを表すサイクルとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38700, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎晩同じ番組を見るサイクルを、もう飽きてしまった。", "corrected_sentence": "毎晩同じ番組を見るサイクルに、もう飽きてしまった。", "error_description": "「飽きる」は「に」を取る。「を」は誤りで、「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38700, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ラジオ体操を中心に朝のサイクルを整えるた、一日が楽に始まる。", "corrected_sentence": "ラジオ体操を中心に朝のサイクルを整えたら、一日が楽に始まる。", "error_description": "「整える」の活用が誤り。条件を表す「たら」に続ける形が正しく、「整えるた」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38701, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「サイクル」が主語になり、「乱れる」の主語を示す「が」が付く。"}, {"text": "を", "is_correct": false, "explanation": "「乱れる」は自動詞なので、目的語の「を」とは組み合わない。"}, {"text": "に", "is_correct": false, "explanation": "「サイクルに乱れる」は成り立たず、主語を示す位置に「に」は入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「乱れる」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「サイクル」が主語になり、「乱れる」の主語を示す「が」が付く。", "を": "「乱れる」は自動詞なので、目的語の「を」とは組み合わない。", "に": "「サイクルに乱れる」は成り立たず、主語を示す位置に「に」は入らない。", "で": "「で」は手段や場所を示すので、「乱れる」の主語にはならない。"}, "error_tags": {"を": "object_marker", "に": "wrong_case", "で": "means_location"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38701, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "期間の単位を示す「で」で、「一か月のサイクルで」の形で繰り返しの周期を表す。"}, {"text": "を", "is_correct": false, "explanation": "「繰り返される」の目的語にはならず、「サイクルを繰り返される」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「サイクルに繰り返される」は周期を示す形として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、周期の単位を示す位置には合わない。"}], "correct_answer": "で", "explanations": {"で": "期間の単位を示す「で」で、「一か月のサイクルで」の形で繰り返しの周期を表す。", "を": "「繰り返される」の目的語にはならず、「サイクルを繰り返される」は不自然。", "に": "「サイクルに繰り返される」は周期を示す形として成り立たない。", "へ": "「へ」は方向を示すので、周期の単位を示す位置には合わない。"}, "error_tags": {"を": "object_marker", "に": "wrong_case", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38701, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が一巡して、再び元の状態に戻る一連の流れ。または、その繰り返し。", "primary_collocate": null, "pronunciation": "さいくる", "ipa": "saikɯɾɯ", "syllable_count": 4, "sentences": [{"text": "かつては安定していた生態系のサイクルが、現代文明の経済活動によって歪められ、その修復は極めて困難な局面を迎えている。", "target_word": "サイクル", "complexity_tier": "T5", "furigana": "かつては安定[あんてい]していた生態系[せいたいけい]のサイクルが、現代[げんだい]文明[ぶんめい]の経済[けいざい]活動[かつどう]によって歪[ゆが]められ、その修復[しゅうふく]は極[きわ]めて困難[こんなん]な局面[きょくめん]を迎[むか]えている。", "sentence_source": "mined"}, {"text": "睡眠のサイクルが乱れると、昼間に強い眠気を感じやすい。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "睡眠[すいみん]のサイクルが乱[みだ]れると、昼間[ひるま]に強[つよ]い眠気[ねむけ]を感[かん]じやすい。", "sentence_source": "generated"}, {"text": "水は蒸発して雨になり、また川に戻るというサイクルを繰り返す。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "水[みず]は蒸発[じょうはつ]して雨[あめ]になり、また川[かわ]に戻[もど]るというサイクルを繰[く]り返[かえ]す。", "sentence_source": "generated"}, {"text": "この工場では、商品を作って売るまでのサイクルが以前より短くなった。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、商品[しょうひん]を作[つく]って売[う]るまでのサイクルが以前[いぜん]より短[みじか]くなった。", "sentence_source": "generated"}, {"text": "景気には好況と不況のサイクルがあると、経済学者は説明した。", "target_word": "サイクル", "complexity_tier": "T4", "furigana": "景気[けいき]には好況[こうきょう]と不況[ふきょう]のサイクルがあると、経済[けいざい]学者[がくしゃ]は説明[せつめい]した。", "sentence_source": "generated"}, {"text": "新しい機種が出るサイクルが早いので、スマホはすぐ古くなる。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "新[あたら]しい機種[きしゅ]が出[で]るサイクルが早[はや]いので、スマホはすぐ古[ふる]くなる。", "sentence_source": "generated"}, {"text": "農家は、種をまいて収穫するサイクルを毎年繰り返している。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "農家[のうか]は、種[たね]をまいて収穫[しゅうかく]するサイクルを毎年[まいとし]繰[く]り返[かえ]している。", "sentence_source": "generated"}, {"text": "月の満ち欠けは、約一か月のサイクルで繰り返される。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "月[つき]の満[み]ち欠[か]けは、約[やく]一[いっ]か月[げつ]のサイクルで繰[く]り返[かえ]される。", "sentence_source": "generated"}, {"text": "寝不足で食べ過ぎ、また寝不足になるというサイクルから抜け出したい。", "target_word": "サイクル", "complexity_tier": "T3", "furigana": "寝不足[ねぶそく]で食[た]べ過[す]ぎ、また寝不足[ねぶそく]になるというサイクルから抜[ぬ]け出[だ]したい。", "sentence_source": "generated"}, {"text": "その企業は、五年のサイクルで中期計画を見直している。", "target_word": "サイクル", "complexity_tier": "T4", "furigana": "その企業[きぎょう]は、五年[ごねん]のサイクルで中期[ちゅうき]計画[けいかく]を見直[みなお]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サイクル", "label": "基本形(名詞)"}], "register": "neutral", "sense_fingerprint": "自然・経済・生産などで、ひと巡りして元に戻る周期的な流れ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38701, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サイクル", "is_correct": true, "explanation": "「生態系のサイクル」は、ひと巡りして元に戻る自然の流れとして成り立つ。"}, {"text": "名刺", "is_correct": false, "explanation": "「生態系の名刺」は成り立たず、流れを表す語ではない。"}, {"text": "帰省", "is_correct": false, "explanation": "「生態系の帰省」は意味が通らず、自然の流れの文脈に合わない。"}, {"text": "駐車", "is_correct": false, "explanation": "「生態系の駐車」は成り立たず、動きが止まる意味になってしまう。"}], "explanations": {"サイクル": "「生態系のサイクル」は、ひと巡りして元に戻る自然の流れとして成り立つ。", "名刺": "「生態系の名刺」は成り立たず、流れを表す語ではない。", "帰省": "「生態系の帰省」は意味が通らず、自然の流れの文脈に合わない。", "駐車": "「生態系の駐車」は成り立たず、動きが止まる意味になってしまう。"}, "sentence_index": 0, "correct_answer": "サイクル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "サイクルで湖の周りを一周した。", "explanation": "ここは〈自転車〉の意味。ひと巡りして元に戻る流れという語義では、乗り物は指せないので合わない。"}, {"text": "この事件は一度きりで、二度と起きないサイクルだ。", "explanation": "ここは〈単発〉の意味。サイクルは元に戻って繰り返す流れを表すので、ひとまわりで終わる出来事には合わない。"}, {"text": "会議室のサイクルを予約した。", "explanation": "ここは〈時間枠〉の意味。サイクルは元に戻って繰り返す流れを表すので、一回ずつ押さえる予約の枠には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38701, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サイクル", "is_correct": true, "explanation": "「種をまいて収穫するサイクル」で、収穫までの一連の流れを指し、毎年の繰り返しとして成り立つ。"}, {"text": "夜", "is_correct": false, "explanation": "「種をまいて収穫する夜」は成り立たず、繰り返す流れを表さない。"}, {"text": "手紙", "is_correct": false, "explanation": "「種をまいて収穫する手紙」は意味が通らない。"}, {"text": "銀行", "is_correct": false, "explanation": "「種をまいて収穫する銀行」は成り立たず、農作業の文脈に合わない。"}], "explanations": {"サイクル": "「種をまいて収穫するサイクル」で、収穫までの一連の流れを指し、毎年の繰り返しとして成り立つ。", "夜": "「種をまいて収穫する夜」は成り立たず、繰り返す流れを表さない。", "手紙": "「種をまいて収穫する手紙」は意味が通らない。", "銀行": "「種をまいて収穫する銀行」は成り立たず、農作業の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "サイクル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅の目的地を、サイクルで一つずつ決めた。", "explanation": "ここは〈自転車〉の意味。自転車で決めるという手段は成り立たず、繰り返す流れを表すサイクルとは合わない。"}, {"text": "病院の受付で、サイクルを待った。", "explanation": "ここは〈順番〉の意味。待つ列での番を言うのは順番で、繰り返す流れを表すサイクルは待ち時間には使わない。"}, {"text": "このバスのサイクルは四十人だ。", "explanation": "ここは〈定員〉の意味。乗れる人数の上限を指す語で、周期を表すサイクルとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38701, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "体内時計のサイクルを乱れると、夜に眠れなくなる。", "corrected_sentence": "体内時計のサイクルが乱れると、夜に眠れなくなる。", "error_description": "「乱れる」は自動詞で、主語に「が」を取る。「を」は誤りで、「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38701, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その企業は、五年のサイクルに中期計画を見直す予定だ。", "corrected_sentence": "その企業は、五年のサイクルで中期計画を見直す予定だ。", "error_description": "周期の単位を示すのは「で」で、「五年のサイクルに」は周期の意味にならない。「五年のサイクルで」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38702, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「湖の生態」の「の」。名詞を修飾して、生態の所属を示す。"}, {"text": "を", "is_correct": false, "explanation": "「湖を生態が」は主語と目的語が重なり、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「湖へ生態が」は方向の意味になり、生態の所属を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「湖に生態が」は場所の意味になり、文に合わない。"}], "correct_answer": "の", "explanations": {"の": "「湖の生態」の「の」。名詞を修飾して、生態の所属を示す。", "を": "「湖を生態が」は主語と目的語が重なり、不自然。", "へ": "「湖へ生態が」は方向の意味になり、生態の所属を示せない。", "に": "「湖に生態が」は場所の意味になり、文に合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38702, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ホタルの生態」の「の」。名詞を修飾して、生態の対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "「ホタルで生態を知れば」は手段の意味になり、知る対象として合わない。"}, {"text": "より", "is_correct": false, "explanation": "「ホタルより生態を知れば」は比較の意味になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「ホタルへ生態を知れば」は知る対象として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「ホタルの生態」の「の」。名詞を修飾して、生態の対象を示す。", "で": "「ホタルで生態を知れば」は手段の意味になり、知る対象として合わない。", "より": "「ホタルより生態を知れば」は比較の意味になり、文が成り立たない。", "へ": "「へ」は方向を表すので、「ホタルへ生態を知れば」は知る対象として成り立たない。"}, "error_tags": {"で": "手段", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38702, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生きものと、その周りの自然や環境との関係のことです。", "primary_collocate": null, "pronunciation": "せいたい", "ipa": "seːtai", "syllable_count": 4, "sentences": [{"text": "ペンギンの生態を調べるために、南極へ行った。", "target_word": "生態", "complexity_tier": "T3", "furigana": "ペンギンの生態[せいたい]を調[しら]べるために、南極[なんきょく]へ行[い]った。", "sentence_source": "generated"}, {"text": "外来種が増えて、湖の生態が大きく変わってしまった。", "target_word": "生態", "complexity_tier": "T3", "furigana": "外来種[がいらいしゅ]が増[ふ]えて、湖[みずうみ]の生態[せいたい]が大[おお]きく変[か]わってしまった。", "sentence_source": "generated"}, {"text": "夜に活動する動物の生態は、まだ分からないことが多い。", "target_word": "生態", "complexity_tier": "T3", "furigana": "夜[よる]に活動[かつどう]する動物[どうぶつ]の生態[せいたい]は、まだ分[わ]からないことが多[おお]い。", "sentence_source": "generated"}, {"text": "この番組では、深海の生き物の生態を紹介している。", "target_word": "生態", "complexity_tier": "T3", "furigana": "この番組[ばんぐみ]では、深海[しんかい]の生[い]き物[もの]の生態[せいたい]を紹介[しょうかい]している。", "sentence_source": "generated"}, {"text": "研究者は、カラスの生態を何年も観察している。", "target_word": "生態", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、カラスの生態[せいたい]を何年[なんねん]も観察[かんさつ]している。", "sentence_source": "generated"}, {"text": "川にダムができると、魚の生態に影響が出ることがある。", "target_word": "生態", "complexity_tier": "T3", "furigana": "川[かわ]にダムができると、魚[さかな]の生態[せいたい]に影響[えいきょう]が出[で]ることがある。", "sentence_source": "generated"}, {"text": "森の生態を守るために、むやみに木を切ってはいけない。", "target_word": "生態", "complexity_tier": "T3", "furigana": "森[もり]の生態[せいたい]を守[まも]るために、むやみに木[き]を切[き]ってはいけない。", "sentence_source": "generated"}, {"text": "ホタルの生態を知れば、なぜ清い水が必要なのか分かる。", "target_word": "生態", "complexity_tier": "T3", "furigana": "ホタルの生態[せいたい]を知[し]れば、なぜ清[きよ]い水[みず]が必要[ひつよう]なのか分[わ]かる。", "sentence_source": "generated"}, {"text": "弟は昆虫の生態に興味があって、毎日図鑑を読んでいる。", "target_word": "生態", "complexity_tier": "T3", "furigana": "弟[おとうと]は昆虫[こんちゅう]の生態[せいたい]に興味[きょうみ]があって、毎日[まいにち]図鑑[ずかん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "季節によって、渡り鳥の生態は少しずつ違います。", "target_word": "生態", "complexity_tier": "T3", "furigana": "季節[きせつ]によって、渡[わた]り鳥[どり]の生態[せいたい]は少[すこ]しずつ違[ちが]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生態", "label": "基本形"}], "register": "標準", "sense_fingerprint": "生態：生き物が環境の中でどのように暮らし、周りと関わっているかという様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38702, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生態", "is_correct": true, "explanation": "「生き物と環境の関わり」を表す名詞。「ペンギンの生態を調べる」の意味に合う。"}, {"text": "工場", "is_correct": false, "explanation": "名詞だが、「ペンギンの工場」は意味をなさない。"}, {"text": "天井", "is_correct": false, "explanation": "名詞だが、「ペンギンの天井」は意味をなさない。"}, {"text": "寝袋", "is_correct": false, "explanation": "名詞だが、「ペンギンの寝袋」は意味をなさない。"}], "explanations": {"生態": "「生き物と環境の関わり」を表す名詞。「ペンギンの生態を調べる」の意味に合う。", "工場": "名詞だが、「ペンギンの工場」は意味をなさない。", "天井": "名詞だが、「ペンギンの天井」は意味をなさない。", "寝袋": "名詞だが、「ペンギンの寝袋」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "生態"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病院で生態検査を受けた。", "explanation": "ここは〈生体〉検査（体の組織を調べる検査）の意味。「生態」は生き物と環境の関わりを指し、体の検査には使わない。"}, {"text": "歌手は生態を痛めて、しばらく歌えなくなった。", "explanation": "同音の〈声帯〉（喉の器官）の意味。「生態」は生き物と環境の関わりで、喉の器官は指さない。"}, {"text": "その男の生態を見破った。", "explanation": "同音の〈正体〉（本当の姿）の意味。「生態」は生き物と環境の関わりで、人の正体は言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38702, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生態", "is_correct": true, "explanation": "「生き物と環境の関わり」を表す名詞。「森の生態を守る」の意味に合う。"}, {"text": "靴", "is_correct": false, "explanation": "名詞だが、「森の靴を守る」は意味をなさない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "名詞だが、「森の冷蔵庫を守る」は意味をなさない。"}, {"text": "窓", "is_correct": false, "explanation": "名詞だが、「森の窓を守る」は意味をなさない。"}], "explanations": {"生態": "「生き物と環境の関わり」を表す名詞。「森の生態を守る」の意味に合う。", "靴": "名詞だが、「森の靴を守る」は意味をなさない。", "冷蔵庫": "名詞だが、「森の冷蔵庫を守る」は意味をなさない。", "窓": "名詞だが、「森の窓を守る」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "生態"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "歌手の生態を検査して、喉の状態を確かめた。", "explanation": "同音の〈声帯〉の意味。「生態」は生き物と環境の関わりで、喉の器官は指さない。"}, {"text": "探偵は犯人の生態を見抜いた。", "explanation": "同音の〈正体〉（本当の姿）の意味。「生態」は生き物と環境の関わりで、人の正体は言わない。"}, {"text": "手術の前に患者の生態を検査した。", "explanation": "同音の〈生体〉（生きている体）の意味。「生態」は環境との関わりで、体そのものは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38702, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その植物を生態を調べた結果、新しい発見があった。", "corrected_sentence": "その植物の生態を調べた結果、新しい発見があった。", "error_description": "「生態」は「の生態」と「の」で修飾する。「を」にすると目的語が二つ重なり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38702, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渡り鳥の生態へ調べる研究が進んでいる。", "corrected_sentence": "渡り鳥の生態を調べる研究が進んでいる。", "error_description": "「調べる」は対象を「を」で示す。「へ」は方向を表すので、調べる対象には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38704, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「自分のパラダイムが狭かった」の主語を示す。形容詞「狭い」は主語に「が」を取る。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「狭い」は目的語を取らないので文意が合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「パラダイムで狭かった」は文意が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "結果や方向を示すが、「パラダイムに狭かった」は「狭い」の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「自分のパラダイムが狭かった」の主語を示す。形容詞「狭い」は主語に「が」を取る。", "を": "目的語を示すが、「狭い」は目的語を取らないので文意が合わない。", "で": "手段や場所を示すが、「パラダイムで狭かった」は文意が成立しない。", "に": "結果や方向を示すが、「パラダイムに狭かった」は「狭い」の主語にならない。"}, "error_tags": {"を": "目的語（狭いは目的語を取らない）", "で": "手段・場所（文意に合わない）", "に": "結果（文意に合わない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
