INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38704, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "考えるときの型や、ものの見方。", "primary_collocate": null, "pronunciation": "ぱらだいむ", "ipa": "paɾadaimɯ", "syllable_count": 5, "sentences": [{"text": "兄と私は育った環境が違うので、物事を考えるパラダイムも違う。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]は育[そだ]った環境[かんきょう]が違[ちが]うので、物事[ものごと]を考[かんが]えるパラダイムも違[ちが]う。", "sentence_source": "generated"}, {"text": "彼の話を聞いて、自分のパラダイムが狭かったことに気づいた。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]を聞[き]いて、自分[じぶん]のパラダイムが狭[せま]かったことに気[き]づいた。", "sentence_source": "generated"}, {"text": "時代が変わると、人々の仕事に対するパラダイムも変わる。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "時代[じだい]が変[か]わると、人々[ひとびと]の仕事[しごと]に対[たい]するパラダイムも変[か]わる。", "sentence_source": "generated"}, {"text": "先生は、これまでのパラダイムにとらわれず、自由に考えるように言った。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "先生[せんせい]は、これまでのパラダイムにとらわれず、自由[じゆう]に考[かんが]えるように言[い]った。", "sentence_source": "generated"}, {"text": "文化の違いは、ものの見方、つまりパラダイムの違いでもある。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "文化[ぶんか]の違[ちが]いは、ものの見方[みかた]、つまりパラダイムの違[ちが]いでもある。", "sentence_source": "generated"}, {"text": "国によって家族に関するパラダイムが違うので、話し合いが必要だ。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "国[くに]によって家族[かぞく]に関[かん]するパラダイムが違[ちが]うので、話[はなし]し合[あ]いが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "新しいパラダイムで見直すと、古い問題にも別の答えが見えてくる。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "新[あたら]しいパラダイムで見直[みなお]すと、古[ふる]い問題[もんだい]にも別[べつ]の答[こた]えが見[み]えてくる。", "sentence_source": "generated"}, {"text": "子どもの考え方を知るには、大人のパラダイムを一度捨てることも大切だ。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "子[こ]どもの考[かんが]え方[かた]を知[し]るには、大人[おとな]のパラダイムを一度[いちど]捨[す]てることも大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "彼女は成功の意味を問い直し、自分のパラダイムを作り直した。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は成功[せいこう]の意味[いみ]を問[と]い直[なお]し、自分[じぶん]のパラダイムを作[つく]り直[なお]した。", "sentence_source": "generated"}, {"text": "旅行で出会った人々によって、私の人生をとらえるパラダイムは大きく変わった。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "旅行[りょこう]で出会[であ]った人々[ひとびと]によって、私[わたし]の人生[じんせい]をとらえるパラダイムは大[おお]きく変[か]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パラダイム", "label": "dictionary form"}, {"form": "パラダイムの", "label": "genitive use"}, {"form": "パラダイムを", "label": "object use"}], "register": "formal", "sense_fingerprint": "人や時代が物事を考えるときの型・ものの見方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38704, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パラダイム", "is_correct": true, "explanation": "「物事を考えるパラダイムも違う」と文意が合い、考え方の型として成立する。"}, {"text": "ジャンケン", "is_correct": false, "explanation": "遊びの一種で、「物事を考える」の型を表さず文意が合わない。"}, {"text": "ボイラー", "is_correct": false, "explanation": "機械の名前で、考え方の型とは意味が合わない。"}, {"text": "ホテル", "is_correct": false, "explanation": "宿泊施設で、物事の考え方を表さない。"}], "explanations": {"パラダイム": "「物事を考えるパラダイムも違う」と文意が合い、考え方の型として成立する。", "ジャンケン": "遊びの一種で、「物事を考える」の型を表さず文意が合わない。", "ボイラー": "機械の名前で、考え方の型とは意味が合わない。", "ホテル": "宿泊施設で、物事の考え方を表さない。"}, "sentence_index": 0, "correct_answer": "パラダイム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕食に、冷蔵庫のパラダイムを使ってカレーを作った。", "explanation": "ここは〈食材〉の意味。カレーに使うのは食材で、考え方の型であるパラダイムは料理の材料にならない。"}, {"text": "雨が降ったので、パラダイムを傘の代わりにさした。", "explanation": "ここは〈道具〉の意味。考え方の型は傘のように使えないので、文として成り立たない。"}, {"text": "彼は電話を切ったあと、パラダイムの電池を交換した。", "explanation": "ここは〈部品〉の意味。電池のように交換できるものではないので、考え方の型の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38704, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パラダイム", "is_correct": true, "explanation": "「新しいパラダイムで見直すと」と文意が合い、考え方の型として使える。"}, {"text": "ファンファーレ", "is_correct": false, "explanation": "祝いの曲の意味で、「で見直す」の手段にならない。"}, {"text": "ピアノ", "is_correct": false, "explanation": "楽器で、考え方の枠組みを見直す手段にならない。"}, {"text": "ルーレット", "is_correct": false, "explanation": "遊具で、物事を見直す手段として文意が合わない。"}], "explanations": {"パラダイム": "「新しいパラダイムで見直すと」と文意が合い、考え方の型として使える。", "ファンファーレ": "祝いの曲の意味で、「で見直す」の手段にならない。", "ピアノ": "楽器で、考え方の枠組みを見直す手段にならない。", "ルーレット": "遊具で、物事を見直す手段として文意が合わない。"}, "sentence_index": 6, "correct_answer": "パラダイム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープはパラダイムが濃くて、塩辛い。", "explanation": "ここは〈味〉の意味。味の濃さは味で言い、考え方の型であるパラダイムには使えない。"}, {"text": "来週の旅行のパラダイムを手帳に書いて、日程を決めた。", "explanation": "ここは〈予定〉の意味。予定は手帳に書くものだが、考え方の型であるパラダイムは予定として書けない。"}, {"text": "彼女は雨が降ったので、パラダイムを着替えてから出かけた。", "explanation": "ここは〈服〉の意味。考え方の型は服のように着替えられないので、文意が成立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38704, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の話を聞いて、私のパラダイムを変わった。", "corrected_sentence": "彼女の話を聞いて、私のパラダイムが変わった。", "error_description": "誤りは助詞の「を」。「変わる」は自動詞で、変化する主語に「が」をつける。「を変わった」は助詞が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38704, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもの頃の経験によって、私のパラダイムを形づくられた。", "corrected_sentence": "子どもの頃の経験によって、私のパラダイムが形づくられた。", "error_description": "誤りは助詞の「を」。受身文では対象が主語になり「が」で示すので、「を」は誤り。正しくは「パラダイムが形づくられた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38705, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「古いパラダイムが入れ替わる」で、入れ替わる主体を示す主格。文意に合う。"}, {"text": "を", "is_correct": false, "explanation": "「入れ替わる」は自動詞なので目的語の「を」は取らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す「で」で、ここでは文意に合わない。"}, {"text": "に", "is_correct": false, "explanation": "方向や結果を表す「に」で、主体が入れ替わる文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「古いパラダイムが入れ替わる」で、入れ替わる主体を示す主格。文意に合う。", "を": "「入れ替わる」は自動詞なので目的語の「を」は取らない。", "で": "手段や場所を表す「で」で、ここでは文意に合わない。", "に": "方向や結果を表す「に」で、主体が入れ替わる文には合わない。"}, "error_tags": {"を": "目的語（入れ替わるは自動詞なので取らない）", "で": "手段・場所（文意に合わない）", "に": "方向・結果（文意に合わない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
