INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38705, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある分野で、模範となる考え方や方法の枠組み。", "primary_collocate": null, "pronunciation": "ぱらだいむ", "ipa": "paɾadaimɯ", "syllable_count": 5, "sentences": [{"text": "しかし現代ファッションの文脈では、この伝統的な職人技はデジタルデザインという新たなパラダイムと衝突し、あるいは融合しつつある。", "target_word": "パラダイム", "complexity_tier": "T5", "furigana": "しかし現代[げんだい]ファッションの文脈[ぶんみゃく]では、この伝統的[でんとうてき]な職人技[しょくにんわざ]はデジタルデザインという新[あら]たなパラダイムと衝突[しょうとつ]し、あるいは融合[ゆうごう]しつつある。", "sentence_source": "mined"}, {"text": "科学の歴史では、新しい発見によって古いパラダイムが入れ替わることがある。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "科学[かがく]の歴史[れきし]では、新[あたら]しい発見[はっけん]によって古[ふる]いパラダイムが入[い]れ替[か]わることがある。", "sentence_source": "generated"}, {"text": "地動説が広まったとき、天文学のパラダイムは大きく変わった。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "地動説[ちどうせつ]が広[ひろ]まったとき、天文学[てんもんがく]のパラダイムは大[おお]きく変[か]わった。", "sentence_source": "generated"}, {"text": "医療の現場では、治療より予防を重んじるパラダイムが力を持ち始めている。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "医療[いりょう]の現場[げんば]では、治療[ちりょう]より予防[よぼう]を重[おも]んじるパラダイムが力[ちから]を持[も]ち始[はじ]めている。", "sentence_source": "generated"}, {"text": "研究者たちは、従来のパラダイムでは説明できない現象に注目した。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]たちは、従来[じゅうらい]のパラダイムでは説明[せつめい]できない現象[げんしょう]に注目[ちゅうもく]した。", "sentence_source": "generated"}, {"text": "この大学は、教育の枠組みを問い直す新しいパラダイムを提案している。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "この大学[だいがく]は、教育[きょういく]の枠組[わくぐ]みを問[と]い直[なお]す新[あたら]しいパラダイムを提案[ていあん]している。", "sentence_source": "generated"}, {"text": "新しいパラダイムが受け入れられるまでには、長い時間がかかる。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "新[あたら]しいパラダイムが受[う]け入[い]れられるまでには、長[なが]い時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "ニュートン力学というパラダイムは、長い間物理学の中心だった。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "ニュートン力学[りきがく]というパラダイムは、長[なが]い間[あいだ]物理学[ぶつりがく]の中心[ちゅうしん]だった。", "sentence_source": "generated"}, {"text": "経営学では、大量生産のパラダイムが長く主流だったが、今は変わりつつある。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "経営学[けいえいがく]では、大量生産[たいりょうせいさん]のパラダイムが長[なが]く主流[しゅりゅう]だったが、今[いま]は変[か]わりつつある。", "sentence_source": "generated"}, {"text": "若い研究者は、既存のパラダイムに疑問を持つことから新しい理論を生み出した。", "target_word": "パラダイム", "complexity_tier": "T3", "furigana": "若[わか]い研究者[けんきゅうしゃ]は、既存[きそん]のパラダイムに疑問[ぎもん]を持[も]つことから新[あたら]しい理論[りろん]を生[う]み出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パラダイム", "label": "dictionary form"}, {"form": "パラダイムの", "label": "genitive use"}, {"form": "パラダイムを", "label": "object use"}], "register": "formal", "sense_fingerprint": "学問や分野で共有される模範的な理論・方法の枠組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38705, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パラダイム", "is_correct": true, "explanation": "「新たなパラダイムと衝突し」の位置に入り、考え方の枠組みとして文意が成立する。"}, {"text": "ナンセンス", "is_correct": false, "explanation": "無意味な話を指し、「衝突し」の相手になる枠組みを表さない。"}, {"text": "ユーモア", "is_correct": false, "explanation": "人の感覚や態度を指し、枠組みとして衝突するとは言えない。"}, {"text": "サンプル", "is_correct": false, "explanation": "見本の意味で、ここで言う新しい枠組みとは合わない。"}], "explanations": {"パラダイム": "「新たなパラダイムと衝突し」の位置に入り、考え方の枠組みとして文意が成立する。", "ナンセンス": "無意味な話を指し、「衝突し」の相手になる枠組みを表さない。", "ユーモア": "人の感覚や態度を指し、枠組みとして衝突するとは言えない。", "サンプル": "見本の意味で、ここで言う新しい枠組みとは合わない。"}, "sentence_index": 0, "correct_answer": "パラダイム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医師は患者に新しいパラダイムを処方した。", "explanation": "ここは〈薬剤〉の意味。パラダイムは薬のように処方できるものではなく、〈枠組み〉の意味では使えない。"}, {"text": "試験で、先生が出したパラダイムに答えを書いた。", "explanation": "ここは〈問題〉の意味。パラダイムは問題文ではないので、答えを書く対象にならない。"}, {"text": "壁のパラダイムを青く塗った。", "explanation": "ここは〈色〉の意味。パラダイムは色ではないので、塗るという行為の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38705, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パラダイム", "is_correct": true, "explanation": "「新しいパラダイムが受け入れられる」と文意が合い、考え方の枠組みとして成立する。"}, {"text": "パニック", "is_correct": false, "explanation": "混乱を指し、「受け入れられる」の対象にならない。"}, {"text": "スキャンダル", "is_correct": false, "explanation": "醜聞の意味で、受け入れられる対象ではない。"}, {"text": "ボイコット", "is_correct": false, "explanation": "不買や拒否の運動を指し、受け入れられるものとは言えない。"}], "explanations": {"パラダイム": "「新しいパラダイムが受け入れられる」と文意が合い、考え方の枠組みとして成立する。", "パニック": "混乱を指し、「受け入れられる」の対象にならない。", "スキャンダル": "醜聞の意味で、受け入れられる対象ではない。", "ボイコット": "不買や拒否の運動を指し、受け入れられるものとは言えない。"}, "sentence_index": 6, "correct_answer": "パラダイム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "若い研究者は、古い実験装置のパラダイムを、重い箱に詰めて運んだ。", "explanation": "ここは〈物品〉の意味。考え方の枠組みは箱に詰めて運べないので、文として成り立たない。"}, {"text": "若い研究者は、既存のパラダイムを一晩で食べた。", "explanation": "ここは〈食べ物〉の意味。考え方の枠組みは食べられないので、文として成り立たない。"}, {"text": "若い研究者は、既存のパラダイムを写真に撮った。", "explanation": "ここは〈写真〉の意味。枠組みは撮影の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38705, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい研究で、教育のパラダイムを大きく見直された。", "corrected_sentence": "新しい研究で、教育のパラダイムが大きく見直された。", "error_description": "誤りは助詞の「を」。「見直された」は受身で、パラダイムは主語になるので「が」が正しい。「を」では受身文の主語にならず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38705, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究チームは、この分野のパラダイムを従って実験を組み立てた。", "corrected_sentence": "研究チームは、この分野のパラダイムに従って実験を組み立てた。", "error_description": "誤りは助詞の「を」。「従う」は「〜に従う」と相手に「に」を取る。「パラダイムを従う」は助詞が誤り。正しくは「パラダイムに従って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38706, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「今後の予定」の「の」は、「今後」と「予定」をつなぐ連体修飾の助詞。正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「今後を予定」では「今後」が目的語になり、意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「今後が予定」では「今後」が主語になってしまい不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。「今後で予定」では名詞どうしをつながず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「今後の予定」の「の」は、「今後」と「予定」をつなぐ連体修飾の助詞。正解。", "を": "「を」は目的語を示す。「今後を予定」では「今後」が目的語になり、意味が通らない。", "が": "「が」は主語を示す。「今後が予定」では「今後」が主語になってしまい不自然。", "で": "「で」は場所や手段を示す。「今後で予定」では名詞どうしをつながず、不自然。"}, "error_tags": {"の": "連体修飾", "を": "目的語", "が": "主語", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38706, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38706, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これから先のこと。", "primary_collocate": null, "pronunciation": "こんご", "ipa": "koŋɡo", "syllable_count": 3, "sentences": [{"text": "今後は、時間を守って来てください。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]は、時間[じかん]を守[まも]って来[き]てください。", "sentence_source": "generated"}, {"text": "今後の予定について、先生から説明があります。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]の予定[よてい]について、先生[せんせい]から説明[せつめい]があります。", "sentence_source": "generated"}, {"text": "失敗したが、今後は同じ間違いをしないようにしたい。", "target_word": "今後", "complexity_tier": "T3", "furigana": "失敗[しっぱい]したが、今後[こんご]は同[おな]じ間違[まちが]いをしないようにしたい。", "sentence_source": "generated"}, {"text": "今後も、この店を続けていくつもりです。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]も、この店[みせ]を続[つづ]けていくつもりです。", "sentence_source": "generated"}, {"text": "雨が多いので、今後の天気が心配だ。", "target_word": "今後", "complexity_tier": "T3", "furigana": "雨[あめ]が多[おお]いので、今後[こんご]の天気[てんき]が心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "今後のことは、家族とよく相談して決めます。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]のことは、家族[かぞく]とよく相談[そうだん]して決[き]めます。", "sentence_source": "generated"}, {"text": "会社は今後、新しい商品を増やす方針だ。", "target_word": "今後", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は今後[こんご]、新[あたら]しい商品[しょうひん]を増[ふ]やす方針[ほうしん]だ。", "sentence_source": "generated"}, {"text": "今後、この道は車が通れなくなります。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]、この道[みち]は車[くるま]が通[とお]れなくなります。", "sentence_source": "generated"}, {"text": "今回は許しますが、今後は気をつけなさい。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今回[こんかい]は許[ゆる]しますが、今後[こんご]は気[き]をつけなさい。", "sentence_source": "generated"}, {"text": "今後も変わらず、よろしくお願いします。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]も変[か]わらず、よろしくお願[ねが]いします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "今後", "label": "基本形"}], "register": "標準", "sense_fingerprint": "今後：今の時点から先、これからのこと（方針・予定・注意などで使う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38706, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今後", "is_correct": true, "explanation": "「今後は」はこれから先を表し、これからの時間の守り方を頼む文に合う。正解。"}, {"text": "昨日", "is_correct": false, "explanation": "過去の日を指すので、これから先のことを頼む文には合わない。"}, {"text": "先週", "is_correct": false, "explanation": "過去の週を指すので、これからの約束を求める文と噛み合わない。"}, {"text": "夜中", "is_correct": false, "explanation": "特定の深夜の時間帯で、時間を守る依頼の時期としては意味が通らない。"}], "explanations": {"今後": "「今後は」はこれから先を表し、これからの時間の守り方を頼む文に合う。正解。", "昨日": "過去の日を指すので、これから先のことを頼む文には合わない。", "先週": "過去の週を指すので、これからの約束を求める文と噛み合わない。", "夜中": "特定の深夜の時間帯で、時間を守る依頼の時期としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "今後"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今後の試合で、チームは三対零で勝った。", "explanation": "ここは〈今回〉の意味。今後は未来に向けて使う語なので、もう終わった試合の結果には合わない。"}, {"text": "今後の会議では、予算が決まらなかった。", "explanation": "ここは〈前回〉の意味。今後は未来のことを指すので、済んだ会議の結果には使えない。"}, {"text": "今後は、この店で毎朝パンを焼いていた。", "explanation": "ここは〈以前〉の意味。今後は未来の方針を述べる語なので、過去の習慣を表す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38706, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今後", "is_correct": true, "explanation": "「今後、新しい商品を増やす方針」は、これから先の方針を表すので正解。"}, {"text": "祝日", "is_correct": false, "explanation": "休日の日を指す語で、会社の方針を示す文の時期としては意味が通らない。"}, {"text": "昼休み", "is_correct": false, "explanation": "一日の中の短い休憩時間で、会社が商品を増やす方針の時期を示す語としては不自然。"}, {"text": "夜明け", "is_correct": false, "explanation": "早朝の時刻を指すので、会社の方針を述べる文の時期にはならない。"}], "explanations": {"今後": "「今後、新しい商品を増やす方針」は、これから先の方針を表すので正解。", "祝日": "休日の日を指す語で、会社の方針を示す文の時期としては意味が通らない。", "昼休み": "一日の中の短い休憩時間で、会社が商品を増やす方針の時期を示す語としては不自然。", "夜明け": "早朝の時刻を指すので、会社の方針を述べる文の時期にはならない。"}, "sentence_index": 6, "correct_answer": "今後"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今後は、週末だけ練習していた。", "explanation": "ここは〈これまで〉の意味。今後は未来に向けて使う語なので、過去の習慣を述べる文には合わない。"}, {"text": "今後の大雨で、川が増水した。", "explanation": "ここは〈先日〉の意味。今後は未来の出来事を指すので、すでに起きた大雨には使えない。"}, {"text": "今後の授業は、とても難しかった。", "explanation": "ここは〈今日〉の意味。今後は今の時点より先を指すので、すでに受けた授業の感想には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38706, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今後で、新しい方針を発表します。", "corrected_sentence": "今後、新しい方針を発表します。", "error_description": "「今後」は時を表す語なので、後ろに「で」を付けるのは誤り。正しくは「今後、」と読点で区切って時を示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38706, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今後が、会議の日程を変更します。", "corrected_sentence": "今後は、会議の日程を変更します。", "error_description": "「今後」を話題として示すには「は」を使う。「が」は主語を示すが、時を表す語は日程を変更する主体にならないので不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
