INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38707, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「今後の成長」の「の」は、「今後」と「成長」をつなぐ連体修飾の助詞。正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「今後が成長」では「今後」が主語になってしまい不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「今後を成長」では成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。「今後で成長」では名詞どうしをつながず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「今後の成長」の「の」は、「今後」と「成長」をつなぐ連体修飾の助詞。正解。", "が": "「が」は主語を示す。「今後が成長」では「今後」が主語になってしまい不自然。", "を": "「を」は目的語を示す。「今後を成長」では成り立たない。", "で": "「で」は場所や手段を示す。「今後で成長」では名詞どうしをつながず、不自然。"}, "error_tags": {"の": "連体修飾", "が": "主語", "を": "目的語", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38707, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これからの時や出来事。将来。", "primary_collocate": null, "pronunciation": "こんご", "ipa": "koŋɡo", "syllable_count": 3, "sentences": [{"text": "今後の世の中がどうなるか、誰にも分からない。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]の世[よ]の中[なか]がどうなるか、誰[だれ]にも分[わ]からない。", "sentence_source": "generated"}, {"text": "彼は今後十年の計画を立てた。", "target_word": "今後", "complexity_tier": "T3", "furigana": "彼[かれ]は今後[こんご]十年[じゅうねん]の計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "この町は今後、人口が減っていくと言われている。", "target_word": "今後", "complexity_tier": "T3", "furigana": "この町[まち]は今後[こんご]、人口[じんこう]が減[へ]っていくと言[い]われている。", "sentence_source": "generated"}, {"text": "今後に備えて、毎月少しずつ貯金している。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]に備[そな]えて、毎月[まいつき]少[すこ]しずつ貯金[ちょきん]している。", "sentence_source": "generated"}, {"text": "技術の進歩で、今後は働き方も変わるだろう。", "target_word": "今後", "complexity_tier": "T3", "furigana": "技術[ぎじゅつ]の進歩[しんぽ]で、今後[こんご]は働[はたら]き方[かた]も変[か]わるだろう。", "sentence_source": "generated"}, {"text": "今後の課題は、費用をどう減らすかだ。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]の課題[かだい]は、費用[ひよう]をどう減[へ]らすかだ。", "sentence_source": "generated"}, {"text": "今後起こりうる地震に、私たちは準備しておく必要がある。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]起[お]こりうる地震[じしん]に、私[わたし]たちは準備[じゅんび]しておく必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "今後の成長が楽しみな選手だ。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]の成長[せいちょう]が楽[たの]しみな選手[せんしゅ]だ。", "sentence_source": "generated"}, {"text": "景気は、今後ゆっくり回復すると予想されている。", "target_word": "今後", "complexity_tier": "T3", "furigana": "景気[けいき]は、今後[こんご]ゆっくり回復[かいふく]すると予想[よそう]されている。", "sentence_source": "generated"}, {"text": "今後を考えて、新しい資格の勉強を始めた。", "target_word": "今後", "complexity_tier": "T3", "furigana": "今後[こんご]を考[かんが]えて、新[あたら]しい資格[しかく]の勉強[べんきょう]を始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "今後", "label": "基本形"}], "register": "標準", "sense_fingerprint": "今後：これから先に来る時期や出来事、将来の見通し・課題", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38707, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今後", "is_correct": true, "explanation": "「今後の世の中」はこれから先の世の中を表すので、誰にも分からないという文に合う。正解。"}, {"text": "食後", "is_correct": false, "explanation": "食事の後を表す語で、世の中の行く末を述べる文には意味が通らない。"}, {"text": "昼休み", "is_correct": false, "explanation": "短い休憩時間を指すので、世の中の行く末を表す語としては不自然。"}, {"text": "祝日", "is_correct": false, "explanation": "休みの日を指すので、世の中の行く末を述べる文と噛み合わない。"}], "explanations": {"今後": "「今後の世の中」はこれから先の世の中を表すので、誰にも分からないという文に合う。正解。", "食後": "食事の後を表す語で、世の中の行く末を述べる文には意味が通らない。", "昼休み": "短い休憩時間を指すので、世の中の行く末を表す語としては不自然。", "祝日": "休みの日を指すので、世の中の行く末を述べる文と噛み合わない。"}, "sentence_index": 0, "correct_answer": "今後"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今後の試験は、思ったより易しかった。", "explanation": "ここは〈前回〉の意味。今後は未来の時期を指すので、もう受けた試験の感想には使えない。"}, {"text": "今後の冬は、雪がほとんど降らなかった。", "explanation": "ここは〈去年〉の意味。今後は未来の季節を指すので、過去の冬の出来事には合わない。"}, {"text": "今後の私は、この町に三年間住んでいた。", "explanation": "ここは〈以前〉の意味。今後は未来を指すので、過去に住んでいた期間には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38707, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今後", "is_correct": true, "explanation": "「今後起こりうる地震」は、これから先に起こる可能性のある地震を表すので正解。"}, {"text": "正午", "is_correct": false, "explanation": "正午という時刻を指すので、起こりうる地震の時期を示す語としては不自然。"}, {"text": "夕食", "is_correct": false, "explanation": "食事を指す語で、地震の時期を表す文の修飾語にはならない。"}, {"text": "放課後", "is_correct": false, "explanation": "授業が終わった後の時間を指すので、地震がこれから起こりうるという文に合わない。"}], "explanations": {"今後": "「今後起こりうる地震」は、これから先に起こる可能性のある地震を表すので正解。", "正午": "正午という時刻を指すので、起こりうる地震の時期を示す語としては不自然。", "夕食": "食事を指す語で、地震の時期を表す文の修飾語にはならない。", "放課後": "授業が終わった後の時間を指すので、地震がこれから起こりうるという文に合わない。"}, "sentence_index": 6, "correct_answer": "今後"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今後の売上は、前年を上回った。", "explanation": "ここは〈先月〉の意味。今後は未来の時期を指すので、すでに終わった月の売上には使えない。"}, {"text": "今後の彼は、三年前にこの町を離れていた。", "explanation": "ここは〈当時〉の意味。今後は未来を指すので、過去のある時点の状態を述べる文には合わない。"}, {"text": "今後の私は、子どもの頃に海外へ行った。", "explanation": "ここは〈当初〉の意味。今後は未来を指すので、以前の出来事を述べる文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38707, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今後が、景気はゆっくり回復すると予想されている。", "corrected_sentence": "今後、景気はゆっくり回復すると予想されている。", "error_description": "「今後」に「が」を付けると主語扱いになり、後ろの文と噛み合わない。時を示す語は読点で区切って「今後、」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38707, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今後と、新しいルールが始まる。", "corrected_sentence": "今後、新しいルールが始まる。", "error_description": "「と」は名詞と名詞をつなぐ助詞なので、並べる相手のない「今後と」は誤り。時を示す語は読点で区切って「今後、」とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38708, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「挙動は」で主題を示し、温度による変化の話につながる。"}, {"text": "を", "is_correct": false, "explanation": "「変わる」は自動詞なので、目的語の「を」は取れない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」では「挙動で温度によって」となり意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、変化の主体にならない。"}], "correct_answer": "は", "explanations": {"は": "「挙動は」で主題を示し、温度による変化の話につながる。", "を": "「変わる」は自動詞なので、目的語の「を」は取れない。", "で": "手段を示す「で」では「挙動で温度によって」となり意味が通らない。", "へ": "方向を示す「へ」では、変化の主体にならない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38708, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「挙動は」で主題を示し、ぎこちなくなるという述語につながる。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、ぎこちなくなる理由や状態にならない。"}, {"text": "と", "is_correct": false, "explanation": "「挙動と」では並列になり、ぎこちなくなる主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "挙動の後に続く名詞がなく、「の」では文が切れて続かない。"}], "correct_answer": "は", "explanations": {"は": "「挙動は」で主題を示し、ぎこちなくなるという述語につながる。", "から": "起点の「から」では、ぎこちなくなる理由や状態にならない。", "と": "「挙動と」では並列になり、ぎこちなくなる主語にならない。", "の": "挙動の後に続く名詞がなく、「の」では文が切れて続かない。"}, "error_tags": {"から": "起点", "と": "並列", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38708, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事がどのように動いたり変わったりするかの、ようすや動きのこと。", "primary_collocate": null, "pronunciation": "きょどう", "ipa": "kʲodoː", "syllable_count": 3, "sentences": [{"text": "地震のとき、建物がどんな挙動を示すかを計算で予測する。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "地震[じしん]のとき、建物[たてもの]がどんな挙動[きょどう]を示[しめ]すかを計算[けいさん]で予測[よそく]する。", "sentence_source": "generated"}, {"text": "水の挙動は温度によって大きく変わる。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "水[みず]の挙動[きょどう]は温度[おんど]によって大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "大雨の前後で、川の水の挙動を比べた。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "大雨[おおあめ]の前後[ぜんご]で、川[かわ]の水[みず]の挙動[きょどう]を比[くら]べた。", "sentence_source": "generated"}, {"text": "市場の挙動が読みにくく、投資家たちは慎重になっている。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "市場[しじょう]の挙動[きょどう]が読[よ]みにくく、投資家[とうしか]たちは慎重[しんちょう]になっている。", "sentence_source": "generated"}, {"text": "犬の挙動が急に落ち着かなくなったので、散歩に連れ出した。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "犬[いぬ]の挙動[きょどう]が急[きゅう]に落[お]ち着[つ]かなくなったので、散歩[さんぽ]に連[つ]れ出[だ]した。", "sentence_source": "generated"}, {"text": "不審な挙動の男が、駅の改札付近をうろついていた。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "不審[ふしん]な挙動[きょどう]の男[おとこ]が、駅[えき]の改札[かいさつ]付近[ふきん]をうろついていた。", "sentence_source": "generated"}, {"text": "液体の挙動を調べる実験で、粘度の違いがはっきりわかった。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "液体[えきたい]の挙動[きょどう]を調[しら]べる実験[じっけん]で、粘度[ねんど]の違[ちが]いがはっきりわかった。", "sentence_source": "generated"}, {"text": "緊張すると、彼の挙動はぎこちなくなる。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "緊張[きんちょう]すると、彼[かれ]の挙動[きょどう]はぎこちなくなる。", "sentence_source": "generated"}, {"text": "電車が急に止まった原因は、信号システムの挙動にあった。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が急[きゅう]に止[と]まった原因[げんいん]は、信号[しんごう]システムの挙動[きょどう]にあった。", "sentence_source": "generated"}, {"text": "氷の上でタイヤがどんな挙動をするか、冬の前に試験する。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "氷[こおり]の上[うえ]でタイヤがどんな挙動[きょどう]をするか、冬[ふゆ]の前[まえ]に試験[しけん]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "挙動", "label": "基本形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "物・自然現象・人や動物などの動きや変化のようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d2050e-73d4-41bb-b305-1aad375477d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38708, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挙動", "is_correct": true, "explanation": "建物がどう動くかを示す語として、「示す」と自然につながる。"}, {"text": "味覚", "is_correct": false, "explanation": "味覚は味を感じる働きで、建物の動きには使えない。"}, {"text": "貯金", "is_correct": false, "explanation": "貯金はお金をためることで、建物の動きを示す文脈に合わない。"}, {"text": "主食", "is_correct": false, "explanation": "主食は主に食べる食品のことで、ここでは意味が通らない。"}], "explanations": {"挙動": "建物がどう動くかを示す語として、「示す」と自然につながる。", "味覚": "味覚は味を感じる働きで、建物の動きには使えない。", "貯金": "貯金はお金をためることで、建物の動きを示す文脈に合わない。", "主食": "主食は主に食べる食品のことで、ここでは意味が通らない。"}, "sentence_index": 0, "correct_answer": "挙動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このラジオは挙動を大きくできる。", "explanation": "ここは〈音量〉の意味。挙動は動き方のようすで、音の強さは表せないので合わない。"}, {"text": "明日は挙動が晴れるでしょう。", "explanation": "ここは〈天気〉の意味。挙動は物事の動き方で、空模様には使わない。"}, {"text": "この新商品は挙動が安くて、学生にも買いやすい。", "explanation": "ここは〈価格〉の意味。挙動は動き方のことで、値段は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38708, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挙動", "is_correct": true, "explanation": "液体がどう動くかを調べるという文脈に合う。"}, {"text": "家計簿", "is_correct": false, "explanation": "家計簿は家のお金の記録で、液体を調べる文脈には合わない。"}, {"text": "勤務表", "is_correct": false, "explanation": "勤務表は働く時間の予定表で、液体には使えない。"}, {"text": "献立", "is_correct": false, "explanation": "献立は料理の計画のことで、液体を調べる実験には合わない。"}], "explanations": {"挙動": "液体がどう動くかを調べるという文脈に合う。", "家計簿": "家計簿は家のお金の記録で、液体を調べる文脈には合わない。", "勤務表": "勤務表は働く時間の予定表で、液体には使えない。", "献立": "献立は料理の計画のことで、液体を調べる実験には合わない。"}, "sentence_index": 6, "correct_answer": "挙動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏までに挙動を五キロ減らしたい。", "explanation": "ここは〈体重〉の意味。挙動は動き方で、体の重さは表せないので合わない。"}, {"text": "駅までの挙動は、歩いて十分ほどだ。", "explanation": "ここは〈距離〉の意味。挙動は動きのようすで、道のりの長さには使わない。"}, {"text": "試合で、彼は後半に二点の挙動を挙げた。", "explanation": "ここは〈得点〉の意味。挙動は動き方で、点数を挙げるとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38708, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "気温が上がると、ガラスの挙動を大きく変わる。", "corrected_sentence": "気温が上がると、ガラスの挙動が大きく変わる。", "error_description": "誤: 挙動を（「変わる」は自動詞なので「を」は使えない）。正: 挙動が（主語を示す「が」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38708, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "犬の挙動が、いつもより大きく変わりていた。", "corrected_sentence": "犬の挙動が、いつもより大きく変わっていた。", "error_description": "誤: 変わりていた（「変わっている」の形にするには「変わって」が必要）。正: 変わっていた。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38709, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「挙動が」で、変わる主体を示す。文意に合う。"}, {"text": "を", "is_correct": false, "explanation": "「変わる」は自動詞なので目的語の「を」は取れない。"}, {"text": "と", "is_correct": false, "explanation": "「以前と」の「と」と並び、挙動との並列では文意が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "挙動の後に続く名詞がなく、「の」では文が続かない。"}], "correct_answer": "が", "explanations": {"が": "「挙動が」で、変わる主体を示す。文意に合う。", "を": "「変わる」は自動詞なので目的語の「を」は取れない。", "と": "「以前と」の「と」と並び、挙動との並列では文意が崩れる。", "の": "挙動の後に続く名詞がなく、「の」では文が続かない。"}, "error_tags": {"を": "目的語", "と": "並列", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38709, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「挙動は」で主題を示し、後のシミュレーションとの比較につながる。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」では、一致の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は一致の相手にならず、文意が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」では「挙動で一致した」となり意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「挙動は」で主題を示し、後のシミュレーションとの比較につながる。", "から": "起点を示す「から」では、一致の関係が成り立たない。", "へ": "方向を示す「へ」は一致の相手にならず、文意が通らない。", "で": "手段や場所を示す「で」では「挙動で一致した」となり意味が通らない。"}, "error_tags": {"から": "起点", "へ": "方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38709, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が実際に行われるときの、動作や状態の現れ方。", "primary_collocate": null, "pronunciation": "きょどう", "ipa": "kʲodoː", "syllable_count": 3, "sentences": [{"text": "しかる後に、プログラミングという「神経系」を構築し、抽象的論理と物理的挙動を厳密に同期させるのだ。", "target_word": "挙動", "complexity_tier": "T4", "furigana": "しかる後[のち]に、プログラミングという「神経系[しんけいけい]」を構築[こうちく]し、抽象的[ちゅうしょうてき]論理[ろんり]と物理的[ぶつりてき]挙動[きょどう]を厳密[げんみつ]に同期[どうき]させるのだ。", "sentence_source": "mined"}, {"text": "新しいバージョンでは、アプリの挙動が以前と少し変わった。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "新[あたら]しいバージョンでは、アプリの挙動[きょどう]が以前[いぜん]と少[すこ]し変[か]わった。", "sentence_source": "generated"}, {"text": "テストの結果、ロボットの挙動に異常は見られなかった。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "テストの結果[けっか]、ロボットの挙動[きょどう]に異常[いじょう]は見[み]られなかった。", "sentence_source": "generated"}, {"text": "プログラムの挙動を確認するために、ログを細かく調べた。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "プログラムの挙動[きょどう]を確認[かくにん]するために、ログを細[こま]かく調[しら]べた。", "sentence_source": "generated"}, {"text": "古いパソコンでは、ソフトの挙動が不安定になることがある。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "古[ふる]いパソコンでは、ソフトの挙動[きょどう]が不安定[ふあんてい]になることがある。", "sentence_source": "generated"}, {"text": "設定を変えると、センサーの挙動が不安定になってしまった。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "設定[せってい]を変[か]えると、センサーの挙動[きょどう]が不安定[ふあんてい]になってしまった。", "sentence_source": "generated"}, {"text": "想定外の挙動を防ぐため、入力値のチェックを追加した。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "想定外[そうていがい]の挙動[きょどう]を防[ふせ]ぐため、入力値[にゅうりょくち]のチェックを追加[ついか]した。", "sentence_source": "generated"}, {"text": "実機での挙動は、シミュレーションの結果とほとんど一致していた。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "実機[じっき]での挙動[きょどう]は、シミュレーションの結果[けっか]とほとんど一致[いっち]していた。", "sentence_source": "generated"}, {"text": "この関数は、引数が空のときの挙動が仕様書に書かれていない。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "この関数[かんすう]は、引数[ひきすう]が空[から]のときの挙動[きょどう]が仕様書[しようしょ]に書[か]かれていない。", "sentence_source": "generated"}, {"text": "ロボットアームに重い荷物を載せて、そのときの挙動を観察した。", "target_word": "挙動", "complexity_tier": "T3", "furigana": "ロボットアームに重[おも]い荷物[にもつ]を載[の]せて、そのときの挙動[きょどう]を観察[かんさつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "挙動", "label": "基本形"}], "register": "書き言葉・技術的", "sense_fingerprint": "機械やプログラムなどが実際に動くときの動作・状態の現れ方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d2050e-73d4-41bb-b305-1aad375477d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38709, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挙動", "is_correct": true, "explanation": "「物理的」と並び、実際に動くときの動作のようすを表すので文意に合う。"}, {"text": "天候", "is_correct": false, "explanation": "天候は空模様のことで、機械の動作には使えない。"}, {"text": "機嫌", "is_correct": false, "explanation": "機嫌は人の気分を表し、物理的な動きとは合わない。"}, {"text": "好物", "is_correct": false, "explanation": "好物は食べ物の好みのことで、ここでは意味が通らない。"}], "explanations": {"挙動": "「物理的」と並び、実際に動くときの動作のようすを表すので文意に合う。", "天候": "天候は空模様のことで、機械の動作には使えない。", "機嫌": "機嫌は人の気分を表し、物理的な動きとは合わない。", "好物": "好物は食べ物の好みのことで、ここでは意味が通らない。"}, "sentence_index": 0, "correct_answer": "挙動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店のパンは挙動が高く、毎日は買えない。", "explanation": "ここは〈値段〉の意味。挙動は動き方のようすで、値段の高さは表せないので合わない。"}, {"text": "彼は新しい課長の挙動に就いた。", "explanation": "ここは〈役職〉の意味。挙動は動き方のようすで、職の地位には就けないので合わない。"}, {"text": "テストの結果、彼は挙動が伸びず、先生と相談した。", "explanation": "ここは〈成績〉の意味。挙動は動きのようすで、伸びる得点や評価には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38709, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挙動", "is_correct": true, "explanation": "想定外の動作を防ぐという文脈に合う。"}, {"text": "照明", "is_correct": false, "explanation": "照明は明かりを与える設備で、防ぐ対象にはならない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは匂いのことで、想定外の動きを防ぐ文脈では成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は人や物の重さで、防ぐ対象にはならない。"}], "explanations": {"挙動": "想定外の動作を防ぐという文脈に合う。", "照明": "照明は明かりを与える設備で、防ぐ対象にはならない。", "香り": "香りは匂いのことで、想定外の動きを防ぐ文脈では成り立たない。", "体重": "体重は人や物の重さで、防ぐ対象にはならない。"}, "sentence_index": 6, "correct_answer": "挙動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この電池は挙動が長く、一年以上使える。", "explanation": "ここは〈寿命〉の意味。挙動は動き方のことで、電池がもつ期間は表せない。"}, {"text": "このスープは挙動が濃く、少し塩辛い。", "explanation": "ここは〈味〉の意味。挙動は動きのようすで、食べ物の味の濃さには使わない。"}, {"text": "彼の挙動は今年で三十になる。", "explanation": "ここは〈年齢〉の意味。挙動は動き方やふるまいで、人の年齢は表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38709, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい機能を入れてから、アプリの挙動を以前と大きく変わった。", "corrected_sentence": "新しい機能を入れてから、アプリの挙動が以前と大きく変わった。", "error_description": "誤: 挙動を（「変わる」は自動詞なので目的語の「を」は使えない）。正: 挙動が（変化の主体を示す「が」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38709, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "設定を変えたあと、機械の挙動が予想と一致ていた。", "corrected_sentence": "設定を変えたあと、機械の挙動が予想と一致していた。", "error_description": "誤: 一致ていた（「一致している」の「し」が抜けている）。正: 一致していた。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38710, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「結果を」の〈を〉。予測の対象を示し、ここで自然。"}, {"text": "に", "is_correct": false, "explanation": "「結果に予測して」は成り立たない。〈に〉は位置や相手を表す。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す。予測の向かう先を述べる文脈ではなく合わない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列や相手を示すが、「結果と予測して」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「結果を」の〈を〉。予測の対象を示し、ここで自然。", "に": "「結果に予測して」は成り立たない。〈に〉は位置や相手を表す。", "へ": "〈へ〉は方向を示す。予測の向かう先を述べる文脈ではなく合わない。", "と": "〈と〉は並列や相手を示すが、「結果と予測して」は文として成り立たない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38710, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「結果を」の〈を〉。予測の対象を示す目的語として自然。"}, {"text": "が", "is_correct": false, "explanation": "「結果が予測する前に」は主語と述語が合わず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「結果の予測する前に」は連体修飾として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「結果と予測する」は成り立たない。〈と〉は並列や相手を示す。"}], "correct_answer": "を", "explanations": {"を": "「結果を」の〈を〉。予測の対象を示す目的語として自然。", "が": "「結果が予測する前に」は主語と述語が合わず不自然。", "の": "「結果の予測する前に」は連体修飾として成り立たない。", "と": "「結果と予測する」は成り立たない。〈と〉は並列や相手を示す。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38710, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "まだ起こっていないことについて、どうなるか考えること。", "primary_collocate": null, "pronunciation": "よそく", "ipa": "josokɯ", "syllable_count": 3, "sentences": [{"text": "地震の時期を予測するのは、とても難しい。", "target_word": "予測", "complexity_tier": "T3", "furigana": "地震[じしん]の時期[じき]を予測[よそく]するのは、とても難[むずか]しい。", "sentence_source": "generated"}, {"text": "選挙の結果を予測して、記事を書いた。", "target_word": "予測", "complexity_tier": "T3", "furigana": "選挙[せんきょ]の結果[けっか]を予測[よそく]して、記事[きじ]を書[か]いた。", "sentence_source": "generated"}, {"text": "データから需要を予測する仕事をしています。", "target_word": "予測", "complexity_tier": "T3", "furigana": "データから需要[じゅよう]を予測[よそく]する仕事[しごと]をしています。", "sentence_source": "generated"}, {"text": "先のことは、誰にも予測できない。", "target_word": "予測", "complexity_tier": "T3", "furigana": "先[さき]のことは、誰[だれ]にも予測[よそく]できない。", "sentence_source": "generated"}, {"text": "彼は相手の動きを予測して、ボールを取った。", "target_word": "予測", "complexity_tier": "T3", "furigana": "彼[かれ]は相手[あいて]の動[うご]きを予測[よそく]して、ボールを取[と]った。", "sentence_source": "generated"}, {"text": "天気を予測するために、雲の形を見ます。", "target_word": "予測", "complexity_tier": "T3", "furigana": "天気[てんき]を予測[よそく]するために、雲[くも]の形[かたち]を見[み]ます。", "sentence_source": "generated"}, {"text": "道の混み具合は予測が難しいので、早めに出発しよう。", "target_word": "予測", "complexity_tier": "T3", "furigana": "道[みち]の混[こ]み具合[ぐあい]は予測[よそく]が難[むずか]しいので、早[はや]めに出発[しゅっぱつ]しよう。", "sentence_source": "generated"}, {"text": "結果を予測する前に、まず事実を集めましょう。", "target_word": "予測", "complexity_tier": "T3", "furigana": "結果[けっか]を予測[よそく]する前[まえ]に、まず事実[じじつ]を集[あつ]めましょう。", "sentence_source": "generated"}, {"text": "彼は未来を正確に予測する力があると言われている。", "target_word": "予測", "complexity_tier": "T4", "furigana": "彼[かれ]は未来[みらい]を正確[せいかく]に予測[よそく]する力[ちから]があると言[い]われている。", "sentence_source": "generated"}, {"text": "客の数を予測しないと、料理を作りすぎてしまう。", "target_word": "予測", "complexity_tier": "T3", "furigana": "客[きゃく]の数[かず]を予測[よそく]しないと、料理[りょうり]を作[つく]りすぎてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "予測", "label": "基本形"}, {"form": "予測する", "label": "サ変動詞・終止形"}, {"form": "予測して", "label": "て形"}, {"form": "予測できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "未来の成り行きを前もって見積もる行為（予測する）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38710, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "予測", "is_correct": true, "explanation": "「予測するのは」の語幹。未来の時期を前もって見積もる行為で、文脈に合う。"}, {"text": "修理", "is_correct": false, "explanation": "「時期を修理する」は意味が通らない。"}, {"text": "注文", "is_correct": false, "explanation": "「時期を注文する」は成り立たない。"}, {"text": "掃除", "is_correct": false, "explanation": "「時期を掃除する」は不自然で、文の主題に合わない。"}], "explanations": {"予測": "「予測するのは」の語幹。未来の時期を前もって見積もる行為で、文脈に合う。", "修理": "「時期を修理する」は意味が通らない。", "注文": "「時期を注文する」は成り立たない。", "掃除": "「時期を掃除する」は不自然で、文の主題に合わない。"}, "sentence_index": 0, "correct_answer": "予測"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の部屋を予測しておく。", "explanation": "ここは〈予約〉の意味。予測は見積もる行為で、部屋を押さえる意味ではない。"}, {"text": "風邪の予測を、ワクチンで予防する。", "explanation": "ここは〈予防〉の意味。予測は見通しを立てることで、ワクチンで防ぐ対象にはならないので合わない。"}, {"text": "試験に向けて教科書を予測する。", "explanation": "ここは〈予習〉の意味。予測は見積もる行為で、教科書を前もって読むことではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38710, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "予測", "is_correct": true, "explanation": "「予測が難しい」の語。混み具合を前もって見積もる意味で、文脈に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "「混み具合は翻訳が難しい」は意味が通らない。"}, {"text": "採点", "is_correct": false, "explanation": "「混み具合の採点」は成り立たない。"}, {"text": "梱包", "is_correct": false, "explanation": "「混み具合の梱包」は不自然で、文の内容に合わない。"}], "explanations": {"予測": "「予測が難しい」の語。混み具合を前もって見積もる意味で、文脈に合う。", "翻訳": "「混み具合は翻訳が難しい」は意味が通らない。", "採点": "「混み具合の採点」は成り立たない。", "梱包": "「混み具合の梱包」は不自然で、文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "予測"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週の予測に、みんなで集まる。", "explanation": "ここは〈予定〉の意味。予測は見通しの内容で、人が集まる行事を指さないので合わない。"}, {"text": "予測の電池を引き出しに入れておく。", "explanation": "ここは〈予備〉の意味。予測は見積もる行為で、備えとして置く物ではない。"}, {"text": "来年の予測を使い切った。", "explanation": "ここは〈予算〉の意味。予算は使えるお金の枠だが、予測は見通しで、使い切るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38710, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日の天気を予測たいので、傘を持つ。", "corrected_sentence": "明日の天気を予測したいので、傘を持つ。", "error_description": "「予測する」の希望形は「予測したい」。「予測た」は「し」が抜けた活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38710, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の強さは予測を難しいので、傘を持とう。", "corrected_sentence": "雨の強さは予測が難しいので、傘を持とう。", "error_description": "「予測が難しい」の主語は「が」。「予測を難しい」は助詞の誤りで、「予測が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38711, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「予測では」の〈で〉。予測を根拠や情報源として示す働き。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示すが、後ろに述語がなく「来年は…」と続くので文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す。予測が向かう先を述べる文脈ではなく合わない。"}, {"text": "が", "is_correct": false, "explanation": "「予測がは」は助詞が重なり成り立たない。〈が〉は主語を示す。"}], "correct_answer": "で", "explanations": {"で": "「予測では」の〈で〉。予測を根拠や情報源として示す働き。", "を": "〈を〉は目的語を示すが、後ろに述語がなく「来年は…」と続くので文が成り立たない。", "へ": "〈へ〉は方向を示す。予測が向かう先を述べる文脈ではなく合わない。", "が": "「予測がは」は助詞が重なり成り立たない。〈が〉は主語を示す。"}, "error_tags": {"を": "目的語", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38711, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「予測は」の〈は〉。予測を話題として取り上げる働きで、ここで自然。"}, {"text": "に", "is_correct": false, "explanation": "「予測に甘かった」とは続かず、〈に〉は不自然。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示すが、「予測で甘かった」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「予測を甘かった」は述語と合わず不自然。〈を〉は目的語を示す。"}], "correct_answer": "は", "explanations": {"は": "「予測は」の〈は〉。予測を話題として取り上げる働きで、ここで自然。", "に": "「予測に甘かった」とは続かず、〈に〉は不自然。", "で": "〈で〉は手段や場所を示すが、「予測で甘かった」は成り立たない。", "を": "「予測を甘かった」は述語と合わず不自然。〈を〉は目的語を示す。"}, "error_tags": {"に": "位置・相手", "で": "手段・場所", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38711, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "将来の出来事や結果について、知識やデータをもとに判断した内容。", "primary_collocate": null, "pronunciation": "よそく", "ipa": "josokɯ", "syllable_count": 3, "sentences": [{"text": "この予測を信じて、来年の計画を立てた。", "target_word": "予測", "complexity_tier": "T3", "furigana": "この予測[よそく]を信[しん]じて、来年[らいねん]の計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "専門家の予測では、来年は物価が上がるそうだ。", "target_word": "予測", "complexity_tier": "T3", "furigana": "専門家[せんもんか]の予測[よそく]では、来年[らいねん]は物価[ぶっか]が上[あ]がるそうだ。", "sentence_source": "generated"}, {"text": "彼の予測は当たって、試合は引き分けに終わった。", "target_word": "予測", "complexity_tier": "T3", "furigana": "彼[かれ]の予測[よそく]は当[あ]たって、試合[しあい]は引[ひ]き分[わ]けに終[お]わった。", "sentence_source": "generated"}, {"text": "その予測は、過去のデータをもとにして作られた。", "target_word": "予測", "complexity_tier": "T3", "furigana": "その予測[よそく]は、過去[かこ]のデータをもとにして作[つく]られた。", "sentence_source": "generated"}, {"text": "会社が出した予測よりも、実際の売り上げは低かった。", "target_word": "予測", "complexity_tier": "T3", "furigana": "会社[かいしゃ]が出[だ]した予測[よそく]よりも、実際[じっさい]の売[う]り上[あ]げは低[ひく]かった。", "sentence_source": "generated"}, {"text": "私の予測は外れて、電車はとても空いていた。", "target_word": "予測", "complexity_tier": "T3", "furigana": "私[わたし]の予測[よそく]は外[はず]れて、電車[でんしゃ]はとても空[す]いていた。", "sentence_source": "generated"}, {"text": "研究者の予測どおり、気温は少しずつ上がっている。", "target_word": "予測", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]の予測[よそく]どおり、気温[きおん]は少[すこ]しずつ上[あ]がっている。", "sentence_source": "generated"}, {"text": "彼女の予測は甘かったので、準備が足りなかった。", "target_word": "予測", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の予測[よそく]は甘[あま]かったので、準備[じゅんび]が足[た]りなかった。", "sentence_source": "generated"}, {"text": "この予測が正しいかどうかは、来年になればわかる。", "target_word": "予測", "complexity_tier": "T3", "furigana": "この予測[よそく]が正[ただ]しいかどうかは、来年[らいねん]になればわかる。", "sentence_source": "generated"}, {"text": "医者は、回復までに三か月かかるという予測を伝えた。", "target_word": "予測", "complexity_tier": "T4", "furigana": "医者[いしゃ]は、回復[かいふく]までに三[さん]か月[げつ]かかるという予測[よそく]を伝[つた]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "予測", "label": "基本形"}, {"form": "予測する", "label": "サ変動詞・終止形"}, {"form": "予測した", "label": "過去形"}, {"form": "予測される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "データや知識に基づく将来についての見通し（判断の内容）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38711, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "予測", "is_correct": true, "explanation": "「この予測を信じて」の語。見通しを根拠に計画を立てる文脈に合う。"}, {"text": "梱包", "is_correct": false, "explanation": "「この梱包を信じて」は意味をなさない。"}, {"text": "掃除", "is_correct": false, "explanation": "「この掃除を信じて」は成り立たない。"}, {"text": "注射", "is_correct": false, "explanation": "「この注射を信じて」は文の内容に合わない。"}], "explanations": {"予測": "「この予測を信じて」の語。見通しを根拠に計画を立てる文脈に合う。", "梱包": "「この梱包を信じて」は意味をなさない。", "掃除": "「この掃除を信じて」は成り立たない。", "注射": "「この注射を信じて」は文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "予測"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来年の予測が国会で決まった。", "explanation": "ここは〈予算〉の意味。予測は将来の見通しなので、国会で決まるものではない。"}, {"text": "来年の予測を、今日のうちに予防する。", "explanation": "ここは〈予防〉の意味。予測は将来の見通しを立てることで、防ぐ対象にはならないので合わない。"}, {"text": "テストの前に教科書を予測した。", "explanation": "ここは〈予習〉の意味。予測は見通しを立てる行為で、教科書を前もって読むことは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38711, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "予測", "is_correct": true, "explanation": "「予測どおり」の語。見通しどおりに進んだという意味で、文脈に合う。"}, {"text": "体重", "is_correct": false, "explanation": "「研究者の体重どおり」は意味が通らない。ここは未来の見通しを表す語が入る。"}, {"text": "年齢", "is_correct": false, "explanation": "「研究者の年齢どおり」では気温の上がり方の話と結びつかない。"}, {"text": "身長", "is_correct": false, "explanation": "「身長どおり」は気温が少しずつ上がる説明にはならない。"}], "explanations": {"予測": "「予測どおり」の語。見通しどおりに進んだという意味で、文脈に合う。", "体重": "「研究者の体重どおり」は意味が通らない。ここは未来の見通しを表す語が入る。", "年齢": "「研究者の年齢どおり」では気温の上がり方の話と結びつかない。", "身長": "「身長どおり」は気温が少しずつ上がる説明にはならない。"}, "sentence_index": 6, "correct_answer": "予測"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の席を予測して、電話で頼んだ。", "explanation": "ここは〈予約〉の意味。予測は見積もる行為で、席を確保する意味ではない。"}, {"text": "予測のタイヤを車に積んでおく。", "explanation": "ここは〈予備〉の意味。予測は見通しの内容で、車に積んで備えておく物ではない。"}, {"text": "会議の予測を十時に変えた。", "explanation": "ここは〈予定〉の意味。予測は見通しの内容で、会議の時刻を変える対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38711, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その予測を当たって、翌日は雨になった。", "corrected_sentence": "その予測が当たって、翌日は雨になった。", "error_description": "「当たる」の主語には「が」を使う。「予測を当たって」は誤りで、正しくは「予測が当たって」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38711, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この予測は当たったて、雨は降らなかった。", "corrected_sentence": "この予測は当たって、雨は降らなかった。", "error_description": "「当たる」のて形は「当たって」。「当たったて」は活用の誤りで、て形の作り方を誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
