INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38712, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "何かが、生き物にとって、悪い影響を与える力のことです。", "primary_collocate": null, "pronunciation": "どくせい", "ipa": "dokɯseː", "syllable_count": 4, "sentences": [{"text": "このきのこは毒性が強いので、食べてはいけません。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "このきのこは毒性[どくせい]が強[つよ]いので、食[た]べてはいけません。", "sentence_source": "generated"}, {"text": "毒性の弱い薬でも、飲みすぎると体に悪い。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "毒性[どくせい]の弱[よわ]い薬[くすり]でも、飲[の]みすぎると体[からだ]に悪[わる]い。", "sentence_source": "generated"}, {"text": "植物の中には、毒性を持つものがある。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]の中[なか]には、毒性[どくせい]を持[も]つものがある。", "sentence_source": "generated"}, {"text": "毒性があるかどうか、先生が魚を調べてくれた。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "毒性[どくせい]があるかどうか、先生[せんせい]が魚[さかな]を調[しら]べてくれた。", "sentence_source": "generated"}, {"text": "この虫は、毒性が低いので触っても大丈夫だ。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "この虫[むし]は、毒性[どくせい]が低[ひく]いので触[さわ]っても大丈夫[だいじょうぶ]だ。", "sentence_source": "generated"}, {"text": "毒性のある草を、犬が食べないように気をつけた。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "毒性[どくせい]のある草[くさ]を、犬[いぬ]が食[た]べないように気[き]をつけた。", "sentence_source": "generated"}, {"text": "毒性が強いため、この花は庭に植えないことにした。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "毒性[どくせい]が強[つよ]いため、この花[はな]は庭[にわ]に植[う]えないことにした。", "sentence_source": "generated"}, {"text": "カエルの中には、強い毒性を持つ種類もいる。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "カエルの中[なか]には、強[つよ]い毒性[どくせい]を持[も]つ種類[しゅるい]もいる。", "sentence_source": "generated"}, {"text": "毒性が分からないきのこは、持ち帰らないでください。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "毒性[どくせい]が分からないきのこは、持ち帰らないでください。", "sentence_source": "generated"}, {"text": "この洗剤は毒性が低いと書いてある。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "この洗剤[せんざい]は毒性[どくせい]が低[ひく]いと書[か]いてある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "毒性", "label": "基本形"}], "register": "標準", "sense_fingerprint": "毒性：きのこ・植物・動物・薬などが、食べたり触れたりした生き物に害を与える力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38712, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毒性", "is_correct": true, "explanation": "「毒性が強い」は、きのこが生き物に害を与える力が強いことを表すので、食べてはいけないという文に合う。正解。"}, {"text": "年齢", "is_correct": false, "explanation": "人や物の年数を表す語で、「年齢が強い」とはならず、きのこの性質を述べられない。"}, {"text": "距離", "is_correct": false, "explanation": "離れている長さを表す語で、「距離が強い」は成り立たず、きのこの性質には当たらない。"}, {"text": "重量", "is_correct": false, "explanation": "重さを表す語で、「重量が強い」は成り立たず、食べてはいけない理由にならない。"}], "explanations": {"毒性": "「毒性が強い」は、きのこが生き物に害を与える力が強いことを表すので、食べてはいけないという文に合う。正解。", "年齢": "人や物の年数を表す語で、「年齢が強い」とはならず、きのこの性質を述べられない。", "距離": "離れている長さを表す語で、「距離が強い」は成り立たず、きのこの性質には当たらない。", "重量": "重さを表す語で、「重量が強い」は成り立たず、食べてはいけない理由にならない。"}, "sentence_index": 0, "correct_answer": "毒性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は、熱を下げる毒性がある。", "explanation": "ここは〈薬効〉の意味。毒性は生き物に害を与える力なので、熱を下げる効果を表す文には使えない。"}, {"text": "この豆は毒性が豊富で、子どもにも人気だ。", "explanation": "ここは〈栄養〉の意味。毒性は良い成分を表す語ではないので、豊富さを述べる文には合わない。"}, {"text": "このきのこは毒性が良く、炒め物に合う。", "explanation": "ここは〈食感〉の意味。毒性は味や歯ごたえを表す語ではないので、料理に合うかどうかの文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38712, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毒性", "is_correct": true, "explanation": "「毒性が強いため、この花は庭に植えない」は、花が生き物に害を与える力の強さを理由にした文なので正解。"}, {"text": "年収", "is_correct": false, "explanation": "一年間の収入を表す語で、「年収が強い」とは言えず、花を植えない理由にならない。"}, {"text": "体重", "is_correct": false, "explanation": "人や動物の重さを表す語で、「体重が強い」は成り立たず、花の性質を述べられない。"}, {"text": "残業", "is_correct": false, "explanation": "勤務時間外の仕事を指す語で、花を植えない理由としては意味が通らない。"}], "explanations": {"毒性": "「毒性が強いため、この花は庭に植えない」は、花が生き物に害を与える力の強さを理由にした文なので正解。", "年収": "一年間の収入を表す語で、「年収が強い」とは言えず、花を植えない理由にならない。", "体重": "人や動物の重さを表す語で、「体重が強い」は成り立たず、花の性質を述べられない。", "残業": "勤務時間外の仕事を指す語で、花を植えない理由としては意味が通らない。"}, "sentence_index": 6, "correct_answer": "毒性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この板は毒性が十分なので、棚に使える。", "explanation": "ここは〈硬さ〉の意味。毒性は生き物への害の強さなので、板の丈夫さを述べる文には合わない。"}, {"text": "このカーテンは毒性が落ち着いていて、部屋に合う。", "explanation": "ここは〈色合い〉の意味。毒性は色の印象を表す語ではないので、部屋の雰囲気の文には使えない。"}, {"text": "このタオルは毒性が柔らかく、赤ちゃんにも使える。", "explanation": "ここは〈手触り〉の意味。毒性は肌ざわりを表す語ではないので、柔らかさを述べる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38712, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毒性を強いこの虫は、触らないでください。", "corrected_sentence": "毒性が強いこの虫は、触らないでください。", "error_description": "「強い」は形容詞なので、主語を示す「が」で「毒性が強い」とする。「を」は目的語に付く助詞なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38712, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毒性弱い薬は、子どもにも使えるとされる。", "corrected_sentence": "毒性の弱い薬は、子どもにも使えるとされる。", "error_description": "名詞「毒性」を形容詞「弱い」で修飾するには「の」が必要。「毒性弱い」は直接つながらず、名詞句として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
