INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38713, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "生物に対して有害な作用を及ぼす性質のこと。特に、化学物質などが生物の生命活動に悪影響を及ぼす能力を指す。", "primary_collocate": null, "pronunciation": "どくせい", "ipa": "dokɯseː", "syllable_count": 4, "sentences": [{"text": "新しい化学物質の毒性を、動物実験で確かめた。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "新[あたら]しい化学物質[かがくぶっしつ]の毒性[どくせい]を、動物実験[どうぶつじっけん]で確[たし]かめた。", "sentence_source": "generated"}, {"text": "水銀は、人体に対する毒性が非常に高い物質だ。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "水銀[すいぎん]は、人体[じんたい]に対[たい]する毒性[どくせい]が非常[ひじょう]に高[たか]い物質[ぶっしつ]だ。", "sentence_source": "generated"}, {"text": "研究チームは、農薬の毒性が魚に与える影響を調べた。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "研究[けんきゅう]チームは、農薬[のうやく]の毒性[どくせい]が魚[さかな]に与[あた]える影響[えいきょう]を調[しら]べた。", "sentence_source": "generated"}, {"text": "試験で毒性を評価した結果、この薬品は安全基準を満たしていた。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "試験[しけん]で毒性[どくせい]を評価[ひょうか]した結果[けっか]、この薬品[やくひん]は安全[あんぜん]基準[きじゅん]を満[み]たしていた。", "sentence_source": "generated"}, {"text": "排水に含まれる物質の毒性が、川の生物を減らした。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "排水[はいすい]に含[ふく]まれる物質[ぶっしつ]の毒性[どくせい]が、川[かわ]の生物[せいぶつ]を減[へ]らした。", "sentence_source": "generated"}, {"text": "この化合物は、少量でも毒性を示すことが分かった。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "この化合物[かごうぶつ]は、少量[しょうりょう]でも毒性[どくせい]を示[しめ]すことが分[わ]かった。", "sentence_source": "generated"}, {"text": "毒性の強さは、物質の量や種類によって大きく異なる。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "毒性[どくせい]の強[つよ]さは、物質[ぶっしつ]の量[りょう]や種類[しゅるい]によって大[おお]きく異[こと]なる。", "sentence_source": "generated"}, {"text": "工場は、廃液の毒性を下げる処理を義務づけられている。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "工場[こうじょう]は、廃液[はいえき]の毒性[どくせい]を下[さ]げる処理[しょり]を義務[ぎむ]づけられている。", "sentence_source": "generated"}, {"text": "毒性が確認されたため、その製品は販売が停止された。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "毒性[どくせい]が確認[かくにん]されたため、その製品[せいひん]は販売[はんばい]が停止[ていし]された。", "sentence_source": "generated"}, {"text": "専門家は、微量でも長く摂ると毒性が現れる可能性があると述べた。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、微量[びりょう]でも長[なが]く摂[と]ると毒性[どくせい]が現[あらわ]れる可能性[かのうせい]があると述[の]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "毒性", "label": "基本形"}], "register": "硬い", "sense_fingerprint": "毒性：化学物質などが生物の生命活動に有害な作用を及ぼす性質（科学・研究・規制の文脈）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255d8c61-710b-4ae7-803e-cf34abc89cf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38713, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毒性", "is_correct": true, "explanation": "動物実験で確かめるのは、化学物質が生き物に与える有害な作用なので、「毒性を確かめた」が正解。"}, {"text": "価格", "is_correct": false, "explanation": "値段を表す語で、動物実験で確かめる対象にはならない。"}, {"text": "人気", "is_correct": false, "explanation": "世間での評判を表す語で、動物実験で確かめる対象にはならない。"}, {"text": "売上", "is_correct": false, "explanation": "商品の販売で得た金額を表す語で、動物実験で確かめる対象にはならない。"}], "explanations": {"毒性": "動物実験で確かめるのは、化学物質が生き物に与える有害な作用なので、「毒性を確かめた」が正解。", "価格": "値段を表す語で、動物実験で確かめる対象にはならない。", "人気": "世間での評判を表す語で、動物実験で確かめる対象にはならない。", "売上": "商品の販売で得た金額を表す語で、動物実験で確かめる対象にはならない。"}, "sentence_index": 0, "correct_answer": "毒性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この測定器は毒性が高く、誤差が少ない。", "explanation": "ここは〈精度〉の意味。毒性は有害な作用の強さを表すので、測定の正確さを述べる文には合わない。"}, {"text": "このスピーカーは毒性が大きく、遠くまで響く。", "explanation": "ここは〈音量〉の意味。毒性は音の大きさを表す語ではないので、響きの範囲を述べる文には使えない。"}, {"text": "この素材は毒性が高く、重い荷物も支えられる。", "explanation": "ここは〈強度〉の意味。毒性は有害な作用を表す語なので、荷物を支える力の文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38713, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毒性", "is_correct": true, "explanation": "「毒性の強さは、物質の量や種類によって異なる」は有害な作用の強さを述べる文なので正解。"}, {"text": "年齢", "is_correct": false, "explanation": "人や物の年数を表す語で、物質の量や種類によって変わる強さとは結びつかない。"}, {"text": "寿命", "is_correct": false, "explanation": "生き物や物が存在する期間を表す語で、物質の量や種類によって決まる強さの話には合わない。"}, {"text": "天候", "is_correct": false, "explanation": "気象の状態を表す語で、物質の量や種類によって変わる強さとは結びつかない。"}], "explanations": {"毒性": "「毒性の強さは、物質の量や種類によって異なる」は有害な作用の強さを述べる文なので正解。", "年齢": "人や物の年数を表す語で、物質の量や種類によって変わる強さとは結びつかない。", "寿命": "生き物や物が存在する期間を表す語で、物質の量や種類によって決まる強さの話には合わない。", "天候": "気象の状態を表す語で、物質の量や種類によって変わる強さとは結びつかない。"}, "sentence_index": 6, "correct_answer": "毒性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この金属は毒性が美しく、装飾に使われる。", "explanation": "ここは〈光沢〉の意味。毒性は有害な作用を表す語なので、金属の見た目の美しさには使えない。"}, {"text": "このお茶は毒性が深く、食後にぴったりだ。", "explanation": "ここは〈味わい〉の意味。毒性は味の深さを表す語ではないので、お茶の評価には合わない。"}, {"text": "この毛布は毒性が高く、冬に便利だ。", "explanation": "ここは〈保温性〉の意味。毒性は熱を保つ力を表す語ではないので、冬に便利という文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38713, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究チームは、農薬の毒性が動物実験で確かめた。", "corrected_sentence": "研究チームは、農薬の毒性を動物実験で確かめた。", "error_description": "「確かめる」は目的語を「を」で取る動詞。「が」を付けると毒性が主語になり、確かめる対象がなくなる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38713, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "排水の毒性に測るため、新しい装置が導入された。", "corrected_sentence": "排水の毒性を測るため、新しい装置が導入された。", "error_description": "「測る」は目的語を「を」で取る動詞。「に」を付けると目的語の形を成さず、測る対象が示せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891bed42-7e78-4985-8fde-9cfb8962f692') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38714, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「重点を置く」の目的語を示す助詞で、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「重点が置く」は重点を主語にしてしまい、置く対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「重点で置く」は手段や場所の意味になり、置く対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「重点と置く」は並列の意味になり、置く対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「重点を置く」の目的語を示す助詞で、ここに入る。", "が": "「重点が置く」は重点を主語にしてしまい、置く対象を示せない。", "で": "「重点で置く」は手段や場所の意味になり、置く対象を表せない。", "と": "「重点と置く」は並列の意味になり、置く対象にならない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38714, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「重点を置く」の目的語を示す助詞で、ここに入る。"}, {"text": "の", "is_correct": false, "explanation": "「重点の置いて」は連体修飾になり、置く動作の目的語にならない。"}, {"text": "から", "is_correct": false, "explanation": "「重点から置いて」は起点の意味になり、置く対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「重点より置いて」は比較の意味になり、置く対象を表さない。"}], "correct_answer": "を", "explanations": {"を": "「重点を置く」の目的語を示す助詞で、ここに入る。", "の": "「重点の置いて」は連体修飾になり、置く動作の目的語にならない。", "から": "「重点から置いて」は起点の意味になり、置く対象を示せない。", "より": "「重点より置いて」は比較の意味になり、置く対象を表さない。"}, "error_tags": {"の": "連体修飾", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38714, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一番大事なところに、一番注意を向けること。", "primary_collocate": "置く", "pronunciation": "じゅうてん", "ipa": "dʑɯːteɴ", "syllable_count": 4, "sentences": [{"text": "今日の授業では、文法に重点を置きます。", "target_word": "重点", "complexity_tier": "T3", "furigana": "今日[きょう]の授業[じゅぎょう]では、文法[ぶんぽう]に重点[じゅうてん]を置[お]きます。", "sentence_source": "generated"}, {"text": "この会社は、新人の教育に重点を置いています。", "target_word": "重点", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、新人[しんじん]の教育[きょういく]に重点[じゅうてん]を置[お]いています。", "sentence_source": "generated"}, {"text": "試験前は、苦手な問題に重点を置いて勉強しました。", "target_word": "重点", "complexity_tier": "T3", "furigana": "試験前[しけんまえ]は、苦手[にがて]な問題[もんだい]に重点[じゅうてん]を置[お]いて勉強[べんきょう]しました。", "sentence_source": "generated"}, {"text": "夏の間は、体力づくりに重点を置いて練習します。", "target_word": "重点", "complexity_tier": "T3", "furigana": "夏[なつ]の間[あいだ]は、体力[たいりょく]づくりに重点[じゅうてん]を置[お]いて練習[れんしゅう]します。", "sentence_source": "generated"}, {"text": "会議では、時間が少ないので重点をしぼって話しました。", "target_word": "重点", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、時間[じかん]が少[すく]ないので重点[じゅうてん]をしぼって話[はな]しました。", "sentence_source": "generated"}, {"text": "去年と今年では、計画の重点が変わりました。", "target_word": "重点", "complexity_tier": "T3", "furigana": "去年[きょねん]と今年[ことし]では、計画[けいかく]の重点[じゅうてん]が変[か]わりました。", "sentence_source": "generated"}, {"text": "練習の重点を、走り方から体の使い方に移しました。", "target_word": "重点", "complexity_tier": "T3", "furigana": "練習[れんしゅう]の重点[じゅうてん]を、走[はし]り方[かた]から体[からだ]の使[つか]い方[かた]に移[うつ]しました。", "sentence_source": "generated"}, {"text": "今回の旅行は、観光より食事に重点を置いて計画しました。", "target_word": "重点", "complexity_tier": "T3", "furigana": "今回[こんかい]の旅行[りょこう]は、観光[かんこう]より食事[しょくじ]に重点[じゅうてん]を置[お]いて計画[けいかく]しました。", "sentence_source": "generated"}, {"text": "新しい店は、安さではなく品質に重点を置いています。", "target_word": "重点", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]は、安[やす]さではなく品質[ひんしつ]に重点[じゅうてん]を置[お]いています。", "sentence_source": "generated"}, {"text": "病院は、予防に重点を置いた取り組みを始めました。", "target_word": "重点", "complexity_tier": "T3", "furigana": "病院[びょういん]は、予防[よぼう]に重点[じゅうてん]を置[お]いた取[と]り組[く]みを始[はじ]めました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重点", "label": "基本形"}], "register": "中立", "sense_fingerprint": "最も大事な点に注意や力を向けること(重点を置く・重点を絞る)", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cb9108-8bde-4618-9c38-fbf83d7a73e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38714, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重点", "is_correct": true, "explanation": "「文法に重点を置く」は注意や力を向ける先を表す正しい語で、空所にはこの語だけが入る。"}, {"text": "負担", "is_correct": false, "explanation": "「文法に負担を置きます」は不自然。負担は「負担をかける・負う」と組む語で、「置く」とは続かない。"}, {"text": "単語", "is_correct": false, "explanation": "「文法に単語を置きます」は意味が通らない。単語は学ぶ対象で、注意を向ける先にはならない。"}, {"text": "工夫", "is_correct": false, "explanation": "「工夫を置く」とは言わない。工夫は「工夫を凝らす」と組む語なので、ここには合わない。"}], "explanations": {"重点": "「文法に重点を置く」は注意や力を向ける先を表す正しい語で、空所にはこの語だけが入る。", "負担": "「文法に負担を置きます」は不自然。負担は「負担をかける・負う」と組む語で、「置く」とは続かない。", "単語": "「文法に単語を置きます」は意味が通らない。単語は学ぶ対象で、注意を向ける先にはならない。", "工夫": "「工夫を置く」とは言わない。工夫は「工夫を凝らす」と組む語なので、ここには合わない。"}, "sentence_index": 0, "correct_answer": "重点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱は、重点が左に寄っているので倒れやすい。", "explanation": "ここは〈重心〉の意味。物の釣り合いの中心は重心と言い、重点は注意や力を向ける先を指すので合わない。"}, {"text": "今日は湿度の重点が高くて蒸し暑い。", "explanation": "ここは〈湿度〉の意味。湿度の高さは「湿度が高い」と言い、重点は湿度を表さないので合わない。"}, {"text": "昨日より雨の重点が強いです。", "explanation": "ここは〈強さ〉の意味。雨の勢いは強さで表し、注意の向かう先を指す重点は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38714, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重点", "is_correct": true, "explanation": "「練習の重点」は最も力を入れる点の意味で、空所にこの語だけが入る。"}, {"text": "歌詞", "is_correct": false, "explanation": "「練習の歌詞を移す」は意味が通らない。歌詞は練習の対象になる語ではない。"}, {"text": "色", "is_correct": false, "explanation": "「練習の色を移す」は不自然で、練習の内容を表す語にならない。"}, {"text": "手形", "is_correct": false, "explanation": "「練習の手形を移す」は意味が通らない。手形は練習の内容を表さない。"}], "explanations": {"重点": "「練習の重点」は最も力を入れる点の意味で、空所にこの語だけが入る。", "歌詞": "「練習の歌詞を移す」は意味が通らない。歌詞は練習の対象になる語ではない。", "色": "「練習の色を移す」は不自然で、練習の内容を表す語にならない。", "手形": "「練習の手形を移す」は意味が通らない。手形は練習の内容を表さない。"}, "sentence_index": 6, "correct_answer": "重点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テストで重点を多く取って、合格した。", "explanation": "ここは〈得点〉の意味。テストの点は「点を取る」と言い、重点は注意や力を向ける先を指すので合わない。"}, {"text": "この店は料理の重点が高い。", "explanation": "ここは〈評判〉の意味。「評判が高い」とは言うが、重点は評価の高さを表さないので「高い」とは言わない。"}, {"text": "チームの重点を一人で背負っている。", "explanation": "ここは〈責任〉の意味。「責任を負う・背負う」と言うが、重点は背負うものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38714, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来月は、英語の発音に重点で置いて練習します。", "corrected_sentence": "来月は、英語の発音に重点を置いて練習します。", "error_description": "「重点を置く」の「重点」に付く助詞は「を」が必要。「で」は手段や場所を表す助詞なので、置く対象を示せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38714, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来季は、守備の練習に重点を置きて取り組みます。", "corrected_sentence": "来季は、守備の練習に重点を置いて取り組みます。", "error_description": "「置く」のて形は「置いて」。「置きて」は誤った活用形で、て形は語幹の「おい」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38715, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「重点を書く」の目的語を示す助詞で、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「重点が黒板に書きました」は重点を主語にしてしまい、書く対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「重点で黒板に書きました」は手段の意味になり、書く対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「重点へ書く」は方向の意味になり、書く対象を示さない。"}], "correct_answer": "を", "explanations": {"を": "「重点を書く」の目的語を示す助詞で、ここに入る。", "が": "「重点が黒板に書きました」は重点を主語にしてしまい、書く対象にならない。", "で": "「重点で黒板に書きました」は手段の意味になり、書く対象を示せない。", "へ": "「重点へ書く」は方向の意味になり、書く対象を示さない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38715, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「重点がずれる」の主語を示す助詞で、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「重点をずれる」は対象を示す形になり、ずれるものの主語として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「質問の重点のずれていて」は連体修飾の形になり、述語の主語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「重点にずれていて」は場所を表す形になり、ずれるものを示せない。"}], "correct_answer": "が", "explanations": {"が": "「重点がずれる」の主語を示す助詞で、ここに入る。", "を": "「重点をずれる」は対象を示す形になり、ずれるものの主語として成り立たない。", "の": "「質問の重点のずれていて」は連体修飾の形になり、述語の主語にならない。", "に": "「重点にずれていて」は場所を表す形になり、ずれるものを示せない。"}, "error_tags": {"を": "対象", "の": "連体修飾", "に": "場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38715, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の中で、特に大切に扱うべき部分や中心となる点を指します。", "primary_collocate": null, "pronunciation": "じゅうてん", "ipa": "dʑɯːteɴ", "syllable_count": 4, "sentences": [{"text": "この本の重点は、第三章にまとめられています。", "target_word": "重点", "complexity_tier": "T3", "furigana": "この本[ほん]の重点[じゅうてん]は、第三章[だいさんしょう]にまとめられています。", "sentence_source": "generated"}, {"text": "先生は、テストに出る重点を黒板に書きました。", "target_word": "重点", "complexity_tier": "T3", "furigana": "先生[せんせい]は、テストに出[で]る重点[じゅうてん]を黒板[こくばん]に書[か]きました。", "sentence_source": "generated"}, {"text": "話の重点がわからなくて、もう一度聞きました。", "target_word": "重点", "complexity_tier": "T3", "furigana": "話[はなし]の重点[じゅうてん]がわからなくて、もう一度[いちど]聞[き]きました。", "sentence_source": "generated"}, {"text": "今日の説明の重点は、安全に使う方法です。", "target_word": "重点", "complexity_tier": "T3", "furigana": "今日[きょう]の説明[せつめい]の重点[じゅうてん]は、安全[あんぜん]に使[つか]う方法[ほうほう]です。", "sentence_source": "generated"}, {"text": "計画書を読んで、重点となる部分に線を引きました。", "target_word": "重点", "complexity_tier": "T3", "furigana": "計画書[けいかくしょ]を読[よ]んで、重点[じゅうてん]となる部分[ぶぶん]に線[せん]を引[ひ]きました。", "sentence_source": "generated"}, {"text": "重点だけを短く伝えれば、相手に通じます。", "target_word": "重点", "complexity_tier": "T3", "furigana": "重点[じゅうてん]だけを短[みじか]く伝[つた]えれば、相手[あいて]に通[つう]じます。", "sentence_source": "generated"}, {"text": "契約の重点は、支払いの日にちと金額です。", "target_word": "重点", "complexity_tier": "T3", "furigana": "契約[けいやく]の重点[じゅうてん]は、支払[しはら]いの日[ひ]にちと金額[きんがく]です。", "sentence_source": "generated"}, {"text": "質問の重点がずれていて、答えにくかったです。", "target_word": "重点", "complexity_tier": "T3", "furigana": "質問[しつもん]の重点[じゅうてん]がずれていて、答[こた]えにくかったです。", "sentence_source": "generated"}, {"text": "会議の前に、話す重点をメモにまとめました。", "target_word": "重点", "complexity_tier": "T3", "furigana": "会議[かいぎ]の前[まえ]に、話[はな]す重点[じゅうてん]をメモにまとめました。", "sentence_source": "generated"}, {"text": "資料の重点には赤い印がついています。", "target_word": "重点", "complexity_tier": "T3", "furigana": "資料[しりょう]の重点[じゅうてん]には赤[あか]い印[しるし]がついています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重点", "label": "基本形"}], "register": "中立", "sense_fingerprint": "話・資料・計画などの中で特に大切な中心となる部分(要点)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cb9108-8bde-4618-9c38-fbf83d7a73e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38715, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重点", "is_correct": true, "explanation": "「この本の重点」は内容の中心となる部分の意味で、第三章にまとめられる内容として自然に入る。"}, {"text": "値段", "is_correct": false, "explanation": "「値段は第三章にまとめられています」は意味が通らない。値段は本の内容の中心にはならない。"}, {"text": "色", "is_correct": false, "explanation": "「色は第三章にまとめられています」は不自然で、本の内容を指す語にならない。"}, {"text": "重さ", "is_correct": false, "explanation": "「重さは第三章にまとめられています」は意味が通らない。重さは内容の要点を表さない。"}], "explanations": {"重点": "「この本の重点」は内容の中心となる部分の意味で、第三章にまとめられる内容として自然に入る。", "値段": "「値段は第三章にまとめられています」は意味が通らない。値段は本の内容の中心にはならない。", "色": "「色は第三章にまとめられています」は不自然で、本の内容を指す語にならない。", "重さ": "「重さは第三章にまとめられています」は意味が通らない。重さは内容の要点を表さない。"}, "sentence_index": 0, "correct_answer": "重点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "後半に入って、重点を二つ取って逆転した。", "explanation": "ここは〈得点〉の意味。試合で点を取るのは「点を取る」と言い、重点は話や資料の中心を指すので合わない。"}, {"text": "カメラの重点を合わせて、写真を撮った。", "explanation": "ここは〈焦点〉の意味。カメラのピントは焦点で「焦点を合わせる」と言い、重点は使えない。"}, {"text": "かばんの重点を量ったら五キロあった。", "explanation": "ここは〈重さ〉の意味。物の重さは重さ・重量と言い、重点は内容の中心を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38715, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重点", "is_correct": true, "explanation": "「契約の重点」は契約の中で特に大切な部分の意味で、支払いの日にちと金額を示す文に自然に入る。"}, {"text": "香り", "is_correct": false, "explanation": "「契約の香りは、支払いの日にちと金額です」は意味が通らない。香りは契約の内容を表さない。"}, {"text": "署名", "is_correct": false, "explanation": "「契約の署名は、支払いの日にちと金額です」は意味が通らず、文の内容と合わない。"}, {"text": "手触り", "is_correct": false, "explanation": "「契約の手触りは、支払いの日にちと金額です」は意味が通らない。手触りは契約の内容を表さない。"}], "explanations": {"重点": "「契約の重点」は契約の中で特に大切な部分の意味で、支払いの日にちと金額を示す文に自然に入る。", "香り": "「契約の香りは、支払いの日にちと金額です」は意味が通らない。香りは契約の内容を表さない。", "署名": "「契約の署名は、支払いの日にちと金額です」は意味が通らず、文の内容と合わない。", "手触り": "「契約の手触りは、支払いの日にちと金額です」は意味が通らない。手触りは契約の内容を表さない。"}, "sentence_index": 6, "correct_answer": "重点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨量が多いのに、昨日は雨の重点が多かった。", "explanation": "ここは〈降水量〉の意味。雨の量は降水量と言い、重点は内容や注意の中心を指すので合わない。"}, {"text": "朝の気温の重点が低い。", "explanation": "ここは〈温度〉の意味。温度の低さは「温度が低い」と言い、重点は温度を表さないので合わない。"}, {"text": "この町は人口の重点が多い。", "explanation": "ここは〈人数〉の意味。人の数は人数と言い、重点を人の数に使うことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38715, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "授業の最後に、テストに出る重点に黒板に書きました。", "corrected_sentence": "授業の最後に、テストに出る重点を黒板に書きました。", "error_description": "「書く」の対象を表す「重点」の後の助詞は「を」が必要。「に」にすると、重点を書く対象として示せなくなる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
