INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38716, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを、ある場所に、落ち着かせるようにして置くこと。", "primary_collocate": null, "pronunciation": "おく", "ipa": "oku", "syllable_count": 2, "sentences": [{"text": "机の上に本を置きます。", "target_word": "置きます", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に本[ほん]を置[お]きます。", "sentence_source": "generated"}, {"text": "重いかばんを床に置いて、少し休みました。", "target_word": "置いて", "complexity_tier": "T3", "furigana": "重[おも]いかばんを床[ゆか]に置[お]いて、少[すこ]し休[やす]みました。", "sentence_source": "generated"}, {"text": "花びんをテーブルの真ん中に置きました。", "target_word": "置きました", "complexity_tier": "T3", "furigana": "花[はな]びんをテーブルの真[ま]ん中[なか]に置[お]きました。", "sentence_source": "generated"}, {"text": "傘は玄関の横に置いてください。", "target_word": "置いて", "complexity_tier": "T3", "furigana": "傘[かさ]は玄関[げんかん]の横[よこ]に置[お]いてください。", "sentence_source": "generated"}, {"text": "熱いなべは、このマットの上に置いてください。", "target_word": "置いて", "complexity_tier": "T3", "furigana": "熱[あつ]いなべは、このマットの上[うえ]に置[お]いてください。", "sentence_source": "generated"}, {"text": "眠った赤ちゃんをそっとベッドに置きました。", "target_word": "置きました", "complexity_tier": "T3", "furigana": "眠[ねむ]った赤[あか]ちゃんをそっとベッドに置[お]きました。", "sentence_source": "generated"}, {"text": "重い箱は、ここではなく棚の下に置きましょう。", "target_word": "置きましょう", "complexity_tier": "T3", "furigana": "重[おも]い箱[はこ]は、ここではなく棚[たな]の下[した]に置[お]きましょう。", "sentence_source": "generated"}, {"text": "財布をどこに置いたか、思い出せません。", "target_word": "置いた", "complexity_tier": "T3", "furigana": "財布[さいふ]をどこに置[お]いたか、思[おも]い出[だ]せません。", "sentence_source": "generated"}, {"text": "鍵はいつも玄関の小さな皿に置いています。", "target_word": "置いて", "complexity_tier": "T3", "furigana": "鍵[かぎ]はいつも玄関[げんかん]の小[ちい]さな皿[さら]に置[お]いています。", "sentence_source": "generated"}, {"text": "疲れたので、荷物を駅のベンチに置いて座りました。", "target_word": "置いて", "complexity_tier": "T3", "furigana": "疲[つか]れたので、荷物[にもつ]を駅[えき]のベンチに置[お]いて座[すわ]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "置く", "label": "辞書形"}, {"form": "置きます", "label": "丁寧形"}, {"form": "置いて", "label": "て形"}, {"form": "置いた", "label": "た形"}, {"form": "置かない", "label": "ない形"}, {"form": "置ける", "label": "可能形"}, {"form": "置けば", "label": "仮定形"}, {"form": "置こう", "label": "意向形"}, {"form": "置かれる", "label": "受身形"}], "register": "中立", "sense_fingerprint": "物をある場所に落ち着かせて据える(物を机の上に置く)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 花びん (Zipf 1.51)']::text[], '40cb9108-8bde-4618-9c38-fbf83d7a73e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38716, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "置きます", "is_correct": true, "explanation": "「机の上に本を置く」の丁寧形で、ここに入ると置く動作として文が成り立つ。"}, {"text": "破きます", "is_correct": false, "explanation": "「机の上に本を破きます」は本を破る動作になり、据える意味にならない。"}, {"text": "倒します", "is_correct": false, "explanation": "「机の上に本を倒します」は倒す動作で、本を据える意味にならない。"}, {"text": "転がします", "is_correct": false, "explanation": "「机の上に本を転がします」は転がす動作で、本を落ち着かせて置く意味にはならない。"}], "explanations": {"置きます": "「机の上に本を置く」の丁寧形で、ここに入ると置く動作として文が成り立つ。", "破きます": "「机の上に本を破きます」は本を破る動作になり、据える意味にならない。", "倒します": "「机の上に本を倒します」は倒す動作で、本を据える意味にならない。", "転がします": "「机の上に本を転がします」は転がす動作で、本を落ち着かせて置く意味にはならない。"}, "sentence_index": 0, "correct_answer": "置きます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は眼鏡を耳に置いて、新聞を読んだ。", "explanation": "ここは〈かける〉の意味。眼鏡は耳にかけるもので、「置く」とは言わない。"}, {"text": "クリームを手に置いて、よくこすった。", "explanation": "ここは〈塗る〉の意味。クリームは手に塗るもので、「置く」とは言わない。"}, {"text": "汚れた水を排水口に置いて、掃除を終えた。", "explanation": "ここは〈流す〉の意味。水は排水口に流すもので、置くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38716, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "置きましょう", "is_correct": true, "explanation": "「棚の下に置く」の意向形で、ここに入ると提案の文として成り立つ。"}, {"text": "投げましょう", "is_correct": false, "explanation": "「棚の下に投げましょう」は投げる動作になり、箱を据える意味にならない。"}, {"text": "蹴りましょう", "is_correct": false, "explanation": "「棚の下に蹴りましょう」は足で蹴る動作で、箱を置く行為にならない。"}, {"text": "叩きましょう", "is_correct": false, "explanation": "「棚の下に叩きましょう」は叩く動作になり、箱を据える意味にならない。"}], "explanations": {"置きましょう": "「棚の下に置く」の意向形で、ここに入ると提案の文として成り立つ。", "投げましょう": "「棚の下に投げましょう」は投げる動作になり、箱を据える意味にならない。", "蹴りましょう": "「棚の下に蹴りましょう」は足で蹴る動作で、箱を置く行為にならない。", "叩きましょう": "「棚の下に叩きましょう」は叩く動作になり、箱を据える意味にならない。"}, "sentence_index": 6, "correct_answer": "置きましょう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疲れたので、荷物を三階まで置いた。", "explanation": "ここは〈運ぶ〉の意味。場所まで移動させるなら「運ぶ」と言い、「置く」は据える動作なので「まで」には合わない。"}, {"text": "コンセントにプラグを置いて、スイッチを入れた。", "explanation": "ここは〈差し込む〉の意味。プラグはコンセントに差し込むもので、「置く」とは言わない。"}, {"text": "水道の蛇口を置いて、水を止めた。", "explanation": "ここは〈閉める〉の意味。蛇口を閉じる動作は「閉める」と言い、「置く」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38716, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は、傘を玄関の横に置きて、タオルで拭いてください。", "corrected_sentence": "雨の日は、傘を玄関の横に置いて、タオルで拭いてください。", "error_description": "「置く」のて形は「置いて」。「置きて」は誤った活用形で、て形は「おいて」になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "置いて", "is_correct": true, "explanation": "て形で、後ろに「少し休みました」と続けて動作を並べる形。ここに入る。"}, {"text": "置く", "is_correct": false, "explanation": "辞書形は文を終えるか名詞を修飾する形で、「床に置く、少し休みました」とは続かない。"}, {"text": "置きます", "is_correct": false, "explanation": "丁寧形は文の終わりに使う形で、「置きます、少し休みました」と続けられない。"}, {"text": "置かない", "is_correct": false, "explanation": "「床に置かない、少し休みました」は否定形が文を続けられず、文として成り立たない。"}], "correct_form": "置いて", "base_form": "置く", "form_label": "て形", "sentence_index": 1, "explanations": {"置いて": "て形で、後ろに「少し休みました」と続けて動作を並べる形。ここに入る。", "置く": "辞書形は文を終えるか名詞を修飾する形で、「床に置く、少し休みました」とは続かない。", "置きます": "丁寧形は文の終わりに使う形で、「置きます、少し休みました」と続けられない。", "置かない": "「床に置かない、少し休みました」は否定形が文を続けられず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38716, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "資料は、受付の机の上に置きてあります。", "corrected_sentence": "資料は、受付の机の上に置いてあります。", "error_description": "「置く」のて形は「置いて」。「置きて」は誤った活用形で、「置いてあります」の形にする必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "置いた", "is_correct": true, "explanation": "た形で、「どこに置いたか」と名詞節を作る形。ここに入る。"}, {"text": "置いて", "is_correct": false, "explanation": "て形は「どこに置いて、か」と続けられず、「置いたか」の形にならない。"}, {"text": "置かれる", "is_correct": false, "explanation": "受身形は「財布がどこに置かれたか」になり、「を」の文には合わない。"}, {"text": "置け", "is_correct": false, "explanation": "命令形は「どこに置け、思い出せません」となり、文の意味が成り立たない。"}], "correct_form": "置いた", "base_form": "置く", "form_label": "た形", "sentence_index": 7, "explanations": {"置いた": "た形で、「どこに置いたか」と名詞節を作る形。ここに入る。", "置いて": "て形は「どこに置いて、か」と続けられず、「置いたか」の形にならない。", "置かれる": "受身形は「財布がどこに置かれたか」になり、「を」の文には合わない。", "置け": "命令形は「どこに置け、思い出せません」となり、文の意味が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38718, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "においの出どころを表す。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「する」の目的語を示すが、においは目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "向かう先を示すので、においの出どころにはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示すが、「いいにおい」と比べる文脈がなく不自然。"}], "correct_answer": "から", "explanations": {"から": "においの出どころを表す。正しい。", "を": "「する」の目的語を示すが、においは目的語にならない。", "へ": "向かう先を示すので、においの出どころにはならない。", "より": "比較の基準を示すが、「いいにおい」と比べる文脈がなく不自然。"}, "error_tags": {"を": "目的語（においは対象ではない）", "へ": "方向（出どころではない）", "より": "比較（比べる文脈がなく不自然）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38718, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "動作の場所を示す。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「朝ごはんを」ですでに目的語があり、重複する。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すので、キッチンが用意する側になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、朝ごはんを用意する場所としては不自然。"}], "correct_answer": "で", "explanations": {"で": "動作の場所を示す。正しい。", "を": "「朝ごはんを」ですでに目的語があり、重複する。", "が": "主語を示すので、キッチンが用意する側になり不自然。", "へ": "方向を示すが、朝ごはんを用意する場所としては不自然。"}, "error_tags": {"を": "目的語の重複", "が": "主語（用意する主体ではない）", "へ": "方向（用意する場所として不自然）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38718, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ごはんをつくるところです。", "primary_collocate": null, "pronunciation": "きっちん", "ipa": "kitt͡ɕiɴ", "syllable_count": 4, "sentences": [{"text": "母はキッチンで晩ごはんを作っています。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "母[はは]はキッチンで晩[ばん]ごはんを作[つく]っています。", "sentence_source": "generated"}, {"text": "キッチンからいいにおいがします。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "キッチンからいいにおいがします。", "sentence_source": "generated"}, {"text": "新しいキッチンは広くて使いやすいです。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "新[あたら]しいキッチンは広[ひろ]くて使[つか]いやすいです。", "sentence_source": "generated"}, {"text": "キッチンで手を洗ってから料理を始めます。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "キッチンで手[て]を洗[あら]ってから料理[りょうり]を始[はじ]めます。", "sentence_source": "generated"}, {"text": "コップをキッチンに運んでください。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "コップをキッチンに運[はこ]んでください。", "sentence_source": "generated"}, {"text": "キッチンが汚れていたので、掃除をしました。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "キッチンが汚[よご]れていたので、掃除[そうじ]をしました。", "sentence_source": "generated"}, {"text": "このうちのキッチンには窓があります。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "このうちのキッチンには窓[まど]があります。", "sentence_source": "generated"}, {"text": "父はキッチンで朝ごはんを用意しています。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "父[ちち]はキッチンで朝[あさ]ごはんを用意[ようい]しています。", "sentence_source": "generated"}, {"text": "キッチンの電気をつけてください。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "キッチンの電気[でんき]をつけてください。", "sentence_source": "generated"}, {"text": "お客さんが来るので、キッチンをきれいにしました。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "お客[きゃく]さんが来[く]るので、キッチンをきれいにしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "キッチン", "label": "基本形"}], "register": "中立", "sense_fingerprint": "家の中で料理をする場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38718, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "キッチン", "is_correct": true, "explanation": "料理をする場所で、晩ごはんを作る場所として文が成り立つ。"}, {"text": "枕", "is_correct": false, "explanation": "枕は寝るためのもので、晩ごはんを作る場所にはならない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下は身につけるもので、料理をする場所ではない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "歯ブラシは歯を磨くもので、料理の場所にはならない。"}], "explanations": {"キッチン": "料理をする場所で、晩ごはんを作る場所として文が成り立つ。", "枕": "枕は寝るためのもので、晩ごはんを作る場所にはならない。", "靴下": "靴下は身につけるもので、料理をする場所ではない。", "歯ブラシ": "歯ブラシは歯を磨くもので、料理の場所にはならない。"}, "sentence_index": 0, "correct_answer": "キッチン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "キッチンは、家族が食事をするための、四本脚の家具です。", "explanation": "ここは〈テーブル〉の説明。キッチンは家具ではなく、料理をする部屋。"}, {"text": "キッチンは、本を並べて入れる、木でできた棚です。", "explanation": "ここは〈本棚〉の説明。キッチンは棚ではなく、料理をする部屋。"}, {"text": "キッチンは、お客さんを乗せて町を走る車です。", "explanation": "ここは〈タクシー〉の説明。キッチンは車ではなく、料理をする部屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38718, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "キッチン", "is_correct": true, "explanation": "家の中の料理用の部屋で、窓がある設備として文が成り立つ。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は本で、窓がないので文の意味が通らない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下には窓がないので、文が成り立たない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆には窓がないので、文の意味が通らない。"}], "explanations": {"キッチン": "家の中の料理用の部屋で、窓がある設備として文が成り立つ。", "辞書": "辞書は本で、窓がないので文の意味が通らない。", "靴下": "靴下には窓がないので、文が成り立たない。", "鉛筆": "鉛筆には窓がないので、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "キッチン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "キッチンは、寒い夜に食べる温かい料理の名前です。", "explanation": "ここは〈鍋〉の説明。キッチンは料理の名前ではなく、料理をする部屋。"}, {"text": "キッチンは、髪を切るための道具です。", "explanation": "ここは〈ハサミ〉の用途の説明。キッチンは道具ではなく、部屋。"}, {"text": "キッチンは、青くて小さな鳥の名前です。", "explanation": "ここは〈ツバメ〉の説明。キッチンは鳥ではなく、料理をする部屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38718, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "キッチンを夕食のスープを温めました。", "corrected_sentence": "キッチンで夕食のスープを温めました。", "error_description": "動作の場所は「で」で示す。「を」は誤りで、正しくは「で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38718, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "キッチンを立って、朝ごはんを作ります。", "corrected_sentence": "キッチンに立って、朝ごはんを作ります。", "error_description": "「立つ」の場所は「に」で示す。「を」は誤りで、正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
