INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38719, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "所属を示し、「キッチンの水道」となる。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「壊れる」は目的語を取らない自動詞なので、キッチンを対象にできない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」がすでに「水道が」にあり、主語が二つになる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「壊れる」の場所にはならず不自然。"}], "correct_answer": "の", "explanations": {"の": "所属を示し、「キッチンの水道」となる。正しい。", "を": "「壊れる」は目的語を取らない自動詞なので、キッチンを対象にできない。", "が": "主語の「が」がすでに「水道が」にあり、主語が二つになる。", "へ": "方向を示すが、「壊れる」の場所にはならず不自然。"}, "error_tags": {"を": "自動詞に目的語（壊れる）", "が": "主語の重複", "へ": "方向（壊れる場所にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38719, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "料理をするために使われる部屋のことです。", "primary_collocate": null, "pronunciation": "きっちん", "ipa": "kitt͡ɕiɴ", "syllable_count": 4, "sentences": [{"text": "キッチンには冷蔵庫とコンロがあります。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "キッチンには冷蔵庫[れいぞうこ]とコンロがあります。", "sentence_source": "generated"}, {"text": "このアパートはキッチンが狭いので、料理がしにくいです。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "このアパートはキッチンが狭[せま]いので、料理[りょうり]がしにくいです。", "sentence_source": "generated"}, {"text": "キッチンで野菜を切って、スープを作りました。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "キッチンで野菜[やさい]を切[き]って、スープを作[つく]りました。", "sentence_source": "generated"}, {"text": "引っ越しのとき、キッチンを新しくしました。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しのとき、キッチンを新[あたら]しくしました。", "sentence_source": "generated"}, {"text": "キッチンの棚にお皿をしまいます。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "キッチンの棚[たな]にお皿[さら]をしまいます。", "sentence_source": "generated"}, {"text": "彼女はキッチンに立つのが好きです。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はキッチンに立[た]つのが好[す]きです。", "sentence_source": "generated"}, {"text": "家族みんなでキッチンに集まって、ケーキを作りました。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "家族[かぞく]みんなでキッチンに集[あつ]まって、ケーキを作[つく]りました。", "sentence_source": "generated"}, {"text": "キッチンの水道が壊れたので、修理を頼みました。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "キッチンの水道[すいどう]が壊[こわ]れたので、修理[しゅうり]を頼[たの]みました。", "sentence_source": "generated"}, {"text": "広いキッチンなので、二人で料理できます。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "広[ひろ]いキッチンなので、二人[ふたり]で料理[りょうり]できます。", "sentence_source": "generated"}, {"text": "キッチンが暗いので、明かりを増やしました。", "target_word": "キッチン", "complexity_tier": "T3", "furigana": "キッチンが暗[くら]いので、明[あ]かりを増[ふ]やしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "キッチン", "label": "基本形"}], "register": "中立", "sense_fingerprint": "料理用の部屋。設備や広さを話題にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38719, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "キッチン", "is_correct": true, "explanation": "冷蔵庫とコンロがある料理用の部屋で、文が成り立つ。"}, {"text": "本棚", "is_correct": false, "explanation": "本棚は本を置く家具で、冷蔵庫やコンロはない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下は身につけるもので、冷蔵庫やコンロはない。"}, {"text": "郵便ポスト", "is_correct": false, "explanation": "郵便ポストは郵便を入れる箱で、冷蔵庫やコンロはない。"}], "explanations": {"キッチン": "冷蔵庫とコンロがある料理用の部屋で、文が成り立つ。", "本棚": "本棚は本を置く家具で、冷蔵庫やコンロはない。", "靴下": "靴下は身につけるもので、冷蔵庫やコンロはない。", "郵便ポスト": "郵便ポストは郵便を入れる箱で、冷蔵庫やコンロはない。"}, "sentence_index": 0, "correct_answer": "キッチン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "キッチンは、大切なお金をしまっておく、鍵のかかった箱です。", "explanation": "ここは〈金庫〉の説明。キッチンは箱ではなく、料理をするための部屋。"}, {"text": "キッチンは、時間を知らせる、壁にかける道具です。", "explanation": "ここは〈時計〉の説明。キッチンは道具ではなく、料理をするための部屋。"}, {"text": "キッチンは、壁にかけて飾る、額に入った絵です。", "explanation": "ここは〈絵画〉の説明。キッチンは絵ではなく、料理をするための部屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38719, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "キッチン", "is_correct": true, "explanation": "家族が集まって料理をする場所で、空欄に入るのはこの語だけ。"}, {"text": "宇宙", "is_correct": false, "explanation": "宇宙は家族が集まってケーキを作る場所ではなく、文の意味が通らない。"}, {"text": "本棚", "is_correct": false, "explanation": "本棚は集まって料理をする場所ではないので、文が成り立たない。"}, {"text": "靴箱", "is_correct": false, "explanation": "靴箱は靴を入れる箱で、家族が集まってケーキを作る場所ではない。"}], "explanations": {"キッチン": "家族が集まって料理をする場所で、空欄に入るのはこの語だけ。", "宇宙": "宇宙は家族が集まってケーキを作る場所ではなく、文の意味が通らない。", "本棚": "本棚は集まって料理をする場所ではないので、文が成り立たない。", "靴箱": "靴箱は靴を入れる箱で、家族が集まってケーキを作る場所ではない。"}, "sentence_index": 6, "correct_answer": "キッチン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "キッチンは、明日の天気を教えてくれるものです。", "explanation": "ここは〈天気予報〉の説明。キッチンは部屋で、天気を知らせるものではない。"}, {"text": "キッチンは、英語を教えてくれる人のことです。", "explanation": "ここは〈先生〉の説明。キッチンは人ではなく、料理をする部屋。"}, {"text": "キッチンは、寒い夜に体を包む布団です。", "explanation": "ここは〈布団〉の説明。キッチンは寝具ではなく、料理をする部屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38719, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "キッチンを入ると、いい香りがしました。", "corrected_sentence": "キッチンに入ると、いい香りがしました。", "error_description": "「入る」の場所は「に」で示す。「を」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38719, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "キッチンが野菜を運びます。", "corrected_sentence": "キッチンへ野菜を運びます。", "error_description": "「運ぶ」の移動先は「へ」で示す。「が」は誤りで、キッチンが運ぶ主体になってしまうので正しくは「へ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38720, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "入れる先を示す『に』。『紙を塵箱に入れる』と続く。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段・場所を示すので、入れる先は表せず合わない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列・相手を示すので、入れる先にはならず合わない。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語で、ここでは『入れてください』の行き先にならないので合わない。"}], "correct_answer": "に", "explanations": {"に": "入れる先を示す『に』。『紙を塵箱に入れる』と続く。", "で": "『で』は手段・場所を示すので、入れる先は表せず合わない。", "と": "『と』は並列・相手を示すので、入れる先にはならず合わない。", "が": "『が』は主語で、ここでは『入れてください』の行き先にならないので合わない。"}, "error_tags": {"に": "方向・帰着", "で": "手段・場所", "と": "並列・相手", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38720, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『塵箱の中』と名詞を修飾して所属を示す『の』。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語で、『中のごみ』を修飾する形には使えないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、名詞を修飾できないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示すので、名詞の修飾には使えないので合わない。"}], "correct_answer": "の", "explanations": {"の": "『塵箱の中』と名詞を修飾して所属を示す『の』。", "を": "『を』は目的語で、『中のごみ』を修飾する形には使えないので合わない。", "へ": "『へ』は方向を示すので、名詞を修飾できないので合わない。", "より": "『より』は比較を示すので、名詞の修飾には使えないので合わない。"}, "error_tags": {"の": "所属・修飾", "を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38720, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ごみを いれる はこ です。", "primary_collocate": null, "pronunciation": "ごみばこ", "ipa": "ɡomibako", "syllable_count": 4, "sentences": [{"text": "教室の入り口に塵箱があります。", "target_word": "塵箱", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の入[い]り口[ぐち]に塵箱[ごみばこ]があります。", "sentence_source": "generated"}, {"text": "紙を塵箱に入れてください。", "target_word": "塵箱", "complexity_tier": "T3", "furigana": "紙[かみ]を塵箱[ごみばこ]に入[い]れてください。", "sentence_source": "generated"}, {"text": "塵箱がいっぱいになったので、ごみを捨てに行きました。", "target_word": "塵箱", "complexity_tier": "T3", "furigana": "塵箱[ごみばこ]がいっぱいになったので、ごみを捨[す]てに行[い]きました。", "sentence_source": "generated"}, {"text": "弟は食べ終わったあと、袋を塵箱に捨てました。", "target_word": "塵箱", "complexity_tier": "T3", "furigana": "弟[おとうと]は食[た]べ終[お]わったあと、袋[ふくろ]を塵箱[ごみばこ]に捨[す]てました。", "sentence_source": "generated"}, {"text": "台所の塵箱は、流しの下に置いてあります。", "target_word": "塵箱", "complexity_tier": "T3", "furigana": "台所[だいどころ]の塵箱[ごみばこ]は、流[なが]しの下[した]に置[お]いてあります。", "sentence_source": "generated"}, {"text": "公園には大きい塵箱が二つあります。", "target_word": "塵箱", "complexity_tier": "T3", "furigana": "公園[こうえん]には大[おお]きい塵箱[ごみばこ]が二[ふた]つあります。", "sentence_source": "generated"}, {"text": "塵箱にふたがないので、においが部屋に広がります。", "target_word": "塵箱", "complexity_tier": "T3", "furigana": "塵箱[ごみばこ]にふたがないので、においが部屋[へや]に広[ひろ]がります。", "sentence_source": "generated"}, {"text": "母は毎朝、塵箱の中のごみを袋に集めます。", "target_word": "塵箱", "complexity_tier": "T3", "furigana": "母[はは]は毎朝[まいあさ]、塵箱[ごみばこ]の中[なか]のごみを袋[ふくろ]に集[あつ]めます。", "sentence_source": "generated"}, {"text": "駅で塵箱を探しましたが、見つかりませんでした。", "target_word": "塵箱", "complexity_tier": "T3", "furigana": "駅[えき]で塵箱[ごみばこ]を探[さが]しましたが、見[み]つかりませんでした。", "sentence_source": "generated"}, {"text": "塵箱は赤いので、遠くからでもすぐわかります。", "target_word": "塵箱", "complexity_tier": "T3", "furigana": "塵箱[ごみばこ]は赤[あか]いので、遠[とお]くからでもすぐわかります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "塵箱", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ごみを入れる箱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c11be19-e1cc-49c2-a822-0ba302475d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38720, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塵箱", "is_correct": true, "explanation": "ごみを入れる箱を指すので、教室の入り口にあるものとして入る。"}, {"text": "雲", "is_correct": false, "explanation": "空にあるもので、教室の入り口にあるとは言えないので合わない。"}, {"text": "川", "is_correct": false, "explanation": "自然の川で、教室の入り口にあるとは言えないので合わない。"}, {"text": "空", "is_correct": false, "explanation": "教室の入り口に『ある』ものではないので合わない。"}], "explanations": {"塵箱": "ごみを入れる箱を指すので、教室の入り口にあるものとして入る。", "雲": "空にあるもので、教室の入り口にあるとは言えないので合わない。", "川": "自然の川で、教室の入り口にあるとは言えないので合わない。", "空": "教室の入り口に『ある』ものではないので合わない。"}, "sentence_index": 0, "correct_answer": "塵箱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園で、塵箱に座って話しました。", "explanation": "ここは座るためのベンチの話。塵箱はごみを入れる容器なので、座る場所としては使わないので合わない。"}, {"text": "塵箱に本を並べて、部屋をすっきりさせました。", "explanation": "ここは本を並べる本棚の話。塵箱は本を並べる家具ではないので合わない。"}, {"text": "塵箱に花を生けました。", "explanation": "ここは花を入れる花瓶の話。塵箱は花を生ける容器ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38720, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塵箱", "is_correct": true, "explanation": "ふたがあるごみ入れを指すので、『ふたがない』の主語として入る。"}, {"text": "電車", "is_correct": false, "explanation": "ふたがない、の主語として成り立たないので合わない。"}, {"text": "歌", "is_correct": false, "explanation": "ふたの有無を言う対象として成り立たないので合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "ふたがない手紙、という話はにおいとは結びつかないので合わない。"}], "explanations": {"塵箱": "ふたがあるごみ入れを指すので、『ふたがない』の主語として入る。", "電車": "ふたがない、の主語として成り立たないので合わない。", "歌": "ふたの有無を言う対象として成り立たないので合わない。", "手紙": "ふたがない手紙、という話はにおいとは結びつかないので合わない。"}, "sentence_index": 6, "correct_answer": "塵箱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "塵箱に生ごみを入れて、口をしっかり縛ります。", "explanation": "ここは〈ごみ袋〉の話。塵箱は口を縛れない容器なので、袋の口を縛る文には合わない。"}, {"text": "塵箱でほこりを集めて、床をきれいにしました。", "explanation": "ここは〈ちりとり〉の話。塵箱は床のほこりを集める道具ではないので合わない。"}, {"text": "塵箱に洗濯物を入れて、ベランダに運びました。", "explanation": "ここは〈かご〉の話。塵箱は洗濯物を運ぶための入れ物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38720, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "塵箱を、ごみを入れてください。", "corrected_sentence": "塵箱に、ごみを入れてください。", "error_description": "『入れる』の行き先は『に』で示す。『を』では塵箱が目的語になり、ごみを入れる先を示せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38720, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "塵箱で中には、ごみ袋が入っています。", "corrected_sentence": "塵箱の中には、ごみ袋が入っています。", "error_description": "『中』の前は『の』。『で』だと『塵箱で』が手段になり、『中には』とつながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38722, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「腰に手を当てる」の「に」。手を当てる場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「腰が手を当てて」は主語が不自然で、「当てる」の場所には「が」を使わない。"}, {"text": "を", "is_correct": false, "explanation": "「手を当てて」で既に「を」を使っているので、「腰を」を続けると二重になり不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「腰で手を当てて」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「腰に手を当てる」の「に」。手を当てる場所を示す。", "が": "「腰が手を当てて」は主語が不自然で、「当てる」の場所には「が」を使わない。", "を": "「手を当てて」で既に「を」を使っているので、「腰を」を続けると二重になり不自然。", "で": "「で」は手段や場所を示すが、「腰で手を当てて」は意味が通らない。"}, "error_tags": {"が": "主語の誤り", "を": "対象の二重使用", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38722, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38722, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "からだのまんなかあたりの、うしろのほうにあるところです。", "primary_collocate": null, "pronunciation": "こし", "ipa": "koɕi", "syllable_count": 2, "sentences": [{"text": "重い荷物を持って、腰が痛くなりました。", "target_word": "腰", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を持[も]って、腰[こし]が痛[いた]くなりました。", "sentence_source": "generated"}, {"text": "おじいさんは、腰に手を当ててゆっくり立ち上がりました。", "target_word": "腰", "complexity_tier": "T3", "furigana": "おじいさんは、腰[こし]に手[て]を当[あ]ててゆっくり立[た]ち上[あ]がりました。", "sentence_source": "generated"}, {"text": "腰にタオルを巻いて、サウナに入りました。", "target_word": "腰", "complexity_tier": "T3", "furigana": "腰[こし]にタオルを巻[ま]いて、サウナに入[はい]りました。", "sentence_source": "generated"}, {"text": "長い時間座っていたので、腰を伸ばしました。", "target_word": "腰", "complexity_tier": "T3", "furigana": "長[なが]い時間[じかん]座[すわ]っていたので、腰[こし]を伸[の]ばしました。", "sentence_source": "generated"}, {"text": "川の水が深くて、腰まで水につかりました。", "target_word": "腰", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が深[ふか]くて、腰[こし]まで水[みず]につかりました。", "sentence_source": "generated"}, {"text": "ズボンが大きいので、腰のところをベルトで留めました。", "target_word": "腰", "complexity_tier": "T3", "furigana": "ズボンが大[おお]きいので、腰[こし]のところをベルトで留[と]めました。", "sentence_source": "generated"}, {"text": "母は腰をかがめて、庭の草を取っていました。", "target_word": "腰", "complexity_tier": "T3", "furigana": "母[はは]は腰[こし]をかがめて、庭[にわ]の草[くさ]を取[と]っていました。", "sentence_source": "generated"}, {"text": "子どもを抱き上げようとして、腰を痛めました。", "target_word": "腰", "complexity_tier": "T3", "furigana": "子[こ]どもを抱[だ]き上[あ]げようとして、腰[こし]を痛[いた]めました。", "sentence_source": "generated"}, {"text": "ダンスの先生は、腰を大きく回す動きを見せました。", "target_word": "腰", "complexity_tier": "T3", "furigana": "ダンスの先生[せんせい]は、腰[こし]を大[おお]きく回[まわ]す動[うご]きを見[み]せました。", "sentence_source": "generated"}, {"text": "腰に付けた小さなバッグに、財布を入れています。", "target_word": "腰", "complexity_tier": "T3", "furigana": "腰[こし]に付[つ]けた小[ちい]さなバッグに、財布[さいふ]を入[い]れています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "腰", "label": "基本形"}], "register": "中立", "sense_fingerprint": "体の中ほどの後ろ側にある部位(腰が痛い・腰に手を当てる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: かがめ (Zipf 2.21)','sentence 7 above tier T2: contains vocabulary far above tier T2: 抱き上げよ (Zipf 2.41)']::text[], '40cb9108-8bde-4618-9c38-fbf83d7a73e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38722, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腰", "is_correct": true, "explanation": "「腰が痛くなる」の主語として自然。重い荷物で痛めたのは体の後ろ側の腰。"}, {"text": "眉", "is_correct": false, "explanation": "荷物を持って眉が痛くなることはない。眉は体の後ろ側の部位ではなく、痛みの主語にならない。"}, {"text": "髪", "is_correct": false, "explanation": "「髪が痛くなる」とは言わない。重い荷物の負担で痛む部位として不自然。"}, {"text": "指輪", "is_correct": false, "explanation": "指輪は痛くならない。装身具なので、重い荷物で痛みが生じる主語にはならない。"}], "explanations": {"腰": "「腰が痛くなる」の主語として自然。重い荷物で痛めたのは体の後ろ側の腰。", "眉": "荷物を持って眉が痛くなることはない。眉は体の後ろ側の部位ではなく、痛みの主語にならない。", "髪": "「髪が痛くなる」とは言わない。重い荷物の負担で痛む部位として不自然。", "指輪": "指輪は痛くならない。装身具なので、重い荷物で痛みが生じる主語にはならない。"}, "sentence_index": 0, "correct_answer": "腰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達と腰を並べて歩いた。", "explanation": "ここは〈肩を並べる〉（対等に並んで歩く）の〈肩〉の意味。腰は並べるものではないので、この言い方はしない。"}, {"text": "食べすぎて、腰がいっぱいになった。", "explanation": "ここは〈腹〉（おなか）の意味。腰は体の後ろ側の部位で、満腹を表すときは使わないので合わない。"}, {"text": "不満そうに、腰を組んで黙っていた。", "explanation": "ここは〈腕を組む〉の意味。腰は組むものではないので、この言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38722, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腰", "is_correct": true, "explanation": "「腰をかがめる」の「腰」。体を前に曲げる部位として自然。"}, {"text": "耳", "is_correct": false, "explanation": "耳をかがめるとは言わない。体を曲げる動作の対象にならないので合わない。"}, {"text": "歯", "is_correct": false, "explanation": "歯はかがめられない。体を曲げる動作の対象として不自然。"}, {"text": "爪", "is_correct": false, "explanation": "爪をかがめるとは言わない。かがむ動作の対象にならないので合わない。"}], "explanations": {"腰": "「腰をかがめる」の「腰」。体を前に曲げる部位として自然。", "耳": "耳をかがめるとは言わない。体を曲げる動作の対象にならないので合わない。", "歯": "歯はかがめられない。体を曲げる動作の対象として不自然。", "爪": "爪をかがめるとは言わない。かがむ動作の対象にならないので合わない。"}, "sentence_index": 6, "correct_answer": "腰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は堂々と腰を張って歩いた。", "explanation": "ここは〈胸を張る〉（得意げに堂々とする）の〈胸〉の意味。腰を張るという言い方はしないので、この文は合わない。"}, {"text": "友達と腰を交えて話すのは、いつも楽しい。", "explanation": "ここは〈膝を交える〉（膝をつき合わせて話す）の意味。腰を交えるとは言わないので、この言い方は不自然。"}, {"text": "彼女は友達の来るのを、腰を長くして待っている。", "explanation": "ここは〈首を長くして待つ〉（待ちわびる）の意味。腰を長くするという言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38722, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重い荷物を持ち上げて、腰を痛くなりました。", "corrected_sentence": "重い荷物を持ち上げて、腰が痛くなりました。", "error_description": "「痛くなる」の主語は「が」で示す。「を」は動作の対象に使うので誤り。正しくは「腰が痛くなりました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38722, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "マッサージをしてもらったら、腰に楽になりました。", "corrected_sentence": "マッサージをしてもらったら、腰が楽になりました。", "error_description": "「楽になる」で変化する部分の主語は「が」で示す。「に」は誤りで、正しくは「腰が楽になりました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38723, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「腰に負担がかかる」の「に」。負担がかかる相手を示す。"}, {"text": "を", "is_correct": false, "explanation": "「かかる」は「に」で相手を示すので、「腰を負担がかかります」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「腰で負担がかかります」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「腰より負担がかかります」は比較の文になり、意味が通らず不自然。"}], "correct_answer": "に", "explanations": {"に": "「腰に負担がかかる」の「に」。負担がかかる相手を示す。", "を": "「かかる」は「に」で相手を示すので、「腰を負担がかかります」は不自然。", "で": "「で」は手段や場所を示すが、「腰で負担がかかります」は意味が通らない。", "より": "「より」は比較を示す。「腰より負担がかかります」は比較の文になり、意味が通らず不自然。"}, "error_tags": {"を": "対象の誤り", "で": "場所・手段", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38723, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「腰を支える」の「を」。支える対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「腰に支える」とは言わず、「支える」は対象に「を」を使う。"}, {"text": "が", "is_correct": false, "explanation": "「腰が支えてくれる」は、支える対象を示す形として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「腰から支えてくれる」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「腰を支える」の「を」。支える対象を示す。", "に": "「腰に支える」とは言わず、「支える」は対象に「を」を使う。", "が": "「腰が支えてくれる」は、支える対象を示す形として不自然。", "から": "「から」は起点を示すが、「腰から支えてくれる」は意味が通らない。"}, "error_tags": {"に": "位置・相手", "が": "主語の誤り", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38723, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間や動物の体の、背中側の中央部分で、胴体を支える部分。", "primary_collocate": null, "pronunciation": "こし", "ipa": "koɕi", "syllable_count": 2, "sentences": [{"text": "腰は体を支える大切な部分なので、強くしたいです。", "target_word": "腰", "complexity_tier": "T3", "furigana": "腰[こし]は体[からだ]を支[ささ]える大切[たいせつ]な部分[ぶぶん]なので、強[つよ]くしたいです。", "sentence_source": "generated"}, {"text": "立ち仕事が続くと、腰に負担がかかります。", "target_word": "腰", "complexity_tier": "T3", "furigana": "立[た]ち仕事[しごと]が続[つづ]くと、腰[こし]に負担[ふたん]がかかります。", "sentence_source": "generated"}, {"text": "腰を守るために、重い物は膝を曲げて持ち上げます。", "target_word": "腰", "complexity_tier": "T3", "furigana": "腰[こし]を守[まも]るために、重[おも]い物[もの]は膝[ひざ]を曲[ま]げて持[も]ち上[あ]げます。", "sentence_source": "generated"}, {"text": "医者に、腰を冷やさないようにと言われました。", "target_word": "腰", "complexity_tier": "T3", "furigana": "医者[いしゃ]に、腰[こし]を冷[ひ]やさないようにと言[い]われました。", "sentence_source": "generated"}, {"text": "毎朝、腰を回す体操をして体をほぐしています。", "target_word": "腰", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、腰[こし]を回[まわ]す体操[たいそう]をして体[からだ]をほぐしています。", "sentence_source": "generated"}, {"text": "年を取ると、腰が曲がる人が増えてきます。", "target_word": "腰", "complexity_tier": "T3", "furigana": "年[とし]を取[と]ると、腰[こし]が曲[ま]がる人[ひと]が増[ふ]えてきます。", "sentence_source": "generated"}, {"text": "猫は高い所から落ちても、腰をひねって上手に着地します。", "target_word": "腰", "complexity_tier": "T3", "furigana": "猫[ねこ]は高[たか]い所[ところ]から落[お]ちても、腰[こし]をひねって上手[じょうず]に着地[ちゃくち]します。", "sentence_source": "generated"}, {"text": "椅子の背もたれが腰を支えてくれるので、楽です。", "target_word": "腰", "complexity_tier": "T3", "furigana": "椅子[いす]の背[せ]もたれが腰[こし]を支[ささ]えてくれるので、楽[らく]です。", "sentence_source": "generated"}, {"text": "腰の骨が折れてしまい、しばらく入院しました。", "target_word": "腰", "complexity_tier": "T3", "furigana": "腰[こし]の骨[ほね]が折[お]れてしまい、しばらく入院[にゅういん]しました。", "sentence_source": "generated"}, {"text": "柔道では、相手を投げるときに腰の力を使います。", "target_word": "腰", "complexity_tier": "T3", "furigana": "柔道[じゅうどう]では、相手[あいて]を投[な]げるときに腰[こし]の力[ちから]を使[つか]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "腰", "label": "基本形"}], "register": "中立", "sense_fingerprint": "背中側の中央にあって胴体を支える部位(腰に負担がかかる・腰を守る)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cb9108-8bde-4618-9c38-fbf83d7a73e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38723, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腰", "is_correct": true, "explanation": "胴体を支える部位として、「体を支える大切な部分」と合う。"}, {"text": "髪", "is_correct": false, "explanation": "髪は体を支える部分ではないので、「体を支える大切な部分」には合わない。"}, {"text": "眉", "is_correct": false, "explanation": "眉は体を支える部位ではない。文の説明とは合わない。"}, {"text": "爪", "is_correct": false, "explanation": "爪は体を支える部位ではない。「強くしたい」対象としても不自然。"}], "explanations": {"腰": "胴体を支える部位として、「体を支える大切な部分」と合う。", "髪": "髪は体を支える部分ではないので、「体を支える大切な部分」には合わない。", "眉": "眉は体を支える部位ではない。文の説明とは合わない。", "爪": "爪は体を支える部位ではない。「強くしたい」対象としても不自然。"}, "sentence_index": 0, "correct_answer": "腰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "腰に汗して働く人は立派だ。", "explanation": "ここは〈額に汗して〉の〈額〉の意味。汗をかくのは額で、腰に汗するとは言わないので合わない。"}, {"text": "彼はおこって、腰を立てて部屋を出ていきました。", "explanation": "ここは〈腹を立てる〉（怒る）の意味。腰を立てるとは言わないので、この文は成り立たない。"}, {"text": "友達が来るのを、腰を長くして待っています。", "explanation": "ここは〈首を長くして待つ〉（待ちわびる）の意味。腰を長くするとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38723, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腰", "is_correct": true, "explanation": "「腰をひねる」の「腰」。着地のために体をひねる部位として自然。"}, {"text": "歯", "is_correct": false, "explanation": "歯をひねるとは言わない。体をひねる動作の対象にならないので合わない。"}, {"text": "耳", "is_correct": false, "explanation": "耳をひねるとは言わない。着地の動作と結びつかないので合わない。"}, {"text": "目", "is_correct": false, "explanation": "目をひねるとは言わない。体をひねる動作の対象にはならない。"}], "explanations": {"腰": "「腰をひねる」の「腰」。着地のために体をひねる部位として自然。", "歯": "歯をひねるとは言わない。体をひねる動作の対象にならないので合わない。", "耳": "耳をひねるとは言わない。着地の動作と結びつかないので合わない。", "目": "目をひねるとは言わない。体をひねる動作の対象にはならない。"}, "sentence_index": 6, "correct_answer": "腰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は腰をすくめて、よく分からないと言った。", "explanation": "ここは〈肩をすくめる〉（わからない仕草をする）の〈肩〉の意味。腰をすくめるとは言わないので合わない。"}, {"text": "嬉しそうに、腰を細めて笑っていた。", "explanation": "ここは〈目を細める〉（嬉しさで目を細くする）の意味。腰を細めるとは言わないので、この言い方は不自然。"}, {"text": "彼は堂々と腰を張って歩いた。", "explanation": "ここは〈胸を張る〉（得意げにする）の意味。腰を張るという言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38723, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "椅子に長く座ると、腰で痛くなります。", "corrected_sentence": "椅子に長く座ると、腰が痛くなります。", "error_description": "「痛くなる」の主語は「が」で示す。「で」は場所や手段を示すので誤り。正しくは「腰が痛くなります」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38723, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ベッドで寝ていると、腰を楽になります。", "corrected_sentence": "ベッドで寝ていると、腰が楽になります。", "error_description": "「楽になる」で変化する部分の主語は「が」で示す。「を」は誤りで、正しくは「腰が楽になります」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38724, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「シーツを裂く」の「を」。裂く対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「シーツに裂いて」は対象を示せず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「シーツと裂いて」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「シーツへ裂いて」は動作の対象として不自然。"}], "correct_answer": "を", "explanations": {"を": "「シーツを裂く」の「を」。裂く対象を示す。", "に": "「シーツに裂いて」は対象を示せず、不自然。", "と": "「と」は相手や並列を示すが、「シーツと裂いて」は意味が通らない。", "へ": "「へ」は方向を示すが、「シーツへ裂いて」は動作の対象として不自然。"}, "error_tags": {"に": "位置・相手", "と": "相手・並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38724, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「写真を裂く」の「を」。裂く対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「裂く」は対象に「を」を使う他動詞なので、「写真が裂いて」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「写真で裂いて」は対象を示せず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「写真から裂いて」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「写真を裂く」の「を」。裂く対象を示す。", "が": "「裂く」は対象に「を」を使う他動詞なので、「写真が裂いて」は不自然。", "で": "「で」は手段や場所を示すが、「写真で裂いて」は対象を示せず不自然。", "から": "「から」は起点を示すが、「写真から裂いて」は意味が通らない。"}, "error_tags": {"が": "主語の誤り", "で": "場所・手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38724, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものをちからでふたつにわけること。", "primary_collocate": null, "pronunciation": "さく", "ipa": "sakɯ", "syllable_count": 2, "sentences": [{"text": "彼は怒って、手紙を二つに裂いた。", "target_word": "裂いた", "complexity_tier": "T3", "furigana": "彼[かれ]は怒[おこ]って、手紙[てがみ]を二[ふた]つに裂[さ]いた。", "sentence_source": "generated"}, {"text": "母は古いシーツを裂いて、掃除用の布にした。", "target_word": "裂いて", "complexity_tier": "T3", "furigana": "母[はは]は古[ふる]いシーツを裂[さ]いて、掃除用[そうじよう]の布[ぬの]にした。", "sentence_source": "generated"}, {"text": "子どもが絵本のページを裂いてしまい、泣き出した。", "target_word": "裂いて", "complexity_tier": "T3", "furigana": "子[こ]どもが絵本[えほん]のページを裂[さ]いてしまい、泣[な]き出[だ]した。", "sentence_source": "generated"}, {"text": "強い風が古い旗を裂いた。", "target_word": "裂いた", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]が古[ふる]い旗[はた]を裂[さ]いた。", "sentence_source": "generated"}, {"text": "けがをした友達のために、シャツを裂いて包帯の代わりにした。", "target_word": "裂いて", "complexity_tier": "T3", "furigana": "けがをした友達[ともだち]のために、シャツを裂[さ]いて包帯[ほうたい]の代[か]わりにした。", "sentence_source": "generated"}, {"text": "紙を裂く音が静かな教室に大きく響いた。", "target_word": "裂く", "complexity_tier": "T3", "furigana": "紙[かみ]を裂[さ]く音[おと]が静[しず]かな教室[きょうしつ]に大[おお]きく響[ひび]いた。", "sentence_source": "generated"}, {"text": "布は手で裂くと、まっすぐに切れる。", "target_word": "裂く", "complexity_tier": "T3", "furigana": "布[ぬの]は手[て]で裂[さ]くと、まっすぐに切[き]れる。", "sentence_source": "generated"}, {"text": "彼女は写真を裂いて、過去を忘れようとした。", "target_word": "裂いて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は写真[しゃしん]を裂[さ]いて、過去[かこ]を忘[わす]れようとした。", "sentence_source": "generated"}, {"text": "猫がカーテンを裂いたので、新しいものを買った。", "target_word": "裂いた", "complexity_tier": "T3", "furigana": "猫[ねこ]がカーテンを裂[さ]いたので、新[あたら]しいものを買[か]った。", "sentence_source": "generated"}, {"text": "袋をハサミで切らずに、手で裂いて開けた。", "target_word": "裂いて", "complexity_tier": "T3", "furigana": "袋[ふくろ]をハサミで切[き]らずに、手[て]で裂[さ]いて開[あ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "裂かない", "label": "未然形"}, {"form": "裂き", "label": "連用形"}, {"form": "裂く", "label": "終止形"}, {"form": "裂けば", "label": "仮定形"}, {"form": "裂こう", "label": "意志形"}, {"form": "裂いた", "label": "過去形"}, {"form": "裂いて", "label": "て形"}], "register": "neutral", "sense_fingerprint": "tear paper, cloth or a photo in two with the hands or with force", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cb9108-8bde-4618-9c38-fbf83d7a73e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38724, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裂いた", "is_correct": true, "explanation": "「手紙を二つに裂いた」の過去形。手で二つに破く動作として自然。"}, {"text": "煮た", "is_correct": false, "explanation": "手紙を煮て二つにするとは言わない。紙を二つに分ける動作と合わない。"}, {"text": "焼いた", "is_correct": false, "explanation": "手紙を焼くことは二つに分けることではなく、文の意味と合わない。"}, {"text": "炒めた", "is_correct": false, "explanation": "手紙を炒めることはできず、紙を二つに分ける動作としても不自然。"}], "explanations": {"裂いた": "「手紙を二つに裂いた」の過去形。手で二つに破く動作として自然。", "煮た": "手紙を煮て二つにするとは言わない。紙を二つに分ける動作と合わない。", "焼いた": "手紙を焼くことは二つに分けることではなく、文の意味と合わない。", "炒めた": "手紙を炒めることはできず、紙を二つに分ける動作としても不自然。"}, "sentence_index": 0, "correct_answer": "裂いた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "野原で、きれいな花を裂いて持ち帰った。", "explanation": "ここは〈花を摘む〉（花を手で取る）の〈摘む〉の意味。花は裂くのではなく摘むものなので、この言い方は合わない。"}, {"text": "彼は子どもとの約束を裂いてしまった。", "explanation": "ここは〈約束を破る〉の〈破る〉の意味。裂くは紙や布を二つにすることなので、約束には使わない。"}, {"text": "うっかり、窓ガラスを裂いてしまった。", "explanation": "ここは〈ガラスを割る〉の〈割る〉の意味。ガラスは裂けないので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38724, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裂く", "is_correct": true, "explanation": "「布は手で裂くと、まっすぐに切れる」の「裂く」。手で布を裂く動作として自然。"}, {"text": "揚げる", "is_correct": false, "explanation": "布を手で揚げることはできず、文の動作として合わない。"}, {"text": "蒸す", "is_correct": false, "explanation": "布を手で蒸すとは言わない。布を裂く動作と合わない。"}, {"text": "茹でる", "is_correct": false, "explanation": "布を手で茹でるとは言わない。布を分ける動作として不自然。"}], "explanations": {"裂く": "「布は手で裂くと、まっすぐに切れる」の「裂く」。手で布を裂く動作として自然。", "揚げる": "布を手で揚げることはできず、文の動作として合わない。", "蒸す": "布を手で蒸すとは言わない。布を裂く動作と合わない。", "茹でる": "布を手で茹でるとは言わない。布を分ける動作として不自然。"}, "sentence_index": 6, "correct_answer": "裂く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "えんぴつを裂いて、先を細くした。", "explanation": "ここは〈えんぴつを削る〉（けずって形を整える）の〈削る〉の意味。えんぴつは裂けないので、この言い方は合わない。"}, {"text": "古い機械を裂いて、部品を取り出した。", "explanation": "ここは〈壊す〉の意味。機械は裂けるものではないので、裂くとは言わない。"}, {"text": "フライパンで、バターを裂いた。", "explanation": "ここは〈溶かす〉の意味。バターを裂くとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38724, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は怒って、古い紙を二つに裂くた。", "corrected_sentence": "彼は怒って、古い紙を二つに裂いた。", "error_description": "「裂く」の過去形は「裂いた」。「裂くた」は誤った活用形なので、正しくは「裂いた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "裂いて", "is_correct": true, "explanation": "て形。「シーツを裂いて、布にした」と続けるための形。"}, {"text": "裂いた", "is_correct": false, "explanation": "過去形。文中で動作を並べるときは「て」でつなぐので、過去形は入らない。"}, {"text": "裂く", "is_correct": false, "explanation": "終止形。「古いシーツを裂く、布にした」と文を切らずに続けることはできず、この位置には入らない。"}, {"text": "裂こう", "is_correct": false, "explanation": "意志形。「裂こう、布にした」は自分の意思の文になり、過去の動作を並べる流れと合わない。"}], "correct_form": "裂いて", "base_form": "裂く", "form_label": "て形", "sentence_index": 1, "explanations": {"裂いて": "て形。「シーツを裂いて、布にした」と続けるための形。", "裂いた": "過去形。文中で動作を並べるときは「て」でつなぐので、過去形は入らない。", "裂く": "終止形。「古いシーツを裂く、布にした」と文を切らずに続けることはできず、この位置には入らない。", "裂こう": "意志形。「裂こう、布にした」は自分の意思の文になり、過去の動作を並べる流れと合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38724, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は思い出の写真を裂くて、前に進もうとした。", "corrected_sentence": "彼女は思い出の写真を裂いて、前に進もうとした。", "error_description": "「裂く」のて形は「裂いて」。「裂くて」は誤った活用形なので、正しくは「裂いて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "裂いて", "is_correct": true, "explanation": "て形。「写真を裂いて、過去を忘れようとした」と続けるための形。"}, {"text": "裂かない", "is_correct": false, "explanation": "未然形。「ない」などに続く形で、「て」でつないで動作を並べる文には入らない。"}, {"text": "裂けば", "is_correct": false, "explanation": "仮定形。「もし〜なら」の意味になり、文の流れと合わない。"}, {"text": "裂き", "is_correct": false, "explanation": "連用形。単独では文を続けられず、「て」を伴わないと「写真を裂き、過去を忘れようとした」の流れにならない。"}], "correct_form": "裂いて", "base_form": "裂く", "form_label": "て形", "sentence_index": 7, "explanations": {"裂いて": "て形。「写真を裂いて、過去を忘れようとした」と続けるための形。", "裂かない": "未然形。「ない」などに続く形で、「て」でつないで動作を並べる文には入らない。", "裂けば": "仮定形。「もし〜なら」の意味になり、文の流れと合わない。", "裂き": "連用形。単独では文を続けられず、「て」を伴わないと「写真を裂き、過去を忘れようとした」の流れにならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38725, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38725, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「裂くと」の「と」。裂いたときに起きる結果を示す条件の用法。"}, {"text": "を", "is_correct": false, "explanation": "「裂くを」は動詞に直接続く形として不自然で、条件の意味を作れない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「裂くで」は条件として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「裂くへ」は動詞に続けられず不自然。"}], "correct_answer": "と", "explanations": {"と": "「裂くと」の「と」。裂いたときに起きる結果を示す条件の用法。", "を": "「裂くを」は動詞に直接続く形として不自然で、条件の意味を作れない。", "で": "「で」は手段を示すが、「裂くで」は条件として成り立たない。", "へ": "「へ」は方向を示すが、「裂くへ」は動詞に続けられず不自然。"}, "error_tags": {"を": "対象の誤り", "で": "場所・手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38725, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ひとつながりになっているものに力を加えて、二つ以上に分けること。", "primary_collocate": null, "pronunciation": "さく", "ipa": "sakɯ", "syllable_count": 2, "sentences": [{"text": "魚の腹を裂いて、中のわたを取り出す。", "target_word": "裂いて", "complexity_tier": "T3", "furigana": "魚[さかな]の腹[はら]を裂[さ]いて、中[なか]のわたを取[と]り出[だ]す。", "sentence_source": "generated"}, {"text": "鶏肉を手で細く裂いて、サラダにのせた。", "target_word": "裂いて", "complexity_tier": "T3", "furigana": "鶏肉[とりにく]を手[て]で細[ほそ]く裂[さ]いて、サラダにのせた。", "sentence_source": "generated"}, {"text": "竹を縦に裂いて、かごを編む材料にする。", "target_word": "裂いて", "complexity_tier": "T3", "furigana": "竹[たけ]を縦[たて]に裂[さ]いて、かごを編[あ]む材料[ざいりょう]にする。", "sentence_source": "generated"}, {"text": "さけの身を裂いて、おにぎりの具にした。", "target_word": "裂いて", "complexity_tier": "T3", "furigana": "さけの身[み]を裂[さ]いて、おにぎりの具[ぐ]にした。", "sentence_source": "generated"}, {"text": "大工は太い木を裂いて、薪を作った。", "target_word": "裂いて", "complexity_tier": "T3", "furigana": "大工[だいく]は太[ふと]い木[き]を裂[さ]いて、薪[まき]を作[つく]った。", "sentence_source": "generated"}, {"text": "スルメを細く裂くと、食べやすくなる。", "target_word": "裂く", "complexity_tier": "T3", "furigana": "スルメを細[ほそ]く裂[さ]くと、食[た]べやすくなる。", "sentence_source": "generated"}, {"text": "雷が大木を裂いたので、村の人は驚いた。", "target_word": "裂いた", "complexity_tier": "T3", "furigana": "雷[かみなり]が大木[たいぼく]を裂[さ]いたので、村[むら]の人[ひと]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "チーズは手で裂くと、細い糸のようにほぐれる。", "target_word": "裂く", "complexity_tier": "T3", "furigana": "チーズは手[て]で裂[さ]くと、細[ほそ]い糸[いと]のようにほぐれる。", "sentence_source": "generated"}, {"text": "蒸した貝柱を裂いて、スープに入れた。", "target_word": "裂いて", "complexity_tier": "T3", "furigana": "蒸[む]した貝柱[かいばしら]を裂[さ]いて、スープに入[い]れた。", "sentence_source": "generated"}, {"text": "料理人は魚を裂く前に、ナイフをよく洗った。", "target_word": "裂く", "complexity_tier": "T3", "furigana": "料理人[りょうりにん]は魚[さかな]を裂[さ]く前[まえ]に、ナイフをよく洗[あら]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "裂かない", "label": "未然形"}, {"form": "裂き", "label": "連用形"}, {"form": "裂く", "label": "終止形"}, {"form": "裂けば", "label": "仮定形"}, {"form": "裂こう", "label": "意志形"}, {"form": "裂いた", "label": "過去形"}, {"form": "裂いて", "label": "て形"}], "register": "neutral", "sense_fingerprint": "split a single connected piece such as fish, meat, bamboo or wood into two or more parts along its grain", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cb9108-8bde-4618-9c38-fbf83d7a73e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38725, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裂いて", "is_correct": true, "explanation": "「魚の腹を裂いて、中のわたを取り出す」と自然につながる。魚を裂いて開く動作。"}, {"text": "煮て", "is_correct": false, "explanation": "魚の腹を煮ることは、中のわたを取り出す動作として意味が通らない。"}, {"text": "焼いて", "is_correct": false, "explanation": "魚の腹を焼くことは、わたを取り出すための開く動作ではないので合わない。"}, {"text": "炒めて", "is_correct": false, "explanation": "魚の腹を炒めることは、わたを取り出す作業として不自然。"}], "explanations": {"裂いて": "「魚の腹を裂いて、中のわたを取り出す」と自然につながる。魚を裂いて開く動作。", "煮て": "魚の腹を煮ることは、中のわたを取り出す動作として意味が通らない。", "焼いて": "魚の腹を焼くことは、わたを取り出すための開く動作ではないので合わない。", "炒めて": "魚の腹を炒めることは、わたを取り出す作業として不自然。"}, "sentence_index": 0, "correct_answer": "裂いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玉ねぎを細かく裂いて、炒めた。", "explanation": "ここは〈刻む〉（細かく切る）の意味。玉ねぎは裂くのではなく刻むものなので、この言い方は合わない。"}, {"text": "卵を裂いてフライパンに入れた。", "explanation": "ここは〈卵を割る〉の〈割る〉の意味。卵は裂くものではないので、この言い方は合わない。"}, {"text": "鉛筆を裂いて細くした。", "explanation": "ここは〈鉛筆を削る〉の〈削る〉の意味。鉛筆は裂けないので、この言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38725, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裂いた", "is_correct": true, "explanation": "「雷が大木を裂いた」の過去形。雷が木を縦に割るような裂く動作として自然。"}, {"text": "揚げた", "is_correct": false, "explanation": "雷が大木を揚げることはなく、「ので、村の人は驚いた」とも意味が続かない。"}, {"text": "蒸した", "is_correct": false, "explanation": "大木を蒸すことは、雷の出来事として意味が通らない。"}, {"text": "茹でた", "is_correct": false, "explanation": "大木を茹でるとは言わず、雷の文脈と合わない。"}], "explanations": {"裂いた": "「雷が大木を裂いた」の過去形。雷が木を縦に割るような裂く動作として自然。", "揚げた": "雷が大木を揚げることはなく、「ので、村の人は驚いた」とも意味が続かない。", "蒸した": "大木を蒸すことは、雷の出来事として意味が通らない。", "茹でた": "大木を茹でるとは言わず、雷の文脈と合わない。"}, "sentence_index": 6, "correct_answer": "裂いた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汚れた雑巾をよく裂いてから、干した。", "explanation": "ここは〈絞る〉（水を押し出す）の意味。雑巾は裂くのではなく絞るものなので、この言い方は合わない。"}, {"text": "空き缶を裂いて、ごみ箱に入れた。", "explanation": "ここは〈潰す〉の意味。缶は裂けないので、裂くとは言わない。"}, {"text": "鍋に入れて、ゼラチンを裂いた。", "explanation": "ここは〈溶かす〉の意味。ゼラチンは裂くものではないので、この言い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38725, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "竹を縦に裂くて、ざるを編みます。", "corrected_sentence": "竹を縦に裂いて、ざるを編みます。", "error_description": "「裂く」のて形は「裂いて」。「裂くて」は誤った活用形なので、正しくは「裂いて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "裂いて", "is_correct": true, "explanation": "て形。「鶏肉を細く裂いて、サラダにのせた」と続けるための形。"}, {"text": "裂けば", "is_correct": false, "explanation": "仮定形。「もし〜なら」の意味になり、文の流れと合わない。"}, {"text": "裂こう", "is_correct": false, "explanation": "意志形。自分の意思を表すので、過去の動作を述べる文と合わない。"}, {"text": "裂く", "is_correct": false, "explanation": "終止形。「鶏肉を手で細く裂く、サラダにのせた」と文を切らずに続けることはできず、この位置には入らない。"}], "correct_form": "裂いて", "base_form": "裂く", "form_label": "て形", "sentence_index": 1, "explanations": {"裂いて": "て形。「鶏肉を細く裂いて、サラダにのせた」と続けるための形。", "裂けば": "仮定形。「もし〜なら」の意味になり、文の流れと合わない。", "裂こう": "意志形。自分の意思を表すので、過去の動作を述べる文と合わない。", "裂く": "終止形。「鶏肉を手で細く裂く、サラダにのせた」と文を切らずに続けることはできず、この位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38725, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鮭の身に裂いて、おにぎりの具にします。", "corrected_sentence": "鮭の身を裂いて、おにぎりの具にします。", "error_description": "「裂く」が対象を取るときは「を」を使う。「に」は誤りで、正しくは「身を裂いて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "裂く", "is_correct": true, "explanation": "終止形。「裂くと」の形で、条件を表す文に使われている。"}, {"text": "裂き", "is_correct": false, "explanation": "連用形。「裂くと」の「と」に続く形としては使えない。"}, {"text": "裂いた", "is_correct": false, "explanation": "過去形。「裂くと、ほぐれる」の一般的な性質を述べる文とは合わない。"}, {"text": "裂かれた", "is_correct": false, "explanation": "受身の過去形。「裂かれる」は受け身で、手で裂く動作を表す文と合わない。"}], "correct_form": "裂く", "base_form": "裂く", "form_label": "終止形", "sentence_index": 7, "explanations": {"裂く": "終止形。「裂くと」の形で、条件を表す文に使われている。", "裂き": "連用形。「裂くと」の「と」に続く形としては使えない。", "裂いた": "過去形。「裂くと、ほぐれる」の一般的な性質を述べる文とは合わない。", "裂かれた": "受身の過去形。「裂かれる」は受け身で、手で裂く動作を表す文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38726, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『足りなくなる』の主語は〈栄養〉なので〈が〉が入る。"}, {"text": "を", "is_correct": false, "explanation": "『足りなくなる』は目的語を取らない動きなので〈を〉は入らない。"}, {"text": "に", "is_correct": false, "explanation": "〈栄養に足りなくなる〉とは言わないので〈に〉は不自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の〈で〉は『足りなくなる』とつながらない。"}], "correct_answer": "が", "explanations": {"が": "『足りなくなる』の主語は〈栄養〉なので〈が〉が入る。", "を": "『足りなくなる』は目的語を取らない動きなので〈を〉は入らない。", "に": "〈栄養に足りなくなる〉とは言わないので〈に〉は不自然。", "で": "場所や手段の〈で〉は『足りなくなる』とつながらない。"}, "error_tags": {"を": "目的語を示す", "に": "方向・対象を示す", "で": "場所・手段を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38726, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『考える』の対象を示す〈を〉。〈栄養を考える〉で自然。"}, {"text": "が", "is_correct": false, "explanation": "『考える』は主語ではなく対象を取るので〈が〉は合わない。"}, {"text": "に", "is_correct": false, "explanation": "〈栄養に考えて〉とは言わないので〈に〉は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段の〈で〉では『考えて作る』とつながらない。"}], "correct_answer": "を", "explanations": {"を": "『考える』の対象を示す〈を〉。〈栄養を考える〉で自然。", "が": "『考える』は主語ではなく対象を取るので〈が〉は合わない。", "に": "〈栄養に考えて〉とは言わないので〈に〉は不自然。", "で": "手段の〈で〉では『考えて作る』とつながらない。"}, "error_tags": {"が": "主語を示す", "に": "方向・対象を示す", "で": "手段・場所を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38726, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "からだを つくる ちからに なる もの。", "primary_collocate": null, "pronunciation": "えいよう", "ipa": "eːjoː", "syllable_count": 4, "sentences": [{"text": "野菜には体に必要な栄養がたくさん入っている。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "野菜[やさい]には体[からだ]に必要[ひつよう]な栄養[えいよう]がたくさん入[はい]っている。", "sentence_source": "generated"}, {"text": "朝ごはんを食べないと、栄養が足りなくなる。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんを食[た]べないと、栄養[えいよう]が足[た]りなくなる。", "sentence_source": "generated"}, {"text": "赤ちゃんはミルクから栄養をとって大きくなる。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんはミルクから栄養[えいよう]をとって大[おお]きくなる。", "sentence_source": "generated"}, {"text": "この料理は栄養のバランスがよく、子どもにも安心だ。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "この料理[りょうり]は栄養[えいよう]のバランスがよく、子[こ]どもにも安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "病気のときは、栄養のあるものを食べて早く休もう。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "病気[びょうき]のときは、栄養[えいよう]のあるものを食[た]べて早[はや]く休[やす]もう。", "sentence_source": "generated"}, {"text": "植物は土から水と栄養を吸い上げて育つ。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は土[つち]から水[みず]と栄養[えいよう]を吸[す]い上[あ]げて育[そだ]つ。", "sentence_source": "generated"}, {"text": "ジュースばかり飲んでいると、栄養が偏ってしまう。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "ジュースばかり飲[の]んでいると、栄養[えいよう]が偏[かたよ]ってしまう。", "sentence_source": "generated"}, {"text": "給食は栄養を考えて作られているので、残さず食べなさい。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "給食[きゅうしょく]は栄養[えいよう]を考[かんが]えて作[つく]られているので、残[のこ]さず食[た]べなさい。", "sentence_source": "generated"}, {"text": "納豆は栄養が豊富なので、毎日の食事に取り入れている。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "納豆[なっとう]は栄養[えいよう]が豊富[ほうふ]なので、毎日[まいにち]の食事[しょくじ]に取[と]り入[い]れている。", "sentence_source": "generated"}, {"text": "栄養をとっても、運動をしなければ体は強くならない。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "栄養[えいよう]をとっても、運動[うんどう]をしなければ体[からだ]は強[つよ]くならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "栄養", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "nutrition: the substances in food that build and sustain the body", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cb9108-8bde-4618-9c38-fbf83d7a73e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38726, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "栄養", "is_correct": true, "explanation": "体に必要な物質を指す〈栄養〉。野菜に入っているものとして自然に入る。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠ること。野菜の中に入っている物ではないので合わない。"}, {"text": "運動", "is_correct": false, "explanation": "体を動かすこと。食品の中に入っているものではないので『入っている』と合わない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたいと感じる気持ち。野菜の中に入っている物ではないので合わない。"}], "explanations": {"栄養": "体に必要な物質を指す〈栄養〉。野菜に入っているものとして自然に入る。", "睡眠": "眠ること。野菜の中に入っている物ではないので合わない。", "運動": "体を動かすこと。食品の中に入っているものではないので『入っている』と合わない。", "食欲": "食べたいと感じる気持ち。野菜の中に入っている物ではないので合わない。"}, "sentence_index": 0, "correct_answer": "栄養"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の話には栄養がこもっていて、聞く人の心を動かした。", "explanation": "ここは〈熱意〉の意味。〈こもる〉と結びつくのは熱意で、栄養は食べ物や体に取り込む成分を指すので合わない。"}, {"text": "あの職人は栄養が豊富で、どんな仕事も任せられる。", "explanation": "ここは〈経験〉の意味。〈豊富〉と言えるのは人の経験で、栄養は食品に含まれる成分なので合わない。"}, {"text": "授業中、急に栄養が襲ってきて、あくびが止まらなかった。", "explanation": "ここは〈眠気〉の意味。〈襲う〉のは眠気で、栄養は体に襲ってくるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38726, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "栄養", "is_correct": true, "explanation": "〈偏る〉に合うのは〈栄養〉。ジュースばかりだと栄養の種類が片寄る。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度のこと。『偏る』とは結びつかないので合わない。"}, {"text": "体力", "is_correct": false, "explanation": "体を動かす力のこと。『偏ってしまう』とは言わないので合わない。"}, {"text": "顔色", "is_correct": false, "explanation": "肌の血色のこと。『偏る』と結びつかないので合わない。"}], "explanations": {"栄養": "〈偏る〉に合うのは〈栄養〉。ジュースばかりだと栄養の種類が片寄る。", "体温": "体の温度のこと。『偏る』とは結びつかないので合わない。", "体力": "体を動かす力のこと。『偏ってしまう』とは言わないので合わない。", "顔色": "肌の血色のこと。『偏る』と結びつかないので合わない。"}, "sentence_index": 6, "correct_answer": "栄養"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店員は客の一人ひとりに栄養を払った。", "explanation": "ここは〈注意〉の意味。〈払う〉と結びつくのは注意で、栄養は食べ物の成分なので合わない。"}, {"text": "先生の説明に、私は栄養を抱いた。", "explanation": "ここは〈疑い〉の意味。〈抱く〉対象は疑いで、栄養は食べ物の成分なので合わない。"}, {"text": "彼は長年の栄養を晴らした。", "explanation": "ここは〈恨み〉の意味。〈晴らす〉のは恨みで、栄養は体に取り込む成分を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38726, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この魚は栄養を豊富だ。", "corrected_sentence": "この魚は栄養が豊富だ。", "error_description": "誤: 〈栄養〉に〈を〉を付けている。〈Nが豊富だ〉の形なので、正しくは〈が〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38726, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎日同じ店で弁当を買うと、栄養を偏りやすい。", "corrected_sentence": "毎日同じ店で弁当を買うと、栄養が偏りやすい。", "error_description": "誤: 〈偏る〉は〈Nが偏る〉の形で、主語の〈栄養〉には〈を〉ではなく〈が〉を付ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
