INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38728, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "何かをするために、それが足りないと思うこと。", "primary_collocate": null, "pronunciation": "いる", "ipa": "iɾɯ", "syllable_count": 2, "sentences": [{"text": "海外へ行くには、パスポートが要る。", "target_word": "要る", "complexity_tier": "T3", "furigana": "海外[かいがい]へ行[い]くには、パスポートが要[い]る。", "sentence_source": "generated"}, {"text": "この仕事を終わらせるには、あと三日要る。", "target_word": "要る", "complexity_tier": "T3", "furigana": "この仕事[しごと]を終[お]わらせるには、あと三日[みっか]要[い]る。", "sentence_source": "generated"}, {"text": "家を建てるには、たくさんのお金が要る。", "target_word": "要る", "complexity_tier": "T3", "furigana": "家[いえ]を建[た]てるには、たくさんのお金[かね]が要[い]る。", "sentence_source": "generated"}, {"text": "試験に合格するには、毎日の勉強が要る。", "target_word": "要る", "complexity_tier": "T3", "furigana": "試験[しけん]に合格[ごうかく]するには、毎日[まいにち]の勉強[べんきょう]が要[い]る。", "sentence_source": "generated"}, {"text": "引っ越しをするので、段ボールがもっと要ります。", "target_word": "要ります", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しをするので、段[だん]ボールがもっと要[い]ります。", "sentence_source": "generated"}, {"text": "このケーキを作るには、卵が三つ要る。", "target_word": "要る", "complexity_tier": "T3", "furigana": "このケーキを作[つく]るには、卵[たまご]が三[みっ]つ要[い]る。", "sentence_source": "generated"}, {"text": "山に登るには、丈夫な靴が要ります。", "target_word": "要ります", "complexity_tier": "T3", "furigana": "山[やま]に登[のぼ]るには、丈夫[じょうぶ]な靴[くつ]が要[い]ります。", "sentence_source": "generated"}, {"text": "絵を完成させるには、まだ時間が要ると思う。", "target_word": "要る", "complexity_tier": "T3", "furigana": "絵[え]を完成[かんせい]させるには、まだ時間[じかん]が要[い]ると思[おも]う。", "sentence_source": "generated"}, {"text": "図書館で本を借りるには、カードが要る。", "target_word": "要る", "complexity_tier": "T3", "furigana": "図書館[としょかん]で本[ほん]を借[か]りるには、カードが要[い]る。", "sentence_source": "generated"}, {"text": "荷物を運ぶために、もう一人手伝いが要った。", "target_word": "要った", "complexity_tier": "T3", "furigana": "荷物[にもつ]を運[はこ]ぶために、もう一人[ひとり]手伝[てつだ]いが要[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "要らない", "label": "未然形"}, {"form": "要り", "label": "連用形"}, {"form": "要る", "label": "終止形"}, {"form": "要れば", "label": "仮定形"}, {"form": "要った", "label": "過去形"}, {"form": "要って", "label": "て形"}], "register": "neutral", "sense_fingerprint": "be needed in order to do something: money, time or documents required for a goal", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cb9108-8bde-4618-9c38-fbf83d7a73e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38728, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要る", "is_correct": true, "explanation": "『〜には〜が要る』で必要を表す〈要る〉。ここに入って自然。"}, {"text": "見る", "is_correct": false, "explanation": "『パスポートが見る』は意味をなさないので合わない。"}, {"text": "登る", "is_correct": false, "explanation": "山などに上ることを表すので、パスポートとは結びつかない。"}, {"text": "売る", "is_correct": false, "explanation": "商品を渡すことを表すので、必要を表す文には合わない。"}], "explanations": {"要る": "『〜には〜が要る』で必要を表す〈要る〉。ここに入って自然。", "見る": "『パスポートが見る』は意味をなさないので合わない。", "登る": "山などに上ることを表すので、パスポートとは結びつかない。", "売る": "商品を渡すことを表すので、必要を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "要る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍋でごまを要って、香りを立たせた。", "explanation": "ここは〈煎る〉（火で乾かし焼く）の意味。〈要る〉は必要の意味なので、調理の動作には合わない。"}, {"text": "選手は弓で的を要った。", "explanation": "ここは〈射る〉（矢を放つ）の意味。〈要る〉は必要の意味で、矢を放つ場面には合わない。"}, {"text": "フライパンで卵を要った。", "explanation": "ここは〈炒る〉（火で炒める）の意味。〈要る〉は必要の意味なので、料理の動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38728, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要ります", "is_correct": true, "explanation": "『〜には〜が要ります』で必要を表す。山に登るための靴として自然。"}, {"text": "見ます", "is_correct": false, "explanation": "『靴が見ます』では意味が通らないので、この文に合わない。"}, {"text": "聞きます", "is_correct": false, "explanation": "『靴が聞きます』では意味が通らないので、この文に合わない。"}, {"text": "登ります", "is_correct": false, "explanation": "『靴が登ります』では意味が通らない。山に登る動作は靴の動きではない。"}], "explanations": {"要ります": "『〜には〜が要ります』で必要を表す。山に登るための靴として自然。", "見ます": "『靴が見ます』では意味が通らないので、この文に合わない。", "聞きます": "『靴が聞きます』では意味が通らないので、この文に合わない。", "登ります": "『靴が登ります』では意味が通らない。山に登る動作は靴の動きではない。"}, "sentence_index": 6, "correct_answer": "要ります"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鍋で大豆を要った。", "explanation": "ここは〈煎る〉（火で乾かし焼く）の意味。〈要った〉は必要の意味なので、調理の動作には合わない。"}, {"text": "職人は溶かした金属を要って、新しい鈴を作った。", "explanation": "ここは〈鋳る〉（溶かした金属を型に流す）の意味。〈要って〉は必要の意味で、金属加工の動作には合わない。"}, {"text": "森に一頭の鹿が要った。", "explanation": "ここは〈居る〉（そこに存在する）の意味。〈要る〉は必要を表すので、鹿がいたことは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38728, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会議には資料を要ります。", "corrected_sentence": "この会議には資料が要ります。", "error_description": "誤: 〈要る〉は必要なものを主語に取るので、〈資料〉には〈を〉ではなく〈が〉を付ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "要る", "is_correct": true, "explanation": "文末の終止形。『あと三日要る』と言い切る形で、この文に合う。"}, {"text": "要れば", "is_correct": false, "explanation": "仮定形で、条件を表す形。文末を言い切れないので合わない。"}, {"text": "要って", "is_correct": false, "explanation": "て形で、後ろに続く言葉が必要。文を言い切れないので合わない。"}, {"text": "要らない", "is_correct": false, "explanation": "否定形で『必要ない』の意味になり、三日必要だという文脈に反する。"}], "correct_form": "要る", "base_form": "要る", "form_label": "終止形", "sentence_index": 1, "explanations": {"要る": "文末の終止形。『あと三日要る』と言い切る形で、この文に合う。", "要れば": "仮定形で、条件を表す形。文末を言い切れないので合わない。", "要って": "て形で、後ろに続く言葉が必要。文を言い切れないので合わない。", "要らない": "否定形で『必要ない』の意味になり、三日必要だという文脈に反する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38728, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日の遠足には、お弁当を要ります。", "corrected_sentence": "明日の遠足には、お弁当が要ります。", "error_description": "誤: 〈要ります〉の主語〈お弁当〉には〈を〉ではなく〈が〉を付ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "要る", "is_correct": true, "explanation": "終止形。『〜と思う』の前で言い切る普通体の形で、この文に合う。"}, {"text": "要った", "is_correct": false, "explanation": "過去形で、これから必要だという文脈に合わない。"}, {"text": "要り", "is_correct": false, "explanation": "連用形。後ろに続く言葉が必要で、『と思う』へ続けても文を言い切れないので合わない。"}, {"text": "要ります", "is_correct": false, "explanation": "丁寧形。普通体の『要ると思う』の文とは文体が合わないので合わない。"}], "correct_form": "要る", "base_form": "要る", "form_label": "終止形", "sentence_index": 7, "explanations": {"要る": "終止形。『〜と思う』の前で言い切る普通体の形で、この文に合う。", "要った": "過去形で、これから必要だという文脈に合わない。", "要り": "連用形。後ろに続く言葉が必要で、『と思う』へ続けても文を言い切れないので合わない。", "要ります": "丁寧形。普通体の『要ると思う』の文とは文体が合わないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
