INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38729, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "必要である。なくてはならない。必要なものとして存在する。", "primary_collocate": null, "pronunciation": "いる", "ipa": "iɾɯ", "syllable_count": 2, "sentences": [{"text": "傘は要らないよ。もう雨はやんだから。", "target_word": "要らない", "complexity_tier": "T3", "furigana": "傘[かさ]は要[い]らないよ。もう雨[あめ]はやんだから。", "sentence_source": "generated"}, {"text": "今日の会議に資料は要りません。", "target_word": "要りません", "complexity_tier": "T3", "furigana": "今日[きょう]の会議[かいぎ]に資料[しりょう]は要[い]りません。", "sentence_source": "generated"}, {"text": "友達に話すのに、遠慮は要らない。", "target_word": "要らない", "complexity_tier": "T3", "furigana": "友達[ともだち]に話[はな]すのに、遠慮[えんりょ]は要[い]らない。", "sentence_source": "generated"}, {"text": "心配は要らない。医者が大丈夫だと言った。", "target_word": "要らない", "complexity_tier": "T3", "furigana": "心配[しんぱい]は要[い]らない。医者[いしゃ]が大丈夫[だいじょうぶ]だと言[い]った。", "sentence_source": "generated"}, {"text": "この部屋の鍵は、もう要らなくなった。", "target_word": "要らなく", "complexity_tier": "T3", "furigana": "この部屋[へや]の鍵[かぎ]は、もう要[い]らなくなった。", "sentence_source": "generated"}, {"text": "入場に予約が要る店なので、電話をかけた。", "target_word": "要る", "complexity_tier": "T3", "furigana": "入場[にゅうじょう]に予約[よやく]が要[い]る店[みせ]なので、電話[でんわ]をかけた。", "sentence_source": "generated"}, {"text": "彼は説明が要らないほど、よく知っている人だ。", "target_word": "要らない", "complexity_tier": "T3", "furigana": "彼[かれ]は説明[せつめい]が要[い]らないほど、よく知[し]っている人[ひと]だ。", "sentence_source": "generated"}, {"text": "荷物が多いので、大きいかばんが要る。", "target_word": "要る", "complexity_tier": "T3", "furigana": "荷物[にもつ]が多[おお]いので、大[おお]きいかばんが要[い]る。", "sentence_source": "generated"}, {"text": "子どもには、愛情と時間が要る。", "target_word": "要る", "complexity_tier": "T3", "furigana": "子[こ]どもには、愛情[あいじょう]と時間[じかん]が要[い]る。", "sentence_source": "generated"}, {"text": "お土産は要りませんので、気を使わないでください。", "target_word": "要りません", "complexity_tier": "T3", "furigana": "お土産[みやげ]は要[い]りませんので、気[き]を使[つか]わないでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "要らない", "label": "未然形"}, {"form": "要り", "label": "連用形"}, {"form": "要る", "label": "終止形"}, {"form": "要れば", "label": "仮定形"}, {"form": "要った", "label": "過去形"}, {"form": "要って", "label": "て形"}], "register": "neutral", "sense_fingerprint": "be necessary or indispensable as a state; often negated to say something is not needed", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cb9108-8bde-4618-9c38-fbf83d7a73e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38729, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要らない", "is_correct": true, "explanation": "『傘は要らない』で必要ないことを表す。雨がやんだ文脈に合う。"}, {"text": "見る", "is_correct": false, "explanation": "『傘は見るよ』では意味が通らないので合わない。"}, {"text": "聞く", "is_correct": false, "explanation": "『傘は聞くよ』では意味が通らないので合わない。"}, {"text": "登る", "is_correct": false, "explanation": "『傘は登るよ』では意味が通らないので合わない。"}], "explanations": {"要らない": "『傘は要らない』で必要ないことを表す。雨がやんだ文脈に合う。", "見る": "『傘は見るよ』では意味が通らないので合わない。", "聞く": "『傘は聞くよ』では意味が通らないので合わない。", "登る": "『傘は登るよ』では意味が通らないので合わない。"}, "sentence_index": 0, "correct_answer": "要らない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍋で豆を要って香ばしくした。", "explanation": "ここは〈煎る〉（火で乾かし焼く）の意味。〈要る〉は必要の意味なので、豆を火にかける動作には合わない。"}, {"text": "選手は弓で的を要ったが、一本も当たらなかった。", "explanation": "ここは〈射る〉（的に矢を放つ）の意味。〈要った〉は必要の意味なので、弓で矢を放つ場面には合わない。"}, {"text": "職人は溶けた鉛を要って、型に流し込んだ。", "explanation": "ここは〈鋳る〉（溶かした金属を型に流す）の意味。〈要って〉は必要の意味なので、金属を型に流す動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38729, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要らない", "is_correct": true, "explanation": "『説明が要らないほど』で、説明が不要なほど知っている、の意味に合う。"}, {"text": "見ない", "is_correct": false, "explanation": "『説明が見ないほど』では意味が通らないので合わない。"}, {"text": "聞かない", "is_correct": false, "explanation": "『説明を聞かない』とは違い、『説明が聞かないほど』では意味が通らないので合わない。"}, {"text": "登らない", "is_correct": false, "explanation": "『説明が登らないほど』では意味が通らないので合わない。"}], "explanations": {"要らない": "『説明が要らないほど』で、説明が不要なほど知っている、の意味に合う。", "見ない": "『説明が見ないほど』では意味が通らないので合わない。", "聞かない": "『説明を聞かない』とは違い、『説明が聞かないほど』では意味が通らないので合わない。", "登らない": "『説明が登らないほど』では意味が通らないので合わない。"}, "sentence_index": 6, "correct_answer": "要らない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鍋で大豆を要ってから、香ばしい匂いを楽しんだ。", "explanation": "ここは〈煎る〉（火で乾かし焼く）の意味。〈要る〉は必要の意味なので、大豆を鍋で火にかける動作には合わない。"}, {"text": "フライパンで卵を要ってかき混ぜた。", "explanation": "ここは〈炒る〉（火にかけて炒める）の意味。〈要る〉は必要の意味なので、卵を炒める動作には合わない。"}, {"text": "職人は溶けた銅を要って、新しい鈴の型に流した。", "explanation": "ここは〈鋳る〉（溶かした金属を型に流して作る）の意味。〈要る〉は必要の意味なので、金属を型に流す動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38729, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日の旅行に、雨具を要りません。", "corrected_sentence": "明日の旅行に、雨具は要りません。", "error_description": "誤: 〈要りません〉に付く助詞は〈を〉ではなく〈は〉。〈雨具は要りません〉の形にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "要りません", "is_correct": true, "explanation": "丁寧形で、この丁寧な会議の文に合う。"}, {"text": "要らなく", "is_correct": false, "explanation": "連用形のままでは文を言い切れず、文末には使えない。"}, {"text": "要った", "is_correct": false, "explanation": "過去形で、今の必要を話す文脈に合わない。"}, {"text": "要れば", "is_correct": false, "explanation": "仮定形で、文末を言い切れないので合わない。"}], "correct_form": "要りません", "base_form": "要る", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"要りません": "丁寧形で、この丁寧な会議の文に合う。", "要らなく": "連用形のままでは文を言い切れず、文末には使えない。", "要った": "過去形で、今の必要を話す文脈に合わない。", "要れば": "仮定形で、文末を言い切れないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38729, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国内の旅行なら、パスポートは要らないません。", "corrected_sentence": "国内の旅行なら、パスポートは要りません。", "error_description": "誤: 〈要らない〉に丁寧形の〈ません〉を続けている。否定の丁寧形は〈要りません〉。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "要る", "is_correct": true, "explanation": "連体形。『大きいかばんが要る』と名詞を修飾しないで言い切る形で、この文に合う。"}, {"text": "要って", "is_correct": false, "explanation": "て形。文末を言い切れず、ここでは文末の言い切りが必要なので合わない。"}, {"text": "要り", "is_correct": false, "explanation": "連用形。後ろに続く言葉が必要で、文末の言い切りとして使えないので合わない。"}, {"text": "要らなく", "is_correct": false, "explanation": "連用形のままでは文を言い切れず、文末には使えない。"}], "correct_form": "要る", "base_form": "要る", "form_label": "終止形", "sentence_index": 7, "explanations": {"要る": "連体形。『大きいかばんが要る』と名詞を修飾しないで言い切る形で、この文に合う。", "要って": "て形。文末を言い切れず、ここでは文末の言い切りが必要なので合わない。", "要り": "連用形。後ろに続く言葉が必要で、文末の言い切りとして使えないので合わない。", "要らなく": "連用形のままでは文を言い切れず、文末には使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f431a8d-5c0f-460e-bd75-8fe2871ef561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38732, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「辺の長さ」と所有の「の」でつなぐのが自然"}, {"text": "を", "is_correct": false, "explanation": "「辺を長さが同じ」では文が成り立たない"}, {"text": "に", "is_correct": false, "explanation": "「辺に長さが同じ」は位置を示すので、長さの説明に合わない"}, {"text": "で", "is_correct": false, "explanation": "「辺で長さが同じ」は手段・場所を表し、文の意味が通らない"}], "correct_answer": "の", "explanations": {"の": "「辺の長さ」と所有の「の」でつなぐのが自然", "を": "「辺を長さが同じ」では文が成り立たない", "に": "「辺に長さが同じ」は位置を示すので、長さの説明に合わない", "で": "「辺で長さが同じ」は手段・場所を表し、文の意味が通らない"}, "error_tags": {"を": "目的語の誤用", "に": "位置・帰着", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38732, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「長い辺に赤い線を引く」と、線を引く位置・対象を示す「に」が自然"}, {"text": "が", "is_correct": false, "explanation": "「辺が赤い線を引く」では辺が動作の主体になり、意味が通らない"}, {"text": "と", "is_correct": false, "explanation": "「辺と赤い線を引く」は並べる意味になり、文が合わない"}, {"text": "を", "is_correct": false, "explanation": "「辺を赤い線を引きました」と目的語が二つ重なり、文が成り立たない"}], "correct_answer": "に", "explanations": {"に": "「長い辺に赤い線を引く」と、線を引く位置・対象を示す「に」が自然", "が": "「辺が赤い線を引く」では辺が動作の主体になり、意味が通らない", "と": "「辺と赤い線を引く」は並べる意味になり、文が合わない", "を": "「辺を赤い線を引きました」と目的語が二つ重なり、文が成り立たない"}, "error_tags": {"が": "主語（動作主）", "と": "並列・相手", "を": "目的語の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38732, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「辺」は、三角形や四角形などの図形を囲む、一本ずつの線の部分のことです。", "primary_collocate": null, "pronunciation": "へん", "ipa": "heɴ", "syllable_count": 2, "sentences": [{"text": "三角形の三つの辺の長さを、定規ではかりました。", "target_word": "辺", "complexity_tier": "T3", "furigana": "三角形[さんかくけい]の三[みっ]つの辺[へん]の長[なが]さを、定規[じょうぎ]ではかりました。", "sentence_source": "generated"}, {"text": "長方形は、向かい合う辺の長さが同じです。", "target_word": "辺", "complexity_tier": "T3", "furigana": "長方形[ちょうほうけい]は、向[む]かい合[あ]う辺[へん]の長[なが]さが同[おな]じです。", "sentence_source": "generated"}, {"text": "この四角形は、辺の長さがすべて五センチです。", "target_word": "辺", "complexity_tier": "T3", "furigana": "この四角形[しかくけい]は、辺[へん]の長[なが]さがすべて五[ご]センチです。", "sentence_source": "generated"}, {"text": "短い辺を下にして、紙を机に置いてください。", "target_word": "辺", "complexity_tier": "T3", "furigana": "短[みじか]い辺[へん]を下[した]にして、紙[かみ]を机[つくえ]に置[お]いてください。", "sentence_source": "generated"}, {"text": "正方形の一つの辺が三センチなら、まわりは十二センチです。", "target_word": "辺", "complexity_tier": "T3", "furigana": "正方形[せいほうけい]の一[ひと]つの辺[へん]が三[さん]センチなら、まわりは十二[じゅうに]センチです。", "sentence_source": "generated"}, {"text": "辺の長さが三つとも同じ三角形は、正三角形です。", "target_word": "辺", "complexity_tier": "T3", "furigana": "辺[へん]の長[なが]さが三[みっ]つとも同[おな]じ三角形[さんかくけい]は、正三角形[せいさんかくけい]です。", "sentence_source": "generated"}, {"text": "長い辺は十センチで、短い辺は六センチです。", "target_word": "辺", "complexity_tier": "T3", "furigana": "長[なが]い辺[へん]は十[じゅっ]センチで、短[みじか]い辺[へん]は六[ろく]センチです。", "sentence_source": "generated"}, {"text": "図の中で、いちばん長い辺に赤い線を引きました。", "target_word": "辺", "complexity_tier": "T3", "furigana": "図[ず]の中[なか]で、いちばん長[なが]い辺[へん]に赤[あか]い線[せん]を引[ひ]きました。", "sentence_source": "generated"}, {"text": "この図形は辺が五つあるので、五角形です。", "target_word": "辺", "complexity_tier": "T3", "furigana": "この図形[ずけい]は辺[へん]が五[いつ]つあるので、五角形[ごかっけい]です。", "sentence_source": "generated"}, {"text": "紙を折って、辺と辺をぴったり合わせました。", "target_word": "辺", "complexity_tier": "T3", "furigana": "紙[かみ]を折[お]って、辺[へん]と辺[へん]をぴったり合[あ]わせました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "辺", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "図形の辺：三角形や四角形などを囲む、一本ずつの線の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 正三角形 (Zipf 2.03)','sentence 8 above tier T2: contains vocabulary far above tier T2: 五角形 (Zipf 2.31)']::text[], '1482d3a5-b226-445e-b588-4975f8b011fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38732, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辺", "is_correct": true, "explanation": "図形を囲む一本ずつの線の部分。三角形の辺の長さをはかる文に合う"}, {"text": "角", "is_correct": false, "explanation": "頂点で開いた部分。長さではなく角度で表すので、長さの話には合わない"}, {"text": "面", "is_correct": false, "explanation": "平らな広がりを指し、線の長さをはかる対象にはならない"}, {"text": "頂点", "is_correct": false, "explanation": "点を指す語で、長さをはかる対象にはならない"}], "explanations": {"辺": "図形を囲む一本ずつの線の部分。三角形の辺の長さをはかる文に合う", "角": "頂点で開いた部分。長さではなく角度で表すので、長さの話には合わない", "面": "平らな広がりを指し、線の長さをはかる対象にはならない", "頂点": "点を指す語で、長さをはかる対象にはならない"}, "sentence_index": 0, "correct_answer": "辺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コップの辺に口をつけました。", "explanation": "ここは〈縁（ふち）〉の意味。コップや丸い器のふちは縁と言い、直線で囲まれた図形の辺とは言わないので合わない"}, {"text": "紙に辺を引きました。", "explanation": "ここは〈線〉の意味。自由に引く線は線と言い、辺は図形の囲みを作る一本の線を指すので合わない"}, {"text": "この三角形は、辺が一つ直角になっています。", "explanation": "ここは〈角〉の意味。直角は角の大きさについて言うので、線である辺には使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38732, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辺", "is_correct": true, "explanation": "図形の線の部分で、センチの長さで表せる"}, {"text": "角度", "is_correct": false, "explanation": "角の開き具合を表し、センチで測る長さとは言わない"}, {"text": "面積", "is_correct": false, "explanation": "平面の広さを表し、長さの単位では表さない"}, {"text": "体積", "is_correct": false, "explanation": "立体の大きさで、十センチという長さには合わない"}], "explanations": {"辺": "図形の線の部分で、センチの長さで表せる", "角度": "角の開き具合を表し、センチで測る長さとは言わない", "面積": "平面の広さを表し、長さの単位では表さない", "体積": "立体の大きさで、十センチという長さには合わない"}, "sentence_index": 6, "correct_answer": "辺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "正方形を辺で二つの三角形に分けました。", "explanation": "ここは〈対角線〉の意味。図形を二つに分けるのは対角線で、図形のふちである辺では分けられない"}, {"text": "この箱は、どの辺も正方形です。", "explanation": "ここは〈面〉の意味。正方形は平らな面の形で、線である辺には使わない"}, {"text": "定規に辺を書きました。", "explanation": "ここは〈目盛り〉の意味。辺は図形の一本の線を指し、定規の細かい刻み（目盛り）を指すことはないので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38732, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この長方形の辺に長さが四センチです。", "corrected_sentence": "この長方形の辺の長さが四センチです。", "error_description": "助詞の誤り。「辺の長さ」と「の」で結ぶべきところを「辺に長さ」と「に」にしている。「の」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38732, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この立方体は辺が十二つあります。", "corrected_sentence": "この立方体は辺が十二本あります。", "error_description": "数え方の誤り。辺は細長いものとして「本」で数える。「つ」は主に十までの数に使うので、十二には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
