INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38733, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「辺」は、ある場所や区域の周囲、またはその付近を指します。", "primary_collocate": null, "pronunciation": "へん", "ipa": "heɴ", "syllable_count": 2, "sentences": [{"text": "この辺に、安いレストランはありますか。", "target_word": "辺", "complexity_tier": "T3", "furigana": "この辺[へん]に、安[やす]いレストランはありますか。", "sentence_source": "generated"}, {"text": "この辺は夜も静かで、人通りが少ないです。", "target_word": "辺", "complexity_tier": "T3", "furigana": "この辺[へん]は夜[よる]も静[しず]かで、人通[ひとどお]りが少[すく]ないです。", "sentence_source": "generated"}, {"text": "道に迷って、この辺がどこなのか分かりません。", "target_word": "辺", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]って、この辺[へん]がどこなのか分[わ]かりません。", "sentence_source": "generated"}, {"text": "公園のこの辺で財布を落としたと思います。", "target_word": "辺", "complexity_tier": "T3", "furigana": "公園[こうえん]のこの辺[へん]で財布[さいふ]を落[お]としたと思[おも]います。", "sentence_source": "generated"}, {"text": "あの辺にコンビニがあったはずですが、今はありません。", "target_word": "辺", "complexity_tier": "T3", "furigana": "あの辺[へん]にコンビニがあったはずですが、今[いま]はありません。", "sentence_source": "generated"}, {"text": "この辺は昔、田んぼばかりでした。", "target_word": "辺", "complexity_tier": "T3", "furigana": "この辺[へん]は昔[むかし]、田[た]んぼばかりでした。", "sentence_source": "generated"}, {"text": "財布をなくしたので、その辺をもう一度さがしてみてください。", "target_word": "辺", "complexity_tier": "T3", "furigana": "財布[さいふ]をなくしたので、その辺[へん]をもう一度[いちど]さがしてみてください。", "sentence_source": "generated"}, {"text": "この辺は坂が多いので、自転車で行くのは大変です。", "target_word": "辺", "complexity_tier": "T3", "furigana": "この辺[へん]は坂[さか]が多[おお]いので、自転車[じてんしゃ]で行[い]くのは大変[たいへん]です。", "sentence_source": "generated"}, {"text": "駅の南のあの辺に、新しい図書館ができました。", "target_word": "辺", "complexity_tier": "T3", "furigana": "駅[えき]の南[みなみ]のあの辺[へん]に、新[あたら]しい図書館[としょかん]ができました。", "sentence_source": "generated"}, {"text": "お住まいはどの辺ですか。", "target_word": "辺", "complexity_tier": "T2", "furigana": "お住[す]まいはどの辺[へん]ですか。", "sentence_source": "generated"}], "morphological_forms": [{"form": "辺", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "場所の付近：「この辺」「あの辺」のように、ある場所のまわりを大まかに指す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1482d3a5-b226-445e-b588-4975f8b011fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38733, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辺", "is_correct": true, "explanation": "場所の周辺を大まかに指すので、「この辺」で近くの場所を表せる"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、場所の付近は指せない"}, {"text": "理由", "is_correct": false, "explanation": "原因を表す語で、場所を示せない"}, {"text": "体重", "is_correct": false, "explanation": "人の重さを表し、場所の話には合わない"}], "explanations": {"辺": "場所の周辺を大まかに指すので、「この辺」で近くの場所を表せる", "季節": "時期を表す語で、場所の付近は指せない", "理由": "原因を表す語で、場所を示せない", "体重": "人の重さを表し、場所の話には合わない"}, "sentence_index": 0, "correct_answer": "辺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱の辺を、テープで囲みました。", "explanation": "ここは〈線の部分〉の意味。箱の角と角をつなぐ一本の線を指す辺で、場所の付近を表す辺とは違うので合わない"}, {"text": "ここから駅まで、辺は歩いて十分です。", "explanation": "ここは〈距離〉の意味。道のりは時間や距離で言うが、場所の付近を表す辺では言えない"}, {"text": "正方形の辺を、定規で測りました。", "explanation": "ここは〈線の部分〉の意味。図形を囲む一本の線の長さを測る辺で、場所の付近を表す辺とは違うので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38733, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辺", "is_correct": true, "explanation": "その周辺一帯を指すので、探す場所として合う"}, {"text": "金額", "is_correct": false, "explanation": "お金の額を表し、探す場所にはならない"}, {"text": "時刻", "is_correct": false, "explanation": "時間を表し、探す場所にはならない"}, {"text": "年齢", "is_correct": false, "explanation": "人の年数を表し、場所を探す文には合わない"}], "explanations": {"辺": "その周辺一帯を指すので、探す場所として合う", "金額": "お金の額を表し、探す場所にはならない", "時刻": "時間を表し、探す場所にはならない", "年齢": "人の年数を表し、場所を探す文には合わない"}, "sentence_index": 6, "correct_answer": "辺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "正方形の辺に、印をつけました。", "explanation": "ここは〈線の部分〉の意味。図形を囲む一本の線を指す辺で、場所の付近を表す辺とは違うので合わない"}, {"text": "ここから駅まで、歩いて十分の辺です。", "explanation": "ここは〈時間〉の意味。辺は場所の付近を指し、時間の長さを言うのには使わない"}, {"text": "お住まいの番地を、辺でぴったり書いてください。", "explanation": "ここは〈正確な住所〉の意味。辺は大まかな付近を指すので、ぴったり特定する住所の書き方とは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38733, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅の南の辺が、新しい図書館があります。", "corrected_sentence": "駅の南の辺に、新しい図書館があります。", "error_description": "存在する場所を表すときは「に」を使う。「辺が」にすると主語になってしまい、「ある」の場所が示せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38733, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その辺をお財布を落としたようです。", "corrected_sentence": "その辺でお財布を落としたようです。", "error_description": "「辺」は落とした場所を表すので「で」を使う。「を」を付けると目的語のように読まれ、場所が示せない。正しくは「その辺でお財布を落としたようです」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38734, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ごみ袋に捨てる」と、捨てる先を示す「に」が自然"}, {"text": "の", "is_correct": false, "explanation": "「ごみ袋の捨てました」では動詞につながらず、文が成り立たない"}, {"text": "と", "is_correct": false, "explanation": "「ごみ袋と捨てました」は並べる意味になり、捨てる先を示せない"}, {"text": "が", "is_correct": false, "explanation": "「ごみ袋が捨てました」では袋が主語になり、意味が逆になる"}], "correct_answer": "に", "explanations": {"に": "「ごみ袋に捨てる」と、捨てる先を示す「に」が自然", "の": "「ごみ袋の捨てました」では動詞につながらず、文が成り立たない", "と": "「ごみ袋と捨てました」は並べる意味になり、捨てる先を示せない", "が": "「ごみ袋が捨てました」では袋が主語になり、意味が逆になる"}, "error_tags": {"の": "連体・所有", "と": "並列・相手", "が": "主語"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拾う", "is_correct": true, "explanation": "「捨てる」（ごみに入れる）の反対で、物を手に取る動作"}, {"text": "探す", "is_correct": false, "explanation": "見つけようとする動作で、捨てるの対義語にはならない"}, {"text": "包む", "is_correct": false, "explanation": "物を覆う動作で、捨てる行為の反対ではない"}, {"text": "洗う", "is_correct": false, "explanation": "汚れを落とす動作で、捨てる行為の反対ではない"}], "correct_answer": "拾う", "explanations": {"拾う": "「捨てる」（ごみに入れる）の反対で、物を手に取る動作", "探す": "見つけようとする動作で、捨てるの対義語にはならない", "包む": "物を覆う動作で、捨てる行為の反対ではない", "洗う": "汚れを落とす動作で、捨てる行為の反対ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38734, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ごみ箱に捨てる」と、捨てる先を示す「に」が自然"}, {"text": "で", "is_correct": false, "explanation": "「ごみ箱で捨てました」では場所・手段が不自然で、捨てる先を示せない"}, {"text": "より", "is_correct": false, "explanation": "比較の意味になり、捨てる先を示す文の意味が通らない"}, {"text": "から", "is_correct": false, "explanation": "「ごみ箱から捨てました」は出どころを表し、捨てる先を示せない"}], "correct_answer": "に", "explanations": {"に": "「ごみ箱に捨てる」と、捨てる先を示す「に」が自然", "で": "「ごみ箱で捨てました」では場所・手段が不自然で、捨てる先を示せない", "より": "比較の意味になり、捨てる先を示す文の意味が通らない", "から": "「ごみ箱から捨てました」は出どころを表し、捨てる先を示せない"}, "error_tags": {"で": "手段・場所", "より": "比較", "から": "起点・出どころ"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拾う", "is_correct": true, "explanation": "「捨てる」（ごみに入れる）の反対で、物を手に取る動作"}, {"text": "買う", "is_correct": false, "explanation": "物を手に入れる動作だが、捨てるの対義語として辞典に載らない"}, {"text": "運ぶ", "is_correct": false, "explanation": "場所を移す動作で、捨てるの対義語ではない"}, {"text": "集める", "is_correct": false, "explanation": "まとめる動作で、捨てるの対義語としては挙がらない"}], "correct_answer": "拾う", "explanations": {"拾う": "「捨てる」（ごみに入れる）の反対で、物を手に取る動作", "買う": "物を手に入れる動作だが、捨てるの対義語として辞典に載らない", "運ぶ": "場所を移す動作で、捨てるの対義語ではない", "集める": "まとめる動作で、捨てるの対義語としては挙がらない"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38734, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いらなくなったものを、ごみばこにいれること。", "primary_collocate": null, "pronunciation": "すてる", "ipa": "sɯteɾɯ", "syllable_count": 3, "sentences": [{"text": "いらない紙は、ごみ箱に捨てます。", "target_word": "捨てます", "complexity_tier": "T3", "furigana": "いらない紙[かみ]は、ごみ箱[ばこ]に捨[す]てます。", "sentence_source": "generated"}, {"text": "昨日、古くなったパンを、ごみ袋に捨てました。", "target_word": "捨てました", "complexity_tier": "T3", "furigana": "昨日[きのう]、古[ふる]くなったパンを、ごみ袋[ぶくろ]に捨[す]てました。", "sentence_source": "generated"}, {"text": "レシートは、ごみ箱に捨ててください。", "target_word": "捨てて", "complexity_tier": "T3", "furigana": "レシートは、ごみ箱[ばこ]に捨[す]ててください。", "sentence_source": "generated"}, {"text": "使ったティッシュは、すぐにごみ箱に捨てましょう。", "target_word": "捨てましょう", "complexity_tier": "T3", "furigana": "使[つか]ったティッシュは、すぐにごみ箱[ばこ]に捨[す]てましょう。", "sentence_source": "generated"}, {"text": "台所の生ごみは、毎朝ごみ置き場に捨てています。", "target_word": "捨てています", "complexity_tier": "T3", "furigana": "台所[だいどころ]の生[なま]ごみは、毎朝[まいあさ]ごみ置[お]き場[ば]に捨[す]てています。", "sentence_source": "generated"}, {"text": "穴があいた靴下は、もう履けないので捨てました。", "target_word": "捨てました", "complexity_tier": "T3", "furigana": "穴[あな]があいた靴下[くつした]は、もう履[は]けないので捨[す]てました。", "sentence_source": "generated"}, {"text": "空き缶を捨てるときは、中を水で洗います。", "target_word": "捨てる", "complexity_tier": "T3", "furigana": "空[あ]き缶[かん]を捨[す]てるときは、中[なか]を水[みず]で洗[あら]います。", "sentence_source": "generated"}, {"text": "友だちは食べ終わったお菓子の袋を、ごみ箱に捨てました。", "target_word": "捨てました", "complexity_tier": "T3", "furigana": "友[とも]だちは食[た]べ終[お]わったお菓子[かし]の袋[ふくろ]を、ごみ箱[ばこ]に捨[す]てました。", "sentence_source": "generated"}, {"text": "割れたコップは、新聞紙に包んで捨てます。", "target_word": "捨てます", "complexity_tier": "T3", "furigana": "割[わ]れたコップは、新聞紙[しんぶんし]に包[つつ]んで捨[す]てます。", "sentence_source": "generated"}, {"text": "冷蔵庫の古い野菜は、全部ごみ箱に捨てました。", "target_word": "捨てました", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の古[ふる]い野菜[やさい]は、全部[ぜんぶ]ごみ箱[ばこ]に捨[す]てました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "捨てる", "label": "終止形・連体形"}, {"form": "捨てます", "label": "丁寧形"}, {"form": "捨てて", "label": "て形"}, {"form": "捨てた", "label": "た形"}, {"form": "捨てない", "label": "ない形"}, {"form": "捨てれば", "label": "仮定形"}, {"form": "捨てよう", "label": "意志形"}], "register": "丁寧", "sense_fingerprint": "いらなくなった物をごみ箱やごみ袋に入れて処分する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1482d3a5-b226-445e-b588-4975f8b011fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38734, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捨てます", "is_correct": true, "explanation": "ごみ箱に入れて処分する動詞の丁寧形。文末を丁寧に言い切れる"}, {"text": "洗います", "is_correct": false, "explanation": "水で汚れを落とす動作で、ごみ箱に入れる意味に合わない"}, {"text": "探します", "is_correct": false, "explanation": "見つけようとする動作で、物を処分する文には合わない"}, {"text": "包みます", "is_correct": false, "explanation": "物を覆う動作で、ごみ箱に入れる意味とは合わない"}], "explanations": {"捨てます": "ごみ箱に入れて処分する動詞の丁寧形。文末を丁寧に言い切れる", "洗います": "水で汚れを落とす動作で、ごみ箱に入れる意味に合わない", "探します": "見つけようとする動作で、物を処分する文には合わない", "包みます": "物を覆う動作で、ごみ箱に入れる意味とは合わない"}, "sentence_index": 0, "correct_answer": "捨てます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大事な本は、友だちに捨てました。", "explanation": "ここは〈譲る〉の意味。大切な物を人に渡すのは譲るで、処分する捨てるとは合わない"}, {"text": "テーブルにコップを捨てました。", "explanation": "ここは〈置く〉の意味。捨てるは手放して処分する動作で、そっと置く動作とは合わない"}, {"text": "机の上を捨てて、本を並べました。", "explanation": "ここは〈片付ける〉の意味。捨てるは物を処分する動作で、場所を整える意味では使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38734, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捨てる", "is_correct": true, "explanation": "空き缶を処分する動作。「捨てるときは」で処分する前の場面を表す"}, {"text": "飲む", "is_correct": false, "explanation": "空き缶を飲む動作にはならず、文の意味が通らない"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作で、処分の場面に合わない"}, {"text": "並べる", "is_correct": false, "explanation": "並べる動作で、洗う前の処分の場面とは合わない"}], "explanations": {"捨てる": "空き缶を処分する動作。「捨てるときは」で処分する前の場面を表す", "飲む": "空き缶を飲む動作にはならず、文の意味が通らない", "眺める": "見る動作で、処分の場面に合わない", "並べる": "並べる動作で、洗う前の処分の場面とは合わない"}, "sentence_index": 6, "correct_answer": "捨てる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プリントを全員に捨てました。", "explanation": "ここは〈配る〉の意味。全員に渡して回るのは配るで、処分する捨てるとは合わない"}, {"text": "コップを水で捨てて、きれいにしました。", "explanation": "ここは〈洗う〉の意味。汚れを水で落とす動作で、処分する捨てるとは合わない"}, {"text": "壁を白く捨てました。", "explanation": "ここは〈塗る〉の意味。色を重ねて面を覆うのは塗るで、処分する捨てるとは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38734, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "使い終わったカイロは、ごみ箱で捨てます。", "corrected_sentence": "使い終わったカイロは、ごみ箱に捨てます。", "error_description": "処分する先は「に」で示す。「で」では動作の場所になり、捨てる先を表せないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "捨てました", "is_correct": true, "explanation": "丁寧な過去の形。過去の出来事を丁寧に述べられる"}, {"text": "捨てます", "is_correct": false, "explanation": "丁寧な現在形で、過去の出来事を述べる文には合わない"}, {"text": "捨てない", "is_correct": false, "explanation": "否定形で、捨てた事実と反対の意味になる"}, {"text": "捨てよう", "is_correct": false, "explanation": "意志形で、まだ行っていない意志を表す"}], "correct_form": "捨てました", "base_form": "捨てる", "form_label": "丁寧形・過去", "sentence_index": 1, "explanations": {"捨てました": "丁寧な過去の形。過去の出来事を丁寧に述べられる", "捨てます": "丁寧な現在形で、過去の出来事を述べる文には合わない", "捨てない": "否定形で、捨てた事実と反対の意味になる", "捨てよう": "意志形で、まだ行っていない意志を表す"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38734, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "使い終わった乾電池は、ごみ箱に捨ないでください。", "corrected_sentence": "使い終わった乾電池は、ごみ箱に捨てないでください。", "error_description": "ない形は「捨てない」になる。「捨」の後に「て」が必要なので、「捨ない」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "捨てました", "is_correct": true, "explanation": "丁寧な過去の形。過去の出来事を丁寧に述べられる"}, {"text": "捨てて", "is_correct": false, "explanation": "て形で、文末では言い切れず、丁寧な過去の文に合わない"}, {"text": "捨てれば", "is_correct": false, "explanation": "仮定形で、条件を表すので過去の事実を述べる文には合わない"}, {"text": "捨てず", "is_correct": false, "explanation": "否定の連用形で、文末に単独では置けない"}], "correct_form": "捨てました", "base_form": "捨てる", "form_label": "丁寧形・過去", "sentence_index": 7, "explanations": {"捨てました": "丁寧な過去の形。過去の出来事を丁寧に述べられる", "捨てて": "て形で、文末では言い切れず、丁寧な過去の文に合わない", "捨てれば": "仮定形で、条件を表すので過去の事実を述べる文には合わない", "捨てず": "否定の連用形で、文末に単独では置けない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38735, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「家具を捨てる」の目的語を示す「を」が自然"}, {"text": "に", "is_correct": false, "explanation": "「家具に捨てました」は捨てる先として不自然で、文の意味が通らない"}, {"text": "で", "is_correct": false, "explanation": "「家具で捨てました」は手段を示すが、不自然で意味が通らない"}, {"text": "が", "is_correct": false, "explanation": "「家具が捨てました」では家具が主語になり、文が成り立たない"}], "correct_answer": "を", "explanations": {"を": "「家具を捨てる」の目的語を示す「を」が自然", "に": "「家具に捨てました」は捨てる先として不自然で、文の意味が通らない", "で": "「家具で捨てました」は手段を示すが、不自然で意味が通らない", "が": "「家具が捨てました」では家具が主語になり、文が成り立たない"}, "error_tags": {"に": "帰着・位置", "で": "手段・場所", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38735, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一緒に捨てる」と、いっしょにする対象を示す「に」が自然"}, {"text": "を", "is_correct": false, "explanation": "「一緒を捨てて」と目的語を重ねると文が成り立たない"}, {"text": "の", "is_correct": false, "explanation": "「一緒の捨てて」では名詞が動詞につながらず、文が成り立たない"}, {"text": "と", "is_correct": false, "explanation": "「一緒と捨てて」では並べる意味になり、文の流れが合わない"}], "correct_answer": "に", "explanations": {"に": "「一緒に捨てる」と、いっしょにする対象を示す「に」が自然", "を": "「一緒を捨てて」と目的語を重ねると文が成り立たない", "の": "「一緒の捨てて」では名詞が動詞につながらず、文が成り立たない", "と": "「一緒と捨てて」では並べる意味になり、文の流れが合わない"}, "error_tags": {"を": "目的語の重複", "の": "連体・所有", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38735, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "不要なものや、もう使わないものを、手放したり、ごみとして処理したりすること。", "primary_collocate": null, "pronunciation": "すてる", "ipa": "sɯteɾɯ", "syllable_count": 3, "sentences": [{"text": "着ない服を、思い切って捨てることにしました。", "target_word": "捨てる", "complexity_tier": "T3", "furigana": "着[き]ない服[ふく]を、思[おも]い切[き]って捨[す]てることにしました。", "sentence_source": "generated"}, {"text": "先週、引っ越しの前に、使わない家具を捨てました。", "target_word": "捨てました", "complexity_tier": "T3", "furigana": "先週[せんしゅう]、引[ひ]っ越[こ]しの前[まえ]に、使[つか]わない家具[かぐ]を捨[す]てました。", "sentence_source": "generated"}, {"text": "古い雑誌は、まとめて資源ごみの日に捨てます。", "target_word": "捨てます", "complexity_tier": "T3", "furigana": "古[ふる]い雑誌[ざっし]は、まとめて資源[しげん]ごみの日[ひ]に捨[す]てます。", "sentence_source": "generated"}, {"text": "壊れた傘は直さずに、新しいのを買って古いほうを捨てました。", "target_word": "捨てました", "complexity_tier": "T3", "furigana": "壊[こわ]れた傘[かさ]は直[なお]さずに、新[あたら]しいのを買[か]って古[ふる]いほうを捨[す]てました。", "sentence_source": "generated"}, {"text": "賞味期限が切れた食品は、捨てたほうがいいです。", "target_word": "捨てた", "complexity_tier": "T3", "furigana": "賞味期限[しょうみきげん]が切[き]れた食品[しょくひん]は、捨[す]てたほうがいいです。", "sentence_source": "generated"}, {"text": "手紙は大切なので、捨てずにとってあります。", "target_word": "捨てず", "complexity_tier": "T3", "furigana": "手紙[てがみ]は大切[たいせつ]なので、捨[す]てずにとってあります。", "sentence_source": "generated"}, {"text": "部屋が狭いので、読まない本を捨ててすっきりさせました。", "target_word": "捨てて", "complexity_tier": "T3", "furigana": "部屋[へや]が狭[せま]いので、読[よ]まない本[ほん]を捨[す]ててすっきりさせました。", "sentence_source": "generated"}, {"text": "電池を普通のごみと一緒に捨ててはいけません。", "target_word": "捨てて", "complexity_tier": "T3", "furigana": "電池[でんち]を普通[ふつう]のごみと一緒[いっしょ]に捨[す]ててはいけません。", "sentence_source": "generated"}, {"text": "この机はまだ使えるので、捨てるのはもったいないです。", "target_word": "捨てる", "complexity_tier": "T3", "furigana": "この机[つくえ]はまだ使[つか]えるので、捨[す]てるのはもったいないです。", "sentence_source": "generated"}, {"text": "母は古くなった食器を捨てて、新しいものに買いかえました。", "target_word": "捨てて", "complexity_tier": "T3", "furigana": "母[はは]は古[ふる]くなった食器[しょっき]を捨[す]てて、新[あたら]しいものに買[か]いかえました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "捨てる", "label": "終止形・連体形"}, {"form": "捨てます", "label": "丁寧形"}, {"form": "捨てて", "label": "て形"}, {"form": "捨てた", "label": "た形"}, {"form": "捨てない", "label": "ない形"}, {"form": "捨てれば", "label": "仮定形"}, {"form": "捨てよう", "label": "意志形"}], "register": "丁寧", "sense_fingerprint": "不要になった物や使わない物を手放し、ごみとして処分する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1482d3a5-b226-445e-b588-4975f8b011fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38735, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捨てる", "is_correct": true, "explanation": "不要な服を手放す意味で、思い切って処分する場面に合う"}, {"text": "飲む", "is_correct": false, "explanation": "服には使わず、文の意味が通らない"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作で、手放す決断とは合わない"}, {"text": "割る", "is_correct": false, "explanation": "壊す動作で、手放すとは違う意味になる"}], "explanations": {"捨てる": "不要な服を手放す意味で、思い切って処分する場面に合う", "飲む": "服には使わず、文の意味が通らない", "眺める": "見る動作で、手放す決断とは合わない", "割る": "壊す動作で、手放すとは違う意味になる"}, "sentence_index": 0, "correct_answer": "捨てる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアを捨てて開けました。", "explanation": "ここは〈押す〉の意味。ドアを押して開ける動作は押すで、物を手放す捨てるとは合わない"}, {"text": "大切な写真は、パソコンに捨てました。", "explanation": "ここは〈保存する〉の意味。捨てるは処分することで、データを残す場合には使わない"}, {"text": "古い電池を新しいものに捨てました。", "explanation": "ここは〈取り替える〉の意味。古いものを別のものと入れ替えるのは取り替えるで、処分する捨てるとは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38735, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捨てて", "is_correct": true, "explanation": "読まない本を手放す動作のて形。「捨ててすっきり」の流れに合う"}, {"text": "洗って", "is_correct": false, "explanation": "汚れを落とす動作で、本を手放して部屋を広くする意味には合わない"}, {"text": "叩いて", "is_correct": false, "explanation": "たたく動作で、本を手放す流れに合わない"}, {"text": "踏んで", "is_correct": false, "explanation": "踏みつける動作で、すっきりする理由にならない"}], "explanations": {"捨てて": "読まない本を手放す動作のて形。「捨ててすっきり」の流れに合う", "洗って": "汚れを落とす動作で、本を手放して部屋を広くする意味には合わない", "叩いて": "たたく動作で、本を手放す流れに合わない", "踏んで": "踏みつける動作で、すっきりする理由にならない"}, "sentence_index": 6, "correct_answer": "捨てて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "髪を短く捨てました。", "explanation": "ここは〈切る〉の意味。髪を短く切り落とすのは切るで、手放す・処分する捨てるとは合わない"}, {"text": "古い自転車を、安く捨てました。", "explanation": "ここは〈売る〉の意味。値段をつけて渡す行為で、ただ処分する捨てるとは合わない"}, {"text": "黒板の文字を捨てました。", "explanation": "ここは〈消す〉の意味。書いた文字を消すのは消すで、処分する捨てるとは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38735, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "着なくなったコートを、思い切って捨ててことにしました。", "corrected_sentence": "着なくなったコートを、思い切って捨てることにしました。", "error_description": "辞書形「捨てる」に「こと」を続けて名詞化する。「捨てて」の形は「こと」につながらないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "捨てました", "is_correct": true, "explanation": "丁寧な過去の形。引っ越しという過去の出来事を丁寧に述べられる"}, {"text": "捨てません", "is_correct": false, "explanation": "丁寧な否定形で、捨てた事実と反対の意味になる"}, {"text": "捨てよう", "is_correct": false, "explanation": "意志形で、まだ行っていない意志を表す"}, {"text": "捨てれば", "is_correct": false, "explanation": "仮定形で、条件を表すので過去の出来事を述べる文には合わない"}], "correct_form": "捨てました", "base_form": "捨てる", "form_label": "丁寧形・過去", "sentence_index": 1, "explanations": {"捨てました": "丁寧な過去の形。引っ越しという過去の出来事を丁寧に述べられる", "捨てません": "丁寧な否定形で、捨てた事実と反対の意味になる", "捨てよう": "意志形で、まだ行っていない意志を表す", "捨てれば": "仮定形で、条件を表すので過去の出来事を述べる文には合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38735, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いシャツに、思い切って捨てました。", "corrected_sentence": "古いシャツを、思い切って捨てました。", "error_description": "「捨てる」の目的語は「を」で示す。「に」では対象が示せず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "捨てて", "is_correct": true, "explanation": "て形。「〜てはいけません」の形に続けて禁止を表せる"}, {"text": "捨てず", "is_correct": false, "explanation": "否定の連用形で、「〜てはいけません」の形には続かない"}, {"text": "捨てた", "is_correct": false, "explanation": "過去形で、「〜てはいけません」の形に続かない"}, {"text": "捨てない", "is_correct": false, "explanation": "否定形で、禁止の文の意味が逆になる"}], "correct_form": "捨てて", "base_form": "捨てる", "form_label": "て形", "sentence_index": 7, "explanations": {"捨てて": "て形。「〜てはいけません」の形に続けて禁止を表せる", "捨てず": "否定の連用形で、「〜てはいけません」の形には続かない", "捨てた": "過去形で、「〜てはいけません」の形に続かない", "捨てない": "否定形で、禁止の文の意味が逆になる"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38736, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散る", "is_correct": true, "explanation": "対義語。人や物が一か所に寄る「集まる」の反対で、あちこちへ離れていく意味。"}, {"text": "眠る", "is_correct": false, "explanation": "睡眠を表す動詞で、「集まる」の対義語ではない。"}, {"text": "走る", "is_correct": false, "explanation": "移動の動作を表す動詞で、「集まる」の対義関係にない。"}, {"text": "話す", "is_correct": false, "explanation": "言葉を交わす動作を表す動詞で、「集まる」の対義関係にない。"}], "correct_answer": "散る", "explanations": {"散る": "対義語。人や物が一か所に寄る「集まる」の反対で、あちこちへ離れていく意味。", "眠る": "睡眠を表す動詞で、「集まる」の対義語ではない。", "走る": "移動の動作を表す動詞で、「集まる」の対義関係にない。", "話す": "言葉を交わす動作を表す動詞で、「集まる」の対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38736, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "踊る", "is_correct": false, "explanation": "身体を動かす動作を表す動詞で、「集まる」の対義関係にない。"}, {"text": "散る", "is_correct": true, "explanation": "対義語。人や物が一か所に寄る「集まる」の反対で、あちこちへ離れていく意味。"}, {"text": "歌う", "is_correct": false, "explanation": "声を出す動作を表す動詞で、「集まる」の対義関係にない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "水中を進む動作を表す動詞で、「集まる」の対義関係にない。"}], "correct_answer": "散る", "explanations": {"踊る": "身体を動かす動作を表す動詞で、「集まる」の対義関係にない。", "散る": "対義語。人や物が一か所に寄る「集まる」の反対で、あちこちへ離れていく意味。", "歌う": "声を出す動作を表す動詞で、「集まる」の対義関係にない。", "泳ぐ": "水中を進む動作を表す動詞で、「集まる」の対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38736, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ひとやものが、一つのところへ まとまることです。", "primary_collocate": null, "pronunciation": "あつまる", "ipa": "atsɯmaɾɯ", "syllable_count": 4, "sentences": [{"text": "日曜日の朝、子どもたちが公園に集まります。", "target_word": "集まります", "complexity_tier": "T3", "furigana": "日曜日[にちようび]の朝[あさ]、子[こ]どもたちが公園[こうえん]に集[あつ]まります。", "sentence_source": "generated"}, {"text": "駅の前に、クラスの友だちが十人集まりました。", "target_word": "集まりました", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]に、クラスの友[とも]だちが十人[じゅうにん]集[あつ]まりました。", "sentence_source": "generated"}, {"text": "雨がやんだので、池のまわりに鳥が集まってきました。", "target_word": "集まって", "complexity_tier": "T3", "furigana": "雨[あめ]がやんだので、池[いけ]のまわりに鳥[とり]が集[あつ]まってきました。", "sentence_source": "generated"}, {"text": "会議室に全員が集まったら、会議を始めます。", "target_word": "集まったら", "complexity_tier": "T3", "furigana": "会議室[かいぎしつ]に全員[ぜんいん]が集[あつ]まったら、会議[かいぎ]を始[はじ]めます。", "sentence_source": "generated"}, {"text": "花火を見るために、川の近くに大勢の人が集まっています。", "target_word": "集まっています", "complexity_tier": "T3", "furigana": "花火[はなび]を見[み]るために、川[かわ]の近[ちか]くに大勢[おおぜい]の人[ひと]が集[あつ]まっています。", "sentence_source": "generated"}, {"text": "放課後、教室にみんなが集まって文化祭の相談をしました。", "target_word": "集まって", "complexity_tier": "T3", "furigana": "放課後[ほうかご]、教室[きょうしつ]にみんなが集[あつ]まって文化祭[ぶんかさい]の相談[そうだん]をしました。", "sentence_source": "generated"}, {"text": "砂糖のまわりにアリが集まっていました。", "target_word": "集まって", "complexity_tier": "T3", "furigana": "砂糖[さとう]のまわりにアリが集[あつ]まっていました。", "sentence_source": "generated"}, {"text": "九時までに、校庭に集まってください。", "target_word": "集まって", "complexity_tier": "T3", "furigana": "九時[くじ]までに、校庭[こうてい]に集[あつ]まってください。", "sentence_source": "generated"}, {"text": "大きな音がして、たくさんの人が集まってきました。", "target_word": "集まって", "complexity_tier": "T3", "furigana": "大[おお]きな音[おと]がして、たくさんの人[ひと]が集[あつ]まってきました。", "sentence_source": "generated"}, {"text": "家族が集まる夜は、いつも母が大きなお鍋を作ります。", "target_word": "集まる", "complexity_tier": "T3", "furigana": "家族[かぞく]が集[あつ]まる夜[よる]は、いつも母[はは]が大[おお]きなお鍋[なべ]を作[つく]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集まる", "label": "終止形・連体形"}, {"form": "集まります", "label": "丁寧形"}, {"form": "集まって", "label": "て形"}, {"form": "集まった", "label": "た形"}, {"form": "集まらない", "label": "ない形"}, {"form": "集まれば", "label": "仮定形"}, {"form": "集まろう", "label": "意志形"}], "register": "丁寧", "sense_fingerprint": "人や動物、物が一つの場所に寄ってくる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1482d3a5-b226-445e-b588-4975f8b011fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38736, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集まります", "is_correct": true, "explanation": "丁寧な現在形。朝の集まりを述べる平叙文の述語として自然。"}, {"text": "集まれ", "is_correct": false, "explanation": "命令形。文末が「ます」の平叙文に合わず、文の形が崩れる。"}, {"text": "集まろう", "is_correct": false, "explanation": "意志形。子どもたちの行動を事実として述べる文には合わない。"}, {"text": "集めます", "is_correct": false, "explanation": "他動詞。目的語（何を）がないまま「子どもたちが公園に集めます」とすると不自然。"}], "explanations": {"集まります": "丁寧な現在形。朝の集まりを述べる平叙文の述語として自然。", "集まれ": "命令形。文末が「ます」の平叙文に合わず、文の形が崩れる。", "集まろう": "意志形。子どもたちの行動を事実として述べる文には合わない。", "集めます": "他動詞。目的語（何を）がないまま「子どもたちが公園に集めます」とすると不自然。"}, "sentence_index": 0, "correct_answer": "集まります"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は数学の勉強に集まって、時間を忘れるほどだった。", "explanation": "ここは〈集中〉の意味。〈集まる〉は人や物が一か所に寄ることで、心を一つのことに向ける意味では使わない。〈勉強に集中する〉が正しい。"}, {"text": "冷蔵庫で冷やすと、ゼリーがちゃんと集まります。", "explanation": "ここは〈固まる〉の意味。ゼリーが冷えて形を保つ変化は〈固まる〉で言う。〈集まる〉は人や物が寄ることなので合わない。"}, {"text": "寝癖がひどくて、髪がうまく集まらない。", "explanation": "ここは〈まとまる〉の意味。髪が落ち着いて整う様子は〈まとまる〉で言う。〈集まる〉は人や物が一か所に寄る意味なので、髪の状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38736, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集まって", "is_correct": true, "explanation": "て形。「集まっていました」の一部で、アリが寄っていた状態を表す。"}, {"text": "集まったら", "is_correct": false, "explanation": "たら形。「集まったら、いました」とは続かず、「〜ていました」の形にならない。"}, {"text": "集まる", "is_correct": false, "explanation": "基本形。「集まるいました」とは続かず、「〜ていました」の形にならない。"}, {"text": "集まれば", "is_correct": false, "explanation": "仮定形。「集まればいました」とは続かず、過去の状態を述べられない。"}], "explanations": {"集まって": "て形。「集まっていました」の一部で、アリが寄っていた状態を表す。", "集まったら": "たら形。「集まったら、いました」とは続かず、「〜ていました」の形にならない。", "集まる": "基本形。「集まるいました」とは続かず、「〜ていました」の形にならない。", "集まれば": "仮定形。「集まればいました」とは続かず、過去の状態を述べられない。"}, "sentence_index": 6, "correct_answer": "集まって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人で旅行を重ねて、友情が集まった。", "explanation": "ここは〈深まる〉の意味。友情が深くなる変化は〈深まる〉で言う。〈集まる〉は人や物が寄ることなので合わない。"}, {"text": "新しい靴が足のサイズにぴったり集まった。", "explanation": "ここは〈合う〉の意味。寸法がぴったり合うことは〈合う〉で言う。〈集まる〉は人や物が寄ることで、サイズには使わない。"}, {"text": "毎日の疲れが少しずつ集まって、体が重い。", "explanation": "ここは〈溜まる〉の意味。疲れが少しずつ積もる様子は〈溜まる〉で言う。〈集まる〉では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38736, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末の朝、子どもたちが校庭を集まります。", "corrected_sentence": "週末の朝、子どもたちが校庭に集まります。", "error_description": "「集まる」は場所を表す「に」を取る。「を」は他動詞用の助詞なので誤り。正しくは「校庭に集まります」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "集まりませんでした", "is_correct": false, "explanation": "丁寧な過去の否定形。「十人集まらなかった」となり、十人が来たという文の内容と矛盾する。"}, {"text": "集まりました", "is_correct": true, "explanation": "丁寧な過去形。「十人集まった」という過去の出来事を述べる文に合う。"}, {"text": "集まって", "is_correct": false, "explanation": "て形。文末にならず、「十人集まって。」では文が終わらない。"}, {"text": "集まらない", "is_correct": false, "explanation": "ない形。「十人集まらない」は来なかったという逆の意味になり、文の内容と矛盾する。"}], "correct_form": "集まりました", "base_form": "集まる", "form_label": "丁寧な過去形", "sentence_index": 1, "explanations": {"集まりませんでした": "丁寧な過去の否定形。「十人集まらなかった」となり、十人が来たという文の内容と矛盾する。", "集まりました": "丁寧な過去形。「十人集まった」という過去の出来事を述べる文に合う。", "集まって": "て形。文末にならず、「十人集まって。」では文が終わらない。", "集まらない": "ない形。「十人集まらない」は来なかったという逆の意味になり、文の内容と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38736, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日の朝、校門を集まってください。", "corrected_sentence": "明日の朝、校門に集まってください。", "error_description": "「集まる」は場所を表す「に」を取る。「を」は誤り。正しくは「校門に集まってください」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "集まって", "is_correct": true, "explanation": "て形。「〜てください」に続けて依頼の文になる。"}, {"text": "集まった", "is_correct": false, "explanation": "た形。「〜ください」に続かず、依頼の文にならない。"}, {"text": "集まれば", "is_correct": false, "explanation": "仮定形。「集まればください」は成り立たず、依頼の文にならない。"}, {"text": "集まる", "is_correct": false, "explanation": "基本形。「集まるください」は成り立たず、依頼の文にならない。"}], "correct_form": "集まって", "base_form": "集まる", "form_label": "て形", "sentence_index": 7, "explanations": {"集まって": "て形。「〜てください」に続けて依頼の文になる。", "集まった": "た形。「〜ください」に続かず、依頼の文にならない。", "集まれば": "仮定形。「集まればください」は成り立たず、依頼の文にならない。", "集まる": "基本形。「集まるください」は成り立たず、依頼の文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38737, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歩く", "is_correct": false, "explanation": "移動の動作を表す動詞で、「集まる」の対義関係にない。"}, {"text": "笑う", "is_correct": false, "explanation": "表情や声を伴う動作で、「集まる」の対義関係にない。"}, {"text": "散る", "is_correct": true, "explanation": "対義語。人や物が一か所に寄る「集まる」の反対で、あちこちへ離れていく意味。"}, {"text": "考える", "is_correct": false, "explanation": "思考を表す動詞で、「集まる」の対義関係にない。"}], "correct_answer": "散る", "explanations": {"歩く": "移動の動作を表す動詞で、「集まる」の対義関係にない。", "笑う": "表情や声を伴う動作で、「集まる」の対義関係にない。", "散る": "対義語。人や物が一か所に寄る「集まる」の反対で、あちこちへ離れていく意味。", "考える": "思考を表す動詞で、「集まる」の対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
