INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38737, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人・物・情報などが、一つの場所や状態にまとまること。また、そのようにする。", "primary_collocate": null, "pronunciation": "あつまる", "ipa": "atsɯmaɾɯ", "syllable_count": 4, "sentences": [{"text": "募金には、一週間で百万円も集まりました。", "target_word": "集まりました", "complexity_tier": "T3", "furigana": "募金[ぼきん]には、一週間[いっしゅうかん]で百万円[ひゃくまんえん]も集[あつ]まりました。", "sentence_source": "generated"}, {"text": "調べているうちに、必要な情報が少しずつ集まってきました。", "target_word": "集まって", "complexity_tier": "T3", "furigana": "調[しら]べているうちに、必要[ひつよう]な情報[じょうほう]が少[すこ]しずつ集[あつ]まってきました。", "sentence_source": "generated"}, {"text": "この店の新商品に、若い人の注目が集まっています。", "target_word": "集まっています", "complexity_tier": "T3", "furigana": "この店[みせ]の新商品[しんしょうひん]に、若[わか]い人[ひと]の注目[ちゅうもく]が集[あつ]まっています。", "sentence_source": "generated"}, {"text": "このお祭りには、毎年全国から二万人が集まります。", "target_word": "集まります", "complexity_tier": "T3", "furigana": "このお祭[まつ]りには、毎年[まいとし]全国[ぜんこく]から二万人[にまんにん]が集[あつ]まります。", "sentence_source": "generated"}, {"text": "アンケートの答えが集まったら、グラフにまとめます。", "target_word": "集まったら", "complexity_tier": "T3", "furigana": "アンケートの答[こた]えが集[あつ]まったら、グラフにまとめます。", "sentence_source": "generated"}, {"text": "寄付で、図書館に新しい本が三百冊集まりました。", "target_word": "集まりました", "complexity_tier": "T3", "furigana": "寄付[きふ]で、図書館[としょかん]に新[あたら]しい本[ほん]が三百冊[さんびゃくさつ]集[あつ]まりました。", "sentence_source": "generated"}, {"text": "低い土地には水が集まるので、大雨のときは注意が必要です。", "target_word": "集まる", "complexity_tier": "T3", "furigana": "低[ひく]い土地[とち]には水[みず]が集[あつ]まるので、大雨[おおあめ]のときは注意[ちゅうい]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "有名な料理人が来ると聞いて、店には多くの客が集まりました。", "target_word": "集まりました", "complexity_tier": "T3", "furigana": "有名[ゆうめい]な料理人[りょうりにん]が来[く]ると聞[き]いて、店[みせ]には多[おお]くの客[きゃく]が集[あつ]まりました。", "sentence_source": "generated"}, {"text": "彼は人柄がいいので、まわりに自然と人が集まります。", "target_word": "集まります", "complexity_tier": "T3", "furigana": "彼[かれ]は人柄[ひとがら]がいいので、まわりに自然[しぜん]と人[ひと]が集[あつ]まります。", "sentence_source": "generated"}, {"text": "世界の優れた研究者が集まって、新しい薬の開発を進めています。", "target_word": "集まって", "complexity_tier": "T3", "furigana": "世界[せかい]の優[すぐ]れた研究者[けんきゅうしゃ]が集[あつ]まって、新[あたら]しい薬[くすり]の開発[かいはつ]を進[すす]めています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集まる", "label": "終止形・連体形"}, {"form": "集まります", "label": "丁寧形"}, {"form": "集まって", "label": "て形"}, {"form": "集まった", "label": "た形"}, {"form": "集まらない", "label": "ない形"}, {"form": "集まれば", "label": "仮定形"}, {"form": "集まろう", "label": "意志形"}], "register": "丁寧", "sense_fingerprint": "人・お金・情報・注目などが、一つの所や対象に寄り集まって量や数が増える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1482d3a5-b226-445e-b588-4975f8b011fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38737, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集まりました", "is_correct": true, "explanation": "丁寧な過去形。一週間の結果として額が集まったと述べる文に合う。"}, {"text": "集まって", "is_correct": false, "explanation": "て形。文末にならず、文が終わらない。"}, {"text": "集まれ", "is_correct": false, "explanation": "命令形。結果を述べる文には合わない。"}, {"text": "集まろう", "is_correct": false, "explanation": "意志形。「百万円も集まろう」は提案の形になり、結果の説明に合わない。"}], "explanations": {"集まりました": "丁寧な過去形。一週間の結果として額が集まったと述べる文に合う。", "集まって": "て形。文末にならず、文が終わらない。", "集まれ": "命令形。結果を述べる文には合わない。", "集まろう": "意志形。「百万円も集まろう」は提案の形になり、結果の説明に合わない。"}, "sentence_index": 0, "correct_answer": "集まりました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一週間で百万円も集まった。", "explanation": "ここは〈稼ぐ〉の意味。人が働いて金額を得る行為は〈稼ぐ〉で言う。〈集まる〉はお金などが寄り集まる意味なので、人を主語にできない。"}, {"text": "寝癖がひどくて、髪がうまく集まらない。", "explanation": "ここは〈まとまる〉の意味。髪が落ち着いて整う様子は〈まとまる〉で言う。〈集まる〉はお金や情報が増える意味なので、髪の状態には使わない。"}, {"text": "砂糖がお湯にすっかり集まった。", "explanation": "ここは〈溶ける〉の意味。砂糖が液体に混ざって見えなくなる変化は〈溶ける〉で言う。〈集まる〉では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38737, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集まる", "is_correct": true, "explanation": "基本形。「集まるので」と理由を続ける形に合う。"}, {"text": "集める", "is_correct": false, "explanation": "他動詞。「水が集めるので」は、目的語を取る他動詞に「が」の主語を置く誤りになる。"}, {"text": "集まり", "is_correct": false, "explanation": "連用形。「集まりので」と「ので」に続かず、理由を述べる文が成り立たない。"}, {"text": "集めよう", "is_correct": false, "explanation": "意志形。「集めようので」の形にならず、理由を述べる文に合わない。"}], "explanations": {"集まる": "基本形。「集まるので」と理由を続ける形に合う。", "集める": "他動詞。「水が集めるので」は、目的語を取る他動詞に「が」の主語を置く誤りになる。", "集まり": "連用形。「集まりので」と「ので」に続かず、理由を述べる文が成り立たない。", "集めよう": "意志形。「集めようので」の形にならず、理由を述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "集まる"}, "level_6": {"correct_sentence_index": 2, "wrong_sentences": [{"text": "難しい問題がやっと集まった。", "explanation": "ここは〈解ける〉の意味。問題に答えが出る意味は〈解ける〉で言う。〈集まる〉は人や物が寄ることなので合わない。"}, {"text": "カーテンの隙間から、夕日が一筋に集まった。", "explanation": "ここは〈差す〉の意味。細く光が入り込む様子は〈差す〉で言う。〈集まる〉は人や物が一つの場所に寄る意味で、光の差し込みには使わない。"}, {"text": "セーターを洗ったら、袖が集まって、腕が出なくなった。", "explanation": "ここは〈縮む〉の意味。布が縮んで小さくなる変化は〈縮む〉で言う。〈集まる〉はお金や情報などが増える意味で、布の縮みには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38737, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の祭りには、寄付が百万円集めました。", "corrected_sentence": "町の祭りには、寄付が百万円集まりました。", "error_description": "「寄付が」が主語なので自動詞「集まる」を使う。他動詞「集める」は人が主語で目的語を取るため、ここでは誤り。正しくは「集まりました」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "集まって", "is_correct": true, "explanation": "て形。「〜てきました」に続き、だんだん寄ってくる変化を表す。"}, {"text": "集まります", "is_correct": false, "explanation": "丁寧な現在形。「集まりますてきました」のように続かない。"}, {"text": "集まった", "is_correct": false, "explanation": "た形。「集まったてきました」の形にならない。"}, {"text": "集まれば", "is_correct": false, "explanation": "仮定形。「〜てきました」に続かず、文が成り立たない。"}], "correct_form": "集まって", "base_form": "集まる", "form_label": "て形", "sentence_index": 1, "explanations": {"集まって": "て形。「〜てきました」に続き、だんだん寄ってくる変化を表す。", "集まります": "丁寧な現在形。「集まりますてきました」のように続かない。", "集まった": "た形。「集まったてきました」の形にならない。", "集まれば": "仮定形。「〜てきました」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38737, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末の市場には、多くの客が集めました。", "corrected_sentence": "週末の市場には、多くの客が集まりました。", "error_description": "「客が」が主語なので自動詞の「集まる」を使う。他動詞「集める」は目的語を必要とするため誤り。正しくは「集まりました」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "集まりました", "is_correct": true, "explanation": "丁寧な過去形。「多くの客が集まりました」と過去の出来事を述べる。"}, {"text": "集まる", "is_correct": false, "explanation": "基本形。過去の出来事を述べる文の時制と合わず、現在や習慣の話になってしまう。"}, {"text": "集まり", "is_correct": false, "explanation": "連用形。文末に置くと文が終わらず、過去の出来事を述べられない。"}, {"text": "集まらなかった", "is_correct": false, "explanation": "否定の過去形。「多くの客が集まらなかった」は、客が来たという文脈と矛盾する。"}], "correct_form": "集まりました", "base_form": "集まる", "form_label": "丁寧な過去形", "sentence_index": 7, "explanations": {"集まりました": "丁寧な過去形。「多くの客が集まりました」と過去の出来事を述べる。", "集まる": "基本形。過去の出来事を述べる文の時制と合わず、現在や習慣の話になってしまう。", "集まり": "連用形。文末に置くと文が終わらず、過去の出来事を述べられない。", "集まらなかった": "否定の過去形。「多くの客が集まらなかった」は、客が来たという文脈と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
