INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38738, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "function", "definition": "前に示した内容と同じ様子であることを表す。", "primary_collocate": null, "pronunciation": "このようだ", "ipa": "konojoːda", "syllable_count": 5, "sentences": [{"text": "地図を指して、町の形はこのようだと説明した。", "target_word": "このようだ", "complexity_tier": "T3", "furigana": "地図[ちず]を指[さ]して、町[まち]の形[かたち]はこのようだと説明[せつめい]した。", "sentence_source": "generated"}, {"text": "事故の原因は、調べたところこのようだ。", "target_word": "このようだ", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]は、調[しら]べたところこのようだ。", "sentence_source": "generated"}, {"text": "先生の話をまとめると、このようだ。", "target_word": "このようだ", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]をまとめると、このようだ。", "sentence_source": "generated"}, {"text": "今日の予定表の内容は、このようだ。", "target_word": "このようだ", "complexity_tier": "T3", "furigana": "今日[きょう]の予定表[よていひょう]の内容[ないよう]は、このようだ。", "sentence_source": "generated"}, {"text": "祖母は絵を見せて、昔の祭りはこのようだと教えてくれた。", "target_word": "このようだ", "complexity_tier": "T3", "furigana": "祖母[そぼ]は絵[え]を見[み]せて、昔[むかし]の祭[まつ]りはこのようだと教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "私の考えはこのようだが、あなたはどう思うか。", "target_word": "このようだ", "complexity_tier": "T3", "furigana": "私[わたし]の考[かんが]えはこのようだが、あなたはどう思[おも]うか。", "sentence_source": "generated"}, {"text": "黒板に描かれた図は、このようだ。", "target_word": "このようだ", "complexity_tier": "T3", "furigana": "黒板[こくばん]に描[か]かれた図[ず]は、このようだ。", "sentence_source": "generated"}, {"text": "このゲームのルールはこのようだから、よく読んでおくこと。", "target_word": "このようだ", "complexity_tier": "T3", "furigana": "このゲームのルールはこのようだから、よく読[よ]んでおくこと。", "sentence_source": "generated"}, {"text": "新しい駅の中は、写真で見るとこのようだと聞いた。", "target_word": "このようだ", "complexity_tier": "T3", "furigana": "新[あたら]しい駅[えき]の中[なか]は、写真[しゃしん]で見[み]るとこのようだと聞[き]いた。", "sentence_source": "generated"}, {"text": "問題の答えは、このようだと先生が黒板に書いた。", "target_word": "このようだ", "complexity_tier": "T3", "furigana": "問題[もんだい]の答[こた]えは、このようだと先生[せんせい]が黒板[こくばん]に書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "このようだ", "label": "終止形"}, {"form": "このような", "label": "連体形"}, {"form": "このように", "label": "連用形"}], "register": "書き言葉（普通体）", "sense_fingerprint": "前に示したものと同じ様子であることを表す言い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95344bd9-fdcd-410b-94e3-d1adfb174457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38738, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "このようだ", "is_correct": true, "explanation": "前に示した町の形を指す「このようだ」が、地図で示した形を説明する文に合う。"}, {"text": "なかよしだ", "is_correct": false, "explanation": "人どうしの親しさを表す語で、町の形の説明には合わない。"}, {"text": "にぎやかだ", "is_correct": false, "explanation": "人や店の活気を表す語で、町の形そのものには使わない。"}, {"text": "おだやかだ", "is_correct": false, "explanation": "天候や性格を表す語で、形を説明する文には合わない。"}], "explanations": {"このようだ": "前に示した町の形を指す「このようだ」が、地図で示した形を説明する文に合う。", "なかよしだ": "人どうしの親しさを表す語で、町の形の説明には合わない。", "にぎやかだ": "人や店の活気を表す語で、町の形そのものには使わない。", "おだやかだ": "天候や性格を表す語で、形を説明する文には合わない。"}, "sentence_index": 0, "correct_answer": "このようだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が降っているのに、このようだと言って外へ出かけた。", "explanation": "ここは「このようだ」を外出の理由や決意の言葉として使っている。この語は様子を説明するもので、行動の理由には使えない。"}, {"text": "わあ、このようだ！ 花火がきれいだ。", "explanation": "ここは「わあ」のような感嘆の声として「このようだ」を使っている。この語は示した様子を説明する言葉で、感動の声としては使わない。"}, {"text": "午後三時に、このようだと言って電話を切った。", "explanation": "ここは「このようだ」を時刻を言う言葉として使っている。この語は様子を説明するもので、時刻を言うのには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38738, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "このようだ", "is_correct": true, "explanation": "黒板に描かれた図の様子を示す「このようだ」が入り、文として自然に成り立つ。"}, {"text": "ひまだ", "is_correct": false, "explanation": "暇な状態を表す語で、図の様子の説明には合わない。"}, {"text": "まじめだ", "is_correct": false, "explanation": "人の態度を表す語で、図には使わない。"}, {"text": "げんきだ", "is_correct": false, "explanation": "人や動物の状態を表す語で、図には使わない。"}], "explanations": {"このようだ": "黒板に描かれた図の様子を示す「このようだ」が入り、文として自然に成り立つ。", "ひまだ": "暇な状態を表す語で、図の様子の説明には合わない。", "まじめだ": "人の態度を表す語で、図には使わない。", "げんきだ": "人や動物の状態を表す語で、図には使わない。"}, "sentence_index": 6, "correct_answer": "このようだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は怒りを抑えて、このようだと小さく言った。", "explanation": "ここは「このようだ」を感情を表す言葉として使っている。この語は様子を説明するもので、気持ちを言う語ではない。"}, {"text": "空が晴れたので、このようだと喜んだ。", "explanation": "ここは喜びの気持ちを表す言葉として「このようだ」を使っている。この語は示された様子を説明するもので、感情を表す語ではない。"}, {"text": "受付で名前を呼ばれて、このようだと返事をした。", "explanation": "ここは「はい」のような返事の言葉として「このようだ」を使っている。この語は様子を説明するもので、返事には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38738, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試験の範囲は、このようなと先生が言った。", "corrected_sentence": "試験の範囲は、このようだと先生が言った。", "error_description": "「と」の前では終止形「このようだ」を使う。連体形「このような」は名詞の前に置くので、「このようなと」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38738, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゲームの説明書は、このようだ書いてある。", "corrected_sentence": "ゲームの説明書は、このようだと書いてある。", "error_description": "「このようだ」の後には引用の「と」が必要。「と」が抜けているため、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
