INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38740, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "つるや いとの ことを いう ことばです。", "primary_collocate": null, "pronunciation": "げん", "ipa": "ɡeɴ", "syllable_count": 2, "sentences": [{"text": "ギターの弦が切れたので、楽器店で新しいのを買った。", "target_word": "弦", "complexity_tier": "T3", "furigana": "ギターの弦[げん]が切[き]れたので、楽器店[がっきてん]で新[あたら]しいのを買[か]った。", "sentence_source": "generated"}, {"text": "バイオリンは、弓で弦をこすって音を出す楽器だ。", "target_word": "弦", "complexity_tier": "T3", "furigana": "バイオリンは、弓[ゆみ]で弦[げん]をこすって音[おと]を出[だ]す楽器[がっき]だ。", "sentence_source": "generated"}, {"text": "古い弦は音がにぶいので、ライブの前に張り替えた。", "target_word": "弦", "complexity_tier": "T3", "furigana": "古[ふる]い弦[げん]は音[おと]がにぶいので、ライブの前[まえ]に張[は]り替[か]えた。", "sentence_source": "generated"}, {"text": "弦を強く張りすぎると、切れやすくなる。", "target_word": "弦", "complexity_tier": "T3", "furigana": "弦[げん]を強[つよ]く張[は]りすぎると、切[き]れやすくなる。", "sentence_source": "generated"}, {"text": "先生は、ピアノの中にある弦を見せてくれた。", "target_word": "弦", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ピアノの中[なか]にある弦[げん]を見[み]せてくれた。", "sentence_source": "generated"}, {"text": "この三味線は、弦が太いので低くて深い音が出る。", "target_word": "弦", "complexity_tier": "T3", "furigana": "この三味線[しゃみせん]は、弦[げん]が太[ふと]いので低[ひく]くて深[ふか]い音[おと]が出[で]る。", "sentence_source": "generated"}, {"text": "ハープの弦は四十本以上あり、指ではじいて演奏する。", "target_word": "弦", "complexity_tier": "T3", "furigana": "ハープの弦[げん]は四十本[よんじっぽん]以上[いじょう]あり、指[ゆび]ではじいて演奏[えんそう]する。", "sentence_source": "generated"}, {"text": "弦をゆるめてから、ギターをケースにしまった。", "target_word": "弦", "complexity_tier": "T3", "furigana": "弦[げん]をゆるめてから、ギターをケースにしまった。", "sentence_source": "generated"}, {"text": "新しい弦に替えたら、音がはっきりして聞きやすくなった。", "target_word": "弦", "complexity_tier": "T3", "furigana": "新[あたら]しい弦[げん]に替[か]えたら、音[おと]がはっきりして聞[き]きやすくなった。", "sentence_source": "generated"}, {"text": "弟は弦を押さえる指が痛いと言って、練習をやめた。", "target_word": "弦", "complexity_tier": "T3", "furigana": "弟[おとうと]は弦[げん]を押[お]さえる指[ゆび]が痛[いた]いと言[い]って、練習[れんしゅう]をやめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "弦", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ギターやバイオリンなど楽器に張る糸(げん)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: にぶい (Zipf 1.68)']::text[], '1482d3a5-b226-445e-b588-4975f8b011fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38740, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弦", "is_correct": true, "explanation": "楽器に張る糸のこと。「ギターの弦が切れた」に合う。"}, {"text": "弓", "is_correct": false, "explanation": "弦楽器を弾く道具で、ギターには付かないので合わない。"}, {"text": "楽譜", "is_correct": false, "explanation": "紙に書かれた曲のことで、切れる部品ではないので合わない。"}, {"text": "ピック", "is_correct": false, "explanation": "ギターを弾く小さな道具で、切れて交換する部品ではないので合わない。"}], "explanations": {"弦": "楽器に張る糸のこと。「ギターの弦が切れた」に合う。", "弓": "弦楽器を弾く道具で、ギターには付かないので合わない。", "楽譜": "紙に書かれた曲のことで、切れる部品ではないので合わない。", "ピック": "ギターを弾く小さな道具で、切れて交換する部品ではないので合わない。"}, "sentence_index": 0, "correct_answer": "弦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "段ボールを弦でしっかり縛った。", "explanation": "ここは〈紐〉の意味。物を縛る細い糸は〈紐〉で言う。〈弦〉は楽器に張る糸なので、縛るのには使わない。"}, {"text": "針に弦を通して、ボタンを付けた。", "explanation": "ここは〈糸〉の意味。針に通して縫う糸は〈糸〉で言う。〈弦〉は楽器の糸なので合わない。"}, {"text": "川で魚を弦ですくった。", "explanation": "ここは〈網〉の意味。魚などをすくう道具は〈網〉で言う。〈弦〉は楽器の糸なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38740, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弦", "is_correct": true, "explanation": "楽器に張る糸のこと。「ハープの弦は四十本以上ある」に合う。"}, {"text": "鍵盤", "is_correct": false, "explanation": "ピアノなどの押す部分で、ハープにはなく、本数を数える対象として合わない。"}, {"text": "撥", "is_correct": false, "explanation": "弦をはじく道具で、本数を数える部品ではないので合わない。"}, {"text": "蓋", "is_correct": false, "explanation": "物の覆いのことで、楽器の部品の本数を述べる文に合わない。"}], "explanations": {"弦": "楽器に張る糸のこと。「ハープの弦は四十本以上ある」に合う。", "鍵盤": "ピアノなどの押す部分で、ハープにはなく、本数を数える対象として合わない。", "撥": "弦をはじく道具で、本数を数える部品ではないので合わない。", "蓋": "物の覆いのことで、楽器の部品の本数を述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "弦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関のドアに弦をかけた。", "explanation": "ここは〈鍵〉の意味。ドアに鍵をかける使い方を、弦に置き換えた。〈弦〉は楽器の糸なので、ドアには使えない。"}, {"text": "新しい弦でフックを作った。", "explanation": "ここは〈針金〉の意味。細い金属の線で形を作る材料は〈針金〉で言う。〈弦〉は楽器に張る糸なので、フックには合わない。"}, {"text": "弦で肉を刺した。", "explanation": "ここは〈フォーク〉の意味。肉を刺す道具は〈フォーク〉で言う。〈弦〉は楽器の糸なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38740, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ギターは、指で弦に押さえて音を出す。", "corrected_sentence": "ギターは、指で弦を押さえて音を出す。", "error_description": "「押さえる」は目的語に「を」を取る。「に」は誤り。正しくは「弦を押さえて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38740, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ハープは弦を四十本以上あり、指ではじいて演奏する。", "corrected_sentence": "ハープは弦が四十本以上あり、指ではじいて演奏する。", "error_description": "「あり」の主語は「弦が」。「を」は誤り。正しくは「弦が四十本以上あり」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38741, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38741, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語の「が」。「弦が」が「おすすめだ」の主語にあたる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「弦をおすすめだ」は文の形が合わない。"}, {"text": "に", "is_correct": false, "explanation": "場所・相手の「に」。「弦におすすめだ」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手・共同の「と」。「弦とおすすめだ」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "主語の「が」。「弦が」が「おすすめだ」の主語にあたる。", "を": "目的語の「を」。「弦をおすすめだ」は文の形が合わない。", "に": "場所・相手の「に」。「弦におすすめだ」は不自然。", "と": "相手・共同の「と」。「弦とおすすめだ」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "と": "相手・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38741, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "弓や楽器などに張る、細くて丈夫な糸。また、三味線などの楽器の糸。", "primary_collocate": null, "pronunciation": "げん", "ipa": "ɡeɴ", "syllable_count": 2, "sentences": [{"text": "チェロの弦は太くて長いので、触ると振動が手に伝わる。", "target_word": "弦", "complexity_tier": "T3", "furigana": "チェロの弦[げん]は太[ふと]くて長[なが]いので、触[さわ]ると振動[しんどう]が手[て]に伝[つた]わる。", "sentence_source": "generated"}, {"text": "楽器の弦は、湿気が多い夏にさびやすい。", "target_word": "弦", "complexity_tier": "T3", "furigana": "楽器[がっき]の弦[げん]は、湿気[しっけ]が多[おお]い夏[なつ]にさびやすい。", "sentence_source": "generated"}, {"text": "切れた弦を結んで使うと、正しい音が出なくなる。", "target_word": "弦", "complexity_tier": "T3", "furigana": "切[き]れた弦[げん]を結[むす]んで使[つか]うと、正[ただ]しい音[おと]が出[で]なくなる。", "sentence_source": "generated"}, {"text": "兄はギターの弦を一本ずつ張りながら、音の高さを合わせた。", "target_word": "弦", "complexity_tier": "T3", "furigana": "兄[あに]はギターの弦[げん]を一本[いっぽん]ずつ張[は]りながら、音[おと]の高[たか]さを合[あ]わせた。", "sentence_source": "generated"}, {"text": "三味線の弦は絹の糸でできていて、やわらかい音がする。", "target_word": "弦", "complexity_tier": "T3", "furigana": "三味線[しゃみせん]の弦[げん]は絹[きぬ]の糸[いと]でできていて、やわらかい音[おと]がする。", "sentence_source": "generated"}, {"text": "弦が細いほど、高い音が出やすい。", "target_word": "弦", "complexity_tier": "T3", "furigana": "弦[げん]が細[ほそ]いほど、高[たか]い音[おと]が出[で]やすい。", "sentence_source": "generated"}, {"text": "演奏会の直前に弦が切れて、予備のギターに持ちかえた。", "target_word": "弦", "complexity_tier": "T3", "furigana": "演奏会[えんそうかい]の直前[ちょくぜん]に弦[げん]が切[き]れて、予備[よび]のギターに持[も]ちかえた。", "sentence_source": "generated"}, {"text": "店員さんは、初心者にはやわらかい弦がおすすめだと教えてくれた。", "target_word": "弦", "complexity_tier": "T3", "furigana": "店員[てんいん]さんは、初心者[しょしんしゃ]にはやわらかい弦[げん]がおすすめだと教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "ウクレレは弦が四本しかないので、ギターよりコードを押さえやすい。", "target_word": "弦", "complexity_tier": "T3", "furigana": "ウクレレは弦[げん]が四本しかないので、ギターよりコードを押さえやすい。", "sentence_source": "generated"}, {"text": "弦を新しくしたばかりなので、音がまだ安定しない。", "target_word": "弦", "complexity_tier": "T3", "furigana": "弦[げん]を新[あたら]しくしたばかりなので、音[おと]がまだ安定[あんてい]しない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "弦", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "楽器に張って音を出す、細くて丈夫な糸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1482d3a5-b226-445e-b588-4975f8b011fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38741, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弦", "is_correct": true, "explanation": "弓や楽器に張る細い糸のこと。「チェロの弦は太くて長い」に合う。"}, {"text": "楽譜", "is_correct": false, "explanation": "紙に書かれた曲のことで、太くて長い部品ではないので合わない。"}, {"text": "鍵盤", "is_correct": false, "explanation": "ピアノなどの押す部分で、チェロにはないので合わない。"}, {"text": "撥", "is_correct": false, "explanation": "弦を弾く道具で、太くて長い部品ではないので合わない。"}], "explanations": {"弦": "弓や楽器に張る細い糸のこと。「チェロの弦は太くて長い」に合う。", "楽譜": "紙に書かれた曲のことで、太くて長い部品ではないので合わない。", "鍵盤": "ピアノなどの押す部分で、チェロにはないので合わない。", "撥": "弦を弾く道具で、太くて長い部品ではないので合わない。"}, "sentence_index": 0, "correct_answer": "弦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バイオリンを弦でこすって弾いた。", "explanation": "ここは〈弓〉の意味。弦をこすって音を出す道具は〈弓〉で言う。〈弦〉は音を出す糸で、こする道具ではない。"}, {"text": "縫い物で、弦を通してボタンを付けた。", "explanation": "ここは〈糸〉の意味。縫い針に通す糸は〈糸〉で言う。〈弦〉は楽器に張る糸なので合わない。"}, {"text": "自転車を弦でつないだ。", "explanation": "ここは〈鎖〉の意味。金属の輪をつなぐくさりは〈鎖〉で言う。〈弦〉は楽器に張る糸で、物をつなぐには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38741, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指板", "is_correct": false, "explanation": "ギターの指で押さえる板で、切れる部品ではないので合わない。"}, {"text": "弦", "is_correct": true, "explanation": "弓や楽器に張る細い糸のこと。「演奏会の直前に弦が切れた」に合う。"}, {"text": "胴", "is_correct": false, "explanation": "楽器の本体のことで、切れて交換するものではないので合わない。"}, {"text": "蓋", "is_correct": false, "explanation": "物の覆いのことで、楽器の部品として切れる対象ではないので合わない。"}], "explanations": {"指板": "ギターの指で押さえる板で、切れる部品ではないので合わない。", "弦": "弓や楽器に張る細い糸のこと。「演奏会の直前に弦が切れた」に合う。", "胴": "楽器の本体のことで、切れて交換するものではないので合わない。", "蓋": "物の覆いのことで、楽器の部品として切れる対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "弦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弦でスープをすくった。", "explanation": "ここは〈お玉〉の意味。スープをすくう道具は〈お玉〉で言う。〈弦〉は楽器に張る糸なので、すくう道具には使わない。"}, {"text": "壊れた炊飯器の電源を、弦でつないで直した。", "explanation": "ここは〈電線〉の意味。電気を通す線は〈電線〉で言う。〈弦〉は楽器に張る糸なので、電源の配線には使わない。"}, {"text": "川で魚を弦で釣った。", "explanation": "ここは〈釣り竿〉の意味。魚を釣る道具は〈釣り竿〉で言う。〈弦〉は楽器の糸なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38741, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三味線は、弦に弾いて音を出す楽器だ。", "corrected_sentence": "三味線は、弦を弾いて音を出す楽器だ。", "error_description": "「弾く」は目的語に「を」を取る。「に」は誤り。正しくは「弦を弾いて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38741, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店員さんは、初心者に軽い弦が勧めた。", "corrected_sentence": "店員さんは、初心者に軽い弦を勧めた。", "error_description": "「勧める」は目的語に「を」を取る。「弦が」は主語になってしまい誤り。正しくは「弦を勧めた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38742, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「準備を」の「を」。「する」は目的語に「を」を取る。"}, {"text": "が", "is_correct": false, "explanation": "「準備が」は主語になり、「する」の目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、動作の対象とは合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」で、「準備からしている」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「準備を」の「を」。「する」は目的語に「を」を取る。", "が": "「準備が」は主語になり、「する」の目的語にならない。", "へ": "方向を表す「へ」で、動作の対象とは合わない。", "から": "起点を表す「から」で、「準備からしている」は不自然。"}, "error_tags": {"が": "主語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38742, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「電話を」の「を」。「する」は目的語に「を」を取る。"}, {"text": "の", "is_correct": false, "explanation": "「電話の」は名詞を修飾する「の」で、「する」の目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」で、動作の対象とは合わない。"}, {"text": "と", "is_correct": false, "explanation": "資格や引用を表す「と」で、「電話としている」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「電話を」の「を」。「する」は目的語に「を」を取る。", "の": "「電話の」は名詞を修飾する「の」で、「する」の目的語にならない。", "より": "比較を表す「より」で、動作の対象とは合わない。", "と": "資格や引用を表す「と」で、「電話としている」は不自然。"}, "error_tags": {"の": "連体修飾", "より": "比較", "と": "資格・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38742, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「して いる」は、いま やっている こと を いう ことば です。", "primary_collocate": null, "pronunciation": "するている", "ipa": "sɯɾɯteiɾɯ", "syllable_count": 6, "sentences": [{"text": "今、弟は部屋で宿題をしている。", "target_word": "している", "complexity_tier": "T3", "furigana": "今[いま]、弟[おとうと]は部屋[へや]で宿題[しゅくだい]をしている。", "sentence_source": "generated"}, {"text": "母は台所で料理の準備をしているところです。", "target_word": "している", "complexity_tier": "T3", "furigana": "母[はは]は台所[だいどころ]で料理[りょうり]の準備[じゅんび]をしているところです。", "sentence_source": "generated"}, {"text": "「いま何をしているの?」と友だちが電話で聞きました。", "target_word": "している", "complexity_tier": "T3", "furigana": "「いま何[なに]をしているの?」と友[とも]だちが電話[でんわ]で聞[き]きました。", "sentence_source": "generated"}, {"text": "兄は今、ガレージで車の掃除をしている。", "target_word": "している", "complexity_tier": "T3", "furigana": "兄[あに]は今[いま]、ガレージで車[くるま]の掃除[そうじ]をしている。", "sentence_source": "generated"}, {"text": "田中さんは窓のそばで、静かに読書をしているよ。", "target_word": "している", "complexity_tier": "T3", "furigana": "田中[たなか]さんは窓[まど]のそばで、静[しず]かに読書[どくしょ]をしているよ。", "sentence_source": "generated"}, {"text": "子どもたちは校庭でサッカーをしているので、声が聞こえます。", "target_word": "している", "complexity_tier": "T3", "furigana": "子[こ]どもたちは校庭[こうてい]でサッカーをしているので、声[こえ]が聞[き]こえます。", "sentence_source": "generated"}, {"text": "父は今、庭で水やりをしているから、あとで呼びます。", "target_word": "している", "complexity_tier": "T3", "furigana": "父[ちち]は今[いま]、庭[にわ]で水[みず]やりをしているから、あとで呼[よ]びます。", "sentence_source": "generated"}, {"text": "彼女は大きな声で電話をしているので、とてもうるさいです。", "target_word": "している", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大[おお]きな声[こえ]で電話[でんわ]をしているので、とてもうるさいです。", "sentence_source": "generated"}, {"text": "先生は職員室で、会議をしているはずです。", "target_word": "している", "complexity_tier": "T3", "furigana": "先生[せんせい]は職員室[しょくいんしつ]で、会議[かいぎ]をしているはずです。", "sentence_source": "generated"}, {"text": "今、隣の部屋で、だれかがピアノの練習をしているのが聞こえます。", "target_word": "している", "complexity_tier": "T3", "furigana": "今[いま]、隣[となり]の部屋[へや]で、だれかがピアノの練習[れんしゅう]をしているのが聞[き]こえます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "している", "label": "進行形"}, {"form": "しています", "label": "丁寧形"}, {"form": "していた", "label": "過去形"}, {"form": "していない", "label": "否定形"}, {"form": "していて", "label": "て形"}], "register": "中立", "sense_fingerprint": "今まさに行われている動作を表す「している」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c11be19-e1cc-49c2-a822-0ba302475d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38742, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "している", "is_correct": true, "explanation": "今まさに進行中の動作を表す形で、「今」と合う。"}, {"text": "して", "is_correct": false, "explanation": "て形のままでは文が終わらず、述語として成立しない。"}, {"text": "しながら", "is_correct": false, "explanation": "同時進行を表す接続の形で、ここでは文の述語にならない。"}, {"text": "しつつ", "is_correct": false, "explanation": "文語的な同時進行の接続形で、文末に置くと文が成立しない。"}], "explanations": {"している": "今まさに進行中の動作を表す形で、「今」と合う。", "して": "て形のままでは文が終わらず、述語として成立しない。", "しながら": "同時進行を表す接続の形で、ここでは文の述語にならない。", "しつつ": "文語的な同時進行の接続形で、文末に置くと文が成立しない。"}, "sentence_index": 0, "correct_answer": "している"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は今、無職をしている。", "explanation": "ここは〈無職でいる〉の意味。〈している〉は動作の進行を表すので、〈無職〉のような状態の名詞には合わない（「無職でいる」を使う）。"}, {"text": "さっき、宿題をしているところです。", "explanation": "ここは〈〜したところ（直前の完了）〉の意味。〈している〉は今まさに進行中を表すので、「さっき」の直前の出来事とは合わない。"}, {"text": "私は一度、スキューバダイビングをしている。", "explanation": "ここは〈〜したことがある（経験）〉の意味。〈している〉は今進行中の動作を表すので、「一度」の経験の話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38742, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "している", "is_correct": true, "explanation": "「から」の前で原因を述べる、進行中の動作の形。文として成立する。"}, {"text": "しよう", "is_correct": false, "explanation": "意志形で、「から」の前に置くと理由の文が成立しない。"}, {"text": "しそう", "is_correct": false, "explanation": "様態の語幹で、「そうだ」の形にしないと「から」の前に置けない。"}, {"text": "しろ", "is_correct": false, "explanation": "命令形で、理由を述べる「から」の前には立たない。"}], "explanations": {"している": "「から」の前で原因を述べる、進行中の動作の形。文として成立する。", "しよう": "意志形で、「から」の前に置くと理由の文が成立しない。", "しそう": "様態の語幹で、「そうだ」の形にしないと「から」の前に置けない。", "しろ": "命令形で、理由を述べる「から」の前には立たない。"}, "sentence_index": 6, "correct_answer": "している"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宿題は一瞬でしている。", "explanation": "ここは〈一瞬で終わらせる〉の意味。〈している〉は時間をかけて続く動作を表すので、一瞬で終わる話には合わない。"}, {"text": "彼はタバコをしている。", "explanation": "ここは〈タバコを吸う〉の意味。〈している〉は「タバコをする」とは言わず「吸っている」を使うので、ここでは合わない。"}, {"text": "レポートは明日までにしている。", "explanation": "ここは〈仕上げる〉の意味。〈している〉は今の進行を表すので、期限までに完成させる意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38742, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今、祖父は縁側で新聞を読むしている。", "corrected_sentence": "今、祖父は縁側で新聞を読んでいる。", "error_description": "誤: 読むしている（動詞の辞書形に直接「している」を付けている）／正: 読んでいる（「読む」をて形「読んで」にして「いる」を付ける）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "している", "is_correct": true, "explanation": "「今」と「ところです」で進行を表す、文中の形と一致する。"}, {"text": "しよう", "is_correct": false, "explanation": "意志形で、「ところです」の前には立たず文が成立しない。"}, {"text": "していない", "is_correct": false, "explanation": "否定形なので、「準備をしているところ」という肯定の進行と合わない。"}, {"text": "していて", "is_correct": false, "explanation": "て形で止まり、「ところです」で文を締められない。"}], "correct_form": "している", "base_form": "する", "form_label": "進行形", "sentence_index": 1, "explanations": {"している": "「今」と「ところです」で進行を表す、文中の形と一致する。", "しよう": "意志形で、「ところです」の前には立たず文が成立しない。", "していない": "否定形なので、「準備をしているところ」という肯定の進行と合わない。", "していて": "て形で止まり、「ところです」で文を締められない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38742, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今、妹は庭で花の水やりをしているます。", "corrected_sentence": "今、妹は庭で花の水やりをしています。", "error_description": "誤: している＋ます（「ている」に「ます」は続かない）／正: しています（丁寧形は「ています」）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "している", "is_correct": true, "explanation": "「ので」の前で、今の進行という文の意味と一致する形。"}, {"text": "していません", "is_correct": false, "explanation": "否定の丁寧形で、「うるさいです」と続く因果の文と矛盾する。"}, {"text": "していました", "is_correct": false, "explanation": "過去の丁寧形で、「今」と合わない。"}, {"text": "していよう", "is_correct": false, "explanation": "意志形で、「ので」の前に置くと文が成立しない。"}], "correct_form": "している", "base_form": "する", "form_label": "進行形", "sentence_index": 7, "explanations": {"している": "「ので」の前で、今の進行という文の意味と一致する形。", "していません": "否定の丁寧形で、「うるさいです」と続く因果の文と矛盾する。", "していました": "過去の丁寧形で、「今」と合わない。", "していよう": "意志形で、「ので」の前に置くと文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38744, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「腰を入れる」の目的語を示す「を」。慣用句の形として正しい。"}, {"text": "に", "is_correct": false, "explanation": "「腰に入れる」は慣用句として成り立たず、体の部位に何かを入れる意味になってしまう。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「腰へ入れる」は慣用句として意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「腰で入れる」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「腰を入れる」の目的語を示す「を」。慣用句の形として正しい。", "に": "「腰に入れる」は慣用句として成り立たず、体の部位に何かを入れる意味になってしまう。", "へ": "「へ」は方向を示すが、「腰へ入れる」は慣用句として意味が通らない。", "で": "「で」は手段や場所を示すが、「腰で入れる」では意味が通らない。"}, "error_tags": {"に": "位置・対象の格", "へ": "方向の格", "で": "手段・場所の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38744, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「腰を入れる」の目的語を示す「を」。慣用句として正しい。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示すが、「腰と入れる」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「腰から入れる」では慣用句の意味にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「腰より入れる」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「腰を入れる」の目的語を示す「を」。慣用句として正しい。", "と": "相手や引用を示すが、「腰と入れる」は成り立たない。", "から": "起点を示すが、「腰から入れる」では慣用句の意味にならない。", "より": "比較を示すが、「腰より入れる」は意味が通らない。"}, "error_tags": {"と": "相手・引用の格", "から": "起点の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38744, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "本気で身を入れ、しっかり力を込めて取り組むこと。", "primary_collocate": null, "pronunciation": "こしをいれる", "ipa": "koɕi o iɾeɾɯ", "syllable_count": 6, "sentences": [{"text": "今年の試験は腰を入れて勉強しないと、合格できない。", "target_word": "腰を入れて", "complexity_tier": "T3", "furigana": "今年[ことし]の試験[しけん]は腰[こし]を入[い]れて勉強[べんきょう]しないと、合格[ごうかく]できない。", "sentence_source": "generated"}, {"text": "彼は仕事に腰を入れてから、見違えるほど成績が上がった。", "target_word": "腰を入れて", "complexity_tier": "T3", "furigana": "彼[かれ]は仕事[しごと]に腰[こし]を入[い]れてから、見違[みちが]えるほど成績[せいせき]が上[あ]がった。", "sentence_source": "generated"}, {"text": "庭の草むしりは、腰を入れてやれば一日で終わる。", "target_word": "腰を入れて", "complexity_tier": "T3", "furigana": "庭[にわ]の草[くさ]むしりは、腰[こし]を入[い]れてやれば一日[いちにち]で終[お]わる。", "sentence_source": "generated"}, {"text": "掃除に腰を入れたので、部屋がとてもきれいになった。", "target_word": "腰を入れた", "complexity_tier": "T3", "furigana": "掃除[そうじ]に腰[こし]を入[い]れたので、部屋[へや]がとてもきれいになった。", "sentence_source": "generated"}, {"text": "そろそろ腰を入れて就職活動を始めたほうがいい。", "target_word": "腰を入れて", "complexity_tier": "T3", "furigana": "そろそろ腰[こし]を入[い]れて就職活動[しゅうしょくかつどう]を始[はじ]めたほうがいい。", "sentence_source": "generated"}, {"text": "先生に叱られてから、彼は練習に腰を入れるようになった。", "target_word": "腰を入れる", "complexity_tier": "T3", "furigana": "先生[せんせい]に叱[しか]られてから、彼[かれ]は練習[れんしゅう]に腰[こし]を入[い]れるようになった。", "sentence_source": "generated"}, {"text": "腰を入れて探さなかったので、なくした財布は見つからなかった。", "target_word": "腰を入れて", "complexity_tier": "T3", "furigana": "腰[こし]を入[い]れて探[さが]さなかったので、なくした財布[さいふ]は見[み]つからなかった。", "sentence_source": "generated"}, {"text": "母は腰を入れて料理を作り、家族を喜ばせた。", "target_word": "腰を入れて", "complexity_tier": "T3", "furigana": "母[はは]は腰[こし]を入[い]れて料理[りょうり]を作[つく]り、家族[かぞく]を喜[よろこ]ばせた。", "sentence_source": "generated"}, {"text": "彼女は何でも腰を入れて取り組む人で、途中で投げ出さない。", "target_word": "腰を入れて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は何[なん]でも腰[こし]を入[い]れて取[と]り組[く]む人[ひと]で、途中[とちゅう]で投[な]げ出[だ]さない。", "sentence_source": "generated"}, {"text": "腰を入れる気になれば、この宿題は一時間で終わるはずだ。", "target_word": "腰を入れる", "complexity_tier": "T3", "furigana": "腰[こし]を入[い]れる気[き]になれば、この宿題[しゅくだい]は一時間[いちじかん]で終[お]わるはずだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "腰を入れる", "label": "辞書形"}, {"form": "腰を入れて", "label": "て形"}, {"form": "腰を入れた", "label": "た形"}, {"form": "腰を入れない", "label": "ない形"}, {"form": "腰を入れれば", "label": "仮定形"}, {"form": "腰を入れよう", "label": "意志形"}], "register": "普通体（口語）", "sense_fingerprint": "慣用句。物事に本気で身を入れ、しっかり力を込めて取り組む。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38744, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腰を入れて", "is_correct": true, "explanation": "「腰を入れて勉強する」は本気で取り組むという意味で、試験の準備の文脈に合う。"}, {"text": "腰を抜かして", "is_correct": false, "explanation": "「腰を抜かす」は驚いて立てなくなる意味で、勉強の話には合わない。"}, {"text": "腰を折って", "is_correct": false, "explanation": "「腰を折る」は話や作業を途中で止めさせる意味で、ここでは文が成り立たない。"}, {"text": "腰を痛めて", "is_correct": false, "explanation": "「腰を痛める」は体を傷める意味で、勉強の取り組み方を表さないので文脈に合わない。"}], "explanations": {"腰を入れて": "「腰を入れて勉強する」は本気で取り組むという意味で、試験の準備の文脈に合う。", "腰を抜かして": "「腰を抜かす」は驚いて立てなくなる意味で、勉強の話には合わない。", "腰を折って": "「腰を折る」は話や作業を途中で止めさせる意味で、ここでは文が成り立たない。", "腰を痛めて": "「腰を痛める」は体を傷める意味で、勉強の取り組み方を表さないので文脈に合わない。"}, "sentence_index": 0, "correct_answer": "腰を入れて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ちょっと疲れたので、ベンチに腰を入れた。", "explanation": "「腰を下ろす」（座る）と混同している。〈腰を入れる〉は本気で取り組む意味なので、座る動作には使えない。"}, {"text": "彼は途中で話の腰を入れて、みんなの話が止まった。", "explanation": "「話の腰を折る」（話を途中でさえぎる）と混同している。〈腰を入れる〉は取り組む姿勢の意味で、話を止める意味では使えない。"}, {"text": "驚いて、その場で腰を入れてしまった。", "explanation": "「腰を抜かす」（驚いて立てなくなる）と混同している。〈腰を入れる〉は取り組む姿勢の意味なので、驚いた反応には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38744, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腰を入れて", "is_correct": true, "explanation": "「腰を入れて探す」は本気で探すという意味で、探さなかった理由を説明する文に合う。"}, {"text": "足を運んで", "is_correct": false, "explanation": "「足を運ぶ」は現地へ出向く意味で、探さなかった理由の文には合わない。"}, {"text": "手を広げて", "is_correct": false, "explanation": "「手を広げる」は両手を開く動作で、取り組みの意味にはならず文が成り立たない。"}, {"text": "足を入れて", "is_correct": false, "explanation": "「足を入れる」は慣用句ではなく、探す行為の説明として意味が通らない。"}], "explanations": {"腰を入れて": "「腰を入れて探す」は本気で探すという意味で、探さなかった理由を説明する文に合う。", "足を運んで": "「足を運ぶ」は現地へ出向く意味で、探さなかった理由の文には合わない。", "手を広げて": "「手を広げる」は両手を開く動作で、取り組みの意味にはならず文が成り立たない。", "足を入れて": "「足を入れる」は慣用句ではなく、探す行為の説明として意味が通らない。"}, "sentence_index": 6, "correct_answer": "腰を入れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "休日は、腰を入れてのんびり過ごす。", "explanation": "「力を抜く」（くつろぐ）と混同している。〈腰を入れる〉は本気で取り組む意味なので、のんびり休む文には合わない。"}, {"text": "重い荷物を運んだら、腰を入れて痛めてしまった。", "explanation": "「ケガをする」（体を傷める）と混同している。〈腰を入れる〉は取り組む姿勢の意味で、体の故障は表さない。"}, {"text": "重い腰を入れて、やっと宿題を始めた。", "explanation": "「重い腰を上げる」（ようやく動き出す）と混同している。〈腰を入れる〉は最初から本気になる意味なので、重い腰の表現とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38744, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年の面接は腰に入れて準備しないと、うまくいかない。", "corrected_sentence": "今年の面接は腰を入れて準備しないと、うまくいかない。", "error_description": "誤りは「腰に入れて」。「入れる」の対象は「を」で示すので、「腰を入れて」が正しい。「に」は位置や対象を示す格で、この慣用句では使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "腰を入れて", "is_correct": true, "explanation": "て形で「〜てから」と続き、取り組んだ後に成績が上がったという経緯を表すので正しい。"}, {"text": "腰を入れろ", "is_correct": false, "explanation": "命令形は相手への指示になり、過去の経緯を述べるこの文には合わない。"}, {"text": "腰を入れない", "is_correct": false, "explanation": "ない形は否定になり、実際に取り組んで成績が上がったという文の意味と逆になる。"}, {"text": "腰を入れれば", "is_correct": false, "explanation": "仮定形は条件を表すので、既に起きた経緯を述べるこの文には合わない。"}], "correct_form": "腰を入れて", "base_form": "腰を入れる", "form_label": "て形", "sentence_index": 1, "explanations": {"腰を入れて": "て形で「〜てから」と続き、取り組んだ後に成績が上がったという経緯を表すので正しい。", "腰を入れろ": "命令形は相手への指示になり、過去の経緯を述べるこの文には合わない。", "腰を入れない": "ない形は否定になり、実際に取り組んで成績が上がったという文の意味と逆になる。", "腰を入れれば": "仮定形は条件を表すので、既に起きた経緯を述べるこの文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38744, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の草取りは、腰を入れやれば午前中に終わるだろう。", "corrected_sentence": "庭の草取りは、腰を入れてやれば午前中に終わるだろう。", "error_description": "誤りは「入れやれば」。「腰を入れて」のて形が抜けており、「入れやれば」は活用が崩れて成り立たない。正しくは「腰を入れてやれば」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "腰を入れて", "is_correct": true, "explanation": "て形で「作り」「喜ばせた」と続き、料理に本気で取り組んだ様子を表すので正しい。"}, {"text": "腰を入れる", "is_correct": false, "explanation": "辞書形は文を言い切るため、「料理を作り」と続けられない。"}, {"text": "腰を入れよう", "is_correct": false, "explanation": "意志形は本人の意志を表すが、過去の出来事を述べるこの文には合わない。"}, {"text": "腰を入れろ", "is_correct": false, "explanation": "命令形は相手への指示になり、料理を作ったという過去の出来事には合わない。"}], "correct_form": "腰を入れて", "base_form": "腰を入れる", "form_label": "て形", "sentence_index": 7, "explanations": {"腰を入れて": "て形で「作り」「喜ばせた」と続き、料理に本気で取り組んだ様子を表すので正しい。", "腰を入れる": "辞書形は文を言い切るため、「料理を作り」と続けられない。", "腰を入れよう": "意志形は本人の意志を表すが、過去の出来事を述べるこの文には合わない。", "腰を入れろ": "命令形は相手への指示になり、料理を作ったという過去の出来事には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38746, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「葉っぱを集めて」で、集める対象を示す目的語。葉っぱに直接付く助詞。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、集める動作の対象は目的語なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すので、「葉っぱに集めて」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「葉っぱへ集めて」は文として不自然。"}], "correct_answer": "を", "explanations": {"を": "「葉っぱを集めて」で、集める対象を示す目的語。葉っぱに直接付く助詞。", "が": "「が」は主語を示すが、集める動作の対象は目的語なので合わない。", "に": "「に」は場所や相手を示すので、「葉っぱに集めて」は意味が通らない。", "へ": "「へ」は方向を示すので、「葉っぱへ集めて」は文として不自然。"}, "error_tags": {"が": "主語の誤り", "に": "場所・相手の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38746, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「葉っぱをはさんで」で、はさむ対象を示す目的語。葉っぱに直接付く助詞。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「葉っぱとはさんで」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「葉っぱからはさんで」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「葉っぱよりはさんで」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「葉っぱをはさんで」で、はさむ対象を示す目的語。葉っぱに直接付く助詞。", "と": "「と」は並列や相手を示すので、「葉っぱとはさんで」は不自然。", "から": "「から」は起点を示すので、「葉っぱからはさんで」は意味が通らない。", "より": "「より」は比較を示すので、「葉っぱよりはさんで」は文として成り立たない。"}, "error_tags": {"と": "並列・相手の誤り", "から": "起点の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38746, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木や草についている、うすくて平たいところです。", "primary_collocate": null, "pronunciation": "はっぱ", "ipa": "happa", "syllable_count": 3, "sentences": [{"text": "秋になると、木の葉っぱが赤や黄色に変わる。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "秋[あき]になると、木[き]の葉[は]っぱが赤[あか]や黄色[きいろ]に変[か]わる。", "sentence_source": "generated"}, {"text": "子どもたちは、公園で落ちた葉っぱを集めて遊んでいた。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、公園[こうえん]で落[お]ちた葉[は]っぱを集[あつ]めて遊[あそ]んでいた。", "sentence_source": "generated"}, {"text": "風が強かったので、庭が葉っぱだらけになった。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]かったので、庭[にわ]が葉[は]っぱだらけになった。", "sentence_source": "generated"}, {"text": "虫が食べたのか、この葉っぱには小さな穴が空いている。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "虫[むし]が食[た]べたのか、この葉[は]っぱには小[ちい]さな穴[あな]が空[あ]いている。", "sentence_source": "generated"}, {"text": "妹は大きな葉っぱを傘のように頭にのせて笑った。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "妹[いもうと]は大[おお]きな葉[は]っぱを傘[かさ]のように頭[あたま]にのせて笑[わら]った。", "sentence_source": "generated"}, {"text": "雨のあと、葉っぱの上に水のつぶが光っていた。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "雨[あめ]のあと、葉[は]っぱの上[うえ]に水[みず]のつぶが光[ひか]っていた。", "sentence_source": "generated"}, {"text": "冬は木に葉っぱが一枚も残っていなくて、さびしく見える。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "冬[ふゆ]は木[き]に葉[は]っぱが一枚[いちまい]も残[のこ]っていなくて、さびしく見[み]える。", "sentence_source": "generated"}, {"text": "本の間に葉っぱをはさんで、おし葉を作った。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "本[ほん]の間[あいだ]に葉[は]っぱをはさんで、おし葉[ば]を作[つく]った。", "sentence_source": "generated"}, {"text": "カエルが葉っぱの上でじっと動かずにいた。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "カエルが葉[は]っぱの上[うえ]でじっと動[うご]かずにいた。", "sentence_source": "generated"}, {"text": "ほうきで道の葉っぱをはいて、ごみ袋に入れた。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "ほうきで道[みち]の葉[は]っぱをはいて、ごみ袋[ぶくろ]に入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "葉っぱ", "label": "基本形"}], "register": "colloquial", "sense_fingerprint": "木や草についている薄くて平たい部分(日常語)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1482d3a5-b226-445e-b588-4975f8b011fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38746, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "葉っぱ", "is_correct": true, "explanation": "木の葉っぱを指し、秋になると赤や黄色に色づく対象として文に合う。"}, {"text": "幹", "is_correct": false, "explanation": "幹は木の太い部分で、秋に赤や黄色に変わる部位ではないので合わない。"}, {"text": "根", "is_correct": false, "explanation": "根は地中にあり、木の見た目が秋に色づく文脈には合わない。"}, {"text": "枝", "is_correct": false, "explanation": "枝は木の骨組みで、紅葉して木全体が赤や黄色に変わるのは葉なので合わない。"}], "explanations": {"葉っぱ": "木の葉っぱを指し、秋になると赤や黄色に色づく対象として文に合う。", "幹": "幹は木の太い部分で、秋に赤や黄色に変わる部位ではないので合わない。", "根": "根は地中にあり、木の見た目が秋に色づく文脈には合わない。", "枝": "枝は木の骨組みで、紅葉して木全体が赤や黄色に変わるのは葉なので合わない。"}, "sentence_index": 0, "correct_answer": "葉っぱ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桜の葉っぱが満開になって、公園が華やかになった。", "explanation": "ここは〈花〉の意味。満開は花が咲きそろう状態を言うので、葉っぱには使わない。"}, {"text": "りんごの葉っぱが熟して、甘くなった。", "explanation": "ここは〈実〉の意味。熟して甘くなるのは実で、葉っぱには当てはまらない。"}, {"text": "卵の葉っぱを割って、中身をボウルに出した。", "explanation": "ここは〈殻〉の意味。割るのは卵の殻で、葉っぱは割って中身を出すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38746, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "葉っぱ", "is_correct": true, "explanation": "「一枚も残っていなくて」と数えられる葉に合う正解。"}, {"text": "実", "is_correct": false, "explanation": "実は「一枚」と数えないので、「一枚も残っていなくて」とは合わない。"}, {"text": "種", "is_correct": false, "explanation": "種は「一枚」と数えず、冬の木に残るものとしても文脈に合わない。"}, {"text": "芽", "is_correct": false, "explanation": "芽は「一枚」と数えず、冬に木に残っていないという文に合わない。"}], "explanations": {"葉っぱ": "「一枚も残っていなくて」と数えられる葉に合う正解。", "実": "実は「一枚」と数えないので、「一枚も残っていなくて」とは合わない。", "種": "種は「一枚」と数えず、冬の木に残るものとしても文脈に合わない。", "芽": "芽は「一枚」と数えず、冬に木に残っていないという文に合わない。"}, "sentence_index": 6, "correct_answer": "葉っぱ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "バケツの葉っぱを汲んで、植木にかけた。", "explanation": "ここは〈水〉の意味。汲むのは液体で、葉っぱは汲める対象ではないので合わない。"}, {"text": "寝坊して、葉っぱをとかす時間がなかった。", "explanation": "ここは〈髪〉の意味。とかすのは髪で、葉っぱはとかす対象にならないので合わない。"}, {"text": "雲が切れて、葉っぱが晴れてきた。", "explanation": "ここは〈空〉の意味。晴れるのは空や天気で、葉っぱは晴れる対象ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38746, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝露が乾くと、庭の葉っぱを日差しを受けて光る。", "corrected_sentence": "朝露が乾くと、庭の葉っぱが日差しを受けて光る。", "error_description": "誤り：「葉っぱを」。正しくは「葉っぱが」。葉っぱは「光る」の主語なので「が」を使う。「を」は目的語に付く助詞で、ここでは不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38746, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強風で木の葉っぱが倒れた。", "corrected_sentence": "強風で木の葉っぱが舞い落ちた。", "error_description": "誤り：「倒れた」。正しくは「舞い落ちた」。倒れるのは木や人などの立つものに使い、風で落ちる葉っぱには「舞い落ちる」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
