INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38747, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「葉っぱの緑色」で、緑色が葉っぱのものであることを示す連体修飾の「の」。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「葉っぱへ緑色は」は修飾関係が成り立たず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「葉っぱから緑色」は修飾関係にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「葉っぱより緑色」は文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「葉っぱの緑色」で、緑色が葉っぱのものであることを示す連体修飾の「の」。", "へ": "「へ」は方向を示すので、「葉っぱへ緑色は」は修飾関係が成り立たず不自然。", "から": "「から」は起点を示すので、「葉っぱから緑色」は修飾関係にならない。", "より": "「より」は比較を示すので、「葉っぱより緑色」は文の意味が通らない。"}, "error_tags": {"から": "起点の誤り", "より": "比較の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38747, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の茎から生えている、薄くて平たい部分。光合成や呼吸をする重要な器官。", "primary_collocate": null, "pronunciation": "はっぱ", "ipa": "happa", "syllable_count": 3, "sentences": [{"text": "葉っぱは太陽の光を受けて、養分を作っている。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "葉[は]っぱは太陽[たいよう]の光[ひかり]を受[う]けて、養分[ようぶん]を作[つく]っている。", "sentence_source": "generated"}, {"text": "水が足りないと、葉っぱがしおれて元気がなくなる。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "水[みず]が足[た]りないと、葉[は]っぱがしおれて元気[げんき]がなくなる。", "sentence_source": "generated"}, {"text": "先生は、葉っぱの裏にある小さな穴から水分が出ると説明した。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、葉[は]っぱの裏[うら]にある小[ちい]さな穴[あな]から水分[すいぶん]が出[で]ると説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この植物は、葉っぱが厚くて水をためることができる。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "この植物[しょくぶつ]は、葉[は]っぱが厚[あつ]くて水[みず]をためることができる。", "sentence_source": "generated"}, {"text": "葉っぱが黄色くなってきたら、肥料が足りないサインかもしれない。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "葉[は]っぱが黄色[きいろ]くなってきたら、肥料[ひりょう]が足[た]りないサインかもしれない。", "sentence_source": "generated"}, {"text": "虫めがねで葉っぱを見ると、細い筋が何本も通っているのが分かる。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "虫[むし]めがねで葉[は]っぱを見[み]ると、細[ほそ]い筋[すじ]が何本[なんぼん]も通[とお]っているのが分[わ]かる。", "sentence_source": "generated"}, {"text": "日当たりの悪い部屋では、葉っぱが小さくなりがちだ。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "日当[ひあ]たりの悪[わる]い部屋[へや]では、葉[は]っぱが小[ちい]さくなりがちだ。", "sentence_source": "generated"}, {"text": "葉っぱの緑色は、葉緑素という色素のせいだ。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "葉[は]っぱの緑色[みどりいろ]は、葉緑素[ようりょくそ]という色素[しきそ]のせいだ。", "sentence_source": "generated"}, {"text": "植物は葉っぱで息をして、空気中の二酸化炭素を取り入れる。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は葉[は]っぱで息[いき]をして、空気中[くうきちゅう]の二酸化炭素[にさんかたんそ]を取[と]り入[い]れる。", "sentence_source": "generated"}, {"text": "葉っぱに霧吹きで水をかけると、ほこりが落ちて育ちがよくなる。", "target_word": "葉っぱ", "complexity_tier": "T3", "furigana": "葉[は]っぱに霧吹[きりふ]きで水[みず]をかけると、ほこりが落[お]ちて育[そだ]ちがよくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "葉っぱ", "label": "基本形"}], "register": "colloquial", "sense_fingerprint": "植物の茎から生え、光合成や呼吸をする器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: 虫めがね (Zipf 1.44)']::text[], '1482d3a5-b226-445e-b588-4975f8b011fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38747, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "葉っぱ", "is_correct": true, "explanation": "植物の茎から生え、光合成で養分を作る器官として文に合う。"}, {"text": "根", "is_correct": false, "explanation": "根は地中で水や養分を吸う器官で、光を受けて養分を作ってはいないので合わない。"}, {"text": "土", "is_correct": false, "explanation": "土は植物を支える基盤で、光を受けて養分を作るものではないので合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は光を受けて養分を作らないので、この文の主語として意味をなさない。"}], "explanations": {"葉っぱ": "植物の茎から生え、光合成で養分を作る器官として文に合う。", "根": "根は地中で水や養分を吸う器官で、光を受けて養分を作ってはいないので合わない。", "土": "土は植物を支える基盤で、光を受けて養分を作るものではないので合わない。", "石": "石は光を受けて養分を作らないので、この文の主語として意味をなさない。"}, "sentence_index": 0, "correct_answer": "葉っぱ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "葉っぱが土の中に深く伸びて、水を吸い上げる。", "explanation": "ここは〈根〉の意味。土の中に伸びて水を吸い上げるのは根で、葉っぱには合わない。"}, {"text": "葉っぱが咲いて、ハチが蜜を集めに来る。", "explanation": "ここは〈花〉の意味。咲くのは花で、葉っぱは咲かないので合わない。"}, {"text": "葉っぱが熟して、甘い香りを放つ。", "explanation": "ここは〈実〉の意味。熟して香りを放つのは実で、葉っぱには当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38747, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "葉っぱ", "is_correct": true, "explanation": "日当たりが悪いと育ちが悪くなり小さくなる、植物の葉として文に合う。"}, {"text": "樹液", "is_correct": false, "explanation": "樹液は木の中を流れる液で、部屋の日当たりで小さくなる対象ではないので合わない。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉は植物の粒状の細胞で、日当たりの悪い部屋で小さくなるものとして文に合わない。"}, {"text": "落ち葉", "is_correct": false, "explanation": "落ち葉は地面に落ちた葉で、部屋の中で育って小さくなるものではないので合わない。"}], "explanations": {"葉っぱ": "日当たりが悪いと育ちが悪くなり小さくなる、植物の葉として文に合う。", "樹液": "樹液は木の中を流れる液で、部屋の日当たりで小さくなる対象ではないので合わない。", "花粉": "花粉は植物の粒状の細胞で、日当たりの悪い部屋で小さくなるものとして文に合わない。", "落ち葉": "落ち葉は地面に落ちた葉で、部屋の中で育って小さくなるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "葉っぱ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "悲しくて、葉っぱがあふれ出した。", "explanation": "ここは〈涙〉の意味。あふれ出すのは涙で、葉っぱはあふれないので合わない。"}, {"text": "けがをして、葉っぱが止まらなかった。", "explanation": "ここは〈血〉の意味。止まらないのは出血した血で、葉っぱには当てはまらない。"}, {"text": "大声で、葉っぱを張り上げて歌った。", "explanation": "ここは〈声〉の意味。張り上げるのは声で、葉っぱを張り上げることはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38747, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の強い日差しの下で、葉っぱを光を受けて養分を作る。", "corrected_sentence": "夏の強い日差しの下で、葉っぱが光を受けて養分を作る。", "error_description": "誤り：「葉っぱを」。正しくは「葉っぱが」。「受けて」「作る」の主語は葉っぱなので「が」を使う。同じ文に「を」が二つ続くので不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38747, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋の終わりに、庭の葉っぱが一斉に咲いた。", "corrected_sentence": "秋の終わりに、庭の葉っぱが一斉に落ちた。", "error_description": "誤り：「咲いた」。正しくは「落ちた」。咲くのは花で、葉っぱは咲かない。秋に葉っぱが一斉に散るときは「落ちる」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c8ee04-8c21-4771-84a0-07750615aade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38750, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「陰に入る」の「に」。「入る」は到達点に「に」を取る。"}, {"text": "が", "is_correct": false, "explanation": "「陰が入って」は主語になり、「入る」の場所を表さない。"}, {"text": "を", "is_correct": false, "explanation": "「陰を入って」は対象の「を」で、「入る」の場所を表せない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用の「と」で、「陰と入って」は不自然。"}], "correct_answer": "に", "explanations": {"に": "「陰に入る」の「に」。「入る」は到達点に「に」を取る。", "が": "「陰が入って」は主語になり、「入る」の場所を表さない。", "を": "「陰を入って」は対象の「を」で、「入る」の場所を表せない。", "と": "並列や引用の「と」で、「陰と入って」は不自然。"}, "error_tags": {"が": "主語", "を": "対象", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38750, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「家の陰で暗い」の「で」。陰が暗い理由・場所を表す。"}, {"text": "の", "is_correct": false, "explanation": "「陰の暗い」は名詞を修飾する形になり、文の意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、「陰へ暗い」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「陰に暗い」は形容詞に「に」が付かず非文。"}], "correct_answer": "で", "explanations": {"で": "「家の陰で暗い」の「で」。陰が暗い理由・場所を表す。", "の": "「陰の暗い」は名詞を修飾する形になり、文の意味が通らない。", "へ": "方向を表す「へ」で、「陰へ暗い」は成り立たない。", "に": "「陰に暗い」は形容詞に「に」が付かず非文。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "に": "位置・結果"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38750, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ひかりが あたらない ところ。", "primary_collocate": null, "pronunciation": "かげ", "ipa": "kaɡe", "syllable_count": 2, "sentences": [{"text": "暑いので、木の陰で少し休みましょう。", "target_word": "陰", "complexity_tier": "T3", "furigana": "暑[あつ]いので、木[き]の陰[かげ]で少[すこ]し休[やす]みましょう。", "sentence_source": "generated"}, {"text": "犬は建物の陰に入って、昼寝をしています。", "target_word": "陰", "complexity_tier": "T3", "furigana": "犬[いぬ]は建物[たてもの]の陰[かげ]に入[はい]って、昼寝[ひるね]をしています。", "sentence_source": "generated"}, {"text": "大きな木の陰は、夏でも涼しいです。", "target_word": "陰", "complexity_tier": "T3", "furigana": "大[おお]きな木[き]の陰[かげ]は、夏[なつ]でも涼[すず]しいです。", "sentence_source": "generated"}, {"text": "子どもは壁の陰に座って、友だちを待っていました。", "target_word": "陰", "complexity_tier": "T3", "furigana": "子[こ]どもは壁[かべ]の陰[かげ]に座[すわ]って、友[とも]だちを待[ま]っていました。", "sentence_source": "generated"}, {"text": "太陽が強いから、大きな屋根の陰に入ってください。", "target_word": "陰", "complexity_tier": "T3", "furigana": "太陽[たいよう]が強[つよ]いから、大[おお]きな屋根[やね]の陰[かげ]に入[はい]ってください。", "sentence_source": "generated"}, {"text": "山の陰になっている村は、冬になると雪が長く残ります。", "target_word": "陰", "complexity_tier": "T3", "furigana": "山[やま]の陰[かげ]になっている村[むら]は、冬[ふゆ]になると雪[ゆき]が長[なが]く残[のこ]ります。", "sentence_source": "generated"}, {"text": "車の陰で、小さい猫が涼んでいました。", "target_word": "陰", "complexity_tier": "T3", "furigana": "車[くるま]の陰[かげ]で、小[ちい]さい猫[ねこ]が涼[すず]んでいました。", "sentence_source": "generated"}, {"text": "この庭は家の陰で暗いので、花が育ちません。", "target_word": "陰", "complexity_tier": "T3", "furigana": "この庭[にわ]は家[いえ]の陰[かげ]で暗[くら]いので、花[はな]が育[そだ]ちません。", "sentence_source": "generated"}, {"text": "ビルの陰に入ると、急に風が冷たく感じました。", "target_word": "陰", "complexity_tier": "T3", "furigana": "ビルの陰[かげ]に入[はい]ると、急[きゅう]に風[かぜ]が冷[つめ]たく感[かん]じました。", "sentence_source": "generated"}, {"text": "荷物を陰に置いておけば、中のチョコレートは溶けにくいです。", "target_word": "陰", "complexity_tier": "T3", "furigana": "荷物[にもつ]を陰[かげ]に置[お]いておけば、中[なか]のチョコレートは溶[と]けにくいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "陰", "label": "基本形"}], "register": "中立", "sense_fingerprint": "光が当たらない暗い場所（日陰）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c11be19-e1cc-49c2-a822-0ba302475d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38750, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陰", "is_correct": true, "explanation": "「木の陰で」は、光が当たらない場所を表し、文脈に合う。"}, {"text": "風", "is_correct": false, "explanation": "風は空気なので、「木の風で休む」のように場所を表せない。"}, {"text": "雪", "is_correct": false, "explanation": "雪は場所として使えず、「木の雪で休む」は不自然。"}, {"text": "雲", "is_correct": false, "explanation": "雲は場所として使えず、「木の雲で休む」は成り立たない。"}], "explanations": {"陰": "「木の陰で」は、光が当たらない場所を表し、文脈に合う。", "風": "風は空気なので、「木の風で休む」のように場所を表せない。", "雪": "雪は場所として使えず、「木の雪で休む」は不自然。", "雲": "雲は場所として使えず、「木の雲で休む」は成り立たない。"}, "sentence_index": 0, "correct_answer": "陰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は陰が薄くて、クラスではあまり目立たない。", "explanation": "ここは〈影が薄い（存在感がない）〉の意味。〈陰〉は光の当たらない場所を表すので、人の存在感の話には使えない。"}, {"text": "この部屋は窓が大きいので、陰が多い。", "explanation": "ここは〈光の当たらない暗い場所〉の意味。窓が大きいと光がよく入るので、〈陰〉が多いという内容とは矛盾する。"}, {"text": "彼は性格に陰が多く、いつも明るく笑っている。", "explanation": "ここは〈陰気〉の意味。〈陰〉は光の当たらない場所を指すので、性格の暗さを表す語としては使わず、〈陰気〉と混同している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38750, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陰", "is_correct": true, "explanation": "「車の陰で」は、光が当たらない場所を表し、文脈に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は場所として使えず、「車の雨で」は成り立たない。"}, {"text": "霧", "is_correct": false, "explanation": "霧は場所として使えず、「車の霧で涼む」は不自然。"}, {"text": "波", "is_correct": false, "explanation": "波は場所として使えず、「車の波で」は成り立たない。"}], "explanations": {"陰": "「車の陰で」は、光が当たらない場所を表し、文脈に合う。", "雨": "雨は場所として使えず、「車の雨で」は成り立たない。", "霧": "霧は場所として使えず、「車の霧で涼む」は不自然。", "波": "波は場所として使えず、「車の波で」は成り立たない。"}, "sentence_index": 6, "correct_answer": "陰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁に人の陰が映っている。", "explanation": "ここは〈影〉の意味（物に映る形）。〈陰〉は光の当たらない場所を指すので、映る影には使わない。"}, {"text": "月明かりで、庭の陰が明るく輝いていた。", "explanation": "ここは〈光〉の意味。〈陰〉は光が当たらない場所を表すので、自ら明るく輝く様子には使えない。"}, {"text": "窓から陰が差し込んだ。", "explanation": "ここは〈日差し〉の意味。〈陰〉は光が当たらないことを表すので、差し込むものとして使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38750, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "犬は庭の木の陰を休んでいました。", "corrected_sentence": "犬は庭の木の陰で休んでいました。", "error_description": "誤: 陰を（「休む」は場所を表す「で」を取る）／正: 陰で（場所を表す「で」＋「休む」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38750, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の午後、子どもたちは木の陰で入って休みました。", "corrected_sentence": "夏の午後、子どもたちは木の陰に入って休みました。", "error_description": "誤: 陰で（「入る」の着点は「に」）／正: 陰に（着点を表す「に」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38754, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不味い", "is_correct": true, "explanation": "〈おいしい〉の対義語（味が悪い）。ここでは食べ物の味が悪いという意味で「美味しくない」と合う。"}, {"text": "甘い", "is_correct": false, "explanation": "味の種類を表す形容詞で、美味しいの対義語ではないので不適切。"}, {"text": "辛い", "is_correct": false, "explanation": "味の種類（辛味）を表す形容詞で、美味しいの対義語ではないので不適切。"}, {"text": "美しい", "is_correct": false, "explanation": "見た目の美しさを表す形容詞で、美味しいの対義語ではないので不適切。"}], "correct_answer": "不味い", "explanations": {"不味い": "〈おいしい〉の対義語（味が悪い）。ここでは食べ物の味が悪いという意味で「美味しくない」と合う。", "甘い": "味の種類を表す形容詞で、美味しいの対義語ではないので不適切。", "辛い": "味の種類（辛味）を表す形容詞で、美味しいの対義語ではないので不適切。", "美しい": "見た目の美しさを表す形容詞で、美味しいの対義語ではないので不適切。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
