INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38754, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "たべものが とても いい あじが すること", "primary_collocate": null, "pronunciation": "おいしい", "ipa": "oiɕiː", "syllable_count": 4, "sentences": [{"text": "この店のラーメンはとても美味しいので、毎週食べに来ます。", "target_word": "美味しい", "complexity_tier": "T3", "furigana": "この店(みせ)のラーメンはとても美味(おい)しいので、毎週(まいしゅう)食(た)べに来(き)ます。", "sentence_source": "generated"}, {"text": "母が作ったカレーは美味しくて、三杯もおかわりしました。", "target_word": "美味しくて", "complexity_tier": "T3", "furigana": "母(はは)が作(つく)ったカレーは美味(おい)しくて、三杯(さんばい)もおかわりしました。", "sentence_source": "generated"}, {"text": "昨日の晩ご飯は美味しかったので、レシピを教えてもらいました。", "target_word": "美味しかった", "complexity_tier": "T3", "furigana": "昨日(きのう)の晩(ばん)ご飯(はん)は美味(おい)しかったので、レシピを教(おし)えてもらいました。", "sentence_source": "generated"}, {"text": "冷めたスープは美味しくないから、温め直してください。", "target_word": "美味しくない", "complexity_tier": "T3", "furigana": "冷(さ)めたスープは美味(おい)しくないから、温(あたた)め直(なお)してください。", "sentence_source": "generated"}, {"text": "取れたての野菜は、甘くて美味しい。", "target_word": "美味しい", "complexity_tier": "T3", "furigana": "取(と)れたての野菜(やさい)は、甘(あま)くて美味(おい)しい。", "sentence_source": "generated"}, {"text": "この果物は見た目はきれいだが、あまり美味しくなかった。", "target_word": "美味しくなかった", "complexity_tier": "T3", "furigana": "この果物(くだもの)は見(み)た目(め)はきれいだが、あまり美味(おい)しくなかった。", "sentence_source": "generated"}, {"text": "美味しいパンを買うために、朝早くパン屋に並びました。", "target_word": "美味しい", "complexity_tier": "T3", "furigana": "美味(おい)しいパンを買(か)うために、朝早(あさはや)くパン屋(や)に並(なら)びました。", "sentence_source": "generated"}, {"text": "温かい味噌汁は、寒い日にはいっそう美味しく感じます。", "target_word": "美味しく", "complexity_tier": "T3", "furigana": "温(あたた)かい味噌汁(みそしる)は、寒(さむ)い日(ひ)にはいっそう美味(おい)しく感(かん)じます。", "sentence_source": "generated"}, {"text": "友達が焼いたクッキーは、お店のものより美味しいです。", "target_word": "美味しい", "complexity_tier": "T3", "furigana": "友達(ともだち)が焼(や)いたクッキーは、お店(みせ)のものより美味(おい)しいです。", "sentence_source": "generated"}, {"text": "値段が高くても、美味しければ買います。", "target_word": "美味しければ", "complexity_tier": "T3", "furigana": "値段(ねだん)が高(たか)くても、美味(おい)しければ買(か)います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "美味しい", "label": "終止形・連体形"}, {"form": "美味しく", "label": "連用形"}, {"form": "美味しかった", "label": "過去形"}, {"form": "美味しくない", "label": "否定形"}, {"form": "美味しければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "食べ物の味がとても良いこと(味覚の評価)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38754, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美味しい", "is_correct": true, "explanation": "い形容詞の終止形。「とても美味しいので」と、ラーメンの味が良いことを理由として述べる。"}, {"text": "美味しく", "is_correct": false, "explanation": "連用形。「とても美味しくので」と続けると不自然で、「ので」の前に終止形が必要。"}, {"text": "美味しさ", "is_correct": false, "explanation": "名詞形で、「とても美味しさので」では形容詞として続かない。"}, {"text": "美味", "is_correct": false, "explanation": "名詞で、「とても美味ので」と形容詞の位置に続かない。"}], "explanations": {"美味しい": "い形容詞の終止形。「とても美味しいので」と、ラーメンの味が良いことを理由として述べる。", "美味しく": "連用形。「とても美味しくので」と続けると不自然で、「ので」の前に終止形が必要。", "美味しさ": "名詞形で、「とても美味しさので」では形容詞として続かない。", "美味": "名詞で、「とても美味ので」と形容詞の位置に続かない。"}, "sentence_index": 0, "correct_answer": "美味しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この説明書は、とても美味しい。", "explanation": "ここは〈分かりやすい〉の意味。説明書のわかりやすさには「美味しい」は使わず、食べ物の味の評価にだけ使うので合わない。"}, {"text": "今日の天気は美味しい。", "explanation": "ここは〈穏やか〉の意味。天気の様子には「美味しい」は使わず、食べ物の味の評価にだけ使うので合わない。"}, {"text": "その絵は本当に美味しい。", "explanation": "ここは〈美しい〉の意味。絵の見た目の評価には「美味しい」は使わず、味が良いことにだけ使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38754, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美味しい", "is_correct": true, "explanation": "い形容詞の終止形で、名詞「パン」を修飾する形。「美味しいパン」として文意に合う。"}, {"text": "美味しくても", "is_correct": false, "explanation": "譲歩の形で、名詞を修飾できず、「美味しくてもパン」は続かない。"}, {"text": "美味しそうに", "is_correct": false, "explanation": "副詞形で、名詞「パン」を直接修飾できず、「美味しそうにパン」は不自然。"}, {"text": "美味しかったら", "is_correct": false, "explanation": "条件形で、名詞を修飾できず、「美味しかったらパン」は続かない。"}], "explanations": {"美味しい": "い形容詞の終止形で、名詞「パン」を修飾する形。「美味しいパン」として文意に合う。", "美味しくても": "譲歩の形で、名詞を修飾できず、「美味しくてもパン」は続かない。", "美味しそうに": "副詞形で、名詞「パン」を直接修飾できず、「美味しそうにパン」は不自然。", "美味しかったら": "条件形で、名詞を修飾できず、「美味しかったらパン」は続かない。"}, "sentence_index": 6, "correct_answer": "美味しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この靴は、とても美味しい。", "explanation": "ここは〈丈夫〉の意味。靴の強さには「美味しい」は使わず、食べ物の味にだけ使うので合わない。"}, {"text": "この部屋は、いつも美味しい。", "explanation": "ここは〈静か〉の意味。部屋の静けさには「美味しい」は使わず、食べ物の味の評価にだけ使うので合わない。"}, {"text": "夜遅くまで働いて、私はとても美味しい。", "explanation": "ここは〈眠い〉の意味。自分の眠気には「美味しい」は使わず、食べ物の味の評価にだけ使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38754, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この魚は、とても美味しだ。", "corrected_sentence": "この魚は、とても美味しい。", "error_description": "「美味しい」はい形容詞なので、「だ」ではなく「い」で言い切る。「美味しだ」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "美味しくて", "is_correct": true, "explanation": "て形の連用形。「美味しくて、三杯もおかわりした」と理由や並列でつながる形。"}, {"text": "美味しかった", "is_correct": false, "explanation": "過去形で、て形の代わりに使うと文のつながりが「〜した」と合わず、因果関係が崩れる。"}, {"text": "美味しくない", "is_correct": false, "explanation": "否定形。味が悪いことになり、「三杯もおかわりした」と矛盾する。"}, {"text": "美味しさ", "is_correct": false, "explanation": "名詞形で、動詞や文へ続けられず、文が途中で切れる。"}], "correct_form": "美味しくて", "base_form": "美味しい", "form_label": "て形（連用形）", "sentence_index": 1, "explanations": {"美味しくて": "て形の連用形。「美味しくて、三杯もおかわりした」と理由や並列でつながる形。", "美味しかった": "過去形で、て形の代わりに使うと文のつながりが「〜した」と合わず、因果関係が崩れる。", "美味しくない": "否定形。味が悪いことになり、「三杯もおかわりした」と矛盾する。", "美味しさ": "名詞形で、動詞や文へ続けられず、文が途中で切れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38754, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "そのケーキは、家族みんなで食べて美味しいかった。", "corrected_sentence": "そのケーキは、家族みんなで食べて美味しかった。", "error_description": "い形容詞の過去形は「美味しかった」。「美味しいかった」は語幹に余計な「い」が残った誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "美味しく", "is_correct": true, "explanation": "連用形。「いっそう美味しく感じます」と動詞「感じます」を修飾する副詞用法で文意に合う。"}, {"text": "美味しい", "is_correct": false, "explanation": "終止形。「いっそう美味しい感じます」と動詞を修飾できず、文法的に不自然。"}, {"text": "美味しかったら", "is_correct": false, "explanation": "条件形で、動詞「感じます」を修飾できず、文が成り立たない。"}, {"text": "美味しくなかった", "is_correct": false, "explanation": "否定過去形。「いっそう美味しくなかった」と感じると、評価が逆になり文意が合わない。"}], "correct_form": "美味しく", "base_form": "美味しい", "form_label": "連用形（副詞用法）", "sentence_index": 7, "explanations": {"美味しく": "連用形。「いっそう美味しく感じます」と動詞「感じます」を修飾する副詞用法で文意に合う。", "美味しい": "終止形。「いっそう美味しい感じます」と動詞を修飾できず、文法的に不自然。", "美味しかったら": "条件形で、動詞「感じます」を修飾できず、文が成り立たない。", "美味しくなかった": "否定過去形。「いっそう美味しくなかった」と感じると、評価が逆になり文意が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38755, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不味い", "is_correct": true, "explanation": "〈おいしい〉の対義語（味が悪い）。ここでは食べ物の味が悪いという意味で合う。"}, {"text": "甘い", "is_correct": false, "explanation": "味の種類を表す形容詞で、美味しいの対義語ではないので不適切。"}, {"text": "辛い", "is_correct": false, "explanation": "味の種類（辛味）を表す形容詞で、美味しいの対義語ではないので不適切。"}, {"text": "美しい", "is_correct": false, "explanation": "見た目の美しさを表す形容詞で、美味しいの対義語ではないので不適切。"}], "correct_answer": "不味い", "explanations": {"不味い": "〈おいしい〉の対義語（味が悪い）。ここでは食べ物の味が悪いという意味で合う。", "甘い": "味の種類を表す形容詞で、美味しいの対義語ではないので不適切。", "辛い": "味の種類（辛味）を表す形容詞で、美味しいの対義語ではないので不適切。", "美しい": "見た目の美しさを表す形容詞で、美味しいの対義語ではないので不適切。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38755, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不味い", "is_correct": true, "explanation": "〈おいしい〉の対義語（味が悪い）。ここでは食べ物の味が悪いという意味で合う。"}, {"text": "固い", "is_correct": false, "explanation": "硬さを表す形容詞で、美味しいの対義語ではないので不適切。"}, {"text": "軽い", "is_correct": false, "explanation": "重さを表す形容詞で、美味しいの対義語ではないので不適切。"}, {"text": "高い", "is_correct": false, "explanation": "値段や高さを表す形容詞で、美味しいの対義語ではないので不適切。"}], "correct_answer": "不味い", "explanations": {"不味い": "〈おいしい〉の対義語（味が悪い）。ここでは食べ物の味が悪いという意味で合う。", "固い": "硬さを表す形容詞で、美味しいの対義語ではないので不適切。", "軽い": "重さを表す形容詞で、美味しいの対義語ではないので不適切。", "高い": "値段や高さを表す形容詞で、美味しいの対義語ではないので不適切。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38755, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "食べ物の味が良くて、満足できる様子", "primary_collocate": null, "pronunciation": "おいしい", "ipa": "oiɕiː", "syllable_count": 4, "sentences": [{"text": "この店の天ぷらは衣が軽くて、とても美味しいです。", "target_word": "美味しい", "complexity_tier": "T3", "furigana": "この店(みせ)の天(てん)ぷらは衣(ころも)が軽(かる)くて、とても美味(おい)しいです。", "sentence_source": "generated"}, {"text": "寒い朝に飲む温かいお茶は、格別に美味しい。", "target_word": "美味しい", "complexity_tier": "T3", "furigana": "寒(さむ)い朝(あさ)に飲(の)む温(あたた)かいお茶(ちゃ)は、格別(かくべつ)に美味(おい)しい。", "sentence_source": "generated"}, {"text": "母の手料理は美味しくて、いつも全部食べてしまいます。", "target_word": "美味しくて", "complexity_tier": "T3", "furigana": "母(はは)の手料理(てりょうり)は美味(おい)しくて、いつも全部(ぜんぶ)食(た)べてしまいます。", "sentence_source": "generated"}, {"text": "昨夜のお寿司が美味しかったので、また行きたいです。", "target_word": "美味しかった", "complexity_tier": "T3", "furigana": "昨夜(さくや)のお寿司(すし)が美味(おい)しかったので、また行(い)きたいです。", "sentence_source": "generated"}, {"text": "塩を入れすぎた味噌汁は、美味しくありませんでした。", "target_word": "美味しく", "complexity_tier": "T3", "furigana": "塩(しお)を入(い)れすぎた味噌汁(みそしる)は、美味(おい)しくありませんでした。", "sentence_source": "generated"}, {"text": "美味しいケーキを食べて、みんな満足した顔になった。", "target_word": "美味しい", "complexity_tier": "T3", "furigana": "美味(おい)しいケーキを食(た)べて、みんな満足(まんぞく)した顔(かお)になった。", "sentence_source": "generated"}, {"text": "魚は新鮮なほど美味しく食べられます。", "target_word": "美味しく", "complexity_tier": "T3", "furigana": "魚(さかな)は新鮮(しんせん)なほど美味(おい)しく食(た)べられます。", "sentence_source": "generated"}, {"text": "山で食べるおにぎりは、いつもより美味しく感じる。", "target_word": "美味しく", "complexity_tier": "T3", "furigana": "山(やま)で食(た)べるおにぎりは、いつもより美味(おい)しく感(かん)じる。", "sentence_source": "generated"}, {"text": "美味しければ、遠くても食べに行く人が多い。", "target_word": "美味しければ", "complexity_tier": "T3", "furigana": "美味(おい)しければ、遠(とお)くても食(た)べに行(い)く人(ひと)が多(おお)い。", "sentence_source": "generated"}, {"text": "彼女が作ったサラダは、野菜が新鮮で美味しかった。", "target_word": "美味しかった", "complexity_tier": "T3", "furigana": "彼女(かのじょ)が作(つく)ったサラダは、野菜(やさい)が新鮮(しんせん)で美味(おい)しかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "美味しい", "label": "終止形・連体形"}, {"form": "美味しく", "label": "連用形"}, {"form": "美味しかった", "label": "過去形"}, {"form": "美味しくて", "label": "て形"}, {"form": "美味しければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "食べ物の味が良く、食べて満足できること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38755, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美味しい", "is_correct": true, "explanation": "い形容詞の終止形。「とても美味しいです」と味の評価として文が自然に締まる。"}, {"text": "美味しく", "is_correct": false, "explanation": "連用形。「とても美味しくです」と丁寧語「です」に続かず不自然。"}, {"text": "美味しさ", "is_correct": false, "explanation": "名詞形。「とても美味しさです」は形容詞の評価として成り立たない。"}, {"text": "美味しければ", "is_correct": false, "explanation": "仮定形。「とても美味しければです」と文が続かない。"}], "explanations": {"美味しい": "い形容詞の終止形。「とても美味しいです」と味の評価として文が自然に締まる。", "美味しく": "連用形。「とても美味しくです」と丁寧語「です」に続かず不自然。", "美味しさ": "名詞形。「とても美味しさです」は形容詞の評価として成り立たない。", "美味しければ": "仮定形。「とても美味しければです」と文が続かない。"}, "sentence_index": 0, "correct_answer": "美味しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画は、とても美味しかった。", "explanation": "ここは〈面白い〉の意味。映画の内容には「美味しい」は使わず、食べ物の味の評価にだけ使うので合わない。"}, {"text": "この石は、とても美味しい。", "explanation": "ここは〈硬い〉の意味。石の硬さには「美味しい」は使わず、食べ物の味の評価にだけ使うので合わない。"}, {"text": "この建物は、とても美味しい。", "explanation": "ここは〈大きい〉の意味。建物の大きさには「美味しい」は使わず、味の評価にだけ使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38755, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美味しく", "is_correct": true, "explanation": "連用形。「新鮮なほど美味しく食べられます」と動詞「食べられます」を修飾する副詞用法で、文意に合う。"}, {"text": "美味しい", "is_correct": false, "explanation": "終止形。「新鮮なほど美味しい食べられます」と動詞に続かず、文法的に不自然。"}, {"text": "美味しいこと", "is_correct": false, "explanation": "名詞化した形。「美味しいこと食べられます」と続かず、副詞として働かない。"}, {"text": "美味", "is_correct": false, "explanation": "名詞。「美味食べられます」と続かず、副詞としての用法が成り立たない。"}], "explanations": {"美味しく": "連用形。「新鮮なほど美味しく食べられます」と動詞「食べられます」を修飾する副詞用法で、文意に合う。", "美味しい": "終止形。「新鮮なほど美味しい食べられます」と動詞に続かず、文法的に不自然。", "美味しいこと": "名詞化した形。「美味しいこと食べられます」と続かず、副詞として働かない。", "美味": "名詞。「美味食べられます」と続かず、副詞としての用法が成り立たない。"}, "sentence_index": 6, "correct_answer": "美味しく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この道は、とても美味しい。", "explanation": "ここは〈長い〉の意味。道の長さには「美味しい」は使わず、食べ物の味の評価にだけ使うので合わない。"}, {"text": "この部屋は、夜になると美味しい。", "explanation": "ここは〈静か〉の意味。部屋の静かさには「美味しい」は使わず、食べ物の味の評価にだけ使うので合わない。"}, {"text": "私は、夜更かしで美味しい。", "explanation": "ここは〈眠い〉の意味。自分の眠気には「美味しい」は使わず、食べ物の味の評価にだけ使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38755, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店の寿司は、とても美味しいでした。", "corrected_sentence": "この店の寿司は、とても美味しかったです。", "error_description": "い形容詞の過去の丁寧形は「美味しかったです」。「美味しいでした」は「です」を名詞の過去として付けた誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "美味しい", "is_correct": true, "explanation": "終止形。「格別に美味しい。」と現在の評価を言い切る形で文意に合う。"}, {"text": "美味しさ", "is_correct": false, "explanation": "名詞形で、「格別に美味しさ」と形容詞として言い切れず、文が成り立たない。"}, {"text": "美味しくない", "is_correct": false, "explanation": "否定形。「格別に美味しくない」となり、評価が反対になる。"}, {"text": "美味しければ", "is_correct": false, "explanation": "仮定形で、言い切りにならず文が途中で止まる。"}], "correct_form": "美味しい", "base_form": "美味しい", "form_label": "終止形", "sentence_index": 1, "explanations": {"美味しい": "終止形。「格別に美味しい。」と現在の評価を言い切る形で文意に合う。", "美味しさ": "名詞形で、「格別に美味しさ」と形容詞として言い切れず、文が成り立たない。", "美味しくない": "否定形。「格別に美味しくない」となり、評価が反対になる。", "美味しければ": "仮定形で、言い切りにならず文が途中で止まる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38755, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "川の魚は、さっと焼いて美味しいに食べられます。", "corrected_sentence": "川の魚は、さっと焼いて美味しく食べられます。", "error_description": "い形容詞が動詞を修飾するときは連用形「美味しく」になる。「美味しいに」は形容詞に「に」を付けた誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "美味しく", "is_correct": true, "explanation": "連用形。「いつもより美味しく感じる」と動詞「感じる」を修飾する副詞用法で、文意に合う。"}, {"text": "美味しい", "is_correct": false, "explanation": "終止形。「いつもより美味しい感じる」と動詞に続かず、不自然。"}, {"text": "美味しかったら", "is_correct": false, "explanation": "条件形で、動詞「感じる」を修飾できず、文が成り立たない。"}, {"text": "美味しくなかった", "is_correct": false, "explanation": "否定過去形。「いつもより美味しくなかった」と感じると評価が逆になり、文意が合わない。"}], "correct_form": "美味しく", "base_form": "美味しい", "form_label": "連用形（副詞用法）", "sentence_index": 7, "explanations": {"美味しく": "連用形。「いつもより美味しく感じる」と動詞「感じる」を修飾する副詞用法で、文意に合う。", "美味しい": "終止形。「いつもより美味しい感じる」と動詞に続かず、不自然。", "美味しかったら": "条件形で、動詞「感じる」を修飾できず、文が成り立たない。", "美味しくなかった": "否定過去形。「いつもより美味しくなかった」と感じると評価が逆になり、文意が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
