INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38756, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "生き物や植物が大きくなったり、大人になったりする。", "primary_collocate": null, "pronunciation": "そだつ", "ipa": "sodatsɯ", "syllable_count": 3, "sentences": [{"text": "この花は、日当たりのよい場所でよく育ちます。", "target_word": "育ちます", "complexity_tier": "T3", "furigana": "この花[はな]は、日当[ひあ]たりのよい場所[ばしょ]でよく育[そだ]ちます。", "sentence_source": "generated"}, {"text": "子どもたちは、田舎で元気に育ちました。", "target_word": "育ちました", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、田舎[いなか]で元気[げんき]に育[そだ]ちました。", "sentence_source": "generated"}, {"text": "苗が育つまで、毎日水をやります。", "target_word": "育つ", "complexity_tier": "T3", "furigana": "苗[なえ]が育[そだ]つまで、毎日[まいにち]水[みず]をやります。", "sentence_source": "generated"}, {"text": "犬は半年で大人に育ちます。", "target_word": "育ちます", "complexity_tier": "T3", "furigana": "犬[いぬ]は半年[はんとし]で大人[おとな]に育[そだ]ちます。", "sentence_source": "generated"}, {"text": "雨が少ないと、野菜は大きく育ちません。", "target_word": "育ちません", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]ないと、野菜[やさい]は大[おお]きく育[そだ]ちません。", "sentence_source": "generated"}, {"text": "私は海のそばの町で育ちました。", "target_word": "育ちました", "complexity_tier": "T3", "furigana": "私[わたし]は海[うみ]のそばの町[まち]で育[そだ]ちました。", "sentence_source": "generated"}, {"text": "子猫がこんなに大きく育って、うれしいです。", "target_word": "育って", "complexity_tier": "T3", "furigana": "子猫[こねこ]がこんなに大[おお]きく育[そだ]って、うれしいです。", "sentence_source": "generated"}, {"text": "稲は夏の暑さの中で、ぐんぐん育ちます。", "target_word": "育ちます", "complexity_tier": "T3", "furigana": "稲[いね]は夏[なつ]の暑[あつ]さの中[なか]で、ぐんぐん育[そだ]ちます。", "sentence_source": "generated"}, {"text": "都会で育った人は、星をあまり見たことがありません。", "target_word": "育った", "complexity_tier": "T3", "furigana": "都会[とかい]で育[そだ]った人[ひと]は、星[ほし]をあまり見[み]たことがありません。", "sentence_source": "generated"}, {"text": "この魚は小さな池でも、すぐに育ちます。", "target_word": "育ちます", "complexity_tier": "T3", "furigana": "この魚[さかな]は小[ちい]さな池[いけ]でも、すぐに育[そだ]ちます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "育つ", "label": "辞書形"}, {"form": "育ちます", "label": "丁寧形"}, {"form": "育った", "label": "過去形"}, {"form": "育って", "label": "て形"}, {"form": "育ちません", "label": "丁寧否定形"}], "register": "neutral", "sense_fingerprint": "生き物や植物が大きくなり成長すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c060a24-146e-49fd-8615-760bc8dc184c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38756, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "育ちます", "is_correct": true, "explanation": "「よく育ちます」で文が完結し、花が大きくなる意味になり文に合う。"}, {"text": "育てて", "is_correct": false, "explanation": "「育てて」は他動詞の連用形で文が終わらず、花が主語の文では成り立たない。"}, {"text": "育ちかけ", "is_correct": false, "explanation": "「育ちかけ」は途中の形で文が完結せず、述語として入らない。"}, {"text": "育ちにくく", "is_correct": false, "explanation": "「育ちにくく」は連用形で文が終わらず、「よく」と続けても述語にならない。"}], "explanations": {"育ちます": "「よく育ちます」で文が完結し、花が大きくなる意味になり文に合う。", "育てて": "「育てて」は他動詞の連用形で文が終わらず、花が主語の文では成り立たない。", "育ちかけ": "「育ちかけ」は途中の形で文が完結せず、述語として入らない。", "育ちにくく": "「育ちにくく」は連用形で文が終わらず、「よく」と続けても述語にならない。"}, "sentence_index": 0, "correct_answer": "育ちます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この橋は半年で育ちます。", "explanation": "ここは〈完成〉の意味。育つは生き物や植物が大きくなる意味で、建物の工事には使わない。"}, {"text": "このロープは半年で育ちます。", "explanation": "ここは〈伸びる〉の意味。育つは生き物の成長に使い、ロープの長さが変わることには使わない。"}, {"text": "この店の看板は、去年より高く育ちました。", "explanation": "ここは〈高くなる〉の意味。育つは生き物や植物が大きくなる意味で、看板の高さの変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38756, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "育って", "is_correct": true, "explanation": "「大きく育って、うれしい」と続き、子猫が大きくなった結果を表す形で文に合う。"}, {"text": "育ちます", "is_correct": false, "explanation": "丁寧な終止形で、「、うれしい」と続けると文が崩れる。"}, {"text": "育てきれず", "is_correct": false, "explanation": "他動詞で、主語の子猫が育てる側にはならないため文の流れに合わない。"}, {"text": "育ち損ね", "is_correct": false, "explanation": "「育ち損ねて」は育たなかった意味になり、「こんなに大きく」と矛盾する。"}], "explanations": {"育って": "「大きく育って、うれしい」と続き、子猫が大きくなった結果を表す形で文に合う。", "育ちます": "丁寧な終止形で、「、うれしい」と続けると文が崩れる。", "育てきれず": "他動詞で、主語の子猫が育てる側にはならないため文の流れに合わない。", "育ち損ね": "「育ち損ねて」は育たなかった意味になり、「こんなに大きく」と矛盾する。"}, "sentence_index": 6, "correct_answer": "育って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この工場では、部品がすぐに育ちます。", "explanation": "ここは〈製造〉の意味。育つは生き物の成長に使うので、部品を作る意味では使わない。"}, {"text": "この洗濯物は、晴れた日にすぐに育ちます。", "explanation": "ここは〈乾く〉の意味。育つは生き物が大きくなることで、洗濯物が乾く意味では使わない。"}, {"text": "この棚は、一晩で育ちました。", "explanation": "ここは〈組み立て〉の意味。育つは生き物や植物が大きくなる意味で、家具を組み立てる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38756, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "芽が育てるまで、毎日水をやります。", "corrected_sentence": "芽が育つまで、毎日水をやります。", "error_description": "「育つ」は自動詞で、主語「芽」に合う。「育てる」は他動詞で目的語が必要なため、主語の芽とは合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "育ちました", "is_correct": true, "explanation": "過去の出来事を丁寧に述べる形で、「子どもたちは田舎で元気に育った」という文脈に合う。"}, {"text": "育ちましょう", "is_correct": false, "explanation": "意志・勧誘の形で、過去の出来事は表せない。"}, {"text": "育ちません", "is_correct": false, "explanation": "否定形で、元気に育ったという肯定の文脈と逆の意味になる。"}, {"text": "育ちたい", "is_correct": false, "explanation": "希望の形で、すでに育ったという過去の事実を表せない。"}], "correct_form": "育ちました", "base_form": "育つ", "form_label": "丁寧過去形", "sentence_index": 1, "explanations": {"育ちました": "過去の出来事を丁寧に述べる形で、「子どもたちは田舎で元気に育った」という文脈に合う。", "育ちましょう": "意志・勧誘の形で、過去の出来事は表せない。", "育ちません": "否定形で、元気に育ったという肯定の文脈と逆の意味になる。", "育ちたい": "希望の形で、すでに育ったという過去の事実を表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38756, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "犬がこんなに大きく育ちて、うれしいです。", "corrected_sentence": "犬がこんなに大きく育って、うれしいです。", "error_description": "「育つ」のて形は「育って」。「育ちて」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "育ちます", "is_correct": true, "explanation": "丁寧な現在形で、稲が今ぐんぐん大きくなる様子を述べる文に合う。"}, {"text": "育って", "is_correct": false, "explanation": "て形で文が完結せず、述語として成り立たない。"}, {"text": "育ちません", "is_correct": false, "explanation": "否定形で、ぐんぐん育つという文の意味と逆になる。"}, {"text": "育ちなさい", "is_correct": false, "explanation": "命令形で、稲の成長を述べる文の内容と合わない。"}], "correct_form": "育ちます", "base_form": "育つ", "form_label": "丁寧形", "sentence_index": 7, "explanations": {"育ちます": "丁寧な現在形で、稲が今ぐんぐん大きくなる様子を述べる文に合う。", "育って": "て形で文が完結せず、述語として成り立たない。", "育ちません": "否定形で、ぐんぐん育つという文の意味と逆になる。", "育ちなさい": "命令形で、稲の成長を述べる文の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
