INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38758, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38758, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "つよくて、こわれにくいこと。", "primary_collocate": null, "pronunciation": "じょうぶ", "ipa": "dʑoːbɯ", "syllable_count": 3, "sentences": [{"text": "このかばんは丈夫なので、重い本を入れても破れません。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "このかばんは丈夫[じょうぶ]なので、重[おも]い本[ほん]を入[い]れても破[やぶ]れません。", "sentence_source": "generated"}, {"text": "丈夫な靴を買ったから、山道を歩いても平気です。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "丈夫[じょうぶ]な靴[くつ]を買[か]ったから、山道[やまみち]を歩[ある]いても平気[へいき]です。", "sentence_source": "generated"}, {"text": "この机は木が厚くて丈夫です。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "この机[つくえ]は木[き]が厚[あつ]くて丈夫[じょうぶ]です。", "sentence_source": "generated"}, {"text": "丈夫なひもで荷物をしばりました。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "丈夫[じょうぶ]なひもで荷物[にもつ]をしばりました。", "sentence_source": "generated"}, {"text": "紙の箱は丈夫ではないので、水にぬれるとすぐ壊れます。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "紙[かみ]の箱[はこ]は丈夫[じょうぶ]ではないので、水[みず]にぬれるとすぐ壊[こわ]れます。", "sentence_source": "generated"}, {"text": "兄が作った椅子は丈夫で、五年使ってもまったく壊れません。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "兄[あに]が作[つく]った椅子[いす]は丈夫[じょうぶ]で、五年[ごねん]使[つか]ってもまったく壊[こわ]れません。", "sentence_source": "generated"}, {"text": "子ども用の食器は、落としても割れない丈夫なものを選びます。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "子[こ]ども用[よう]の食器[しょっき]は、落[お]としても割[わ]れない丈夫[じょうぶ]なものを選[えら]びます。", "sentence_source": "generated"}, {"text": "このテントは風が強い日でも倒れないくらい丈夫に作られています。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "このテントは風[かぜ]が強[つよ]い日[ひ]でも倒[たお]れないくらい丈夫[じょうぶ]に作[つく]られています。", "sentence_source": "generated"}, {"text": "丈夫なロープがなかったので、重い木を運ぶのをあきらめました。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "丈夫[じょうぶ]なロープがなかったので、重[おも]い木[き]を運[はこ]ぶのをあきらめました。", "sentence_source": "generated"}, {"text": "傘は軽いより、少し重くても丈夫なほうがいいです。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "傘[かさ]は軽[かる]いより、少[すこ]し重[おも]くても丈夫[じょうぶ]なほうがいいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "丈夫だ", "label": "終止形"}, {"form": "丈夫な", "label": "連体形"}, {"form": "丈夫で", "label": "て形"}, {"form": "丈夫に", "label": "連用形"}, {"form": "丈夫だった", "label": "過去形"}, {"form": "丈夫ではない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "物が強くて壊れにくい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: ぬれる (Zipf 1.65)']::text[], '5c11be19-e1cc-49c2-a822-0ba302475d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38758, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丈夫", "is_correct": true, "explanation": "「このかばんは丈夫なので」の形容。壊れにくさの理由として文脈に合う。"}, {"text": "愉快", "is_correct": false, "explanation": "「愉快なので」は理由として成り立たず、かばんの性質とも合わない。"}, {"text": "無口", "is_correct": false, "explanation": "無口は人の性格を表すので、かばんの性質としては使えない。"}, {"text": "迷惑", "is_correct": false, "explanation": "迷惑は人への影響を表すので、かばんの性質としては文が成り立たない。"}], "explanations": {"丈夫": "「このかばんは丈夫なので」の形容。壊れにくさの理由として文脈に合う。", "愉快": "「愉快なので」は理由として成り立たず、かばんの性質とも合わない。", "無口": "無口は人の性格を表すので、かばんの性質としては使えない。", "迷惑": "迷惑は人への影響を表すので、かばんの性質としては文が成り立たない。"}, "sentence_index": 0, "correct_answer": "丈夫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は丈夫な約束を交わしたので、もう変えられない。", "explanation": "ここは〈堅い（約束が固い）〉の意味。〈丈夫〉は物が壊れにくいことなので、約束の固さには使わない。"}, {"text": "この料理は丈夫な味がする。", "explanation": "ここは〈濃い（味が強い）〉の意味。〈丈夫〉は壊れにくさを表すので、味の濃さには使わない。"}, {"text": "彼は丈夫な発想で、新しいことに挑戦する。", "explanation": "ここは〈柔軟（考えが柔らかい）〉の意味。〈丈夫〉は壊れにくさを表すので、考え方の柔らかさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38758, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丈夫", "is_correct": true, "explanation": "「割れない丈夫なものを選ぶ」の形容。食器の壊れにくさを表す。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は人の性格を表すので、食器の性質としては使えない。"}, {"text": "不器用", "is_correct": false, "explanation": "不器用は人の動作の上手さを表すので、食器の性質としては使えない。"}, {"text": "冷淡", "is_correct": false, "explanation": "冷淡は人の態度を表すので、食器の性質としては使えない。"}], "explanations": {"丈夫": "「割れない丈夫なものを選ぶ」の形容。食器の壊れにくさを表す。", "陽気": "陽気は人の性格を表すので、食器の性質としては使えない。", "不器用": "不器用は人の動作の上手さを表すので、食器の性質としては使えない。", "冷淡": "冷淡は人の態度を表すので、食器の性質としては使えない。"}, "sentence_index": 6, "correct_answer": "丈夫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は丈夫な力で、重い石を軽々と持ち上げた。", "explanation": "ここは〈強い〉の意味。〈丈夫〉は物が壊れにくいことなので、力の強さには使えない。"}, {"text": "けがは丈夫です、心配しないでください。", "explanation": "ここは〈大丈夫〉（問題ない）の意味。〈丈夫〉は壊れにくさを表すので、けがの状態には使わない。"}, {"text": "このパンは丈夫で、歯が立たない。", "explanation": "ここは〈硬い〉の意味。食べ物の固さには〈丈夫〉を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38758, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この自転車は丈夫だたので、長く乗れます。", "corrected_sentence": "この自転車は丈夫なので、長く乗れます。", "error_description": "誤: 丈夫だた（過去形の混同）／正: 丈夫なので（連体形＋「ので」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "丈夫な", "is_correct": true, "explanation": "名詞「靴」を修飾する連体形「丈夫な」と一致する。"}, {"text": "丈夫に", "is_correct": false, "explanation": "連用形で、後ろの名詞「靴」を修飾できない。"}, {"text": "丈夫で", "is_correct": false, "explanation": "て形で、「靴を買った」の名詞修飾として成り立たない。"}, {"text": "丈夫だった", "is_correct": false, "explanation": "過去形で、今の状態を述べる文と合わない。"}], "correct_form": "丈夫な", "base_form": "丈夫だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"丈夫な": "名詞「靴」を修飾する連体形「丈夫な」と一致する。", "丈夫に": "連用形で、後ろの名詞「靴」を修飾できない。", "丈夫で": "て形で、「靴を買った」の名詞修飾として成り立たない。", "丈夫だった": "過去形で、今の状態を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38758, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この箱は丈夫が、重い本を入れても壊れません。", "corrected_sentence": "この箱は丈夫で、重い本を入れても壊れません。", "error_description": "誤: 丈夫が（形状詞には「が」を直接付けず「で」で続ける）／正: 丈夫で（形状詞＋「で」）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "丈夫に", "is_correct": true, "explanation": "「作られて」を修飾する連用形「丈夫に」と一致する。"}, {"text": "丈夫な", "is_correct": false, "explanation": "連体形で、「作られて」の前には立てない。"}, {"text": "丈夫だ", "is_correct": false, "explanation": "終止形で、「作られて」の修飾に使えない。"}, {"text": "丈夫ではない", "is_correct": false, "explanation": "否定形で、「壊れない」ほど丈夫だという文の意味と矛盾する。"}], "correct_form": "丈夫に", "base_form": "丈夫だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"丈夫に": "「作られて」を修飾する連用形「丈夫に」と一致する。", "丈夫な": "連体形で、「作られて」の前には立てない。", "丈夫だ": "終止形で、「作られて」の修飾に使えない。", "丈夫ではない": "否定形で、「壊れない」ほど丈夫だという文の意味と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38759, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "虚弱", "is_correct": true, "explanation": "体が弱く病気にかかりやすいことで、丈夫（健康で強い）の対義語。文の「体が弱かった」と対応する。"}, {"text": "活発", "is_correct": false, "explanation": "動きが元気で積極的なことを表し、体の強さの反対ではないので対義語にならない。"}, {"text": "器用", "is_correct": false, "explanation": "手先の動きがうまいことを表す別の性質で、体の強さの対義語ではない。"}, {"text": "穏やか", "is_correct": false, "explanation": "性格や天候が落ち着いていることで、体の強弱の対義語にはならない。"}], "correct_answer": "虚弱", "explanations": {"虚弱": "体が弱く病気にかかりやすいことで、丈夫（健康で強い）の対義語。文の「体が弱かった」と対応する。", "活発": "動きが元気で積極的なことを表し、体の強さの反対ではないので対義語にならない。", "器用": "手先の動きがうまいことを表す別の性質で、体の強さの対義語ではない。", "穏やか": "性格や天候が落ち着いていることで、体の強弱の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38759, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脆弱", "is_correct": true, "explanation": "もろく弱いことで、橋が丈夫そうに見える（壊れにくい）の反対の意味になる。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深く行動することを表し、物の強さの反対ではないので対義語にならない。"}, {"text": "公平", "is_correct": false, "explanation": "偏りがないことを表す語で、物の丈夫さとは関係がない。"}, {"text": "簡素", "is_correct": false, "explanation": "飾りがなくシンプルなことを表す語で、丈夫さの対義語ではない。"}], "correct_answer": "脆弱", "explanations": {"脆弱": "もろく弱いことで、橋が丈夫そうに見える（壊れにくい）の反対の意味になる。", "慎重": "注意深く行動することを表し、物の強さの反対ではないので対義語にならない。", "公平": "偏りがないことを表す語で、物の丈夫さとは関係がない。", "簡素": "飾りがなくシンプルなことを表す語で、丈夫さの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38759, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物が強くて壊れにくい様子。また、体が健康で強いこと。", "primary_collocate": null, "pronunciation": "じょうぶ", "ipa": "dʑoːbɯ", "syllable_count": 3, "sentences": [{"text": "祖父は八十歳ですが、体が丈夫で病気をほとんどしません。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "祖父[そふ]は八十歳[はちじゅっさい]ですが、体[からだ]が丈夫[じょうぶ]で病気[びょうき]をほとんどしません。", "sentence_source": "generated"}, {"text": "丈夫な体を作るために、毎朝走っています。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "丈夫[じょうぶ]な体[からだ]を作[つく]るために、毎朝[まいあさ]走[はし]っています。", "sentence_source": "generated"}, {"text": "この家具は丈夫にできているので、子どもが乗っても壊れません。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "この家具[かぐ]は丈夫[じょうぶ]にできているので、子[こ]どもが乗[の]っても壊[こわ]れません。", "sentence_source": "generated"}, {"text": "弟は小さいころ体が弱かったが、今は丈夫になりました。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "弟[おとうと]は小[ちい]さいころ体[からだ]が弱[よわ]かったが、今[いま]は丈夫[じょうぶ]になりました。", "sentence_source": "generated"}, {"text": "丈夫な赤ちゃんが生まれるように、母は食事に気をつけています。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "丈夫[じょうぶ]な赤[あか]ちゃんが生[う]まれるように、母[はは]は食事[しょくじ]に気[き]をつけています。", "sentence_source": "generated"}, {"text": "雨にも風にも強い丈夫な窓ガラスを入れました。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "雨[あめ]にも風[かぜ]にも強[つよ]い丈夫[じょうぶ]な窓[まど]ガラスを入[い]れました。", "sentence_source": "generated"}, {"text": "彼女は丈夫だから、雪の中でも風邪をひきません。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は丈夫[じょうぶ]だから、雪[ゆき]の中[なか]でも風邪[かぜ]をひきません。", "sentence_source": "generated"}, {"text": "この犬は丈夫で、冬の外でも元気に遊びます。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "この犬[いぬ]は丈夫[じょうぶ]で、冬[ふゆ]の外[そと]でも元気[げんき]に遊[あそ]びます。", "sentence_source": "generated"}, {"text": "丈夫な布で作った作業着は、何度洗っても破れません。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "丈夫[じょうぶ]な布[ぬの]で作[つく]った作業着[さぎょうぎ]は、何度[なんど]洗[あら]っても破[やぶ]れません。", "sentence_source": "generated"}, {"text": "古い橋だと聞いていたが、思ったより丈夫そうに見えました。", "target_word": "丈夫", "complexity_tier": "T3", "furigana": "古[ふる]い橋[はし]だと聞[き]いていたが、思[おも]ったより丈夫[じょうぶ]そうに見[み]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "丈夫だ", "label": "終止形"}, {"form": "丈夫な", "label": "連体形"}, {"form": "丈夫で", "label": "て形"}, {"form": "丈夫に", "label": "連用形"}, {"form": "丈夫だった", "label": "過去形"}, {"form": "丈夫ではない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "物が壊れにくい様子、または体が健康で強いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c11be19-e1cc-49c2-a822-0ba302475d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38759, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丈夫", "is_correct": true, "explanation": "正解。「体が丈夫で病気をほとんどしない」の文脈に合う、体が健康で強いことを表す語。"}, {"text": "不器用", "is_correct": false, "explanation": "手先がうまく動かないことを表す語で、体が病気をしないという文脈には合わない。"}, {"text": "派手", "is_correct": false, "explanation": "目立つ・華やかなことを表す語で、体の健康状態を述べる文には入らない。"}, {"text": "正直", "is_correct": false, "explanation": "うそをつかない性格を表す語で、体の強さの説明には使えない。"}], "explanations": {"丈夫": "正解。「体が丈夫で病気をほとんどしない」の文脈に合う、体が健康で強いことを表す語。", "不器用": "手先がうまく動かないことを表す語で、体が病気をしないという文脈には合わない。", "派手": "目立つ・華やかなことを表す語で、体の健康状態を述べる文には入らない。", "正直": "うそをつかない性格を表す語で、体の強さの説明には使えない。"}, "sentence_index": 0, "correct_answer": "丈夫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は英語が丈夫で、留学生と話すのが好きだ。", "explanation": "ここは〈得意〉の意味。丈夫は物や体が壊れにくい・健康なことで、能力の巧みさには使わない。"}, {"text": "熱はもう下がったので、丈夫です。", "explanation": "ここは〈大丈夫〉（問題ない）の意味。丈夫は壊れにくさや健康さを表し、「問題ない」の意味では使わない。"}, {"text": "彼は力が丈夫で、重い荷物も軽々と運ぶ。", "explanation": "ここは〈強い〉（力が強い）の意味。丈夫は壊れにくさや体の健康さを表し、力の強さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38759, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丈夫", "is_correct": true, "explanation": "正解。「彼女は丈夫だから、雪の中でも風邪をひきません」の理由として自然に通る、健康で強いことを表す語。"}, {"text": "几帳面", "is_correct": false, "explanation": "物事をきちんとこなす性格を表す語で、風邪をひかない理由にはならない。"}, {"text": "無口", "is_correct": false, "explanation": "話数が少ない性格を表す語で、雪の中で風邪をひかない理由にはならない。"}, {"text": "陽気", "is_correct": false, "explanation": "明るく快活な性格を表す語で、風邪をひかない理由として成り立たない。"}], "explanations": {"丈夫": "正解。「彼女は丈夫だから、雪の中でも風邪をひきません」の理由として自然に通る、健康で強いことを表す語。", "几帳面": "物事をきちんとこなす性格を表す語で、風邪をひかない理由にはならない。", "無口": "話数が少ない性格を表す語で、雪の中で風邪をひかない理由にはならない。", "陽気": "明るく快活な性格を表す語で、風邪をひかない理由として成り立たない。"}, "sentence_index": 6, "correct_answer": "丈夫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この絵は丈夫で、見る人の心を和ませる。", "explanation": "ここは〈美しい〉の意味。丈夫は壊れにくさや健康さを表し、見た目の美しさには使わない。"}, {"text": "このパンは丈夫で、お年寄りでも食べやすい。", "explanation": "ここは〈柔らかい〉の意味。丈夫は壊れにくさを表し、食感の柔らかさには使わない。"}, {"text": "彼女の所作は丈夫で、見とれてしまう。", "explanation": "ここは〈優雅〉の意味。丈夫は物や体の強さを表し、立ち居振る舞いの上品さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38759, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "丈夫の布で作ったバッグは、長く使えます。", "corrected_sentence": "丈夫な布で作ったバッグは、長く使えます。", "error_description": "形容動詞「丈夫」が名詞を修飾するときの形は「丈夫な」。「丈夫の」は誤りで、「な」を「の」に変えた語形の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "丈夫な", "is_correct": true, "explanation": "正解。連体形で、名詞「体」を修飾する形。"}, {"text": "丈夫だ", "is_correct": false, "explanation": "終止形で、名詞「体」の前に直接置けず「丈夫だ体」は不自然。"}, {"text": "丈夫で", "is_correct": false, "explanation": "て形で、後ろに名詞を続けて修飾することができない。"}, {"text": "丈夫に", "is_correct": false, "explanation": "連用形で、名詞を修飾する位置には使えず「丈夫に体」は不自然。"}], "correct_form": "丈夫な", "base_form": "丈夫だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"丈夫な": "正解。連体形で、名詞「体」を修飾する形。", "丈夫だ": "終止形で、名詞「体」の前に直接置けず「丈夫だ体」は不自然。", "丈夫で": "て形で、後ろに名詞を続けて修飾することができない。", "丈夫に": "連用形で、名詞を修飾する位置には使えず「丈夫に体」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38759, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この靴は丈夫くないので、すぐ壊れてしまいます。", "corrected_sentence": "この靴は丈夫ではないので、すぐ壊れてしまいます。", "error_description": "形容動詞「丈夫」の否定は「丈夫ではない」。「丈夫くない」は形容詞の活用を当てはめた誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "丈夫で", "is_correct": true, "explanation": "正解。て形で、後ろに「元気に遊びます」を続けて文をつなぐ形。"}, {"text": "丈夫な", "is_correct": false, "explanation": "連体形で、後ろに名詞がないと文が続かず「この犬は丈夫な、冬の外で」は不自然。"}, {"text": "丈夫だった", "is_correct": false, "explanation": "過去形で、現在の状態を述べる文の意味と合わない。"}, {"text": "丈夫ではない", "is_correct": false, "explanation": "否定形で、「元気に遊びます」という文の内容と矛盾する。"}], "correct_form": "丈夫で", "base_form": "丈夫だ", "form_label": "て形", "sentence_index": 7, "explanations": {"丈夫で": "正解。て形で、後ろに「元気に遊びます」を続けて文をつなぐ形。", "丈夫な": "連体形で、後ろに名詞がないと文が続かず「この犬は丈夫な、冬の外で」は不自然。", "丈夫だった": "過去形で、現在の状態を述べる文の意味と合わない。", "丈夫ではない": "否定形で、「元気に遊びます」という文の内容と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38762, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無効", "is_correct": true, "explanation": "有効の反対で、効き目がないことを表す。対義語にあたる。"}, {"text": "簡単", "is_correct": false, "explanation": "たやすいという意味で、有効の対義語ではない。"}, {"text": "活発", "is_correct": false, "explanation": "勢いがあるという意味で、有効の対義語ではない。"}, {"text": "確実", "is_correct": false, "explanation": "たしかであるという意味で、有効の対義語ではない。"}], "correct_answer": "無効", "explanations": {"無効": "有効の反対で、効き目がないことを表す。対義語にあたる。", "簡単": "たやすいという意味で、有効の対義語ではない。", "活発": "勢いがあるという意味で、有効の対義語ではない。", "確実": "たしかであるという意味で、有効の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38762, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無効", "is_correct": true, "explanation": "有効の反対で、効き目がないことを表す。対義語にあたる。"}, {"text": "繊細", "is_correct": false, "explanation": "細かく敏感な様子の意味で、有効の対義語ではない。"}, {"text": "円満", "is_correct": false, "explanation": "角が立たず穏やかな様子の意味で、有効の対義語ではない。"}, {"text": "誠実", "is_correct": false, "explanation": "まじめで偽りがない意味で、有効の対義語ではない。"}], "correct_answer": "無効", "explanations": {"無効": "有効の反対で、効き目がないことを表す。対義語にあたる。", "繊細": "細かく敏感な様子の意味で、有効の対義語ではない。", "円満": "角が立たず穏やかな様子の意味で、有効の対義語ではない。", "誠実": "まじめで偽りがない意味で、有効の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38762, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "役に立つことです。", "primary_collocate": null, "pronunciation": "ゆうこう", "ipa": "jɯːkoː", "syllable_count": 4, "sentences": [{"text": "時間を有効に使うために、毎朝計画を立てている。", "target_word": "有効", "complexity_tier": "T3", "furigana": "時間[じかん]を有効[ゆうこう]に使[つか]うために、毎朝[まいあさ]計画[けいかく]を立[た]てている。", "sentence_source": "generated"}, {"text": "風邪には、早く寝ることが有効だ。", "target_word": "有効", "complexity_tier": "T3", "furigana": "風邪[かぜ]には、早[はや]く寝[ね]ることが有効[ゆうこう]だ。", "sentence_source": "generated"}, {"text": "この薬は頭痛に有効だと医者に言われた。", "target_word": "有効", "complexity_tier": "T3", "furigana": "この薬[くすり]は頭痛[ずつう]に有効[ゆうこう]だと医者[いしゃ]に言[い]われた。", "sentence_source": "generated"}, {"text": "短い時間で覚えるには、声に出す方法が有効だ。", "target_word": "有効", "complexity_tier": "T3", "furigana": "短[みじか]い時間[じかん]で覚[おぼ]えるには、声[こえ]に出[だ]す方法[ほうほう]が有効[ゆうこう]だ。", "sentence_source": "generated"}, {"text": "余った野菜を有効に使って、スープを作った。", "target_word": "有効", "complexity_tier": "T3", "furigana": "余[あま]った野菜[やさい]を有効[ゆうこう]に使[つか]って、スープを作[つく]った。", "sentence_source": "generated"}, {"text": "古い方法は、今の問題にはあまり有効ではない。", "target_word": "有効", "complexity_tier": "T3", "furigana": "古[ふる]い方法[ほうほう]は、今[いま]の問題[もんだい]にはあまり有効[ゆうこう]ではない。", "sentence_source": "generated"}, {"text": "空いた部屋を有効に活用して、小さな図書室にした。", "target_word": "有効", "complexity_tier": "T3", "furigana": "空[あ]いた部屋[へや]を有効[ゆうこう]に活用[かつよう]して、小[ちい]さな図書室[としょしつ]にした。", "sentence_source": "generated"}, {"text": "有効な練習を続ければ、成績は必ず上がる。", "target_word": "有効", "complexity_tier": "T3", "furigana": "有効[ゆうこう]な練習[れんしゅう]を続[つづ]ければ、成績[せいせき]は必[かなら]ず上[あ]がる。", "sentence_source": "generated"}, {"text": "話し合いは、けんかをやめさせるのに有効な手段だ。", "target_word": "有効", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いは、けんかをやめさせるのに有効[ゆうこう]な手段[しゅだん]だ。", "sentence_source": "generated"}, {"text": "ごみを有効に利用する新しい技術が生まれた。", "target_word": "有効", "complexity_tier": "T3", "furigana": "ごみを有効[ゆうこう]に利用[りよう]する新[あたら]しい技術[ぎじゅつ]が生[う]まれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "有効だ", "label": "断定形"}, {"form": "有効な", "label": "連体形"}, {"form": "有効に", "label": "連用形"}, {"form": "有効で", "label": "て形相当"}, {"form": "有効ではない", "label": "否定形"}], "register": "neutral (plain form)", "sense_fingerprint": "有効 as useful and effective: a method, medicine or use that actually helps (not the ''still valid'' sense of tickets or contracts)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6a65927-b447-4fa1-9765-03dbf2c9836d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38762, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有効", "is_correct": true, "explanation": "役に立つように使うという意味で、「時間を〜に使う」に合う。"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫で壊れにくい意味で、時間の使い方には合わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "鮮度が高い意味で、時間には使えない。"}, {"text": "静か", "is_correct": false, "explanation": "音が少ない様子の意味で、時間の使い方を表さない。"}], "explanations": {"有効": "役に立つように使うという意味で、「時間を〜に使う」に合う。", "頑丈": "丈夫で壊れにくい意味で、時間の使い方には合わない。", "新鮮": "鮮度が高い意味で、時間には使えない。", "静か": "音が少ない様子の意味で、時間の使い方を表さない。"}, "sentence_index": 0, "correct_answer": "有効"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この画家は有効な存在として、国内外で知られている。", "explanation": "ここは〈有名〉の意味。世間によく知られていることは有名と言い、有効は役に立つことを表す。"}, {"text": "彼は有効な秘書として、社長をよく支えている。", "explanation": "ここは〈有能〉の意味。人の働きぶりは有能と言い、有効は物事が役に立つことにしか使わない。"}, {"text": "この若手は有効な選手として、監督に期待されている。", "explanation": "ここは〈有望〉の意味。将来を期待される人は有望と言い、有効は役に立つことを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38762, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有効", "is_correct": true, "explanation": "役立つように活用する意味で、「空いた部屋を〜に活用して」に合う。"}, {"text": "簡素", "is_correct": false, "explanation": "飾りがなく単純な様子の意味で、部屋の活用とは合わない。"}, {"text": "穏やか", "is_correct": false, "explanation": "やわらかく落ち着いた様子の意味で、部屋の活用には使わない。"}, {"text": "頑固", "is_correct": false, "explanation": "かたくなで意見を曲げない様子の意味で、部屋の活用とは合わない。"}], "explanations": {"有効": "役立つように活用する意味で、「空いた部屋を〜に活用して」に合う。", "簡素": "飾りがなく単純な様子の意味で、部屋の活用とは合わない。", "穏やか": "やわらかく落ち着いた様子の意味で、部屋の活用には使わない。", "頑固": "かたくなで意見を曲げない様子の意味で、部屋の活用とは合わない。"}, "sentence_index": 6, "correct_answer": "有効"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は有効な人で、うそを言ったことがない。", "explanation": "ここは〈正直〉の意味。うそをつかない人柄は正直と言い、有効は役に立つことを表す。"}, {"text": "有効な人たちが集まって、公園を掃除した。", "explanation": "ここは〈有志〉の意味。自分から進んで参加する人は有志と言い、有効は役に立つことを表す。"}, {"text": "彼女は有効な成績で、大学を卒業した。", "explanation": "ここは〈優秀〉の意味。成績の良さは優秀と言い、有効は役に立つことを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38762, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "余った時間を有効使って、本を読んだ。", "corrected_sentence": "余った時間を有効に使って、本を読んだ。", "error_description": "「有効使って」は誤り。形状詞は動詞の前で「有効に」の形にする必要があり、「に」が抜けている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "有効だ", "is_correct": true, "explanation": "文末で言い切る断定形で、「ことが有効だ」と文を終える形。"}, {"text": "有効な", "is_correct": false, "explanation": "名詞を修飾する連体形で、文末には使えない。"}, {"text": "有効に", "is_correct": false, "explanation": "連用形で、動詞を修飾する形。ここでは文を終えられない。"}, {"text": "有効で", "is_correct": false, "explanation": "て形相当の中止形で、ここでは文を終えられない。"}], "correct_form": "有効だ", "base_form": "有効だ", "form_label": "断定形", "sentence_index": 1, "explanations": {"有効だ": "文末で言い切る断定形で、「ことが有効だ」と文を終える形。", "有効な": "名詞を修飾する連体形で、文末には使えない。", "有効に": "連用形で、動詞を修飾する形。ここでは文を終えられない。", "有効で": "て形相当の中止形で、ここでは文を終えられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38762, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この方法は、朝の勉強に有効なった。", "corrected_sentence": "この方法は、朝の勉強に有効になった。", "error_description": "「有効なった」は誤り。「なる」の前は「有効に」の形にする必要があり、「に」が抜けている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "有効な", "is_correct": true, "explanation": "後ろの「練習」を修飾する連体形で、名詞の前に置ける形。"}, {"text": "有効だ", "is_correct": false, "explanation": "文末の断定形で、名詞の前には置けない。"}, {"text": "有効で", "is_correct": false, "explanation": "中止形で、名詞の前には使えない。"}, {"text": "有効だった", "is_correct": false, "explanation": "過去の断定形で、名詞の前には置けない。"}], "correct_form": "有効な", "base_form": "有効だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"有効な": "後ろの「練習」を修飾する連体形で、名詞の前に置ける形。", "有効だ": "文末の断定形で、名詞の前には置けない。", "有効で": "中止形で、名詞の前には使えない。", "有効だった": "過去の断定形で、名詞の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38764, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "入れる対象（目的語）を示す「を」。「茶を入れる」となる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、入れられる茶には付かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、中身の茶には使わない。「茶へ入れる」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「急須に」の後にもう一つ「に」が重なり、「茶に入れて」は不自然。"}], "correct_answer": "を", "explanations": {"を": "入れる対象（目的語）を示す「を」。「茶を入れる」となる。", "が": "主語を示すため、入れられる茶には付かない。", "へ": "方向を示すため、中身の茶には使わない。「茶へ入れる」は不自然。", "に": "「急須に」の後にもう一つ「に」が重なり、「茶に入れて」は不自然。"}, "error_tags": {"が": "主語（対象ではない）", "へ": "方向", "に": "同じ格の重複"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38764, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「茶」が「葉」を修飾する「の」。「茶の葉」という名詞句を作る。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、「茶が葉を粉にして」は不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」だが、ここは名詞どうしをつなぐ位置なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、ここでは合わない。"}], "correct_answer": "の", "explanations": {"の": "「茶」が「葉」を修飾する「の」。「茶の葉」という名詞句を作る。", "が": "主語を示すため、「茶が葉を粉にして」は不自然。", "を": "目的語の「を」だが、ここは名詞どうしをつなぐ位置なので合わない。", "へ": "方向を示すため、ここでは合わない。"}, "error_tags": {"が": "主語", "を": "目的語（名詞をつなぐ位置ではない）", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38764, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お茶や食べ物の味をつけるものに使う、葉っぱのことです。", "primary_collocate": null, "pronunciation": "ちゃ", "ipa": "tɕa", "syllable_count": 1, "sentences": [{"text": "茶の葉を摘んで、日なたで乾かします。", "target_word": "茶", "complexity_tier": "T3", "furigana": "茶[ちゃ]の葉[は]を摘[つ]んで、日[ひ]なたで乾[かわ]かします。", "sentence_source": "generated"}, {"text": "急須に茶を入れて、お湯を注ぎました。", "target_word": "茶", "complexity_tier": "T3", "furigana": "急須[きゅうす]に茶[ちゃ]を入[い]れて、お湯[ゆ]を注[そそ]ぎました。", "sentence_source": "generated"}, {"text": "この店は茶の葉の種類が多くて、選ぶのに迷います。", "target_word": "茶", "complexity_tier": "T3", "furigana": "この店[みせ]は茶[ちゃ]の葉[は]の種類[しゅるい]が多[おお]くて、選[えら]ぶのに迷[まよ]います。", "sentence_source": "generated"}, {"text": "祖母は茶の葉を少し砕いて、パンの生地に混ぜます。", "target_word": "茶", "complexity_tier": "T3", "furigana": "祖母[そぼ]は茶[ちゃ]の葉[は]を少[すこ]し砕[くだ]いて、パンの生地[きじ]に混[ま]ぜます。", "sentence_source": "generated"}, {"text": "茶を煮出すと、葉から濃い色が出てきます。", "target_word": "茶", "complexity_tier": "T3", "furigana": "茶[ちゃ]を煮出[にだ]すと、葉[は]から濃[こ]い色[いろ]が出[で]てきます。", "sentence_source": "generated"}, {"text": "新しい茶は、葉の緑が鮮やかで香りも強いです。", "target_word": "茶", "complexity_tier": "T3", "furigana": "新[あたら]しい茶[ちゃ]は、葉[は]の緑[みどり]が鮮[あざ]やかで香[かお]りも強[つよ]いです。", "sentence_source": "generated"}, {"text": "茶は湿気に弱いので、缶に入れて保存します。", "target_word": "茶", "complexity_tier": "T3", "furigana": "茶[ちゃ]は湿気[しっけ]に弱[よわ]いので、缶[かん]に入[い]れて保存[ほぞん]します。", "sentence_source": "generated"}, {"text": "父は茶の葉を粉にして、お菓子の味つけに使いました。", "target_word": "茶", "complexity_tier": "T3", "furigana": "父[ちち]は茶[ちゃ]の葉[は]を粉[こな]にして、お菓子[かし]の味[あじ]つけに使[つか]いました。", "sentence_source": "generated"}, {"text": "山の畑で、農家の人が茶の葉を一枚ずつ摘んでいます。", "target_word": "茶", "complexity_tier": "T3", "furigana": "山[やま]の畑[はたけ]で、農家[のうか]の人[ひと]が茶[ちゃ]の葉[は]を一枚[いちまい]ずつ摘[つ]んでいます。", "sentence_source": "generated"}, {"text": "古い茶は香りが弱くなるので、早めに使い切りましょう。", "target_word": "茶", "complexity_tier": "T3", "furigana": "古[ふる]い茶[ちゃ]は香[かお]りが弱[よわ]くなるので、早[はや]めに使[つか]い切[き]りましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "茶", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "茶の葉そのもの。飲み物や食べ物の味つけの材料としての茶葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 日なた (Zipf 2.15)','sentence 7 above tier T2: contains vocabulary far above tier T2: 味つけ (Zipf 2.13)','sentence 9 above tier T2: contains vocabulary far above tier T2: 使い切り (Zipf 2.41)']::text[], 'd6a65927-b447-4fa1-9765-03dbf2c9836d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38764, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "茶", "is_correct": true, "explanation": "「茶の葉」の「茶」で、摘んで乾かす対象の葉を指す。"}, {"text": "紙", "is_correct": false, "explanation": "紙には葉がなく、「紙の葉を摘んで乾かす」は成り立たない。"}, {"text": "石", "is_correct": false, "explanation": "石には葉がなく、摘んで乾かすことができないので文として合わない。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄に葉はなく、摘んで乾かすものにもならない。"}], "explanations": {"茶": "「茶の葉」の「茶」で、摘んで乾かす対象の葉を指す。", "紙": "紙には葉がなく、「紙の葉を摘んで乾かす」は成り立たない。", "石": "石には葉がなく、摘んで乾かすことができないので文として合わない。", "鉄": "鉄に葉はなく、摘んで乾かすものにもならない。"}, "sentence_index": 0, "correct_answer": "茶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "おにぎりを茶で巻きます。", "explanation": "ここは〈海苔〉の意味（薄い板状の食品で包む）と混同。茶はそのような板状の物ではなく、巻く材料にはならないので合わない。"}, {"text": "茶を水で戻して、味噌汁に入れます。", "explanation": "ここは〈ワカメ〉の意味（乾物を水で戻して使う）と混同。茶の葉は水で戻して使う乾物ではないので合わない。"}, {"text": "玉ねぎの茶を剥いて、スープに入れます。", "explanation": "ここは〈皮〉の意味（剥いて取り除く外側の部分）と混同。茶は玉ねぎの皮ではなく、剥く対象にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38764, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "茶", "is_correct": true, "explanation": "湿気に弱く缶に保存する対象の茶（茶葉）を指す。"}, {"text": "空", "is_correct": false, "explanation": "空は缶に入れて保存できないので、「空を缶に入れて保存する」は成り立たない。"}, {"text": "山", "is_correct": false, "explanation": "山は缶に入らないので、保存する文として合わない。"}, {"text": "車", "is_correct": false, "explanation": "車を缶に入れて保存する文にはならない。"}], "explanations": {"茶": "湿気に弱く缶に保存する対象の茶（茶葉）を指す。", "空": "空は缶に入れて保存できないので、「空を缶に入れて保存する」は成り立たない。", "山": "山は缶に入らないので、保存する文として合わない。", "車": "車を缶に入れて保存する文にはならない。"}, "sentence_index": 6, "correct_answer": "茶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本棚の上の茶を払って、きれいにします。", "explanation": "ここは〈ほこり〉の意味（払って取る細かいごみ）と混同。茶は本棚に積もるごみではないので合わない。"}, {"text": "茶を削って、うどんにのせます。", "explanation": "ここは〈かつお節〉の意味（削って料理にのせる乾物）と混同。茶は削って使う材料ではないので合わない。"}, {"text": "庭の茶をむしって、畑をきれいにします。", "explanation": "〈草〉と混同した例。茶は雑草ではないので、むしって片づける対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38764, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市場で茶を葉を少し買って、家で乾かします。", "corrected_sentence": "市場で茶の葉を少し買って、家で乾かします。", "error_description": "「茶の葉」の「の」が「を」になっている。「茶」は後ろの「葉」を修飾するので「の」が正しく、「茶を葉」は文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38764, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "香りの強い茶を炊きました。", "corrected_sentence": "香りの強い茶を炒りました。", "error_description": "「茶」に付く動詞が「炊く」になっている。茶の葉は「炒る」で処理するもので、「炊く」は主に米などに使うため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38765, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「いれる」の対象（目的語）を示す「を」。茶は入れられる対象。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、入れられる茶には付かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「茶へいれる」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、「茶からいれる」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「いれる」の対象（目的語）を示す「を」。茶は入れられる対象。", "が": "主語を示すため、入れられる茶には付かない。", "へ": "方向を示すため、「茶へいれる」は不自然。", "から": "起点を示すため、「茶からいれる」は不自然。"}, "error_tags": {"が": "主語（対象ではない）", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38765, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「出す」の対象（目的語）を示す「を」。「茶を出す」となる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、出される茶には付かない。"}, {"text": "に", "is_correct": false, "explanation": "「みんなに」の後にもう一つ「に」が重なり、「茶に出して」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「茶へ出す」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「出す」の対象（目的語）を示す「を」。「茶を出す」となる。", "が": "主語を示すため、出される茶には付かない。", "に": "「みんなに」の後にもう一つ「に」が重なり、「茶に出して」は不自然。", "へ": "方向を示すため、「茶へ出す」は不自然。"}, "error_tags": {"が": "主語（対象ではない）", "に": "同じ格の重複", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38765, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "茶の葉をお湯に浸してつくる飲み物のことです。", "primary_collocate": null, "pronunciation": "ちゃ", "ipa": "tɕa", "syllable_count": 1, "sentences": [{"text": "朝ご飯のあとで、熱い茶を一杯飲みます。", "target_word": "茶", "complexity_tier": "T3", "furigana": "朝[あさ]ご飯[はん]のあとで、熱[あつ]い茶[ちゃ]を一杯[いっぱい]飲[の]みます。", "sentence_source": "generated"}, {"text": "客が来たので、母が茶をいれました。", "target_word": "茶", "complexity_tier": "T3", "furigana": "客[きゃく]が来[き]たので、母[はは]が茶[ちゃ]をいれました。", "sentence_source": "generated"}, {"text": "茶が冷めてしまったので、もう一度温めました。", "target_word": "茶", "complexity_tier": "T3", "furigana": "茶[ちゃ]が冷[さ]めてしまったので、もう一度[いちど]温[あたた]めました。", "sentence_source": "generated"}, {"text": "祖父は毎日、縁側で茶を飲みながら庭を見ています。", "target_word": "茶", "complexity_tier": "T3", "furigana": "祖父[そふ]は毎日[まいにち]、縁側[えんがわ]で茶[ちゃ]を飲[の]みながら庭[にわ]を見[み]ています。", "sentence_source": "generated"}, {"text": "疲れたときは、甘いお菓子と茶で休みます。", "target_word": "茶", "complexity_tier": "T3", "furigana": "疲[つか]れたときは、甘[あま]いお菓子[かし]と茶[ちゃ]で休[やす]みます。", "sentence_source": "generated"}, {"text": "この茶は苦すぎて、子どもには飲めません。", "target_word": "茶", "complexity_tier": "T3", "furigana": "この茶[ちゃ]は苦[にが]すぎて、子[こ]どもには飲[の]めません。", "sentence_source": "generated"}, {"text": "寒い日は、温かい茶が体にしみます。", "target_word": "茶", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、温[あたた]かい茶[ちゃ]が体[からだ]にしみます。", "sentence_source": "generated"}, {"text": "先生は会議の前に、みんなに茶を出してくれました。", "target_word": "茶", "complexity_tier": "T3", "furigana": "先生[せんせい]は会議[かいぎ]の前[まえ]に、みんなに茶[ちゃ]を出[だ]してくれました。", "sentence_source": "generated"}, {"text": "冷たい茶を水筒に入れて、遠足に持っていきます。", "target_word": "茶", "complexity_tier": "T3", "furigana": "冷[つめ]たい茶[ちゃ]を水筒[すいとう]に入[い]れて、遠足[えんそく]に持[も]っていきます。", "sentence_source": "generated"}, {"text": "夕食のあと、家族で茶を飲みながら話しました。", "target_word": "茶", "complexity_tier": "T3", "furigana": "夕食[ゆうしょく]のあと、家族[かぞく]で茶[ちゃ]を飲[の]みながら話[はな]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "茶", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "茶の葉でいれた飲み物。飲む、いれる、冷めるなどの対象としての茶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6a65927-b447-4fa1-9765-03dbf2c9836d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38765, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "茶", "is_correct": true, "explanation": "「熱い茶を一杯飲む」の目的語の「茶」で、飲み物を指す。"}, {"text": "豆腐", "is_correct": false, "explanation": "豆腐は一杯飲むものではなく、「熱い豆腐を一杯飲む」は成り立たない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖を熱いまま一杯飲む文にはならない。"}, {"text": "海苔", "is_correct": false, "explanation": "海苔は飲むものではないので、「熱い海苔を一杯飲む」は不自然。"}], "explanations": {"茶": "「熱い茶を一杯飲む」の目的語の「茶」で、飲み物を指す。", "豆腐": "豆腐は一杯飲むものではなく、「熱い豆腐を一杯飲む」は成り立たない。", "砂糖": "砂糖を熱いまま一杯飲む文にはならない。", "海苔": "海苔は飲むものではないので、「熱い海苔を一杯飲む」は不自然。"}, "sentence_index": 0, "correct_answer": "茶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "茶は、ぶどうの果汁を醸して造ります。", "explanation": "ここは〈ワイン〉の意味（果汁を醸して造る酒）と混同。茶はぶどうから醸して造るものではないので、この定義には合わない。"}, {"text": "茶を水で練って、器を作ります。", "explanation": "ここは〈粘土〉の意味（水で練って器に成形する材料）と混同。茶は器を作る材料ではないので合わない。"}, {"text": "パンに茶が生えてしまいました。", "explanation": "ここは〈カビ〉の意味（食品に生える菌）と混同。茶は生えて広がるものではなく、カビの代わりには使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38765, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "茶", "is_correct": true, "explanation": "「温かい茶が体にしみる」の主語で、飲み物の茶を指す。"}, {"text": "石", "is_correct": false, "explanation": "温かい石が体にしみる文にはならない。"}, {"text": "砂", "is_correct": false, "explanation": "温かい砂が体にしみるという文は成り立たない。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄が体にしみるという文は不自然で、「温かい」ものとしても合わない。"}], "explanations": {"茶": "「温かい茶が体にしみる」の主語で、飲み物の茶を指す。", "石": "温かい石が体にしみる文にはならない。", "砂": "温かい砂が体にしみるという文は成り立たない。", "鉄": "鉄が体にしみるという文は不自然で、「温かい」ものとしても合わない。"}, "sentence_index": 6, "correct_answer": "茶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汗をかいたので、茶で顔を拭きました。", "explanation": "ここは〈ハンカチ〉の意味（汗を拭く布）と混同。茶は布ではないので、拭く道具にはならず合わない。"}, {"text": "書類を、茶で留めます。", "explanation": "ここは〈ホッチキス〉の意味（紙を留める道具）と混同。茶は紙を留める道具ではないので合わない。"}, {"text": "ラジオに茶を入れて、音を出します。", "explanation": "ここは〈電池〉の意味（電気を供給する部品）と混同。茶は電気を出す物ではないので、ラジオの電源としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38765, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喫茶店で熱い茶が注文しました。", "corrected_sentence": "喫茶店で熱い茶を注文しました。", "error_description": "「注文する」の対象を示す助詞は「を」。「が」は主語を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38765, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い夜は、熱い茶をゆっくり飲むます。", "corrected_sentence": "寒い夜は、熱い茶をゆっくり飲みます。", "error_description": "動詞「飲む」の連用形は「飲み」。「飲むます」は活用の誤りで、正しくは「飲みます」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38766, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『容器』が主語になり、『小さすぎて』という状態を述べる正しい格助詞。"}, {"text": "を", "is_correct": false, "explanation": "『小さすぎる』は形容詞なので、目的語を取る『を』は合わない。"}, {"text": "に", "is_correct": false, "explanation": "『に』では『容器に小さすぎて』となり、状態の主体を示せない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すもので、『小さい』の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "『容器』が主語になり、『小さすぎて』という状態を述べる正しい格助詞。", "を": "『小さすぎる』は形容詞なので、目的語を取る『を』は合わない。", "に": "『に』では『容器に小さすぎて』となり、状態の主体を示せない。", "で": "『で』は手段や場所を示すもので、『小さい』の主語にはならない。"}, "error_tags": {"を": "形容詞への目的語の誤用", "に": "状態主体の誤用", "で": "手段・場所の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38766, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『容器に』は入れる先を示し、『入れる』に合う正しい格助詞。"}, {"text": "が", "is_correct": false, "explanation": "『容器が』では主語になり、『入れてくれた』の到達先を示せない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示すもので、入れる先の指定にはならない。"}, {"text": "の", "is_correct": false, "explanation": "『容器の』では名詞を修飾するだけで、入れる先を表す格助詞として不完全。"}], "correct_answer": "に", "explanations": {"に": "『容器に』は入れる先を示し、『入れる』に合う正しい格助詞。", "が": "『容器が』では主語になり、『入れてくれた』の到達先を示せない。", "と": "『と』は並列や相手を示すもので、入れる先の指定にはならない。", "の": "『容器の』では名詞を修飾するだけで、入れる先を表す格助詞として不完全。"}, "error_tags": {"が": "主語の誤用", "と": "並列・相手の誤用", "の": "修飾の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38766, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものを入れるための入れ物のことです。", "primary_collocate": null, "pronunciation": "ようき", "ipa": "joːki", "syllable_count": 3, "sentences": [{"text": "この容器にスープを入れて、冷蔵庫に置いてください。", "target_word": "容器", "complexity_tier": "T3", "furigana": "この容器[ようき]にスープを入[い]れて、冷蔵庫[れいぞうこ]に置[お]いてください。", "sentence_source": "generated"}, {"text": "弁当の容器が小さすぎて、ご飯が全部入らなかった。", "target_word": "容器", "complexity_tier": "T3", "furigana": "弁当[べんとう]の容器[ようき]が小[ちい]さすぎて、ご飯[はん]が全部[ぜんぶ]入[はい]らなかった。", "sentence_source": "generated"}, {"text": "容器のふたを閉めないと、中身がこぼれます。", "target_word": "容器", "complexity_tier": "T3", "furigana": "容器[ようき]のふたを閉[し]めないと、中身[なかみ]がこぼれます。", "sentence_source": "generated"}, {"text": "食べ終わった容器は、洗ってからごみに出します。", "target_word": "容器", "complexity_tier": "T3", "furigana": "食[た]べ終[お]わった容器[ようき]は、洗[あら]ってからごみに出[だ]します。", "sentence_source": "generated"}, {"text": "プラスチックの容器は軽いので、持ち運びに便利だ。", "target_word": "容器", "complexity_tier": "T3", "furigana": "プラスチックの容器[ようき]は軽[かる]いので、持[も]ち運[はこ]びに便利[べんり]だ。", "sentence_source": "generated"}, {"text": "容器が割れてしまい、牛乳が床に広がった。", "target_word": "容器", "complexity_tier": "T3", "furigana": "容器[ようき]が割[わ]れてしまい、牛乳[ぎゅうにゅう]が床[ゆか]に広[ひろ]がった。", "sentence_source": "generated"}, {"text": "この容器は電子レンジで使えますか。", "target_word": "容器", "complexity_tier": "T3", "furigana": "この容器[ようき]は電子[でんし]レンジで使[つか]えますか。", "sentence_source": "generated"}, {"text": "店員さんは、買ったケーキを小さな容器に入れてくれた。", "target_word": "容器", "complexity_tier": "T3", "furigana": "店員[てんいん]さんは、買[か]ったケーキを小[ちい]さな容器[ようき]に入[い]れてくれた。", "sentence_source": "generated"}, {"text": "薬は子どもの手が届かない所に、容器ごとしまっておく。", "target_word": "容器", "complexity_tier": "T3", "furigana": "薬[くすり]は子[こ]どもの手[て]が届[とど]かない所[ところ]に、容器[ようき]ごとしまっておく。", "sentence_source": "generated"}, {"text": "容器に水を入れて、花を数日間さしておいた。", "target_word": "容器", "complexity_tier": "T3", "furigana": "容器[ようき]に水[みず]を入[い]れて、花[はな]を数日間[すうじつかん]さしておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "容器", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物を入れておく入れ物（食べ物・液体などを入れる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38766, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "容器", "is_correct": true, "explanation": "スープを入れる入れ物を指すので、空欄に入って文が成り立つ。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は切るための刃物で、スープを入れる入れ物ではないので文が成り立たない。"}, {"text": "まな板", "is_correct": false, "explanation": "まな板は食材を切る板で、液体を入れられないので合わない。"}, {"text": "ふきん", "is_correct": false, "explanation": "ふきんは拭くための布で、スープを入れる入れ物ではないので不自然。"}], "explanations": {"容器": "スープを入れる入れ物を指すので、空欄に入って文が成り立つ。", "包丁": "包丁は切るための刃物で、スープを入れる入れ物ではないので文が成り立たない。", "まな板": "まな板は食材を切る板で、液体を入れられないので合わない。", "ふきん": "ふきんは拭くための布で、スープを入れる入れ物ではないので不自然。"}, "sentence_index": 0, "correct_answer": "容器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上司は容器が大きいので、部下の小さなミスを大目に見てくれる。", "explanation": "ここは〈器量〉（人の心の広さ）の意味。容器は物を入れる入れ物を指すので、人の度量には使えない。"}, {"text": "彼には指導者としての容器がある。", "explanation": "ここは〈器〉（才能・素質）の意味。容器は物理的な入れ物なので、人の素質の意味では使わない。"}, {"text": "心臓は血液を送る重要な容器だ。", "explanation": "ここは〈臓器〉の意味。心臓は体の器官なので、物を入れる道具の容器とは呼ばない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38766, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "容器", "is_correct": true, "explanation": "電子レンジで使える入れ物を指すので、空欄に入って自然な文になる。"}, {"text": "電池", "is_correct": false, "explanation": "電池は電気を蓄える部品で、電子レンジで使う対象ではないので不自然。"}, {"text": "電球", "is_correct": false, "explanation": "電球は照明器具で、電子レンジに入れて使うものではないので合わない。"}, {"text": "洗剤", "is_correct": false, "explanation": "洗剤は洗うための液体で、電子レンジで使う対象にならないので文が成り立たない。"}], "explanations": {"容器": "電子レンジで使える入れ物を指すので、空欄に入って自然な文になる。", "電池": "電池は電気を蓄える部品で、電子レンジで使う対象ではないので不自然。", "電球": "電球は照明器具で、電子レンジに入れて使うものではないので合わない。", "洗剤": "洗剤は洗うための液体で、電子レンジで使う対象にならないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "容器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お菓子を容器で包み、リボンをかけてプレゼントにした。", "explanation": "ここは〈包装〉（包み紙で包むこと）の意味。容器は物を入れる道具で、包んで覆う意味では使わない。"}, {"text": "かたつむりは容器を背負って、ゆっくり歩いていく。", "explanation": "ここは〈殻〉（生き物の外側の固い覆い）の意味。容器は中に物を入れる道具で、生き物の体の一部には使わない。"}, {"text": "バスは大勢の人を運ぶ容器だ。", "explanation": "ここは〈乗り物〉の意味。容器は中に物を入れておく道具で、人を運ぶ乗り物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38766, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この容器の野菜を入れて、冷蔵庫に置いてください。", "corrected_sentence": "この容器に野菜を入れて、冷蔵庫に置いてください。", "error_description": "『入れる』の到達先は『に』で示すので、『容器の』は野菜の所属を表すだけで入れる先にならない。正しくは『容器に』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38766, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "容器を割れてしまい、中身が外にこぼれた。", "corrected_sentence": "容器が割れてしまい、中身が外にこぼれた。", "error_description": "『割れる』は自動詞なので、動作の主体は『が』で示す。『容器を』は誤りで、正しくは『容器が』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
