INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38767, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『容器に』は液体を注ぐ先を示し、『注ぐ』に合う正しい格助詞。"}, {"text": "を", "is_correct": false, "explanation": "『容器を』では目的語になり、『液体を注いだ』と続けると意味が崩れる。"}, {"text": "が", "is_correct": false, "explanation": "『容器が』では主語になり、液体を注ぐ動作の主体として合わない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列を示すもので、注ぐ先の指定にはならない。"}], "correct_answer": "に", "explanations": {"に": "『容器に』は液体を注ぐ先を示し、『注ぐ』に合う正しい格助詞。", "を": "『容器を』では目的語になり、『液体を注いだ』と続けると意味が崩れる。", "が": "『容器が』では主語になり、液体を注ぐ動作の主体として合わない。", "と": "『と』は並列を示すもので、注ぐ先の指定にはならない。"}, "error_tags": {"を": "目的語の誤用", "が": "主語の誤用", "と": "並列の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38767, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を入れておくための入れ物や道具。", "primary_collocate": null, "pronunciation": "ようき", "ipa": "joːki", "syllable_count": 3, "sentences": [{"text": "おみやげのお菓子は、かわいい容器に入っていた。", "target_word": "容器", "complexity_tier": "T3", "furigana": "おみやげのお菓子[かし]は、かわいい容器[ようき]に入[はい]っていた。", "sentence_source": "generated"}, {"text": "調味料を入れる容器を、台所の棚に並べた。", "target_word": "容器", "complexity_tier": "T3", "furigana": "調味料[ちょうみりょう]を入[い]れる容器[ようき]を、台所[だいどころ]の棚[たな]に並[なら]べた。", "sentence_source": "generated"}, {"text": "容器の底に穴があいていて、水がもれている。", "target_word": "容器", "complexity_tier": "T3", "furigana": "容器[ようき]の底[そこ]に穴[あな]があいていて、水[みず]がもれている。", "sentence_source": "generated"}, {"text": "この容器は軽くて丈夫なので、キャンプによく持っていく。", "target_word": "容器", "complexity_tier": "T3", "furigana": "この容器[ようき]は軽[かる]くて丈夫[じょうぶ]なので、キャンプによく持[も]っていく。", "sentence_source": "generated"}, {"text": "空になった容器は、きれいに洗って次の日も使う。", "target_word": "容器", "complexity_tier": "T3", "furigana": "空[から]になった容器[ようき]は、きれいに洗[あら]って次[つぎ]の日[ひ]も使[つか]う。", "sentence_source": "generated"}, {"text": "透明な容器だから、中に何が入っているかすぐ分かる。", "target_word": "容器", "complexity_tier": "T3", "furigana": "透明[とうめい]な容器[ようき]だから、中[なか]に何[なに]が入[はい]っているかすぐ分[わ]かる。", "sentence_source": "generated"}, {"text": "容器が大きいので、冷蔵庫に入りません。", "target_word": "容器", "complexity_tier": "T3", "furigana": "容器[ようき]が大[おお]きいので、冷蔵庫[れいぞうこ]に入[はい]りません。", "sentence_source": "generated"}, {"text": "実験では、ガラスの容器に液体を少しずつ注いだ。", "target_word": "容器", "complexity_tier": "T3", "furigana": "実験[じっけん]では、ガラスの容器[ようき]に液体[えきたい]を少[すこ]しずつ注[そそ]いだ。", "sentence_source": "generated"}, {"text": "持ち帰り用の容器をお願いしたら、店の人が出してくれた。", "target_word": "容器", "complexity_tier": "T3", "furigana": "持[も]ち帰[かえ]り用[よう]の容器[ようき]をお願[ねが]いしたら、店[みせ]の人[ひと]が出[だ]してくれた。", "sentence_source": "generated"}, {"text": "古い容器を捨てて、新しいものに買いかえた。", "target_word": "容器", "complexity_tier": "T3", "furigana": "古[ふる]い容器[ようき]を捨[す]てて、新[あたら]しいものに買[か]いかえた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "容器", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物を入れて保管する入れ物・道具（ふた付き・ガラス製など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38767, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "容器", "is_correct": true, "explanation": "お菓子を入れておく入れ物を指すので、空欄に入って自然な文になる。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は本のことで、お菓子が入る入れ物ではないので不自然。"}, {"text": "写真", "is_correct": false, "explanation": "写真は画像のことで、お菓子が入る入れ物ではないので文が成り立たない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は時刻を示す道具で、お菓子が入る入れ物ではないので合わない。"}], "explanations": {"容器": "お菓子を入れておく入れ物を指すので、空欄に入って自然な文になる。", "辞書": "辞書は本のことで、お菓子が入る入れ物ではないので不自然。", "写真": "写真は画像のことで、お菓子が入る入れ物ではないので文が成り立たない。", "時計": "時計は時刻を示す道具で、お菓子が入る入れ物ではないので合わない。"}, "sentence_index": 0, "correct_answer": "容器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先輩は容器が大きいので、後輩のささいな失敗も大目に見てくれる。", "explanation": "ここは〈器量〉（人の心の広さ）の意味。容器は物を入れる入れ物を指すので、人の度量には使えない。"}, {"text": "肝臓は体内で働く大切な容器だ。", "explanation": "ここは〈臓器〉の意味。肝臓は体の器官なので、物を入れる道具の容器とは呼ばない。"}, {"text": "お菓子を容器でそっと包み、リボンをかけた。", "explanation": "ここは〈包装〉の意味。容器は中に入れる道具で、包んで覆う意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38767, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "容器", "is_correct": true, "explanation": "大きさを言われる対象で、冷蔵庫に入らない入れ物を指すので文が成り立つ。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、大きさを言う対象にならないので不自然。"}, {"text": "休日", "is_correct": false, "explanation": "休日は日にちのことで、大きさを言えないので文が成り立たない。"}, {"text": "期限", "is_correct": false, "explanation": "期限は日付の区切りのことで、大きさを言う対象にならない。"}], "explanations": {"容器": "大きさを言われる対象で、冷蔵庫に入らない入れ物を指すので文が成り立つ。", "天気": "天気は空模様のことで、大きさを言う対象にならないので不自然。", "休日": "休日は日にちのことで、大きさを言えないので文が成り立たない。", "期限": "期限は日付の区切りのことで、大きさを言う対象にならない。"}, "sentence_index": 6, "correct_answer": "容器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "かたつむりは容器を背負って、雨の日も歩いていく。", "explanation": "ここは〈殻〉（生き物の外側の固い覆い）の意味。容器は中に物を入れる道具で、生き物の体の一部には使わない。"}, {"text": "この電車は多くの乗客を運ぶ容器だ。", "explanation": "ここは〈乗り物〉の意味。容器は中に物を入れておく道具で、人を運ぶ乗り物には使わない。"}, {"text": "このパンは容器が豊富で、朝食にぴったりだ。", "explanation": "ここは〈栄養〉の意味。容器は入れ物のことで、食べ物の成分には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38767, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お菓子は、かわいい容器を入って届いた。", "corrected_sentence": "お菓子は、かわいい容器に入って届いた。", "error_description": "『入る』は自動詞なので、入る先は『に』で示す。『容器を』は誤りで、正しくは『容器に』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38767, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "容器を大きいので、リュックには入りません。", "corrected_sentence": "容器が大きいので、リュックには入りません。", "error_description": "『大きい』は形容詞なので、主語は『が』で示す。『容器を』は誤りで、正しくは『容器が』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38770, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「外に出る」の「に」。出る先の場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「外が出て」は主語として続かず、動作の対象にもならない。"}, {"text": "で", "is_correct": false, "explanation": "場所を示す「で」だが、「外で出て」は「出る」と続かず文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「外の出て」は名詞修飾として続かず、文が成立しない。"}], "correct_answer": "に", "explanations": {"に": "「外に出る」の「に」。出る先の場所を示す。", "が": "「外が出て」は主語として続かず、動作の対象にもならない。", "で": "場所を示す「で」だが、「外で出て」は「出る」と続かず文が成立しない。", "の": "「外の出て」は名詞修飾として続かず、文が成立しない。"}, "error_tags": {"が": "主格", "で": "動作の場所", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38770, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38770, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いえのそと。", "primary_collocate": null, "pronunciation": "そと", "ipa": "soto", "syllable_count": 2, "sentences": [{"text": "家の外で犬が吠えているので、目が覚めた。", "target_word": "外", "complexity_tier": "T3", "furigana": "家(いえ)の外(そと)で犬(いぬ)が吠(ほ)えているので、目(め)が覚(さ)めた。", "sentence_source": "generated"}, {"text": "雨がやんだので、外に出て洗濯物を干した。", "target_word": "外", "complexity_tier": "T3", "furigana": "雨(あめ)がやんだので、外(そと)に出(で)て洗濯物(せんたくもの)を干(ほ)した。", "sentence_source": "generated"}, {"text": "今日は天気がいいから、外でお弁当を食べよう。", "target_word": "外", "complexity_tier": "T3", "furigana": "今日(きょう)は天気(てんき)がいいから、外(そと)でお弁当(べんとう)を食(た)べよう。", "sentence_source": "generated"}, {"text": "外は寒いから、コートを着て出かける。", "target_word": "外", "complexity_tier": "T3", "furigana": "外(そと)は寒(さむ)いから、コートを着(き)て出(で)かける。", "sentence_source": "generated"}, {"text": "鍵を忘れて、しばらく家の外で母の帰りを待った。", "target_word": "外", "complexity_tier": "T3", "furigana": "鍵(かぎ)を忘(わす)れて、しばらく家(いえ)の外(そと)で母(はは)の帰(かえ)りを待(ま)った。", "sentence_source": "generated"}, {"text": "子どもたちは雪が降ると、外で元気に雪だるまを作る。", "target_word": "外", "complexity_tier": "T3", "furigana": "子(こ)どもたちは雪(ゆき)が降(ふ)ると、外(そと)で元気(げんき)に雪(ゆき)だるまを作(つく)る。", "sentence_source": "generated"}, {"text": "外が暗くなってきたので、部屋の電気をつけた。", "target_word": "外", "complexity_tier": "T3", "furigana": "外(そと)が暗(くら)くなってきたので、部屋(へや)の電気(でんき)をつけた。", "sentence_source": "generated"}, {"text": "夜になると、外から虫の鳴く声が聞こえてくる。", "target_word": "外", "complexity_tier": "T3", "furigana": "夜(よる)になると、外(そと)から虫(むし)の鳴(な)く声(こえ)が聞(き)こえてくる。", "sentence_source": "generated"}, {"text": "兄は外で三十分走ってから、シャワーを浴びた。", "target_word": "外", "complexity_tier": "T3", "furigana": "兄(あに)は外(そと)で三十分(さんじゅっぷん)走(はし)ってから、シャワーを浴(あ)びた。", "sentence_source": "generated"}, {"text": "猫を外に出すと、すぐに庭の木に登った。", "target_word": "外", "complexity_tier": "T3", "furigana": "猫(ねこ)を外(そと)に出(だ)すと、すぐに庭(にわ)の木(き)に登(のぼ)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外", "label": "基本形"}, {"form": "外の", "label": "連体形"}, {"form": "外に", "label": "に格"}, {"form": "外で", "label": "で格"}, {"form": "外は", "label": "は提題"}], "register": "neutral", "sense_fingerprint": "家や建物の外の場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f31001-e24e-4d36-97fe-2a4a88c33e43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38770, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外", "is_correct": true, "explanation": "「家の外で犬が吠えている」と、家の外の場所を表す。"}, {"text": "花", "is_correct": false, "explanation": "「家の花で犬が吠えている」は意味が通らない。"}, {"text": "指", "is_correct": false, "explanation": "「家の指で犬が吠えている」は意味が通らない。"}, {"text": "鍵", "is_correct": false, "explanation": "「家の鍵で犬が吠えている」は意味が通らない。"}], "explanations": {"外": "「家の外で犬が吠えている」と、家の外の場所を表す。", "花": "「家の花で犬が吠えている」は意味が通らない。", "指": "「家の指で犬が吠えている」は意味が通らない。", "鍵": "「家の鍵で犬が吠えている」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は胸の外を明かした。", "explanation": "ここは〈内〉の意味。〈外〉は家の外側を指すので、胸の内側を表す〈内〉の意味にはならない。"}, {"text": "その結果は予想の外だった。", "explanation": "ここは〈予想の範囲外〉の意味。家や建物の外側を表す〈外〉の義ではない。"}, {"text": "私は次回の外を見る。", "explanation": "ここは〈続き〉の意味。〈外〉は家の外側を指すので、続きを表す意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38770, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外", "is_correct": true, "explanation": "「外が暗くなってきた」と、家の外の様子を主語として表す。"}, {"text": "机", "is_correct": false, "explanation": "「机が暗くなってきた」は意味が通らない。"}, {"text": "皿", "is_correct": false, "explanation": "「皿が暗くなってきた」は意味が通らない。"}, {"text": "靴", "is_correct": false, "explanation": "「靴が暗くなってきた」は意味が通らない。"}], "explanations": {"外": "「外が暗くなってきた」と、家の外の様子を主語として表す。", "机": "「机が暗くなってきた」は意味が通らない。", "皿": "「皿が暗くなってきた」は意味が通らない。", "靴": "「靴が暗くなってきた」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その行動は規則の外だった。", "explanation": "ここは〈範囲外〉の意味。家の外側の場所を表す〈外〉ではなく、規則の範囲を表す使い方。"}, {"text": "彼は外に入って、手を洗った。", "explanation": "ここは家の中に入る意味。〈外〉は家の外側を指すので、家の中へ入る意味にはならない。"}, {"text": "夜になったので外を閉めた。", "explanation": "ここは〈雨戸〉を閉める意味。〈外〉は家の外側を指すので、雨戸を閉める対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38770, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨がやんだので、外が出て布団を干した。", "corrected_sentence": "雨がやんだので、外に出て布団を干した。", "error_description": "「出る」は人が主語で、場所は「に」で示す。「外が出て」は主語が誤り。正しくは「外に出て」。助詞「が」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38770, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜になると、窓の外を虫の鳴く声が聞こえてくる。", "corrected_sentence": "夜になると、窓の外から虫の鳴く声が聞こえてくる。", "error_description": "「聞こえる」は音の出どころを「から」で示す。「外を」は誤りで、正しくは「外から」。助詞「を」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38771, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「外の世界」と名詞を修飾する「の」。外側にある世界という意味。"}, {"text": "が", "is_correct": false, "explanation": "「外が世界へと」では主語として続かず、文が成立しない。"}, {"text": "を", "is_correct": false, "explanation": "「外を世界へと」では目的語として続かず、文が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「外に世界へと」では場所を示す形にならず、文が成立しない。"}], "correct_answer": "の", "explanations": {"の": "「外の世界」と名詞を修飾する「の」。外側にある世界という意味。", "が": "「外が世界へと」では主語として続かず、文が成立しない。", "を": "「外を世界へと」では目的語として続かず、文が成立しない。", "に": "「外に世界へと」では場所を示す形にならず、文が成立しない。"}, "error_tags": {"が": "主格", "を": "目的格", "に": "位置・方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内", "is_correct": true, "explanation": "範囲の内側を指し、〈外〉の対義語。"}, {"text": "前", "is_correct": false, "explanation": "前方を指す語で、〈外〉の対義語ではない。"}, {"text": "横", "is_correct": false, "explanation": "側面を指す語で、〈外〉の対義語ではない。"}, {"text": "下", "is_correct": false, "explanation": "位置の低い方を指す語で、〈外〉の対義語ではない。"}], "correct_answer": "内", "explanations": {"内": "範囲の内側を指し、〈外〉の対義語。", "前": "前方を指す語で、〈外〉の対義語ではない。", "横": "側面を指す語で、〈外〉の対義語ではない。", "下": "位置の低い方を指す語で、〈外〉の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38771, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す「で」。門の外という場所で待っていたという意味に合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」だと、外へ向かって待つという不自然な意味になる。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」は、待っていた場所を表す文脈に合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す「と」は、場所を表す文脈に合わない。"}], "correct_answer": "で", "explanations": {"で": "場所を示す「で」。門の外という場所で待っていたという意味に合う。", "へ": "方向を示す「へ」だと、外へ向かって待つという不自然な意味になる。", "より": "比較を示す「より」は、待っていた場所を表す文脈に合わない。", "と": "相手や並列を示す「と」は、場所を表す文脈に合わない。"}, "error_tags": {"へ": "方向", "より": "比較", "と": "相手・並列"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内", "is_correct": true, "explanation": "範囲の内側を指し、〈外〉の対義語。"}, {"text": "上", "is_correct": false, "explanation": "高い方を指す語で、〈外〉の対義語ではない。"}, {"text": "隣", "is_correct": false, "explanation": "隣接する位置を指す語で、〈外〉の対義語ではない。"}, {"text": "北", "is_correct": false, "explanation": "方角を表す語で、〈外〉の対義語ではない。"}], "correct_answer": "内", "explanations": {"内": "範囲の内側を指し、〈外〉の対義語。", "上": "高い方を指す語で、〈外〉の対義語ではない。", "隣": "隣接する位置を指す語で、〈外〉の対義語ではない。", "北": "方角を表す語で、〈外〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38771, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "そと。あるものの範囲の外側。", "primary_collocate": null, "pronunciation": "そと", "ipa": "soto", "syllable_count": 2, "sentences": [{"text": "規則の外にある行動は、この大会では認められない。", "target_word": "外", "complexity_tier": "T3", "furigana": "規則[きそく]の外[そと]にある行動[こうどう]は、この大会[たいかい]では認[みと]められない。", "sentence_source": "generated"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "外", "complexity_tier": "T5", "furigana": "苛烈(かれつ)な寒風(かんぷう)が頬(ほお)を打(う)つ外(そと)の世界(せかい)へと、無垢(むく)な好奇心(こうきしん)を携(たずさ)えて駆(か)け出(だ)していくその背中(せなか)には、人間(にんげん)が本来(ほんらい)備(そな)えている、過酷(かこく)な環境(かんきょう)をも楽(たの)しみへと変貌(へんぼう)させる逞(たくま)しさが凝縮(ぎょうしゅく)されていたのである。", "sentence_source": "mined"}, {"text": "白い線の外にボールが出てしまい、試合が止まった。", "target_word": "外", "complexity_tier": "T3", "furigana": "白(しろ)い線(せん)の外(そと)にボールが出(で)てしまい、試合(しあい)が止(と)まった。", "sentence_source": "generated"}, {"text": "町の外に広がる畑では、秋になると稲が黄金色に実る。", "target_word": "外", "complexity_tier": "T3", "furigana": "町(まち)の外(そと)に広(ひろ)がる畑(はたけ)では、秋(あき)になると稲(いね)が黄金色(こがねいろ)に実(みの)る。", "sentence_source": "generated"}, {"text": "塀の外から聞こえる声に、子どもたちは耳を澄ました。", "target_word": "外", "complexity_tier": "T3", "furigana": "塀(へい)の外(そと)から聞(き)こえる声(こえ)に、子(こ)どもたちは耳(みみ)を澄(す)ました。", "sentence_source": "generated"}, {"text": "円の外に立っている人は、このゲームに参加できない。", "target_word": "外", "complexity_tier": "T3", "furigana": "円(えん)の外(そと)に立(た)っている人(ひと)は、このゲームに参加(さんか)できない。", "sentence_source": "generated"}, {"text": "窓を開けると、部屋の外の冷たい空気が流れ込んできた。", "target_word": "外", "complexity_tier": "T3", "furigana": "窓(まど)を開(あ)けると、部屋(へや)の外(そと)の冷(つめ)たい空気(くうき)が流(なが)れ込(こ)んできた。", "sentence_source": "generated"}, {"text": "門の外で待っていた母は、私を見つけて手を振った。", "target_word": "外", "complexity_tier": "T3", "furigana": "門(もん)の外(そと)で待(ま)っていた母(はは)は、私(わたし)を見(み)つけて手(て)を振(ふ)った。", "sentence_source": "generated"}, {"text": "柵の外へ出た羊を、犬が急いで群れに連れ戻した。", "target_word": "外", "complexity_tier": "T3", "furigana": "柵(さく)の外(そと)へ出(で)た羊(ひつじ)を、犬(いぬ)が急(いそ)いで群(む)れに連(つ)れ戻(もど)した。", "sentence_source": "generated"}, {"text": "会議室の外まで、彼の大きな笑い声が響いていた。", "target_word": "外", "complexity_tier": "T3", "furigana": "会議室(かいぎしつ)の外(そと)まで、彼(かれ)の大(おお)きな笑(わら)い声(ごえ)が響(ひび)いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外", "label": "基本形"}, {"form": "外の", "label": "連体形"}, {"form": "外に", "label": "に格"}, {"form": "外で", "label": "で格"}, {"form": "外から", "label": "から格"}], "register": "neutral", "sense_fingerprint": "ある範囲や境界の外側", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: 寒風 (Zipf 2.18), 逞し (Zipf 2.19)','sentence 8 above tier T1: 3 words above tier T1 (max 2): 柵 (Zipf 3.72), 群れ (Zipf 3.91), 連れ戻し (Zipf 2.57)']::text[], '85f31001-e24e-4d36-97fe-2a4a88c33e43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38771, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外", "is_correct": true, "explanation": "「規則の外にある行動」と、範囲の外側を表す。"}, {"text": "病院", "is_correct": false, "explanation": "「規則の病院にある行動」は意味が通らない。"}, {"text": "図書館", "is_correct": false, "explanation": "「規則の図書館にある行動」は意味が通らない。"}, {"text": "教室", "is_correct": false, "explanation": "「規則の教室にある行動」は意味が通らない。"}], "explanations": {"外": "「規則の外にある行動」と、範囲の外側を表す。", "病院": "「規則の病院にある行動」は意味が通らない。", "図書館": "「規則の図書館にある行動」は意味が通らない。", "教室": "「規則の教室にある行動」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一番外に教室に着いた。", "explanation": "ここは〈先〉の意味。〈外〉は範囲の外側を指すので、順番を表す〈先〉の意味にはならない。"}, {"text": "家の外で遊んだ。", "explanation": "ここは〈屋外〉の意味。場所としての外を表し、範囲の外側の意味ではない。"}, {"text": "外の空は、今日もきれいに晴れていた。", "explanation": "ここは〈屋外〉の意味。建物の外の空を指し、範囲の外側の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38771, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外", "is_correct": true, "explanation": "「部屋の外の冷たい空気」と、部屋の外側にある空気を表す。"}, {"text": "歌", "is_correct": false, "explanation": "「部屋の歌の冷たい空気」は意味が通らない。"}, {"text": "味", "is_correct": false, "explanation": "「部屋の味の冷たい空気」は意味が通らない。"}, {"text": "辞書", "is_correct": false, "explanation": "「部屋の辞書の冷たい空気」は意味が通らない。"}], "explanations": {"外": "「部屋の外の冷たい空気」と、部屋の外側にある空気を表す。", "歌": "「部屋の歌の冷たい空気」は意味が通らない。", "味": "「部屋の味の冷たい空気」は意味が通らない。", "辞書": "「部屋の辞書の冷たい空気」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一年の外で一番寒い月は一月だ。", "explanation": "ここは〈中〉の意味。〈外〉は範囲の外側を指すので、範囲の内側で比べる文には合わない。"}, {"text": "私は外で本を読んだ。", "explanation": "ここは〈屋外〉の意味。場所としての外を表し、範囲の外側の意味ではない。"}, {"text": "彼は心の外を明かした。", "explanation": "ここは〈内〉の意味。〈外〉は範囲の外側を指すので、心の内側を表す〈内〉の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38771, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校舎の外を広い駐車場が広がっている。", "corrected_sentence": "校舎の外に広い駐車場が広がっている。", "error_description": "「広がる」は場所を「に」で示す。「外を」は誤りで、正しくは「外に」。助詞「を」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38771, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓を開けると、廊下の外を冷たい空気が流れ込んできた。", "corrected_sentence": "窓を開けると、廊下の外の冷たい空気が流れ込んできた。", "error_description": "「廊下の外」は名詞を修飾する「の」が要る。「外を」は誤りで、正しくは「外の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38772, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『費用が』は形容詞『高い』の主語を示す正しい格助詞。"}, {"text": "を", "is_correct": false, "explanation": "『費用を』では形容詞の主語にならず、『高くて』と続かない。"}, {"text": "に", "is_correct": false, "explanation": "『費用に』では状態の主体を示せず、『高くて』と結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "『費用で』では手段の意味になり、『高い』の主語として合わない。"}], "correct_answer": "が", "explanations": {"が": "『費用が』は形容詞『高い』の主語を示す正しい格助詞。", "を": "『費用を』では形容詞の主語にならず、『高くて』と続かない。", "に": "『費用に』では状態の主体を示せず、『高くて』と結びつかない。", "で": "『費用で』では手段の意味になり、『高い』の主語として合わない。"}, "error_tags": {"を": "形容詞への目的語の誤用", "に": "状態主体の誤用", "で": "手段の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38772, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『費用は』で話題の主題を示し、『分けます』へ続く正しい係助詞。"}, {"text": "に", "is_correct": false, "explanation": "『費用に』では方向や対象になり、主題として分けるという文の前提が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "『費用で』では手段の意味になり、分けるものを示せない。"}, {"text": "の", "is_correct": false, "explanation": "『費用の』では名詞修飾になり、文の主題を示せない。"}], "correct_answer": "は", "explanations": {"は": "『費用は』で話題の主題を示し、『分けます』へ続く正しい係助詞。", "に": "『費用に』では方向や対象になり、主題として分けるという文の前提が崩れる。", "で": "『費用で』では手段の意味になり、分けるものを示せない。", "の": "『費用の』では名詞修飾になり、文の主題を示せない。"}, "error_tags": {"に": "方向・対象の誤用", "で": "手段の誤用", "の": "修飾の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38772, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときにお金がかかること。", "primary_collocate": null, "pronunciation": "ひよう", "ipa": "çijoː", "syllable_count": 3, "sentences": [{"text": "引っ越しの費用を、家族みんなで少しずつ出した。", "target_word": "費用", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの費用[ひよう]を、家族[かぞく]みんなで少[すこ]しずつ出[だ]した。", "sentence_source": "generated"}, {"text": "旅行の費用が高いので、今年は行くのをやめた。", "target_word": "費用", "complexity_tier": "T3", "furigana": "旅行[りょこう]の費用[ひよう]が高[たか]いので、今年[ことし]は行[い]くのをやめた。", "sentence_source": "generated"}, {"text": "費用を安くするために、自分で部屋のペンキをぬった。", "target_word": "費用", "complexity_tier": "T3", "furigana": "費用[ひよう]を安[やす]くするために、自分[じぶん]で部屋[へや]のペンキをぬった。", "sentence_source": "generated"}, {"text": "結婚式にはたくさんの費用がかかる。", "target_word": "費用", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]にはたくさんの費用[ひよう]がかかる。", "sentence_source": "generated"}, {"text": "この工事の費用は、市が全部はらってくれる。", "target_word": "費用", "complexity_tier": "T3", "furigana": "この工事[こうじ]の費用[ひよう]は、市[し]が全部[ぜんぶ]はらってくれる。", "sentence_source": "generated"}, {"text": "留学の費用を集めるために、毎日アルバイトをしている。", "target_word": "費用", "complexity_tier": "T3", "furigana": "留学[りゅうがく]の費用[ひよう]を集[あつ]めるために、毎日[まいにち]アルバイトをしている。", "sentence_source": "generated"}, {"text": "費用はかかるが、新しい機械を入れることにした。", "target_word": "費用", "complexity_tier": "T3", "furigana": "費用[ひよう]はかかるが、新[あたら]しい機械[きかい]を入[い]れることにした。", "sentence_source": "generated"}, {"text": "パーティーの費用は、参加者で同じ金額ずつ分けます。", "target_word": "費用", "complexity_tier": "T3", "furigana": "パーティーの費用[ひよう]は、参加者[さんかしゃ]で同[おな]じ金額[きんがく]ずつ分[わ]けます。", "sentence_source": "generated"}, {"text": "修理に思ったより費用がかかり、新しいものを買えばよかった。", "target_word": "費用", "complexity_tier": "T3", "furigana": "修理[しゅうり]に思[おも]ったより費用[ひよう]がかかり、新[あたら]しいものを買[か]えばよかった。", "sentence_source": "generated"}, {"text": "費用を考えると、この計画は今は無理だ。", "target_word": "費用", "complexity_tier": "T3", "furigana": "費用[ひよう]を考[かんが]えると、この計画[けいかく]は今[いま]は無理[むり]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "費用", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何かをするために出ていくお金（引っ越し・旅行・工事などにかかるお金）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38772, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "費用", "is_correct": true, "explanation": "引っ越しのためにお金を出すという意味で、空欄に入って自然な文になる。"}, {"text": "予定", "is_correct": false, "explanation": "予定は計画のことで、お金を出す対象ではないので文が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、お金を出す対象にはならない。"}, {"text": "好み", "is_correct": false, "explanation": "好みは嗜好のことで、お金を出す対象にはならないので不自然。"}], "explanations": {"費用": "引っ越しのためにお金を出すという意味で、空欄に入って自然な文になる。", "予定": "予定は計画のことで、お金を出す対象ではないので文が成り立たない。", "天気": "天気は空模様のことで、お金を出す対象にはならない。", "好み": "好みは嗜好のことで、お金を出す対象にはならないので不自然。"}, "sentence_index": 0, "correct_answer": "費用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この車は費用が速くて、高速道路で目立つ。", "explanation": "ここは〈速さ〉の意味。費用はお金の額で、乗り物の速さには使わない。"}, {"text": "このかばんは費用が重くて、毎日持つのがつらい。", "explanation": "ここは〈重さ〉の意味。費用はお金の額で、物の重さには使わない。"}, {"text": "大会で費用を三十万円獲得した。", "explanation": "ここは〈賞金〉（大会で勝って受け取るお金）の意味。費用は何かをするために使うお金で、獲得して受け取るお金の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38772, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "費用", "is_correct": true, "explanation": "新しい機械を入れるためにかかるお金を指すので、空欄に入って自然な文になる。"}, {"text": "機嫌", "is_correct": false, "explanation": "機嫌は気分のことで、かかるものとして言えないので不自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、かかるものとして言えないので文が成り立たない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気の水分量のことで、かかるものとして言えないので合わない。"}], "explanations": {"費用": "新しい機械を入れるためにかかるお金を指すので、空欄に入って自然な文になる。", "機嫌": "機嫌は気分のことで、かかるものとして言えないので不自然。", "天気": "天気は空模様のことで、かかるものとして言えないので文が成り立たない。", "湿度": "湿度は空気の水分量のことで、かかるものとして言えないので合わない。"}, "sentence_index": 6, "correct_answer": "費用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は費用が丸くて、重ねて置きやすい。", "explanation": "ここは〈形〉の意味。費用はお金の額で、物の形には使わない。"}, {"text": "この道具は費用が広く、料理にも掃除にも使える。", "explanation": "ここは〈用途〉（使い道）の意味。費用はお金の額で、道具の使い道の広さには使わない。"}, {"text": "このパンは費用が豊富で、朝食にぴったりだ。", "explanation": "ここは〈栄養〉の意味。費用は使うお金の額で、食べ物の成分には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38772, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅行の費用を高くて、今年は行くのをやめた。", "corrected_sentence": "旅行の費用が高くて、今年は行くのをやめた。", "error_description": "『高い』は形容詞で、主語の『費用』は『が』で示す。『費用を』は誤りで、正しくは『費用が』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38772, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "費用を思ったより少なくて、ほっとした。", "corrected_sentence": "費用が思ったより少なくて、ほっとした。", "error_description": "『少ない』は形容詞なので、主語の『費用』は『が』で示す。『費用を』は誤りで、正しくは『費用が』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38773, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『計算する』の目的語『費用』を示す正しい格助詞。"}, {"text": "が", "is_correct": false, "explanation": "『費用が』では主語になり、『計算してから』の目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "『費用の』では名詞修飾になり、『計算して』の目的語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示すもので、計算する対象の指定にはならない。"}], "correct_answer": "を", "explanations": {"を": "『計算する』の目的語『費用』を示す正しい格助詞。", "が": "『費用が』では主語になり、『計算してから』の目的語にならない。", "の": "『費用の』では名詞修飾になり、『計算して』の目的語を示せない。", "と": "『と』は並列や相手を示すもので、計算する対象の指定にはならない。"}, "error_tags": {"が": "主語の誤用", "の": "修飾の誤用", "と": "並列の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38773, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『聞く』の目的語『費用』を示す正しい格助詞。"}, {"text": "が", "is_correct": false, "explanation": "『費用が』では主語になり、『聞いてから』の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "『費用で』では手段の意味になり、聞く対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "『費用に』では相手の意味になり、費用という物事を聞く対象として合わない。"}], "correct_answer": "を", "explanations": {"を": "『聞く』の目的語『費用』を示す正しい格助詞。", "が": "『費用が』では主語になり、『聞いてから』の目的語にならない。", "で": "『費用で』では手段の意味になり、聞く対象を示せない。", "に": "『費用に』では相手の意味になり、費用という物事を聞く対象として合わない。"}, "error_tags": {"が": "主語の誤用", "で": "手段の誤用", "に": "相手の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38773, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることをするのに必要なお金の額。", "primary_collocate": null, "pronunciation": "ひよう", "ipa": "çijoː", "syllable_count": 3, "sentences": [{"text": "家を建てる費用は、いくらぐらいですか。", "target_word": "費用", "complexity_tier": "T3", "furigana": "家[いえ]を建[た]てる費用[ひよう]は、いくらぐらいですか。", "sentence_source": "generated"}, {"text": "先に費用を計算してから、旅行の計画を立てた。", "target_word": "費用", "complexity_tier": "T3", "furigana": "先[さき]に費用[ひよう]を計算[けいさん]してから、旅行[りょこう]の計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "学校に払う費用の合計は、十万円だった。", "target_word": "費用", "complexity_tier": "T3", "furigana": "学校[がっこう]に払[はら]う費用[ひよう]の合計[ごうけい]は、十万円[じゅうまんえん]だった。", "sentence_source": "generated"}, {"text": "見積書には、必要な費用が一つずつ書いてある。", "target_word": "費用", "complexity_tier": "T3", "furigana": "見積書[みつもりしょ]には、必要[ひつよう]な費用[ひよう]が一[ひと]つずつ書[か]いてある。", "sentence_source": "generated"}, {"text": "費用が足りなくて、計画を半分に減らした。", "target_word": "費用", "complexity_tier": "T3", "furigana": "費用[ひよう]が足[た]りなくて、計画[けいかく]を半分[はんぶん]に減[へ]らした。", "sentence_source": "generated"}, {"text": "この手術の費用は、保険で一部が戻ってくる。", "target_word": "費用", "complexity_tier": "T3", "furigana": "この手術[しゅじゅつ]の費用[ひよう]は、保険[ほけん]で一部[いちぶ]が戻[もど]ってくる。", "sentence_source": "generated"}, {"text": "予想の二倍の費用になり、社長はおどろいた。", "target_word": "費用", "complexity_tier": "T3", "furigana": "予想[よそう]の二倍[にばい]の費用[ひよう]になり、社長[しゃちょう]はおどろいた。", "sentence_source": "generated"}, {"text": "店で費用を聞いてから、買うかどうか決めます。", "target_word": "費用", "complexity_tier": "T3", "furigana": "店[みせ]で費用[ひよう]を聞[き]いてから、買[か]うかどうか決[き]めます。", "sentence_source": "generated"}, {"text": "イベントの費用は、全部で五十万円ほどだった。", "target_word": "費用", "complexity_tier": "T3", "furigana": "イベントの費用[ひよう]は、全部[ぜんぶ]で五十万円[ごじゅうまんえん]ほどだった。", "sentence_source": "generated"}, {"text": "ホテルの費用は、一人一万円以内にしたい。", "target_word": "費用", "complexity_tier": "T3", "furigana": "ホテルの費用[ひよう]は、一人[ひとり]一万円[いちまんえん]以内[いない]にしたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "費用", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "あることに必要なお金の金額（見積もり・合計・予算と結びつく額）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67562c68-4c35-496f-99ad-14c6fca363a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38773, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "費用", "is_correct": true, "explanation": "家を建てるためにかかるお金を指すので、空欄に入って自然な文になる。"}, {"text": "時間", "is_correct": false, "explanation": "時間は長さを表すもので、『いくらぐらい』と金額を尋ねる文に合わない。"}, {"text": "理由", "is_correct": false, "explanation": "理由は事情のことで、金額を尋ねる文の主語にならないので不自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、家を建てる金額の対象にならないので文が成り立たない。"}], "explanations": {"費用": "家を建てるためにかかるお金を指すので、空欄に入って自然な文になる。", "時間": "時間は長さを表すもので、『いくらぐらい』と金額を尋ねる文に合わない。", "理由": "理由は事情のことで、金額を尋ねる文の主語にならないので不自然。", "天気": "天気は空模様のことで、家を建てる金額の対象にならないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "費用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このペンキは費用が鮮やかで、部屋が明るくなった。", "explanation": "ここは〈色合い〉の意味。費用はお金の額で、色の鮮やかさには使わない。"}, {"text": "彼は仕事の費用が豊富で、新人の相談によく乗っている。", "explanation": "ここは〈経験〉の意味。費用はお金の額で、積み重ねた経験の量には使わない。"}, {"text": "このスープは費用が濃く、野菜の旨味がよく出ている。", "explanation": "ここは〈味〉の意味。費用は何かをするための金額で、料理の味の濃さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38773, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "費用", "is_correct": true, "explanation": "予想より多くかかったお金を指すので、空欄に入って自然な文になる。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、『二倍になり』と続く金額の話に合わない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は眠っている間に話す言葉で、二倍になるものとして不自然。"}, {"text": "紙", "is_correct": false, "explanation": "紙は材料の一つで、予想の二倍になるものとして文が成り立たない。"}], "explanations": {"費用": "予想より多くかかったお金を指すので、空欄に入って自然な文になる。", "天気": "天気は空模様のことで、『二倍になり』と続く金額の話に合わない。", "寝言": "寝言は眠っている間に話す言葉で、二倍になるものとして不自然。", "紙": "紙は材料の一つで、予想の二倍になるものとして文が成り立たない。"}, "sentence_index": 6, "correct_answer": "費用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このお菓子は費用が切れたので、食べないでください。", "explanation": "ここは〈賞味期限〉の意味。費用は何かに使うお金で、食品の期限の意味では使わない。"}, {"text": "彼は費用が温かく、誰にでも優しい。", "explanation": "ここは〈人柄〉の意味。費用はお金の額で、人の性格の温かさには使わない。"}, {"text": "駅までの費用は三キロほどだ。", "explanation": "ここは〈距離〉（道のりの長さ）の意味。費用はお金の額で、道のりの長さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38773, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家を直す費用を、思ったより高かった。", "corrected_sentence": "家を直す費用が、思ったより高かった。", "error_description": "『高い』は形容詞なので、主語の『費用』は『が』で示す。『費用を』は誤りで、正しくは『費用が』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38773, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ホテルの費用へ、二人で二万円ほどだった。", "corrected_sentence": "ホテルの費用は、二人で二万円ほどだった。", "error_description": "文の主題を示す『は』の位置に『へ』が使われている。費用が主題なので『は』が正しく、『へ』は方向を示すため不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6f45b3-6920-4e92-89e5-bb342e5c6330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
