INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38774, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "時々は「ときどき」と読んで、何かを何回もするのではなく、たまにするという意味です。", "primary_collocate": null, "pronunciation": "ときどき", "ipa": "tokidoki", "syllable_count": 4, "sentences": [{"text": "毎日は走りませんが、時々公園を走ります。", "target_word": "時々", "complexity_tier": "T3", "furigana": "毎日[まいにち]は走[はし]りませんが、時々[ときどき]公園[こうえん]を走[はし]ります。", "sentence_source": "generated"}, {"text": "弟は料理が苦手ですが、時々夕飯を作ってくれます。", "target_word": "時々", "complexity_tier": "T3", "furigana": "弟[おとうと]は料理[りょうり]が苦手[にがて]ですが、時々[ときどき]夕飯[ゆうはん]を作[つく]ってくれます。", "sentence_source": "generated"}, {"text": "私は普段コーヒーですが、時々紅茶も飲みます。", "target_word": "時々", "complexity_tier": "T3", "furigana": "私[わたし]は普段[ふだん]コーヒーですが、時々[ときどき]紅茶[こうちゃ]も飲[の]みます。", "sentence_source": "generated"}, {"text": "電話は苦手なので、祖母に時々手紙を書きます。", "target_word": "時々", "complexity_tier": "T3", "furigana": "電話[でんわ]は苦手[にがて]なので、祖母[そぼ]に時々[ときどき]手紙[てがみ]を書[か]きます。", "sentence_source": "generated"}, {"text": "忙しいので、友達とは時々会うだけです。", "target_word": "時々", "complexity_tier": "T3", "furigana": "忙[いそが]しいので、友達[ともだち]とは時々[ときどき]会[あ]うだけです。", "sentence_source": "generated"}, {"text": "週末は家にいることが多いですが、時々映画を見に行きます。", "target_word": "時々", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]は家[いえ]にいることが多[おお]いですが、時々[ときどき]映画[えいが]を見[み]に行[い]きます。", "sentence_source": "generated"}, {"text": "彼は無口ですが、時々おもしろい冗談を言います。", "target_word": "時々", "complexity_tier": "T3", "furigana": "彼[かれ]は無口[むくち]ですが、時々[ときどき]おもしろい冗談[じょうだん]を言[い]います。", "sentence_source": "generated"}, {"text": "毎週ではなく、時々図書館で勉強します。", "target_word": "時々", "complexity_tier": "T3", "furigana": "毎週[まいしゅう]ではなく、時々[ときどき]図書館[としょかん]で勉強[べんきょう]します。", "sentence_source": "generated"}, {"text": "運動は嫌いですが、時々プールで泳ぎます。", "target_word": "時々", "complexity_tier": "T3", "furigana": "運動[うんどう]は嫌[きら]いですが、時々[ときどき]プールで泳[およ]ぎます。", "sentence_source": "generated"}, {"text": "姉は忙しい人で、時々しか家に帰ってきません。", "target_word": "時々", "complexity_tier": "T3", "furigana": "姉[あね]は忙[いそが]しい人[ひと]で、時々[ときどき]しか家[いえ]に帰[かえ]ってきません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "時々", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が毎回ではなく、たまにある行動をすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6a65927-b447-4fa1-9765-03dbf2c9836d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38774, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "時々", "is_correct": true, "explanation": "「たまに」の意味で、毎日ではない行動を表すので文に合う。"}, {"text": "全然", "is_correct": false, "explanation": "否定の文と結びつく副詞で、肯定の「走ります」には合わない。"}, {"text": "決して", "is_correct": false, "explanation": "否定の表現と結びつく副詞で、「決して公園を走ります」は不自然。"}, {"text": "一度も", "is_correct": false, "explanation": "否定と結びつくため、「一度も公園を走ります」は成り立たない。"}], "explanations": {"時々": "「たまに」の意味で、毎日ではない行動を表すので文に合う。", "全然": "否定の文と結びつく副詞で、肯定の「走ります」には合わない。", "決して": "否定の表現と結びつく副詞で、「決して公園を走ります」は不自然。", "一度も": "否定と結びつくため、「一度も公園を走ります」は成り立たない。"}, "sentence_index": 0, "correct_answer": "時々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎日、時々夕飯を作ってもらっています。", "explanation": "「毎日」と「時々」は矛盾する。時々は毎回ではなくたまにの意味なので、毎日の行動には使わない。"}, {"text": "毎朝、時々歯を磨きます。", "explanation": "「毎朝」（毎回）と「時々」は矛盾する。定義のたまにの意味では使えない。"}, {"text": "必ず、時々メールを送ります。", "explanation": "「必ず」（例外なく）と「時々」は矛盾する。たまにの意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38774, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "時々", "is_correct": true, "explanation": "「たまに」の意味で、「いつもは無口だがたまに冗談を言う」という文脈に合う。"}, {"text": "少しも", "is_correct": false, "explanation": "否定と結びつく副詞で、肯定の「言います」には合わない。"}, {"text": "一切", "is_correct": false, "explanation": "否定と結びつくため、「一切おもしろい冗談を言います」は不自然。"}, {"text": "めったに", "is_correct": false, "explanation": "否定の文で使う副詞で、肯定の「言います」には合わない。"}], "explanations": {"時々": "「たまに」の意味で、「いつもは無口だがたまに冗談を言う」という文脈に合う。", "少しも": "否定と結びつく副詞で、肯定の「言います」には合わない。", "一切": "否定と結びつくため、「一切おもしろい冗談を言います」は不自然。", "めったに": "否定の文で使う副詞で、肯定の「言います」には合わない。"}, "sentence_index": 6, "correct_answer": "時々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎晩、時々ニュースを見ます。", "explanation": "「毎晩」（毎回）と「時々」は矛盾する。たまにの意味では使えない。"}, {"text": "常に時々、電話が鳴ります。", "explanation": "「常に」（いつも）と「時々」は矛盾する。定義の意味とは合わない。"}, {"text": "一日中、時々テレビをつけっぱなしにしています。", "explanation": "「一日中」（途切れず続く）と「時々」は矛盾する。たまにの意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38774, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は時々に、夜遅くまで仕事をします。", "corrected_sentence": "彼は時々、夜遅くまで仕事をします。", "error_description": "副詞「時々」に助詞「に」が付いている。副詞には「に」が付かないので、「時々、」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38774, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は、時々しか古い映画を見ます。", "corrected_sentence": "私は、時々古い映画を見ます。", "error_description": "副詞「時々」に「しか」が付いている。「しか」は「〜ない」と結ぶ形でしか使えないので、肯定の「見ます」とは合わない。「時々、」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
