INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38775, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「時々」は、頻度が高くなく、あることが間をおいて起こる様子を表す副詞です。たまに、という意味で使われます。", "primary_collocate": null, "pronunciation": "ときどき", "ipa": "tokidoki", "syllable_count": 4, "sentences": [{"text": "空は晴れていますが、時々強い風が吹きます。", "target_word": "時々", "complexity_tier": "T3", "furigana": "空[そら]は晴[は]れていますが、時々[ときどき]強[つよ]い風[かぜ]が吹[ふ]きます。", "sentence_source": "generated"}, {"text": "明日は曇りで、時々雨が降るでしょう。", "target_word": "時々", "complexity_tier": "T3", "furigana": "明日[あした]は曇[くも]りで、時々[ときどき]雨[あめ]が降[ふ]るでしょう。", "sentence_source": "generated"}, {"text": "この道は静かですが、時々大きいトラックが通ります。", "target_word": "時々", "complexity_tier": "T3", "furigana": "この道[みち]は静[しず]かですが、時々[ときどき]大[おお]きいトラックが通[とお]ります。", "sentence_source": "generated"}, {"text": "古いパソコンが、時々急に止まります。", "target_word": "時々", "complexity_tier": "T3", "furigana": "古[ふる]いパソコンが、時々[ときどき]急[きゅう]に止[と]まります。", "sentence_source": "generated"}, {"text": "静かな夜中ですが、時々犬の鳴く声が聞こえます。", "target_word": "時々", "complexity_tier": "T3", "furigana": "静[しず]かな夜中[よなか]ですが、時々[ときどき]犬[いぬ]の鳴[な]く声[こえ]が聞[き]こえます。", "sentence_source": "generated"}, {"text": "山の上では、時々霧が出て景色が見えなくなります。", "target_word": "時々", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]では、時々[ときどき]霧[きり]が出[で]て景色[けしき]が見[み]えなくなります。", "sentence_source": "generated"}, {"text": "いつもは時間どおりですが、電車は時々遅れます。", "target_word": "時々", "complexity_tier": "T3", "furigana": "いつもは時間[じかん]どおりですが、電車[でんしゃ]は時々[ときどき]遅[おく]れます。", "sentence_source": "generated"}, {"text": "川の水は、普段はきれいですが、時々にごります。", "target_word": "時々", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]は、普段[ふだん]はきれいですが、時々[ときどき]にごります。", "sentence_source": "generated"}, {"text": "窓の外から、時々子どもの笑い声が聞こえてきます。", "target_word": "時々", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]から、時々[ときどき]子[こ]どもの笑[わら]い声[ごえ]が聞[き]こえてきます。", "sentence_source": "generated"}, {"text": "この辺りでは、時々きつねを見かけます。", "target_word": "時々", "complexity_tier": "T3", "furigana": "この辺[あた]りでは、時々[ときどき]きつねを見[み]かけます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "時々", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "天気や出来事などが、間をおいてたまに起こる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: にごり (Zipf 2.48)']::text[], 'd6a65927-b447-4fa1-9765-03dbf2c9836d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38775, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "時々", "is_correct": true, "explanation": "「たまに」の意味で、間をおいて強い風が吹く様子を表すので文に合う。"}, {"text": "全然", "is_correct": false, "explanation": "否定の文と結びつく副詞で、肯定の「吹きます」には合わない。"}, {"text": "決して", "is_correct": false, "explanation": "否定の表現と結びつく副詞で、「決して強い風が吹きます」は不自然。"}, {"text": "一度も", "is_correct": false, "explanation": "否定と結びつくため、「一度も強い風が吹きます」は成り立たない。"}], "explanations": {"時々": "「たまに」の意味で、間をおいて強い風が吹く様子を表すので文に合う。", "全然": "否定の文と結びつく副詞で、肯定の「吹きます」には合わない。", "決して": "否定の表現と結びつく副詞で、「決して強い風が吹きます」は不自然。", "一度も": "否定と結びつくため、「一度も強い風が吹きます」は成り立たない。"}, "sentence_index": 0, "correct_answer": "時々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝七時に、時々目覚まし時計が鳴ります。", "explanation": "「毎朝」と「時々」は矛盾する。たまに起こる出来事の意味には合わない。"}, {"text": "川の水は、絶えず時々流れています。", "explanation": "「絶えず」（途切れず）と「時々」は矛盾する。間をおいて起こる意味とは合わない。"}, {"text": "太陽は時々、東から昇ります。", "explanation": "毎日必ず起こる自然現象に「時々」は合わない。たまに起こる出来事の意味とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38775, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "時々", "is_correct": true, "explanation": "「たまに」の意味で、普段は時間どおりだが時々遅れる、という文脈に合う。"}, {"text": "少しも", "is_correct": false, "explanation": "否定と結びつく副詞で、肯定の「遅れます」には合わない。"}, {"text": "一切", "is_correct": false, "explanation": "否定と結びつくため、「一切遅れます」は不自然。"}, {"text": "めったに", "is_correct": false, "explanation": "否定の文で使う副詞で、肯定の「遅れます」には合わない。"}], "explanations": {"時々": "「たまに」の意味で、普段は時間どおりだが時々遅れる、という文脈に合う。", "少しも": "否定と結びつく副詞で、肯定の「遅れます」には合わない。", "一切": "否定と結びつくため、「一切遅れます」は不自然。", "めったに": "否定の文で使う副詞で、肯定の「遅れます」には合わない。"}, "sentence_index": 6, "correct_answer": "時々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜になると、時々必ず街灯が点きます。", "explanation": "「必ず」（例外なく）と「時々」は矛盾する。たまに起こる意味とは合わない。"}, {"text": "この辺りでは、時々いつも、きつねを見かけます。", "explanation": "「いつも」と「時々」は矛盾する。たまに見かける意味とは合わない。"}, {"text": "この町では、時々毎日、雪が降ります。", "explanation": "「毎日」と「時々」は矛盾する。間をおいて起こる意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38775, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明け方は時々に霧が出ます。", "corrected_sentence": "明け方は時々霧が出ます。", "error_description": "副詞「時々」に助詞「に」が付いている。副詞には「に」が付かないので、「時々だけ」で続けるのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38775, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道は、時々しか大きな音がします。", "corrected_sentence": "この道は、時々大きな音がします。", "error_description": "副詞「時々」に「しか」が付いている。「しか」は「〜ない」と結ぶ形でしか使えないので、肯定の「音がします」とは合わない。「時々、」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d162d0-d731-4fc2-a5a7-b42b2e9abcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38776, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ベランダに干す」で、干す場所を示す正しい格。"}, {"text": "が", "is_correct": false, "explanation": "主語の格。「ベランダが干す」ではベランダが動作主になり不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手の格。「ベランダと干す」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の格。「ベランダの干すと」では動詞に続かない。"}], "correct_answer": "に", "explanations": {"に": "「ベランダに干す」で、干す場所を示す正しい格。", "が": "主語の格。「ベランダが干す」ではベランダが動作主になり不自然。", "と": "並列・相手の格。「ベランダと干す」は文が成り立たない。", "の": "連体修飾の格。「ベランダの干すと」では動詞に続かない。"}, "error_tags": {"が": "主格", "と": "並列・相手", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
