INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38776, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家の外にある、屋根のない小さな場所です。", "primary_collocate": null, "pronunciation": "べらんだ", "ipa": "beɾanda", "syllable_count": 4, "sentences": [{"text": "朝、ベランダに出て、空気を吸いました。", "target_word": "ベランダ", "complexity_tier": "T2", "furigana": "朝[あさ]、ベランダに出[で]て、空気[くうき]を吸[す]いました。", "sentence_source": "generated"}, {"text": "洗濯物をベランダに干すと、すぐかわきます。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]をベランダに干[ほ]すと、すぐかわきます。", "sentence_source": "generated"}, {"text": "雨がふってきたので、ベランダの花を中に入れました。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "雨[あめ]がふってきたので、ベランダの花[はな]を中[なか]に入[い]れました。", "sentence_source": "generated"}, {"text": "うちのベランダは小さくて、いすが一つしか置けません。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "うちのベランダは小[ちい]さくて、いすが一[ひと]つしか置[お]けません。", "sentence_source": "generated"}, {"text": "夜、ベランダから星を見るのが好きです。", "target_word": "ベランダ", "complexity_tier": "T2", "furigana": "夜[よる]、ベランダから星[ほし]を見[み]るのが好[す]きです。", "sentence_source": "generated"}, {"text": "猫がベランダに出たがって、ドアの前で鳴いています。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "猫[ねこ]がベランダに出[で]たがって、ドアの前[まえ]で鳴[な]いています。", "sentence_source": "generated"}, {"text": "屋根のないベランダは、雨の日に床がぬれやすい。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "屋根[やね]のないベランダは、雨[あめ]の日[ひ]に床[ゆか]がぬれやすい。", "sentence_source": "generated"}, {"text": "風が強い日は、ベランダの物が飛ばないようにします。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]い日[ひ]は、ベランダの物[もの]が飛[と]ばないようにします。", "sentence_source": "generated"}, {"text": "弟はベランダで、小さなトマトを育てています。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "弟[おとうと]はベランダで、小[ちい]さなトマトを育[そだ]てています。", "sentence_source": "generated"}, {"text": "暑い夜は、ベランダで涼んでからねます。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "暑[あつ]い夜[よる]は、ベランダで涼[すず]んでからねます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ベランダ", "label": "基本形"}, {"form": "ベランダで", "label": "で格"}], "register": "標準（丁寧体・普通体）", "sense_fingerprint": "家の外にある屋根のない小さなスペース", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: かわき (Zipf 1.96)']::text[], '729dc63f-8b18-4b3c-895a-efbae94aab11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38776, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ベランダ", "is_correct": true, "explanation": "「朝、〜に出て、空気を吸いました」で、外に出る場所であるベランダが入る。"}, {"text": "ケーキ", "is_correct": false, "explanation": "出て空気を吸う場所にならない。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "出て空気を吸う場所にならない。"}, {"text": "ボタン", "is_correct": false, "explanation": "出て空気を吸う場所にならない。"}], "explanations": {"ベランダ": "「朝、〜に出て、空気を吸いました」で、外に出る場所であるベランダが入る。", "ケーキ": "出て空気を吸う場所にならない。", "ハンカチ": "出て空気を吸う場所にならない。", "ボタン": "出て空気を吸う場所にならない。"}, "sentence_index": 0, "correct_answer": "ベランダ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の夜、ベランダの押し入れに、家族の布団をしまった。", "explanation": "ここは屋内の収納（押し入れ）の意味。屋根のない屋外の小さな場所とは合わない。"}, {"text": "友だちの靴を、ベランダの靴箱にしまった。", "explanation": "ここは〈玄関〉の意味。靴箱は屋内の玄関にあるもので、屋根のない屋外の張り出し場所とは合わない。"}, {"text": "地下室のベランダに、観葉植物を並べた。", "explanation": "ここは屋内の部屋の意味。地上で建物の外へ張り出す場所を、地下の室内に当てるのは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38776, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ベランダ", "is_correct": true, "explanation": "「屋根のないベランダは、雨の日に床がぬれやすい」で、屋根のない屋外の場所が入る。"}, {"text": "ストーブ", "is_correct": false, "explanation": "屋根のない場所としての文脈に合わない。"}, {"text": "ハーモニカ", "is_correct": false, "explanation": "床がぬれやすいという文脈に合わない。"}, {"text": "ヘルメット", "is_correct": false, "explanation": "屋根のない場所の主語として不自然で、床がぬれる話にならない。"}], "explanations": {"ベランダ": "「屋根のないベランダは、雨の日に床がぬれやすい」で、屋根のない屋外の場所が入る。", "ストーブ": "屋根のない場所としての文脈に合わない。", "ハーモニカ": "床がぬれやすいという文脈に合わない。", "ヘルメット": "屋根のない場所の主語として不自然で、床がぬれる話にならない。"}, "sentence_index": 6, "correct_answer": "ベランダ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ベランダのカウンターで注文し、トレーを受け取った。", "explanation": "ここは店内の注文場所（フードコート）の意味。屋根のない屋外の張り出し場所とは合わない。"}, {"text": "ベランダの席で、映画を最後まで見た。", "explanation": "ここは劇場の二階席（バルコニー席）の意味。屋外の小さな場所とは違う。"}, {"text": "ベランダの床下にハーブを置いて、料理に使っている。", "explanation": "ここは地面の上の場所の意味。張り出した床の下は地面との間の空間で、ベランダとは別の場所になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38776, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日でも、洗濯物をベランダが干す人がいる。", "corrected_sentence": "雨の日でも、洗濯物をベランダに干す人がいる。", "error_description": "「干す」の場所はに格で示す。ベランダが（が格）にすると、ベランダが干す動作をすることになり意味が崩れる。正しくはベランダに。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38776, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "休日は、ベランダを鉢植えを並べて楽しむ。", "corrected_sentence": "休日は、ベランダに鉢植えを並べて楽しむ。", "error_description": "「並べる」の場所はに格で示す。ベランダを（を格）にすると、ベランダを並べる対象のように読まれ文が崩れる。正しくはベランダに。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
