INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38777, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ベランダに出ると」で、移動の到着点を示す正しい格。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の格。「ベランダで出る」は移動の到着点を示せない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の格。「ベランダの出ると」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手の格。「ベランダと出る」は文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「ベランダに出ると」で、移動の到着点を示す正しい格。", "で": "手段・場所の格。「ベランダで出る」は移動の到着点を示せない。", "の": "連体修飾の格。「ベランダの出ると」は文が成り立たない。", "と": "並列・相手の格。「ベランダと出る」は文が成り立たない。"}, "error_tags": {"で": "手段・場所", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38777, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物の外側に張り出した、手すりのついた平らな場所。洗濯物を干したり、植物を育てたりするのに使う。", "primary_collocate": null, "pronunciation": "べらんだ", "ipa": "beɾanda", "syllable_count": 4, "sentences": [{"text": "手すりのついたベランダから、下の道が見える。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "手[て]すりのついたベランダから、下[した]の道[みち]が見[み]える。", "sentence_source": "generated"}, {"text": "マンションの五階のベランダは、見晴らしがいい。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "マンションの五階[ごかい]のベランダは、見晴[みは]らしがいい。", "sentence_source": "generated"}, {"text": "朝、洗濯機を回して、ベランダに洗濯物を干した。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "朝[あさ]、洗濯機[せんたくき]を回[まわ]して、ベランダに洗濯物[せんたくもの]を干[ほ]した。", "sentence_source": "generated"}, {"text": "狭いベランダでも、プランターを並べれば野菜が育てられる。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "狭[せま]いベランダでも、プランターを並[なら]べれば野菜[やさい]が育[そだ]てられる。", "sentence_source": "generated"}, {"text": "隣の家とのあいだのベランダには、仕切りの板がある。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]とのあいだのベランダには、仕切[しき]りの板[いた]がある。", "sentence_source": "generated"}, {"text": "布団をベランダの手すりにかけて、日に当てた。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "布団[ふとん]をベランダの手[て]すりにかけて、日[ひ]に当[あ]てた。", "sentence_source": "generated"}, {"text": "火事のときは、ベランダから隣の部屋へ逃げられる場合がある。", "target_word": "ベランダ", "complexity_tier": "T4", "furigana": "火事[かじ]のときは、ベランダから隣[となり]の部屋[へや]へ逃[に]げられる場合[ばあい]がある。", "sentence_source": "generated"}, {"text": "ベランダに出ると、遠くの山まで見渡せた。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "ベランダに出[で]ると、遠[とお]くの山[やま]まで見渡[みわた]せた。", "sentence_source": "generated"}, {"text": "この部屋は広いベランダがあるので、家賃が少し高い。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "この部屋[へや]は広[ひろ]いベランダがあるので、家賃[やちん]が少[すこ]し高[たか]い。", "sentence_source": "generated"}, {"text": "ベランダにハーブを置いて、料理のときに使っている。", "target_word": "ベランダ", "complexity_tier": "T3", "furigana": "ベランダにハーブを置[お]いて、料理[りょうり]のときに使[つか]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ベランダ", "label": "基本形"}, {"form": "ベランダに", "label": "に格"}], "register": "標準（普通体・丁寧体）", "sense_fingerprint": "建物の外に張り出した手すり付きの平らな場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '729dc63f-8b18-4b3c-895a-efbae94aab11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38777, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ベランダ", "is_correct": true, "explanation": "「手すりのついたベランダから、下の道が見える」で、手すり付きの張り出した場所が入る。"}, {"text": "テーブル", "is_correct": false, "explanation": "手すりのついた場所として不自然で、見える場所にならない。"}, {"text": "ハンガー", "is_correct": false, "explanation": "手すりのついた場所から道が見えるという文脈に合わない。"}, {"text": "カーテン", "is_correct": false, "explanation": "手すり付きの場所とは言えず、下の道が見える文に合わない。"}], "explanations": {"ベランダ": "「手すりのついたベランダから、下の道が見える」で、手すり付きの張り出した場所が入る。", "テーブル": "手すりのついた場所として不自然で、見える場所にならない。", "ハンガー": "手すりのついた場所から道が見えるという文脈に合わない。", "カーテン": "手すり付きの場所とは言えず、下の道が見える文に合わない。"}, "sentence_index": 0, "correct_answer": "ベランダ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ベランダの地面を掘り、野菜の苗を植えた。", "explanation": "ここは花壇（地面に植える場所）の意味。ベランダは建物の外側に張り出した床で、土を掘る場所ではない。"}, {"text": "ベランダの暖房を入れて、部屋を暖めた。", "explanation": "室内を暖める文で、建物の外側に張り出したベランダの意味には合わない。"}, {"text": "廊下のベランダに、傘立てを置いた。", "explanation": "ここは屋内の通路の意味。建物の外へ張り出したベランダとは違い、傘立てを置くような通路ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38777, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ベランダ", "is_correct": true, "explanation": "「火事のときは、ベランダから隣の部屋へ逃げられる」で、隣の部屋へ抜けられる外の場所が入る。"}, {"text": "ゴミ箱", "is_correct": false, "explanation": "隣の部屋へ逃げられる場所にならない。"}, {"text": "ピアノ", "is_correct": false, "explanation": "逃げ道として文が成り立たない。"}, {"text": "ストーブ", "is_correct": false, "explanation": "逃げ道として文が成り立たない。"}], "explanations": {"ベランダ": "「火事のときは、ベランダから隣の部屋へ逃げられる」で、隣の部屋へ抜けられる外の場所が入る。", "ゴミ箱": "隣の部屋へ逃げられる場所にならない。", "ピアノ": "逃げ道として文が成り立たない。", "ストーブ": "逃げ道として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "ベランダ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "床下のベランダに、ハーブを置いて料理に使っている。", "explanation": "ここは地面の上の場所の意味。張り出した床の下は地面との間の空間で、ベランダとは別の場所になる。"}, {"text": "ベランダの室内干しで、ハーブを乾かしている。", "explanation": "ここは屋内の物干し場の意味。屋根のない屋外の張り出し場所とは合わない。"}, {"text": "ベランダの地下で、ワインを寝かせている。", "explanation": "ここは地下の貯蔵庫の意味。建物の外へ張り出した場所とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
